#[cfg(target_os = "linux")]
fn provider_role_numeric_identity(
    router: &RootOwnedProviderRouterConfig,
    role: &str,
) -> Result<(u32, u32), V2RuntimeError> {
    let service_role =
        config::expected_service_for_logical_role(role).ok_or_else(|| {
            V2RuntimeError::new(
                "provider_role_unconfigured",
                "logical provider role has no seven-process assignment",
            )
        })?;
    let offset = config::CustodyServiceRole::ALL
        .iter()
        .position(|candidate| *candidate == service_role)
        .and_then(|index| u32::try_from(index).ok())
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_role_unconfigured",
                "provider role has no isolated numeric identity",
            )
        })?;
    let uid = router
        .provider_uid
        .checked_add(offset)
        .filter(|value| *value != 0)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_uid_range_invalid",
                "provider UID base cannot represent every isolated role",
            )
        })?;
    let gid = router
        .provider_gid
        .checked_add(offset)
        .filter(|value| *value != 0)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_gid_range_invalid",
                "provider GID base cannot represent every isolated role",
            )
        })?;
    Ok((uid, gid))
}

#[derive(Debug)]
pub struct V2RuntimeError {
    code: &'static str,
    message: String,
    suppress_response: bool,
}

pub struct V2ServerPacket {
    control: Vec<u8>,
    exact_objects: Vec<File>,
    response_sha256: String,
    output_manifest_sha256: String,
    completion_lease: Option<OperationCompletionLease>,
}

impl V2ServerPacket {
    pub fn with_parts<R>(
        self,
        operation: impl FnOnce(&[u8], &[File]) -> R,
    ) -> R {
        operation(&self.control, &self.exact_objects)
    }

    fn with_completion_lease(
        mut self,
        completion_lease: OperationCompletionLease,
    ) -> Self {
        self.completion_lease = Some(completion_lease);
        self
    }

    fn attach_fresh_attestation(
        &mut self,
        attestation: V2FreshResponseAttestationV1,
    ) -> Result<(), V2RuntimeError> {
        if attestation.unsigned_response_sha256
            != self.response_sha256
            || attestation.output_manifest_sha256
                != self.output_manifest_sha256
        {
            return Err(V2RuntimeError::new(
                "response_attestation_binding_mismatch",
                "fresh attestation does not bind the exact unsigned response and output manifest",
            ));
        }
        let mut response: V2ControlResponse =
            crate::decode_canonical_json(&self.control).map_err(|_| {
                V2RuntimeError::new(
                    "response_attestation_control_invalid",
                    "unsigned response cannot be decoded before attestation",
                )
            })?;
        let slot = match &mut response {
            V2ControlResponse::Success { attestation, .. }
            | V2ControlResponse::Error { attestation, .. }
            | V2ControlResponse::OutcomeUnknown {
                attestation, ..
            } => attestation,
        };
        if slot.is_some() {
            return Err(V2RuntimeError::new(
                "response_attestation_already_present",
                "provider-supplied or reused response attestation is forbidden",
            ));
        }
        *slot = Some(attestation);
        let bytes =
            crate::canonical_json_bytes(&response).map_err(|_| {
                V2RuntimeError::new(
                    "response_attestation_serialization_failed",
                    "attested response cannot be canonically encoded",
                )
            })?;
        if bytes.len() > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES {
            return Err(V2RuntimeError::new(
                "response_attestation_frame_too_large",
                "attested response exceeds the bounded control frame",
            ));
        }
        self.control = bytes;
        Ok(())
    }
}

