pub(crate) struct ValidatedExactObject {
    descriptor: ExactByteObjectDescriptor,
    file: File,
}

impl ValidatedExactObject {
    pub(crate) fn descriptor(&self) -> &ExactByteObjectDescriptor {
        &self.descriptor
    }

    pub(crate) fn into_file(self) -> File {
        self.file
    }

    #[cfg(unix)]
    pub(crate) fn read_at(
        &self,
        buffer: &mut [u8],
        offset: u64,
    ) -> Result<usize, V2RuntimeError> {
        self.file.read_at(buffer, offset).map_err(|error| {
            V2RuntimeError::new(
                "exact_object_read_failed",
                format!("positionally read sealed memfd: {error}"),
            )
        })
    }

    #[cfg(not(unix))]
    pub(crate) fn read_at(
        &self,
        _buffer: &mut [u8],
        _offset: u64,
    ) -> Result<usize, V2RuntimeError> {
        Err(V2RuntimeError::new(
            "exact_object_primitive_unsupported",
            "positionally read exact objects are unsupported on this platform",
        ))
    }
}

pub(crate) struct ValidatedExactObjects {
    by_fd_index: BTreeMap<u16, ValidatedExactObject>,
}

impl ValidatedExactObjects {
    fn empty() -> Self {
        Self {
            by_fd_index: BTreeMap::new(),
        }
    }

    pub(crate) fn get(
        &self,
        fd_index: u16,
    ) -> Option<&ValidatedExactObject> {
        self.by_fd_index.get(&fd_index)
    }

    fn into_files(self) -> Vec<File> {
        self.by_fd_index
            .into_values()
            .map(|object| object.file)
            .collect()
    }

    fn into_single(
        mut self,
    ) -> Result<ValidatedExactObject, V2RuntimeError> {
        if self.by_fd_index.len() != 1 {
            return Err(V2RuntimeError::new(
                "exact_object_count_mismatch",
                "two-phase release requires exactly one validated immutable object",
            ));
        }
        self.by_fd_index.remove(&0).ok_or_else(|| {
            V2RuntimeError::new(
                "invalid_exact_object_descriptor",
                "two-phase release object must use descriptor index zero",
            )
        })
    }
}

