#[derive(
    Debug, Clone, Copy, Deserialize, Serialize, PartialEq, Eq,
    PartialOrd, Ord,
)]
#[serde(rename_all = "camelCase")]
enum ProviderSubchannelOperation {
    Preflight,
    VerifyLiveContract,
    VerifyArchiveContract,
    VerifyRuntimeAttestation,
    VerifyEvidenceSignature,
    VerifyQuorumSignature,
    VerifyTransparencyProof,
    VerifyFinalizationArtifact,
    RetrieveImmutableEvidence,
    ValidateExactResponsePolicy,
    PublicReleaseSignature,
    TrustedTime,
    Revocation,
    ConsumePublicRelease,
    VerifyOutcomeUnknown,
    VerifyDurableStart,
    VerifyReconciliationRecord,
    ReplayClaim,
    ReplayPersist,
    ReplayRehydrate,
    ReplayVerifyRecord,
    ReplayVerifyRetrieval,
    ReplayAbandon,
    ReplayRecover,
    Recover,
    RecoveryAuthorization,
    RecoveryResolution,
    LifecycleDispatch,
    ArchiveRetrieve,
    ArchiveVerify,
    RuntimeReadiness,
    FreshResponseAttestation,
    VerifyFreshResponseAttestation,
    FenceRevoke,
    EmergencyFenceRevoke,
    EmergencyExecute,
}

impl ProviderSubchannelOperation {
    fn required_role(self) -> &'static str {
        match self {
            Self::Preflight => "custody",
            Self::VerifyLiveContract => "live-proof-verifier",
            Self::VerifyArchiveContract => "archive-proof-verifier",
            Self::VerifyRuntimeAttestation
            | Self::FreshResponseAttestation
            | Self::VerifyFreshResponseAttestation => {
                "runtime-attestation"
            }
            Self::VerifyEvidenceSignature
            | Self::Revocation => "evidence-trust",
            Self::VerifyQuorumSignature => "quorum",
            Self::VerifyTransparencyProof => "transparency",
            Self::VerifyFinalizationArtifact => "attester",
            Self::RetrieveImmutableEvidence => "persistence",
            Self::ValidateExactResponsePolicy => {
                "archive-proof-verifier"
            }
            Self::PublicReleaseSignature => "public-release",
            Self::TrustedTime => "trusted-time",
            Self::ConsumePublicRelease => {
                "public-release-consumption"
            }
            Self::VerifyOutcomeUnknown
            | Self::VerifyDurableStart
            | Self::VerifyReconciliationRecord => {
                "outcome-reconciliation"
            }
            Self::ReplayClaim
            | Self::ReplayPersist
            | Self::ReplayRehydrate
            | Self::ReplayVerifyRecord
            | Self::ReplayVerifyRetrieval
            | Self::ReplayAbandon
            | Self::ReplayRecover
            | Self::FenceRevoke => "linearizable-store",
            Self::EmergencyFenceRevoke => {
                "emergency-fence-revoker"
            }
            Self::Recover
            | Self::RecoveryAuthorization
            | Self::RecoveryResolution => "recovery",
            Self::LifecycleDispatch => "mutation-supervisor",
            Self::EmergencyExecute => "emergency-cleanup-executor",
            Self::ArchiveRetrieve | Self::ArchiveVerify => {
                "archive-store"
            }
            Self::RuntimeReadiness => "custody",
        }
    }
}

const ALL_PROVIDER_SUBCHANNEL_OPERATIONS:
    &[ProviderSubchannelOperation] = &[
        ProviderSubchannelOperation::Preflight,
        ProviderSubchannelOperation::VerifyLiveContract,
        ProviderSubchannelOperation::VerifyArchiveContract,
        ProviderSubchannelOperation::VerifyRuntimeAttestation,
        ProviderSubchannelOperation::VerifyEvidenceSignature,
        ProviderSubchannelOperation::VerifyQuorumSignature,
        ProviderSubchannelOperation::VerifyTransparencyProof,
        ProviderSubchannelOperation::VerifyFinalizationArtifact,
        ProviderSubchannelOperation::RetrieveImmutableEvidence,
        ProviderSubchannelOperation::ValidateExactResponsePolicy,
        ProviderSubchannelOperation::PublicReleaseSignature,
        ProviderSubchannelOperation::TrustedTime,
        ProviderSubchannelOperation::Revocation,
        ProviderSubchannelOperation::ConsumePublicRelease,
        ProviderSubchannelOperation::VerifyOutcomeUnknown,
        ProviderSubchannelOperation::VerifyDurableStart,
        ProviderSubchannelOperation::VerifyReconciliationRecord,
        ProviderSubchannelOperation::ReplayClaim,
        ProviderSubchannelOperation::ReplayPersist,
        ProviderSubchannelOperation::ReplayRehydrate,
        ProviderSubchannelOperation::ReplayVerifyRecord,
        ProviderSubchannelOperation::ReplayVerifyRetrieval,
        ProviderSubchannelOperation::ReplayAbandon,
        ProviderSubchannelOperation::ReplayRecover,
        ProviderSubchannelOperation::Recover,
        ProviderSubchannelOperation::RecoveryAuthorization,
        ProviderSubchannelOperation::RecoveryResolution,
        ProviderSubchannelOperation::LifecycleDispatch,
        ProviderSubchannelOperation::ArchiveRetrieve,
        ProviderSubchannelOperation::ArchiveVerify,
        ProviderSubchannelOperation::RuntimeReadiness,
        ProviderSubchannelOperation::FreshResponseAttestation,
        ProviderSubchannelOperation::VerifyFreshResponseAttestation,
        ProviderSubchannelOperation::FenceRevoke,
        ProviderSubchannelOperation::EmergencyFenceRevoke,
        ProviderSubchannelOperation::EmergencyExecute,
    ];

fn required_provider_operations_for_role(
    role: &str,
) -> BTreeSet<ProviderSubchannelOperation> {
    let mut required = ALL_PROVIDER_SUBCHANNEL_OPERATIONS
        .iter()
        .copied()
        .filter(|operation| {
            operation.required_role() == role
                && !matches!(
                    operation,
                    ProviderSubchannelOperation::Preflight
                )
        })
        .collect::<BTreeSet<_>>();
    required.insert(ProviderSubchannelOperation::Preflight);
    required
}

