#[cfg(target_os = "linux")]
struct ProviderChild {
    pid: libc::pid_t,
    reaped: bool,
}

#[cfg(target_os = "linux")]
impl ProviderChild {
    fn try_wait(&mut self) -> io::Result<Option<libc::c_int>> {
        if self.reaped {
            return Ok(Some(0));
        }
        let mut status = 0;
        // SAFETY: this object exclusively owns wait responsibility for the
        // exact direct child returned by clone3.
        let result = unsafe {
            libc::waitpid(self.pid, &mut status, libc::WNOHANG)
        };
        if result == self.pid {
            self.reaped = true;
            Ok(Some(status))
        } else if result == 0 {
            Ok(None)
        } else if result < 0
            && io::Error::last_os_error().raw_os_error()
                == Some(libc::ECHILD)
        {
            self.reaped = true;
            Ok(Some(status))
        } else {
            Err(io::Error::last_os_error())
        }
    }
}

