    #[allow(clippy::too_many_arguments)]
    fn open_channel(
        self: &Arc<Self>,
        _role: &str,
        _operation: ProviderSubchannelOperation,
        _provider_operation_id: &str,
        _request_sha256: &str,
        _attempt_id: &str,
        _attempt_revision: u64,
        _fencing_token: u64,
        _predecessor_state_sha256: &str,
        _deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderOperationBinding, V2RuntimeError> {
        Err(V2RuntimeError::new(
            "provider_router_unsupported",
            "measured subprocess provider routing requires Linux",
        ))
    }

    #[cfg(target_os = "linux")]
    fn lookup_active_channel(
        self: &Arc<Self>,
        provider_operation_id: &str,
        missing_message: &'static str,
    ) -> Result<
        Arc<Mutex<ProviderSubprocessCall>>,
        V2RuntimeError,
    > {
        let channels = match self.active_channels.lock() {
            Ok(channels) => channels,
            Err(poisoned) => {
                self.ready.store(false, Ordering::Release);
                self.quarantined.store(true, Ordering::Release);
                let mut channels = poisoned.into_inner();
                let detached =
                    std::mem::take(&mut *channels);
                drop(channels);
                self.active_call_count.store(0, Ordering::Release);
                self.synchronously_reap_poisoned_channels(
                    &detached,
                );
                return Err(self.quarantine(
                    "provider_channel_state_unavailable",
                    "provider channel registry was poisoned and entered synchronous reaping",
                ));
            }
        };
        channels
            .get(provider_operation_id)
            .cloned()
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "provider_channel_not_live",
                    missing_message,
                )
            })
    }

    #[cfg(target_os = "linux")]
    fn invoke_bound_with_files<P, R>(
        self: &Arc<Self>,
        binding: &VerifiedProviderOperationBinding,
        operation: ProviderSubchannelOperation,
        payload: &P,
        objects: &ValidatedExactObjects,
        deadline: &OperationDeadline,
    ) -> Result<(R, Vec<File>), V2RuntimeError>
    where
        P: Serialize,
        R: DeserializeOwned,
    {
        let role = self.role(&binding.role)?;
        if operation != ProviderSubchannelOperation::Preflight
            && operation.required_role() != binding.role
        {
            return Err(V2RuntimeError::new(
                "provider_subchannel_role_mismatch",
                "bound provider channel cannot execute this operation",
            ));
        }
        let channel = {
            let channels = match self.active_channels.lock() {
                Ok(channels) => channels,
                Err(poisoned) => {
                    self.ready.store(false, Ordering::Release);
                    self.quarantined.store(true, Ordering::Release);
                    let mut channels = poisoned.into_inner();
                    let detached =
                        std::mem::take(&mut *channels);
                    drop(channels);
                    self.active_call_count.store(0, Ordering::Release);
                    self.synchronously_reap_poisoned_channels(
                        &detached,
                    );
                    return Err(self.quarantine(
                        "provider_channel_state_unavailable",
                        "provider channel registry was poisoned and entered synchronous reaping",
                    ));
                }
            };
            channels
                .get(&binding.provider_operation_id)
                .cloned()
                .ok_or_else(|| {
                    V2RuntimeError::new(
                        "provider_channel_not_live",
                        "bound provider channel is not live",
                    )
                })?
        };
        let mut call = match channel.lock() {
            Ok(call) => call,
            Err(poisoned) => {
                self.ready.store(false, Ordering::Release);
                self.quarantined.store(true, Ordering::Release);
                let mut call = poisoned.into_inner();
                self.synchronously_reap_poisoned_call(&mut call);
                return Err(self.quarantine(
                    "provider_channel_poisoned",
                    "provider channel lock was poisoned and entered synchronous reaping",
                ));
            }
        };
        let mut observed_terminal = None;
        let execution = (|| {
            if call.binding.provider_operation_id
                != binding.provider_operation_id
                || call.binding.provider_generation
                    != binding.provider_generation
                || call.binding.role != binding.role
                || call.operation != operation
            {
                return Err(self.quarantine(
                    "provider_channel_binding_mismatch",
                    "provider channel does not match the exact operation, role, and generation binding",
                ));
            }
            let canonical_payload =
                crate::canonical_json_bytes(payload).map_err(|_| {
                    V2RuntimeError::new(
                        "provider_rpc_payload_invalid",
                        "provider payload cannot be canonically encoded",
                    )
                })?;
            if canonical_payload.len()
                > self.router_config.max_control_bytes
            {
                return Err(V2RuntimeError::new(
                    "provider_rpc_payload_too_large",
                    "provider payload exceeds the bounded control frame",
                ));
            }
            let descriptors = objects
                .by_fd_index
                .values()
                .map(|object| object.descriptor.clone())
                .collect::<Vec<_>>();
            let envelope = ProviderRpcRequestEnvelope {
                api_version: PROVIDER_RPC_API_VERSION.to_owned(),
                operation,
                role: binding.role.clone(),
                provider_id: binding.provider_id.clone(),
                provider_generation: binding.provider_generation,
                provider_operation_id:
                    binding.provider_operation_id.clone(),
                provider_operation_binding_sha256:
                    provider_operation_binding_sha256(binding),
                request_sha256: binding.request_sha256.clone(),
                descriptor_manifest_sha256:
                    descriptor_manifest_sha256(&descriptors),
                attempt_id: binding.attempt_id.clone(),
                attempt_revision: binding.attempt_revision,
                fencing_token: binding.fencing_token,
                predecessor_state_sha256:
                    binding.predecessor_state_sha256.clone(),
                deadline_at_epoch_ms:
                    binding.deadline_at_epoch_ms,
                launch_nonce: binding.launch_nonce.clone(),
                canonical_payload_base64:
                    base64::engine::general_purpose::STANDARD
                        .encode(&canonical_payload),
                canonical_payload_sha256: format!(
                    "sha256:{:x}",
                    Sha256::digest(&canonical_payload)
                ),
                exact_objects: descriptors,
            };
            let request_bytes =
                crate::canonical_json_bytes(&envelope).map_err(
                    |_| {
                        V2RuntimeError::new(
                            "provider_rpc_envelope_invalid",
                            "provider request envelope cannot be canonically encoded",
                        )
                    },
                )?;
            if request_bytes.len()
                > self.router_config.max_control_bytes
            {
                return Err(V2RuntimeError::new(
                    "provider_rpc_frame_too_large",
                    "provider request exceeds the bounded control frame",
                ));
            }
            call.rpc_started = Instant::now();
            send_provider_frame(
                call.socket.as_raw_fd(),
                &request_bytes,
                objects,
            )?;
            let terminal =
                wait_for_provider_terminal(&mut call, deadline)?;
            observed_terminal = Some(terminal.envelope.clone());
            validate_provider_terminal(
                &terminal.envelope,
                binding,
                operation,
                role,
                deadline,
            )?;
            if terminal.envelope.status
                == ProviderRpcTerminalStatus::OutcomeUnknown
            {
                return Err(V2RuntimeError::new(
                    "provider_rpc_outcome_unknown",
                    "provider authority returned a durable outcome-unknown terminal",
                )
                .suppress_response());
            }
            if terminal.envelope.status
                == ProviderRpcTerminalStatus::DeniedNeverStarted
            {
                return Err(V2RuntimeError::new(
                    "provider_rpc_denied",
                    "provider authority returned a signed denial",
                ));
            }
            let response_payload =
                base64::engine::general_purpose::STANDARD
                    .decode(
                        &terminal
                            .envelope
                            .canonical_payload_base64,
                    )
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_rpc_payload_invalid",
                            "provider response payload is not canonical base64",
                        )
                    })?;
            if format!(
                "sha256:{:x}",
                Sha256::digest(&response_payload)
            ) != terminal.envelope.canonical_payload_sha256
            {
                return Err(V2RuntimeError::new(
                    "provider_rpc_payload_digest_mismatch",
                    "provider response payload digest does not match",
                ));
            }
            let result =
                crate::decode_canonical_json(&response_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_rpc_response_invalid",
                            "provider response does not satisfy the expected closed DTO",
                        )
                    })?;
            Ok((result, terminal.output_files))
        })();
        let cleanup_deadline =
            call.lifecycle_deadline.clone();
        let cleanup = self.cleanup_provider_call(
            &mut call,
            observed_terminal.as_ref(),
            &cleanup_deadline,
            ProviderCleanupMode::Normal,
        );
        if let Ok(termination) = &cleanup {
            self.finish_channel(binding, termination)?;
        }
        match (execution, cleanup) {
            (Ok(result), Ok(_)) => Ok(result),
            (Err(error), Ok(_)) => {
                Err(error.suppress_response())
            }
            (_, Err(_)) => Err(self.quarantine(
                "provider_cleanup_unverified",
                "provider RPC did not complete with verified fence revocation, kill, and bounded reap",
            )),
        }
    }

    #[cfg(target_os = "linux")]
    fn invoke_bound<P, R>(
        self: &Arc<Self>,
        binding: &VerifiedProviderOperationBinding,
        operation: ProviderSubchannelOperation,
        payload: &P,
        objects: &ValidatedExactObjects,
        deadline: &OperationDeadline,
    ) -> Result<R, V2RuntimeError>
    where
        P: Serialize,
        R: DeserializeOwned,
    {
        let (result, output_files) = self.invoke_bound_with_files(
            binding,
            operation,
            payload,
            objects,
            deadline,
        )?;
        if !output_files.is_empty() {
            return Err(V2RuntimeError::new(
                "provider_rpc_unexpected_output",
                "typed authority call returned unexpected exact objects",
            )
            .suppress_response());
        }
        Ok(result)
    }

