#[cfg(target_os = "linux")]
fn emergency_target_from_call(
    call: &ProviderSubprocessCall,
) -> EmergencyCleanupTarget {
    EmergencyCleanupTarget {
        target_binding_sha256:
            provider_operation_binding_sha256(&call.binding),
        journal_record_sha256: None,
        provider_operation_id:
            call.binding.provider_operation_id.clone(),
        provider_generation: call.binding.provider_generation,
        provider_role: call.binding.role.clone(),
        request_sha256: call.binding.request_sha256.clone(),
        attempt_id: call.binding.attempt_id.clone(),
        attempt_revision: call.binding.attempt_revision,
        fencing_token: call.binding.fencing_token,
        predecessor_state_sha256:
            call.binding.predecessor_state_sha256.clone(),
        durable_start_receipt_sha256:
            call.binding.durable_start_receipt_sha256.clone(),
        mutation_fence_permit_sha256:
            call.binding.mutation_fence_permit_sha256.clone(),
        kernel_process_identity_sha256: Some(
            call.binding
                .kernel_process_identity_sha256
                .clone(),
        ),
        cgroup_sha256: call.cgroup_sha256.clone(),
        process_group_id: None,
    }
}

#[cfg(target_os = "linux")]
fn emergency_target_from_orphan(
    record: &DurableProviderOrphanRecord,
    journal_record_sha256: &str,
) -> EmergencyCleanupTarget {
    let mut binding = Sha256::new();
    append_hash_frame(
        &mut binding,
        b"serverware.response-v2/recovered-orphan-target/v1",
    );
    append_hash_frame(
        &mut binding,
        journal_record_sha256.as_bytes(),
    );
    append_hash_frame(
        &mut binding,
        record.provider_operation_id.as_bytes(),
    );
    append_hash_frame(
        &mut binding,
        &record.provider_generation.to_be_bytes(),
    );
    append_hash_frame(
        &mut binding,
        &record.fencing_token.to_be_bytes(),
    );
    EmergencyCleanupTarget {
        target_binding_sha256:
            format!("sha256:{:x}", binding.finalize()),
        journal_record_sha256:
            Some(journal_record_sha256.to_owned()),
        provider_operation_id:
            record.provider_operation_id.clone(),
        provider_generation: record.provider_generation,
        provider_role: record.provider_role.clone(),
        request_sha256: record.request_sha256.clone(),
        attempt_id: record.attempt_id.clone(),
        attempt_revision: record.attempt_revision,
        fencing_token: record.fencing_token,
        predecessor_state_sha256:
            record.predecessor_state_sha256.clone(),
        durable_start_receipt_sha256:
            record.durable_start_receipt_sha256.clone(),
        mutation_fence_permit_sha256:
            record.mutation_fence_permit_sha256.clone(),
        kernel_process_identity_sha256:
            record.kernel_process_identity_sha256.clone(),
        cgroup_sha256: record.cgroup_path_sha256.clone(),
        process_group_id: None,
    }
}

#[cfg(target_os = "linux")]
fn process_identity_manifest_sha256<'a>(
    identities: impl Iterator<Item = &'a str>,
) -> String {
    let mut identities = identities.collect::<Vec<_>>();
    identities.sort_unstable();
    let mut hasher = Sha256::new();
    append_hash_frame(
        &mut hasher,
        b"serverware.response-v2/emergency-process-manifest/v1",
    );
    for identity in identities {
        append_hash_frame(&mut hasher, identity.as_bytes());
    }
    format!("sha256:{:x}", hasher.finalize())
}

#[cfg(target_os = "linux")]
fn emergency_fence_as_normal(
    receipt: EmergencyFenceRevocationReceipt,
) -> ProviderFenceRevocationReceipt {
    ProviderFenceRevocationReceipt {
        provider_operation_id: receipt.provider_operation_id,
        provider_operation_binding_sha256:
            receipt.target_binding_sha256,
        provider_generation: receipt.provider_generation,
        fencing_token: receipt.fencing_token,
        durable_fence_receipt_sha256:
            receipt.durable_fence_receipt_sha256,
        fence_quiescent: receipt.fence_quiescent,
        authority_revision: receipt.authority_revision,
        issued_at_epoch_ms: receipt.issued_at_epoch_ms,
        signer_key_id: receipt.signer_key_id,
        signer_key_material_sha256:
            receipt.signer_key_material_sha256,
        signature: receipt.signature,
    }
}

#[cfg(target_os = "linux")]
fn emergency_executor_as_cleanup_receipt(
    call: &ProviderSubprocessCall,
    observation: &EmergencyExecutorObservation,
    local: &LocalProviderTermination,
    fence: &ProviderFenceRevocationReceipt,
) -> ProviderCleanupAttestationReceipt {
    let namespace_quarantine_receipt_sha256 = {
        let mut hasher = Sha256::new();
        append_hash_frame(
            &mut hasher,
            b"serverware.response-v2/emergency-executor-closure/v1",
        );
        append_hash_frame(
            &mut hasher,
            observation.manifest_sha256.as_bytes(),
        );
        append_hash_frame(
            &mut hasher,
            fence.durable_fence_receipt_sha256.as_bytes(),
        );
        append_hash_frame(
            &mut hasher,
            local.process_reap_receipt_sha256.as_bytes(),
        );
        format!("sha256:{:x}", hasher.finalize())
    };
    ProviderCleanupAttestationReceipt {
        provider_operation_id:
            call.binding.provider_operation_id.clone(),
        provider_operation_binding_sha256:
            provider_operation_binding_sha256(&call.binding),
        provider_generation: call.binding.provider_generation,
        namespace_quarantine_receipt_sha256,
        durable_fence_receipt_sha256:
            fence.durable_fence_receipt_sha256.clone(),
        cleanup_request_sha256:
            observation.manifest_sha256.clone(),
        cgroup_kill_receipt_sha256:
            local.cgroup_kill_receipt_sha256.clone(),
        pidfd_kill_receipt_sha256:
            local.pidfd_kill_receipt_sha256.clone(),
        process_group_kill_receipt_sha256:
            local.process_group_kill_receipt_sha256.clone(),
        process_reap_receipt_sha256:
            local.process_reap_receipt_sha256.clone(),
        cgroup_events_sha256:
            observation.cgroup_events_sha256.clone(),
        process_killed: observation.cgroup_kill_attempted
            && observation.pidfd_kill_attempted,
        process_reaped: local.direct_child_reaped
            && observation.pidfd_exit_observed,
        cgroup_empty_observed:
            local.cgroup_empty_observed
                && observation.cgroup_empty_observed,
        namespace_quarantined:
            observation.cgroup_empty_observed,
        verified_at_epoch_ms:
            observation.observed_at_epoch_ms,
    }
}

