/// The configured watchdog is an independently killable process supervisor,
/// not an in-process callback. Every potentially blocking launch, attestation,
/// fence, provider RPC, kill, and reap operation runs in that worker. The
/// custody thread only starts a job, performs bounded nonblocking polls, and
/// validates the independently signed terminal.
mod runtime_watchdog_sealed {
    pub trait Sealed {}
}

pub(crate) trait RuntimeProviderWatchdogAuthority:
    runtime_watchdog_sealed::Sealed + Send + Sync
{
    /// Establish an operation-scoped authenticated channel to one measured
    /// authority process. The returned sealed binding includes the exact peer
    /// socket and process identity. `Err` guarantees no live session remains.
    fn bind_authority_call_nonblocking(
        &self,
        role: &'static str,
        operation: ProviderSubchannelOperation,
        pin: &RoleIdentityPin,
        provider_operation_id: &str,
        request_sha256: &str,
        attempt_id: &str,
        fencing_token: u64,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderOperationBinding, V2RuntimeError>;

    fn measured_provider_identity_from_preflight_nonblocking(
        &self,
        role: &'static str,
        pin: &RoleIdentityPin,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderIdentity, V2RuntimeError>;

    /// Before returning a job, the watchdog must durably mark the mutation
    /// started and acquire the one-use fence. Both receipts are bound into the
    /// returned sealed operation binding. `Err` is permitted only before any
    /// process, fence, durable start, credential, or mutation exists; after
    /// any such effect the watchdog must return a killable job capability.
    fn start_operation_nonblocking(
        &self,
        role: &'static str,
        pin: &RoleIdentityPin,
        request: SupervisedProviderRpcRequest<'_>,
        deadline: &OperationDeadline,
    ) -> Result<RuntimeProviderStartDecision, V2RuntimeError>;

    /// This method must perform one nonblocking status read. It may return
    /// `None` while the worker remains live; it must never wait on provider I/O.
    fn poll_operation_nonblocking(
        &self,
        job: &mut RuntimeProviderWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<Option<RuntimeProviderWatchdogTerminal>, V2RuntimeError>;

    /// The watchdog authority must use an independent pidfd/fence verifier.
    /// Success means the fence is quiescent and the exact measured process is
    /// dead and reaped. An unverifiable result is an error, never a terminal.
    fn quarantine_terminate_and_verify_nonblocking(
        &self,
        job: &mut RuntimeProviderWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedForcedProviderTermination, V2RuntimeError>;

    /// Emergency cleanup is a separate measured process path. It must attempt
    /// namespace quarantine and stable-handle cgroup/pidfd kill even
    /// when fence revocation failed, then prove bounded reap.
    fn emergency_quarantine_kill_reap_nonblocking(
        &self,
        job: &mut RuntimeProviderWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedForcedProviderTermination, V2RuntimeError>;

    /// Read-only workers may hold release capabilities or injected
    /// credentials, so they use the same independently killable process
    /// boundary and exact-process termination proof as mutation workers.
    fn start_read_only_operation_nonblocking(
        &self,
        role: &'static str,
        pin: &RoleIdentityPin,
        request: SupervisedReadOnlyRpcRequest<'_>,
        deadline: &OperationDeadline,
    ) -> Result<RuntimeReadOnlyWatchdogJob, V2RuntimeError>;

    fn poll_read_only_operation_nonblocking(
        &self,
        job: &mut RuntimeReadOnlyWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<Option<RuntimeReadOnlyWatchdogTerminal>, V2RuntimeError>;

    fn quarantine_terminate_read_only_and_verify_nonblocking(
        &self,
        job: &mut RuntimeReadOnlyWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError>;

    fn emergency_quarantine_kill_reap_read_only_nonblocking(
        &self,
        job: &mut RuntimeReadOnlyWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError>;

    fn quarantine_authority_call_and_verify_nonblocking(
        &self,
        binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError>;

    fn emergency_quarantine_authority_call_nonblocking(
        &self,
        binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError>;

    fn verify_terminal_signature_and_freshness(
        &self,
        binding: &VerifiedProviderOperationBinding,
        termination: &VerifiedProviderTermination,
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError>;

    fn verify_never_started_ed25519(
        &self,
        pin: &RoleIdentityPin,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool;
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct LifecycleProviderRpcPayload<'a> {
    canonical_control_base64: String,
    canonical_control_sha256: String,
    descriptor_manifest_sha256: &'a str,
    predecessor_state_sha256: &'a str,
    attempt_revision: u64,
    durable_replay_authority_revision: u64,
    durable_replay_provider_operation_binding_sha256: String,
    live_verifier_operation_binding_sha256: String,
    live_verifier_provider_generation: u64,
    mutation_provider_operation_id: &'a str,
    mutation_provider_generation: u64,
}

impl InstalledProviderGeneration {
    #[cfg(target_os = "linux")]
    fn send_lifecycle_request(
        self: &Arc<Self>,
        binding: &VerifiedProviderOperationBinding,
        request: &SupervisedProviderRpcRequest<'_>,
    ) -> Result<(), V2RuntimeError> {
        let payload = LifecycleProviderRpcPayload {
            canonical_control_base64:
                base64::engine::general_purpose::STANDARD
                    .encode(request.canonical_control),
            canonical_control_sha256: format!(
                "sha256:{:x}",
                Sha256::digest(request.canonical_control)
            ),
            descriptor_manifest_sha256:
                request.descriptor_manifest_sha256,
            predecessor_state_sha256:
                request.predecessor_state_sha256,
            attempt_revision: request.attempt_revision,
            durable_replay_authority_revision:
                request
                    .durable_replay_start
                    .authority_revision,
            durable_replay_provider_operation_binding_sha256:
                provider_operation_binding_sha256(
                    &request
                        .durable_replay_start
                        .adapter_binding,
                ),
            live_verifier_operation_binding_sha256:
                request
                    .live_capability
                    .verifier_operation_binding_sha256
                    .clone(),
            live_verifier_provider_generation:
                request
                    .live_capability
                    .verifier_provider_generation,
            mutation_provider_operation_id:
                request.provider_operation_id,
            mutation_provider_generation:
                request
                    .live_capability
                    .mutation_provider_generation,
        };
        let canonical =
            crate::canonical_json_bytes(&payload).map_err(|_| {
                V2RuntimeError::new(
                    "provider_lifecycle_payload_invalid",
                    "lifecycle provider payload cannot be canonicalized",
                )
            })?;
        let descriptors = request
            .exact_objects
            .by_fd_index
            .values()
            .map(|object| object.descriptor.clone())
            .collect::<Vec<_>>();
        let envelope = ProviderRpcRequestEnvelope {
            attempt_revision: request.attempt_revision,
            predecessor_state_sha256:
                request.predecessor_state_sha256.to_owned(),
            ..provider_rpc_request_envelope(
                binding,
                ProviderSubchannelOperation::LifecycleDispatch,
                &canonical,
                descriptors,
            )
        };
        let frame =
            crate::canonical_json_bytes(&envelope).map_err(|_| {
                V2RuntimeError::new(
                    "provider_lifecycle_envelope_invalid",
                    "lifecycle provider envelope cannot be canonicalized",
                )
            })?;
        let channel = self.lookup_active_channel(
            &binding.provider_operation_id,
            "lifecycle provider channel is not live",
        )?;
        let mut call = match channel.lock() {
            Ok(call) => call,
            Err(poisoned) => {
                self.ready.store(false, Ordering::Release);
                self.quarantined.store(true, Ordering::Release);
                let mut call = poisoned.into_inner();
                self.synchronously_reap_poisoned_call(&mut call);
                return Err(self.quarantine(
                    "provider_channel_poisoned",
                    "lifecycle provider channel lock was poisoned and entered synchronous reaping",
                ));
            }
        };
        call.rpc_started = Instant::now();
        send_provider_frame(
            call.socket.as_raw_fd(),
            &frame,
            request.exact_objects,
        )
    }

    #[cfg(target_os = "linux")]
    fn send_read_only_request(
        self: &Arc<Self>,
        binding: &VerifiedProviderOperationBinding,
        request: &SupervisedReadOnlyRpcRequest<'_>,
    ) -> Result<(), V2RuntimeError> {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct ReadOnlyPayload<'a> {
            canonical_control_base64: String,
            canonical_control_sha256: String,
            authorization_binding_sha256: String,
            request_sha256: &'a str,
        }
        let authorization_binding_sha256 = match &request.authorization {
            VerifiedReadOnlyAuthorization::Retrieve(capability) => {
                capability.release_request_commitment_sha256.clone()
            }
            VerifiedReadOnlyAuthorization::VerifyArchive(capability) => {
                capability.verifier_operation_binding_sha256.clone()
            }
        };
        let payload = ReadOnlyPayload {
            canonical_control_base64:
                base64::engine::general_purpose::STANDARD
                    .encode(request.canonical_control),
            canonical_control_sha256: format!(
                "sha256:{:x}",
                Sha256::digest(request.canonical_control)
            ),
            authorization_binding_sha256,
            request_sha256: request.request_sha256,
        };
        let canonical =
            crate::canonical_json_bytes(&payload).map_err(|_| {
                V2RuntimeError::new(
                    "provider_read_payload_invalid",
                    "read-only provider payload cannot be canonicalized",
                )
            })?;
        let descriptors = request
            .exact_objects
            .by_fd_index
            .values()
            .map(|object| object.descriptor.clone())
            .collect::<Vec<_>>();
        let operation = match &request.authorization {
            VerifiedReadOnlyAuthorization::Retrieve(_) => {
                ProviderSubchannelOperation::ArchiveRetrieve
            }
            VerifiedReadOnlyAuthorization::VerifyArchive(_) => {
                ProviderSubchannelOperation::ArchiveVerify
            }
        };
        let envelope = provider_rpc_request_envelope(
            binding,
            operation,
            &canonical,
            descriptors,
        );
        let frame =
            crate::canonical_json_bytes(&envelope).map_err(|_| {
                V2RuntimeError::new(
                    "provider_read_envelope_invalid",
                    "read-only provider envelope cannot be canonicalized",
                )
            })?;
        let channel = self.lookup_active_channel(
            &binding.provider_operation_id,
            "read-only provider channel is not live",
        )?;
        let mut call = match channel.lock() {
            Ok(call) => call,
            Err(poisoned) => {
                self.ready.store(false, Ordering::Release);
                self.quarantined.store(true, Ordering::Release);
                let mut call = poisoned.into_inner();
                self.synchronously_reap_poisoned_call(&mut call);
                return Err(self.quarantine(
                    "provider_channel_poisoned",
                    "read-only provider channel lock was poisoned and entered synchronous reaping",
                ));
            }
        };
        call.rpc_started = Instant::now();
        send_provider_frame(
            call.socket.as_raw_fd(),
            &frame,
            request.exact_objects,
        )
    }

    #[cfg(target_os = "linux")]
    fn poll_started_call(
        self: &Arc<Self>,
        binding: &VerifiedProviderOperationBinding,
        operation: ProviderSubchannelOperation,
        deadline: &OperationDeadline,
    ) -> Result<
        Option<PolledStartedCall>,
        V2RuntimeError,
    > {
        let channel = self.lookup_active_channel(
            &binding.provider_operation_id,
            "provider operation channel is not live",
        )?;
        let mut call = match channel.lock() {
            Ok(call) => call,
            Err(poisoned) => {
                self.ready.store(false, Ordering::Release);
                self.quarantined.store(true, Ordering::Release);
                let mut call = poisoned.into_inner();
                self.synchronously_reap_poisoned_call(&mut call);
                return Err(self.quarantine(
                    "provider_channel_poisoned",
                    "provider operation channel lock was poisoned and entered synchronous reaping",
                ));
            }
        };
        if call.rpc_started.elapsed()
            >= Duration::from_millis(call.rpc_timeout_ms)
        {
            let cleanup_deadline =
                call.lifecycle_deadline.clone();
            let cleanup = self.cleanup_provider_call(
                &mut call,
                None,
                &cleanup_deadline,
                ProviderCleanupMode::Normal,
            );
            return match cleanup {
                Ok(termination) => {
                    let outcome_unknown =
                        self.issue_durable_outcome_unknown(
                            binding,
                            &termination,
                            &cleanup_deadline,
                            ProviderCleanupMode::Normal,
                        )?;
                    self.finish_channel(
                        binding,
                        &termination,
                    )?;
                    Ok(Some(PolledStartedCall::Ambiguous {
                        outcome_unknown,
                        termination,
                    }))
                }
                Err(_) => Err(self.quarantine(
                    "provider_cleanup_unverified",
                    "timed-out provider process could not be fenced, killed, and reaped",
                )),
            };
        }
        let socket = call.socket.as_raw_fd();
        let received = match receive_provider_frame(
            socket,
            &mut call.response_buffer,
        ) {
            Ok(received) => received,
            Err(error) => {
                let cleanup_deadline =
                    call.lifecycle_deadline.clone();
                let cleanup = self.cleanup_provider_call(
                    &mut call,
                    None,
                    &cleanup_deadline,
                    ProviderCleanupMode::Normal,
                );
                return match cleanup {
                    Ok(termination) => {
                        let _ = error;
                        let outcome_unknown =
                            self.issue_durable_outcome_unknown(
                                binding,
                                &termination,
                                &cleanup_deadline,
                                ProviderCleanupMode::Normal,
                            )?;
                        self.finish_channel(
                            binding,
                            &termination,
                        )?;
                        Ok(Some(PolledStartedCall::Ambiguous {
                            outcome_unknown,
                            termination,
                        }))
                    }
                    Err(_) => Err(self.quarantine(
                        "provider_cleanup_unverified",
                        "provider receive failed without verified fence revocation, kill, and bounded reap",
                    )),
                };
            }
        };
        let Some((bytes, fds)) = received else {
            return Ok(None);
        };
        let files = fds.into_iter().map(File::from).collect::<Vec<_>>();
        let mut observed_terminal = None;
        let parsed = (|| {
            let envelope: ProviderRpcTerminalEnvelope =
                crate::decode_canonical_json(&bytes).map_err(|_| {
                    V2RuntimeError::new(
                        "provider_rpc_terminal_invalid",
                        "provider terminal does not satisfy the closed DTO",
                    )
                })?;
            observed_terminal = Some(envelope.clone());
            validate_provider_terminal(
                &envelope,
                binding,
                operation,
                self.role(&binding.role)?,
                deadline,
            )?;
            let validated = validate_exact_object_files(
                &envelope.output_descriptors,
                files,
                Some(deadline),
            )?;
            Ok(ProviderTerminalWithFiles {
                envelope,
                output_files: validated.into_files(),
            })
        })();
        let cleanup_deadline =
            call.lifecycle_deadline.clone();
        let cleanup = self.cleanup_provider_call(
            &mut call,
            observed_terminal.as_ref(),
            &cleanup_deadline,
            ProviderCleanupMode::Normal,
        );
        match (parsed, cleanup) {
            (Ok(terminal), Ok(termination)) => {
                self.finish_channel(
                    binding,
                    &termination,
                )?;
                Ok(Some(PolledStartedCall::Terminal {
                    terminal,
                    termination,
                }))
            }
            (Err(_), Ok(termination)) => {
                let outcome_unknown =
                    self.issue_durable_outcome_unknown(
                        binding,
                        &termination,
                        &cleanup_deadline,
                        ProviderCleanupMode::Normal,
                    )?;
                self.finish_channel(
                    binding,
                    &termination,
                )?;
                Ok(Some(PolledStartedCall::Ambiguous {
                    outcome_unknown,
                    termination,
                }))
            }
            (_, Err(_)) => Err(self.quarantine(
                "provider_cleanup_unverified",
                "provider terminal failed without verified fence revocation, kill, and bounded reap",
            )),
        }
    }

    #[cfg(target_os = "linux")]
    fn terminate_started_call(
        self: &Arc<Self>,
        binding: &VerifiedProviderOperationBinding,
        inherited_deadline: &OperationDeadline,
        cleanup_mode: ProviderCleanupMode,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError> {
        let channels = match self.active_channels.lock() {
            Ok(channels) => channels,
            Err(poisoned) => {
                self.ready.store(false, Ordering::Release);
                self.quarantined.store(true, Ordering::Release);
                let mut channels = poisoned.into_inner();
                let detached =
                    std::mem::take(&mut *channels);
                drop(channels);
                self.active_call_count.store(0, Ordering::Release);
                self.synchronously_reap_poisoned_channels(
                    &detached,
                );
                return Err(self.quarantine(
                    "provider_channel_registry_poisoned",
                    "provider channel registry was poisoned during termination and entered synchronous reaping",
                ));
            }
        };
        let channel = channels
            .get(&binding.provider_operation_id)
            .cloned()
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "provider_channel_not_live",
                    "provider operation channel is not live",
                )
            })?;
        drop(channels);
        let mut call = match channel.lock() {
            Ok(call) => call,
            Err(poisoned) => {
                self.ready.store(false, Ordering::Release);
                self.quarantined.store(true, Ordering::Release);
                let mut call = poisoned.into_inner();
                self.synchronously_reap_poisoned_call(&mut call);
                return Err(self.quarantine(
                    "provider_channel_poisoned",
                    "provider channel lock was poisoned during termination and entered synchronous reaping",
                ));
            }
        };
        let termination = self.cleanup_provider_call(
            &mut call,
            None,
            inherited_deadline,
            cleanup_mode,
        );
        match termination {
            Ok(termination) => {
                self.finish_channel(binding, &termination)?;
                Ok(termination)
            }
            Err(error) => Err(error),
        }
    }
}

impl runtime_watchdog_sealed::Sealed
    for Arc<InstalledProviderGeneration>
{
}

impl RuntimeProviderWatchdogAuthority
    for Arc<InstalledProviderGeneration>
{
    fn bind_authority_call_nonblocking(
        &self,
        role: &'static str,
        operation: ProviderSubchannelOperation,
        pin: &RoleIdentityPin,
        provider_operation_id: &str,
        request_sha256: &str,
        attempt_id: &str,
        fencing_token: u64,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderOperationBinding, V2RuntimeError> {
        if pin.role != role
            || pin.provider_generation != self.generation
        {
            return Err(V2RuntimeError::new(
                "provider_role_pin_mismatch",
                "authority call does not match the installed role generation",
            ));
        }
        self.open_channel(
            role,
            operation,
            provider_operation_id,
            request_sha256,
            attempt_id,
            0,
            fencing_token,
            request_sha256,
            deadline,
        )
    }

    fn measured_provider_identity_from_preflight_nonblocking(
        &self,
        role: &'static str,
        pin: &RoleIdentityPin,
        _deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderIdentity, V2RuntimeError> {
        let installed = self.role(role)?;
        if installed.pin.provider_id != pin.provider_id
            || installed.pin.provider_generation
                != pin.provider_generation
            || !self.provider_ready()
        {
            return Err(V2RuntimeError::new(
                "provider_preflight_identity_mismatch",
                "installed provider identity does not match the root-owned role pin",
            ));
        }
        Ok(VerifiedProviderIdentity {
            role: REQUIRED_ROLE_IDENTITIES
                .iter()
                .copied()
                .find(|candidate| *candidate == role)
                .ok_or_else(|| {
                    V2RuntimeError::new(
                        "provider_role_unconfigured",
                        "provider role is not in the closed role set",
                    )
                })?,
            provider_id: pin.provider_id.clone(),
            provider_generation: pin.provider_generation,
            key_id: pin.key_id.clone(),
            key_material_sha256:
                pin.key_material_sha256.clone(),
            executable_measurement_sha256:
                pin.executable_measurement_sha256.clone(),
            provider_config_sha256:
                pin.provider_config_sha256.clone(),
            tee_measurement_sha256:
                pin.tee_measurement_sha256.clone(),
        })
    }

    fn start_operation_nonblocking(
        &self,
        role: &'static str,
        pin: &RoleIdentityPin,
        request: SupervisedProviderRpcRequest<'_>,
        deadline: &OperationDeadline,
    ) -> Result<RuntimeProviderStartDecision, V2RuntimeError> {
        let binding = self.open_channel(
            role,
            ProviderSubchannelOperation::LifecycleDispatch,
            request.provider_operation_id,
            request.request_sha256,
            request.attempt_id,
            request.attempt_revision,
            request.fencing_token,
            request.predecessor_state_sha256,
            deadline,
        )?;
        if binding.provider_generation != pin.provider_generation {
            let error = V2RuntimeError::new(
                "provider_generation_mismatch",
                "lifecycle provider generation does not match its pin",
            );
            return match self.terminate_started_call(
                &binding,
                deadline,
                ProviderCleanupMode::Normal,
            ) {
                Ok(_) => Err(error.suppress_response()),
                Err(_) => Err(self.quarantine(
                    "provider_cleanup_unverified",
                    "mismatched lifecycle process could not be fenced, killed, and reaped",
                )),
            };
        }
        if let Err(error) =
            self.send_lifecycle_request(&binding, &request)
        {
            return match self.terminate_started_call(
                &binding,
                deadline,
                ProviderCleanupMode::Normal,
            ) {
                Ok(_) => Err(error.suppress_response()),
                Err(_) => Err(self.quarantine(
                    "provider_cleanup_unverified",
                    "lifecycle dispatch failed without verified fence revocation, kill, and bounded reap",
                )),
            };
        }
        Ok(RuntimeProviderStartDecision::Started(
            RuntimeProviderWatchdogJob {
                watchdog_job_lease:
                    provider_operation_binding_sha256(&binding)
                        .into_bytes(),
                exclusive_deadline_at_epoch_ms:
                    deadline.absolute_epoch_ms,
                binding,
                _seal: RuntimeProviderWatchdogJobSeal,
            },
        ))
    }

    fn poll_operation_nonblocking(
        &self,
        job: &mut RuntimeProviderWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<Option<RuntimeProviderWatchdogTerminal>, V2RuntimeError> {
        let Some(polled) = self.poll_started_call(
            &job.binding,
            ProviderSubchannelOperation::LifecycleDispatch,
            deadline,
        )? else {
            return Ok(None);
        };
        let (terminal, termination) = match polled {
            PolledStartedCall::Terminal {
                terminal,
                termination,
            } => (terminal, termination),
            PolledStartedCall::Ambiguous {
                outcome_unknown,
                termination,
            } => {
                return Ok(Some(
                    RuntimeProviderWatchdogTerminal::OutcomeUnknown {
                        result: outcome_unknown,
                        termination,
                    },
                ));
            }
        };
        let response = base64::engine::general_purpose::STANDARD
            .decode(&terminal.envelope.canonical_payload_base64)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_terminal_payload_invalid",
                    "provider terminal payload is not canonical base64",
                )
            })?;
        Ok(Some(match terminal.envelope.status {
            ProviderRpcTerminalStatus::Committed => {
                RuntimeProviderWatchdogTerminal::Committed {
                    canonical_response: response,
                    exact_objects: terminal.output_files,
                    termination,
                }
            }
            ProviderRpcTerminalStatus::OutcomeUnknown => {
                let result: V2OutcomeUnknownResult =
                    crate::decode_canonical_json(&response)
                        .map_err(|_| {
                            V2RuntimeError::new(
                                "provider_unknown_terminal_invalid",
                                "outcome-unknown terminal does not satisfy its closed DTO",
                            )
                        })?;
                RuntimeProviderWatchdogTerminal::OutcomeUnknown {
                    result,
                    termination,
                }
            }
            ProviderRpcTerminalStatus::DeniedNeverStarted => {
                RuntimeProviderWatchdogTerminal::RejectedBeforeStart {
                    error: V2RuntimeError::new(
                        "provider_denied_after_start",
                        "provider labeled a started operation as denied",
                    ),
                    termination: Some(termination),
                }
            }
        }))
    }

    fn quarantine_terminate_and_verify_nonblocking(
        &self,
        job: &mut RuntimeProviderWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedForcedProviderTermination, V2RuntimeError> {
        let termination = self.terminate_started_call(
            &job.binding,
            deadline,
            ProviderCleanupMode::Normal,
        )?;
        let result = self.issue_durable_outcome_unknown(
            &job.binding,
            &termination,
            deadline,
            ProviderCleanupMode::Normal,
        )?;
        Ok(VerifiedForcedProviderTermination {
            termination,
            outcome_unknown: result,
            _seal: VerifiedForcedProviderTerminationSeal,
        })
    }

    fn emergency_quarantine_kill_reap_nonblocking(
        &self,
        job: &mut RuntimeProviderWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedForcedProviderTermination, V2RuntimeError> {
        let termination = self.terminate_started_call(
            &job.binding,
            deadline,
            ProviderCleanupMode::Emergency,
        )?;
        let result = self.issue_durable_outcome_unknown(
            &job.binding,
            &termination,
            deadline,
            ProviderCleanupMode::Emergency,
        )?;
        Ok(VerifiedForcedProviderTermination {
            termination,
            outcome_unknown: result,
            _seal: VerifiedForcedProviderTerminationSeal,
        })
    }

    fn start_read_only_operation_nonblocking(
        &self,
        role: &'static str,
        _pin: &RoleIdentityPin,
        request: SupervisedReadOnlyRpcRequest<'_>,
        deadline: &OperationDeadline,
    ) -> Result<RuntimeReadOnlyWatchdogJob, V2RuntimeError> {
        let operation = match &request.authorization {
            VerifiedReadOnlyAuthorization::Retrieve(_) => {
                ProviderSubchannelOperation::ArchiveRetrieve
            }
            VerifiedReadOnlyAuthorization::VerifyArchive(_) => {
                ProviderSubchannelOperation::ArchiveVerify
            }
        };
        let binding = request.provider_binding.clone();
        if binding.role != role
            || binding.provider_generation != self.generation
        {
            let error = V2RuntimeError::new(
                "provider_read_binding_mismatch",
                "read-only binding does not match the installed archive generation",
            );
            return match self.terminate_started_call(
                &binding,
                deadline,
                ProviderCleanupMode::Normal,
            ) {
                Ok(_) => Err(error.suppress_response()),
                Err(_) => Err(self.quarantine(
                    "provider_cleanup_unverified",
                    "mismatched archive process could not be fenced, killed, and reaped",
                )),
            };
        }
        let channel_result = self.lookup_active_channel(
            &binding.provider_operation_id,
            "read-only provider binding has no live channel",
        );
        let channel = match channel_result {
            Ok(channel) => channel,
            Err(error) => {
                return match self.terminate_started_call(
                    &binding,
                    deadline,
                    ProviderCleanupMode::Normal,
                ) {
                    Ok(_) => Err(error.suppress_response()),
                    Err(_) => Err(self.quarantine(
                        "provider_cleanup_unverified",
                        "archive channel lookup failed without verified process cleanup",
                    )),
                };
            }
        };
        let operation_matches = match channel.lock() {
            Ok(call) => call.operation == operation,
            Err(poisoned) => {
                self.ready.store(false, Ordering::Release);
                self.quarantined.store(true, Ordering::Release);
                let mut call = poisoned.into_inner();
                self.synchronously_reap_poisoned_call(&mut call);
                false
            }
        };
        if !operation_matches {
            let error = V2RuntimeError::new(
                "provider_read_operation_mismatch",
                "read-only channel is not bound to the requested archive operation",
            );
            return match self.terminate_started_call(
                &binding,
                deadline,
                ProviderCleanupMode::Normal,
            ) {
                Ok(_) => Err(error.suppress_response()),
                Err(_) => Err(self.quarantine(
                    "provider_cleanup_unverified",
                    "mismatched archive operation could not be fenced, killed, and reaped",
                )),
            };
        }
        if let Err(error) =
            self.send_read_only_request(&binding, &request)
        {
            return match self.terminate_started_call(
                &binding,
                deadline,
                ProviderCleanupMode::Normal,
            ) {
                Ok(_) => Err(error.suppress_response()),
                Err(_) => Err(self.quarantine(
                    "provider_cleanup_unverified",
                    "archive dispatch failed without verified fence revocation, kill, and bounded reap",
                )),
            };
        }
        Ok(RuntimeReadOnlyWatchdogJob {
            watchdog_job_lease:
                provider_operation_binding_sha256(&binding)
                    .into_bytes(),
            exclusive_deadline_at_epoch_ms:
                deadline.absolute_epoch_ms,
            binding,
            _seal: RuntimeReadOnlyWatchdogJobSeal,
        })
    }

    fn poll_read_only_operation_nonblocking(
        &self,
        job: &mut RuntimeReadOnlyWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<Option<RuntimeReadOnlyWatchdogTerminal>, V2RuntimeError> {
        let operation = {
            let channel = self.lookup_active_channel(
                &job.binding.provider_operation_id,
                "read-only provider channel is not live",
            )?;
            let operation = match channel.lock() {
                Ok(call) => call.operation,
                Err(poisoned) => {
                    self.ready.store(false, Ordering::Release);
                    self.quarantined.store(true, Ordering::Release);
                    let mut call = poisoned.into_inner();
                    self.synchronously_reap_poisoned_call(
                        &mut call,
                    );
                    return Err(self.quarantine(
                        "provider_channel_poisoned",
                        "read-only provider channel lock was poisoned and entered synchronous reaping",
                    ));
                }
            };
            operation
        };
        let Some(polled) =
            self.poll_started_call(
                &job.binding,
                operation,
                deadline,
            )?
        else {
            return Ok(None);
        };
        let (terminal, termination) = match polled {
            PolledStartedCall::Terminal {
                terminal,
                termination,
            } => (terminal, termination),
            PolledStartedCall::Ambiguous { .. } => {
                return Err(self.quarantine(
                    "provider_read_only_outcome_ambiguous",
                    "a started read-only provider failed after launch and cannot be represented as a denial",
                ));
            }
        };
        let response = base64::engine::general_purpose::STANDARD
            .decode(&terminal.envelope.canonical_payload_base64)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_terminal_payload_invalid",
                    "read-only terminal payload is not canonical base64",
                )
                .suppress_response()
            })?;
        Ok(Some(
            if terminal.envelope.status
                == ProviderRpcTerminalStatus::Committed
            {
                RuntimeReadOnlyWatchdogTerminal::Committed {
                    canonical_response: response,
                    exact_objects: terminal.output_files,
                    termination,
                }
            } else {
                RuntimeReadOnlyWatchdogTerminal::RejectedBeforeStart {
                    error: V2RuntimeError::new(
                        "provider_read_terminal_denied",
                        "read-only provider did not return a committed terminal",
                    )
                    .suppress_response(),
                    termination,
                }
            },
        ))
    }

    fn quarantine_terminate_read_only_and_verify_nonblocking(
        &self,
        job: &mut RuntimeReadOnlyWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError> {
        self.terminate_started_call(
            &job.binding,
            deadline,
            ProviderCleanupMode::Normal,
        )
    }

    fn emergency_quarantine_kill_reap_read_only_nonblocking(
        &self,
        job: &mut RuntimeReadOnlyWatchdogJob,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError> {
        self.terminate_started_call(
            &job.binding,
            deadline,
            ProviderCleanupMode::Emergency,
        )
    }

    fn quarantine_authority_call_and_verify_nonblocking(
        &self,
        binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError> {
        self.terminate_started_call(
            binding,
            deadline,
            ProviderCleanupMode::Normal,
        )
    }

    fn emergency_quarantine_authority_call_nonblocking(
        &self,
        binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderTermination, V2RuntimeError> {
        self.terminate_started_call(
            binding,
            deadline,
            ProviderCleanupMode::Emergency,
        )
    }

    fn verify_terminal_signature_and_freshness(
        &self,
        binding: &VerifiedProviderOperationBinding,
        termination: &VerifiedProviderTermination,
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        validate_provider_termination(
            binding,
            termination,
            deadline,
        )
    }

    fn verify_never_started_ed25519(
        &self,
        pin: &RoleIdentityPin,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool {
        if signer_key_id != pin.key_id {
            return false;
        }
        let Some(role) = self.roles.get(&pin.role) else {
            return false;
        };
        let Ok(signature) =
            base64::engine::general_purpose::STANDARD
                .decode(signature)
        else {
            return false;
        };
        ring::signature::UnparsedPublicKey::new(
            &ring::signature::ED25519,
            role.verification_key.as_ref(),
        )
        .verify(domain_separated_message, &signature)
        .is_ok()
    }
}

struct RuntimeProviderOperationLease<'a> {
    active: &'a Mutex<HashSet<String>>,
    provider_operation_id: String,
}

impl Drop for RuntimeProviderOperationLease<'_> {
    fn drop(&mut self) {
        if let Ok(mut active) = self.active.lock() {
            active.remove(&self.provider_operation_id);
        }
    }
}

impl RuntimeOwnedProviderLauncher {
    fn verify_construction(
        &self,
    ) -> Result<VerifiedProviderConstruction, V2RuntimeError> {
        let deadline = operation_deadline_from_now(
            RESPONSE_OBSERVATION_V2_MAX_OPERATION_MS,
            "provider_measurement_deadline_overflow",
        )?;
        Ok(VerifiedProviderConstruction {
            proof_independent_pins_root_sha256:
                proof_independent_pins_root(&self.config),
            role_identity_root_sha256:
                role_identity_root(&self.config),
            mutation: self.measure_identity(
                "mutation-supervisor",
                &deadline,
            )?,
            archive: self.measure_identity("archive-store", &deadline)?,
            live_verifier: self.measure_identity(
                "live-proof-verifier",
                &deadline,
            )?,
            archive_verifier: self.measure_identity(
                "archive-proof-verifier",
                &deadline,
            )?,
            public_release: self.measure_identity(
                "public-release",
                &deadline,
            )?,
            public_release_time: self.measure_identity(
                "trusted-time",
                &deadline,
            )?,
            public_release_revocation: self.measure_identity(
                "evidence-trust",
                &deadline,
            )?,
            public_release_consumption: self.measure_identity(
                "public-release-consumption",
                &deadline,
            )?,
            outcome_reconciliation: self.measure_identity(
                "outcome-reconciliation",
                &deadline,
            )?,
            recovery: self.measure_identity("recovery", &deadline)?,
            durable_replay: self.measure_identity(
                "linearizable-store",
                &deadline,
            )?,
            runtime_attestation: self.measure_identity(
                "runtime-attestation",
                &deadline,
            )?,
            _seal: VerifiedProviderConstructionSeal,
        })
    }

    fn measure_identity(
        &self,
        role: &'static str,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderIdentity, V2RuntimeError> {
        let pin = self
            .config
            .role_identities
            .iter()
            .find(|identity| identity.role == role)
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "provider_role_unconfigured",
                    "provider role is not root-pinned",
                )
            })?;
        let identity = self
            .installed
            .measured_provider_identity_from_preflight_nonblocking(
                role,
                pin,
                deadline,
            )?;
        if identity.role != role
            || !verified_identity_matches_pin(&self.config, &identity)
        {
            return Err(V2RuntimeError::new(
                "provider_measurement_identity_mismatch",
                "watchdog-measured provider identity does not match the root-owned role pin",
            ));
        }
        Ok(identity)
    }
}

impl RuntimeOwnedProviderSupervisor {
    fn acquire_non_reentrant(
        &self,
        provider_operation_id: &str,
    ) -> Result<RuntimeProviderOperationLease<'_>, V2RuntimeError> {
        validate_identifier(provider_operation_id)?;
        let mut active =
            self.active_provider_operations.lock().map_err(|_| {
                V2RuntimeError::new(
                    "runtime_state_unavailable",
                    "provider non-reentrancy state is unavailable",
                )
            })?;
        if active.len()
            >= self.launcher.config.max_concurrent_operations
            || !active.insert(provider_operation_id.to_owned())
        {
            return Err(V2RuntimeError::new(
                "provider_operation_in_progress",
                "provider operation is already active or capacity is exhausted",
            ));
        }
        drop(active);
        Ok(RuntimeProviderOperationLease {
            active: &self.active_provider_operations,
            provider_operation_id: provider_operation_id.to_owned(),
        })
    }

    fn quarantine_error(
        &self,
        code: &'static str,
        message: &'static str,
    ) -> V2RuntimeError {
        self.generation_ready.store(false, Ordering::Release);
        self.quarantined.store(true, Ordering::Release);
        V2RuntimeError::new(code, message).suppress_response()
    }

    fn quarantine(
        &self,
        code: &'static str,
        message: &'static str,
    ) -> SupervisedProviderRpcTerminal {
        SupervisedProviderRpcTerminal::HardUnready(
            self.quarantine_error(code, message),
        )
    }

    fn quarantine_failed_authority_call(
        &self,
        binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> V2RuntimeError {
        self.generation_ready.store(false, Ordering::Release);
        self.quarantined.store(true, Ordering::Release);
        let termination = self
            .launcher
            .installed
            .quarantine_authority_call_and_verify_nonblocking(
                binding,
                deadline,
            )
            .or_else(|_| {
                self.launcher
                    .installed
                    .emergency_quarantine_authority_call_nonblocking(
                        binding,
                        deadline,
                    )
            });
        match termination {
            Ok(termination)
                if validate_provider_termination(
                    binding,
                    &termination,
                    deadline,
                )
                .is_ok() =>
            {
                V2RuntimeError::new(
                    "authority_process_quarantined",
                    "failed authority process was namespace-quarantined, killed, and reaped; provider generation remains unready",
                )
                .suppress_response()
            }
            _ => V2RuntimeError::new(
                "authority_process_termination_unverified",
                "failed authority process could not be proven namespace-quarantined, killed, and reaped",
            )
            .suppress_response(),
        }
    }

    fn force_terminate(
        &self,
        mut job: RuntimeProviderWatchdogJob,
        operation_deadline: &OperationDeadline,
    ) -> SupervisedProviderRpcTerminal {
        let binding = job.binding.clone();
        let termination_deadline = operation_deadline.clone();
        let forced = match self
            .launcher
            .installed
            .quarantine_terminate_and_verify_nonblocking(
                &mut job,
                &termination_deadline,
            )
        {
            Ok(forced) => forced,
            Err(_) => {
                match self
                    .launcher
                    .installed
                    .emergency_quarantine_kill_reap_nonblocking(
                        &mut job,
                        &termination_deadline,
                    )
                {
                    Ok(forced) => forced,
                    Err(_) => {
                        return self.quarantine(
                            "provider_termination_unverified",
                            "normal and emergency namespace quarantine, cgroup/pidfd kill, and bounded reap could not be independently verified",
                        );
                    }
                }
            }
        };
        if forced.outcome_unknown.provider_operation_id
            != binding.provider_operation_id
            || forced
                .outcome_unknown
                .durable_start_receipt_sha256
                != binding.durable_start_receipt_sha256
            || !forced.termination.process_killed_if_required
            || validate_provider_termination(
            &binding,
            &forced.termination,
            &termination_deadline,
        )
        .and_then(|_| {
            self.launcher
                .installed
                .verify_terminal_signature_and_freshness(
                    &binding,
                    &forced.termination,
                    &termination_deadline,
                )
        })
        .is_err()
        {
            return self.quarantine(
                "provider_termination_unverified",
                "forced provider termination does not prove fence quiescence and exact-process kill/reap",
            );
        }
        SupervisedProviderRpcTerminal::OutcomeUnknown(
            forced.outcome_unknown,
        )
    }

    fn force_terminate_read_only(
        &self,
        mut job: RuntimeReadOnlyWatchdogJob,
        operation_deadline: &OperationDeadline,
    ) -> V2RuntimeError {
        let binding = job.binding.clone();
        let termination_deadline = operation_deadline.clone();
        let termination = match self
            .launcher
            .installed
            .quarantine_terminate_read_only_and_verify_nonblocking(
                &mut job,
                &termination_deadline,
            )
        {
            Ok(termination) => termination,
            Err(_) => {
                match self
                    .launcher
                    .installed
                    .emergency_quarantine_kill_reap_read_only_nonblocking(
                        &mut job,
                        &termination_deadline,
                    )
                {
                    Ok(termination) => termination,
                    Err(_) => {
                        return self.quarantine_error(
                            "provider_termination_unverified",
                            "normal and emergency read-only namespace quarantine, cgroup/pidfd kill, and bounded reap could not be independently verified",
                        );
                    }
                }
            }
        };
        if !termination.process_killed_if_required
            || validate_provider_termination(
            &binding,
            &termination,
            &termination_deadline,
        )
        .and_then(|_| {
            self.launcher
                .installed
                .verify_terminal_signature_and_freshness(
                    &binding,
                    &termination,
                    &termination_deadline,
                )
        })
        .is_err()
        {
            return self.quarantine_error(
                "provider_termination_unverified",
                "read-only provider termination does not prove exact-process kill and reap",
            );
        }
        self.quarantine_error(
            "provider_read_only_outcome_unavailable",
            "read-only provider was independently killed and reaped without a signed committed terminal; runtime is hard-unready",
        )
    }
}

impl KillableProviderProcessSupervisor for RuntimeOwnedProviderSupervisor {
    fn supervise_bounded_seqpacket_rpc(
        &self,
        request: SupervisedProviderRpcRequest<'_>,
        replay: &mut ReplayReservation,
    ) -> SupervisedProviderRpcTerminal {
        let deadline = request.deadline;
        if self.quarantined.load(Ordering::Acquire) {
            return SupervisedProviderRpcTerminal::HardUnready(
                V2RuntimeError::new(
                    "provider_runtime_quarantined",
                    "provider runtime remains hard-unready after an unverifiable credential-bearing process termination",
                )
                .suppress_response(),
            );
        }
        let _lease = match self
            .acquire_non_reentrant(request.provider_operation_id)
        {
            Ok(lease) => lease,
            Err(error) => {
                return SupervisedProviderRpcTerminal::RejectedBeforeStart(
                    error,
                );
            }
        };
        let provider_operation_id =
            request.provider_operation_id.to_owned();
        let expected_request_sha256 = request.request_sha256.to_owned();
        let expected_attempt_id = request.attempt_id.to_owned();
        let expected_fencing_token = request.fencing_token;
        let pin = match self
            .launcher
            .config
            .role_identities
            .iter()
            .find(|identity| identity.role == "mutation-supervisor")
        {
            Some(pin) => pin,
            None => {
                return self.quarantine(
                    "provider_role_unconfigured",
                    "mutation supervisor is not root-pinned",
                );
            }
        };
        if request.live_capability.mutation_provider_operation_id
            != provider_operation_id
            || request.live_capability.mutation_provider_generation
                != pin.provider_generation
            || request.live_capability.request_sha256
                != expected_request_sha256
            || request.live_capability.attempt_id
                != expected_attempt_id
            || request.live_capability.fencing_token
                != expected_fencing_token
            || request.live_capability.monotonic_deadline
                != deadline.monotonic
            || request.live_capability.deadline_at_epoch_ms
                != deadline.absolute_epoch_ms
            || request
                .live_capability
                .transition_authorization
                .as_ref()
                .is_none_or(|authorization| {
                    authorization.generation_id
                        != self
                            .launcher
                            .config
                            .custody_topology
                            .generation_id
                        || authorization.generation
                            != self
                                .launcher
                                .config
                                .custody_topology
                                .generation
                        || authorization.attempt_id
                            != expected_attempt_id
                        || authorization.fencing_token
                            != expected_fencing_token
                })
        {
            return SupervisedProviderRpcTerminal::RejectedBeforeStart(
                V2RuntimeError::new(
                    "live_capability_target_binding_mismatch",
                    "live capability is not bound to the exact target provider operation, request, attempt, fence, deadline, and generation",
                ),
            );
        }
        if validate_durable_replay_start_capability(
            &request.durable_replay_start,
            &self.launcher.config,
            &expected_request_sha256,
            request.operation,
            &expected_attempt_id,
            expected_fencing_token,
            deadline,
        )
        .is_err()
        {
            return SupervisedProviderRpcTerminal::RejectedBeforeStart(
                V2RuntimeError::new(
                    "durable_start_capability_invalid",
                    "watchdog start is not bound to the exact replay lease, request, attempt, operation, fence, and measured store",
                ),
            );
        }
        let start = match self
            .launcher
            .installed
            .start_operation_nonblocking(
                "mutation-supervisor",
                pin,
                request,
                deadline,
            )
        {
            Ok(start) => start,
            Err(_) => {
                return self.quarantine(
                    "provider_start_state_unverified",
                    "provider start authority failed without a signed never-started receipt",
                );
            }
        };
        let mut job = match start {
            RuntimeProviderStartDecision::NeverStarted(receipt) => {
                if validate_provider_never_started(
                    &receipt,
                    pin,
                    &provider_operation_id,
                    &expected_request_sha256,
                    &expected_attempt_id,
                    expected_fencing_token,
                    &self.launcher.config.proof_independent_pins,
                    deadline,
                )
                .is_err()
                {
                    return self.quarantine(
                        "provider_never_started_unverified",
                        "provider denial lacks proof that no process, fence, durable start, credential, or mutation ever existed",
                    );
                }
                let signature = receipt.signature.clone();
                let mut unsigned_receipt = receipt.clone();
                unsigned_receipt.signature.clear();
                let unsigned = match crate::canonical_json_bytes(
                    &unsigned_receipt,
                ) {
                    Ok(unsigned) => unsigned,
                    Err(_) => {
                        return self.quarantine(
                            "provider_never_started_unverified",
                            "never-started receipt cannot be canonicalized",
                        );
                    }
                };
                let mut message =
                    b"serverware.response-v2/provider-never-started/v1\0"
                        .to_vec();
                message.extend_from_slice(&unsigned);
                if signature.is_empty()
                    || signature.len() > 4096
                    || !self
                        .launcher
                        .installed
                        .verify_never_started_ed25519(
                            pin,
                            &receipt.signer_key_id,
                            &message,
                            &signature,
                        )
                {
                    return self.quarantine(
                        "provider_never_started_unverified",
                        "provider denial lacks a valid signed never-started receipt",
                    );
                }
                return SupervisedProviderRpcTerminal::RejectedBeforeStart(
                    V2RuntimeError::new(
                        "provider_rejected_before_start",
                        "measured provider returned a signed never-started receipt",
                    ),
                );
            }
            RuntimeProviderStartDecision::Started(job) => job,
        };
        replay.acknowledge_watchdog_start(
            &job.binding.durable_start_receipt_sha256,
        );
        if job.watchdog_job_lease.is_empty()
            || job.watchdog_job_lease.len() > 4096
            || job.exclusive_deadline_at_epoch_ms
                != deadline.absolute_epoch_ms
            || validate_provider_operation_binding(
            &job.binding,
            pin,
            &provider_operation_id,
            &expected_request_sha256,
            &expected_attempt_id,
            expected_fencing_token,
            deadline,
        )
        .is_err()
        {
            return self.force_terminate(job, deadline);
        }
        loop {
            if deadline.expired().unwrap_or(true) {
                return self.force_terminate(job, deadline);
            }
            let terminal = match self
                .launcher
                .installed
                .poll_operation_nonblocking(&mut job, deadline)
            {
                Ok(Some(terminal)) => terminal,
                Ok(None) => {
                    std::thread::park_timeout(
                        Duration::from_micros(250),
                    );
                    continue;
                }
                Err(_) => return self.force_terminate(job, deadline),
            };
            return match terminal {
                RuntimeProviderWatchdogTerminal::RejectedBeforeStart {
                    error: _,
                    termination: _,
                } => {
                    // A returned job has already produced a durable-start
                    // receipt. It can never be converted back into a denial,
                    // regardless of the provider's terminal label.
                    self.force_terminate(job, deadline)
                }
                RuntimeProviderWatchdogTerminal::Committed {
                    canonical_response,
                    exact_objects,
                    termination,
                } => {
                    if validate_provider_termination(
                        &job.binding,
                        &termination,
                        deadline,
                    )
                    .and_then(|_| {
                        self.launcher.installed
                            .verify_terminal_signature_and_freshness(
                                &job.binding,
                                &termination,
                                deadline,
                            )
                    })
                    .is_err()
                    {
                        self.quarantine(
                            "provider_commit_terminal_unverified",
                            "provider commit terminal does not prove fence completion and exact-process reap",
                        )
                    } else {
                        SupervisedProviderRpcTerminal::Committed {
                            canonical_response,
                            exact_objects,
                            started:
                                VerifiedStartedProviderCapability {
                                    binding: job.binding.clone(),
                                    termination,
                                    _seal:
                                        VerifiedStartedProviderCapabilitySeal,
                                },
                        }
                    }
                }
                RuntimeProviderWatchdogTerminal::OutcomeUnknown {
                    result,
                    termination,
                } => {
                    if result.provider_operation_id
                        != job.binding.provider_operation_id
                        || result.durable_start_receipt_sha256
                            != job
                                .binding
                                .durable_start_receipt_sha256
                        || validate_provider_termination(
                        &job.binding,
                        &termination,
                        deadline,
                    )
                    .and_then(|_| {
                        self.launcher.installed
                            .verify_terminal_signature_and_freshness(
                                &job.binding,
                                &termination,
                                deadline,
                            )
                    })
                    .is_err()
                    {
                        self.quarantine(
                            "provider_unknown_terminal_unverified",
                            "outcome-unknown terminal does not prove fence quiescence and exact-process kill/reap",
                        )
                    } else {
                        SupervisedProviderRpcTerminal::OutcomeUnknown(result)
                    }
                }
            };
        }
    }

}

impl RuntimeOwnedProviderSupervisor {
    fn supervise_bounded_read_only_rpc(
        &self,
        request: SupervisedReadOnlyRpcRequest<'_>,
        deadline: &OperationDeadline,
    ) -> Result<(Vec<u8>, Vec<File>), V2RuntimeError> {
        if self.quarantined.load(Ordering::Acquire) {
            return Err(V2RuntimeError::new(
                "provider_runtime_quarantined",
                "provider runtime remains hard-unready after an unverifiable credential-bearing process termination",
            )
            .suppress_response());
        }
        let provider_operation_id =
            request.provider_binding.provider_operation_id.clone();
        let expected_request_sha256 = request.request_sha256.to_owned();
        let expected_attempt_id =
            request.provider_binding.attempt_id.clone();
        let expected_fencing_token =
            request.provider_binding.fencing_token;
        let _lease = self
            .acquire_non_reentrant(&provider_operation_id)
            .map_err(V2RuntimeError::suppress_response)?;
        let pin = self
            .launcher
            .config
            .role_identities
            .iter()
            .find(|identity| identity.role == "archive-store")
            .ok_or_else(|| {
                self.quarantine_error(
                    "provider_role_unconfigured",
                    "archive store is not root-pinned",
                )
            })?;
        if validate_provider_operation_binding(
            &request.provider_binding,
            pin,
            &provider_operation_id,
            &expected_request_sha256,
            &expected_attempt_id,
            expected_fencing_token,
            deadline,
        )
        .is_err()
        {
            return match self
                .launcher
                .installed
                .terminate_started_call(
                    &request.provider_binding,
                    deadline,
                    ProviderCleanupMode::Normal,
                )
            {
                Ok(_) => Err(V2RuntimeError::new(
                    "provider_read_binding_mismatch",
                    "archive binding failed exact measured-process validation",
                )
                .suppress_response()),
                Err(_) => Err(self.quarantine_error(
                    "provider_cleanup_unverified",
                    "invalid archive binding could not be fenced, killed, and reaped",
                )),
            };
        }
        let mut job = self
            .launcher
            .installed
            .start_read_only_operation_nonblocking(
                "archive-store",
                pin,
                request,
                deadline,
            )
            .map_err(V2RuntimeError::suppress_response)?;
        if job.watchdog_job_lease.is_empty()
            || job.watchdog_job_lease.len() > 4096
            || job.exclusive_deadline_at_epoch_ms
                != deadline.absolute_epoch_ms
            || validate_provider_operation_binding(
                &job.binding,
                pin,
                &provider_operation_id,
                &expected_request_sha256,
                &expected_attempt_id,
                expected_fencing_token,
                deadline,
            )
            .is_err()
        {
            return Err(self.force_terminate_read_only(
                job, deadline,
            ));
        }
        loop {
            if deadline.expired().unwrap_or(true) {
                return Err(self.force_terminate_read_only(
                    job, deadline,
                ));
            }
            let terminal = match self
                .launcher
                .installed
                .poll_read_only_operation_nonblocking(&mut job, deadline)
            {
                Ok(Some(terminal)) => terminal,
                Ok(None) => {
                    std::thread::park_timeout(
                        Duration::from_micros(250),
                    );
                    continue;
                }
                Err(_) => {
                    return Err(self.force_terminate_read_only(
                        job, deadline,
                    ));
                }
            };
            return match terminal {
                RuntimeReadOnlyWatchdogTerminal::RejectedBeforeStart {
                    error,
                    termination,
                } => {
                    validate_provider_termination(
                        &job.binding,
                        &termination,
                        deadline,
                    )
                    .and_then(|_| {
                        self.launcher.installed
                            .verify_terminal_signature_and_freshness(
                                &job.binding,
                                &termination,
                                deadline,
                            )
                    })
                    .map_err(|_| {
                        self.quarantine_error(
                            "provider_termination_unverified",
                            "rejected read-only provider job lacks signed exact-process kill/reap evidence",
                        )
                    })?;
                    Err(error.suppress_response())
                }
                RuntimeReadOnlyWatchdogTerminal::Committed {
                    canonical_response,
                    exact_objects,
                    termination,
                } => {
                    validate_provider_termination(
                        &job.binding,
                        &termination,
                        deadline,
                    )
                    .and_then(|_| {
                        self.launcher.installed
                            .verify_terminal_signature_and_freshness(
                                &job.binding,
                                &termination,
                                deadline,
                            )
                    })
                    .map_err(|_| {
                        self.quarantine_error(
                            "provider_commit_terminal_unverified",
                            "read-only commit terminal does not prove exact-process reap",
                        )
                    })?;
                    Ok((canonical_response, exact_objects))
                }
            };
        }
    }
}

fn validate_provider_operation_binding(
    binding: &VerifiedProviderOperationBinding,
    pin: &RoleIdentityPin,
    provider_operation_id: &str,
    request_sha256: &str,
    attempt_id: &str,
    fencing_token: u64,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&binding.provider_operation_id)?;
    validate_digest(&binding.request_sha256)?;
    validate_identifier(&binding.attempt_id)?;
    validate_identifier(&binding.launch_nonce)?;
    validate_digest(&binding.predecessor_state_sha256)?;
    validate_digest(&binding.durable_start_receipt_sha256)?;
    validate_digest(&binding.mutation_fence_permit_sha256)?;
    validate_digest(&binding.kernel_process_identity_sha256)?;
    validate_digest(&binding.socket_peer_identity_sha256)?;
    validate_digest(&binding.executable_measurement_sha256)?;
    validate_digest(&binding.provider_config_sha256)?;
    validate_digest(&binding.key_material_sha256)?;
    validate_digest(&binding.tee_measurement_sha256)?;
    validate_digest(&binding.launch_attestation_sha256)?;
    if binding.provider_generation == 0
        || binding.provider_generation > MAX_SAFE_INTEGER
        || binding.attempt_revision > MAX_SAFE_INTEGER
        || binding.role != pin.role
        || binding.provider_id != pin.provider_id
        || binding.provider_generation != pin.provider_generation
        || binding.provider_operation_id != provider_operation_id
        || binding.request_sha256 != request_sha256
        || binding.attempt_id != attempt_id
        || binding.fencing_token != fencing_token
        || binding.monotonic_deadline != deadline.monotonic
        || binding.deadline_at_epoch_ms != deadline.absolute_epoch_ms
        || binding.executable_measurement_sha256
            != pin.executable_measurement_sha256
        || binding.provider_config_sha256 != pin.provider_config_sha256
        || binding.key_material_sha256 != pin.key_material_sha256
        || binding.tee_measurement_sha256 != pin.tee_measurement_sha256
        || binding.issued_at_epoch_ms == 0
        || binding.expires_at_epoch_ms <= binding.issued_at_epoch_ms
        || binding.expires_at_epoch_ms < deadline.absolute_epoch_ms
    {
        return Err(V2RuntimeError::new(
            "provider_operation_binding_mismatch",
            "watchdog job is not bound to the exact role, operation, request, fence, measured process, peer socket, and fresh launch attestation",
        ));
    }
    Ok(())
}

fn validate_provider_never_started(
    receipt: &VerifiedProviderNeverStarted,
    pin: &RoleIdentityPin,
    provider_operation_id: &str,
    request_sha256: &str,
    attempt_id: &str,
    fencing_token: u64,
    pins: &ProofIndependentPins,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&receipt.provider_operation_id)?;
    validate_digest(&receipt.request_sha256)?;
    validate_identifier(&receipt.attempt_id)?;
    validate_digest(&receipt.authority_receipt_sha256)?;
    validate_digest(&receipt.trust_checkpoint_sha256)?;
    validate_identifier(&receipt.signer_provider_id)?;
    validate_digest(&receipt.signer_key_id)?;
    validate_digest(&receipt.signer_key_material_sha256)?;
    if receipt.provider_operation_id != provider_operation_id
        || receipt.request_sha256 != request_sha256
        || receipt.attempt_id != attempt_id
        || receipt.fencing_token != fencing_token
        || receipt.provider_generation != pin.provider_generation
        || !receipt.durable_start_absent
        || !receipt.fence_not_acquired
        || !receipt.process_never_launched
        || !receipt.credential_never_released
        || receipt.trust_checkpoint_sha256
            != pins.trust_checkpoint_sha256
        || receipt.revocation_epoch != pins.revocation_epoch
        || receipt.signer_provider_id != pin.provider_id
        || receipt.signer_key_id != pin.key_id
        || receipt.signer_key_material_sha256
            != pin.key_material_sha256
        || receipt.signature.is_empty()
        || receipt.signature.len() > 4096
        || receipt.verified_at_epoch_ms == 0
        || receipt.verified_at_epoch_ms
            > deadline.absolute_epoch_ms
    {
        return Err(V2RuntimeError::new(
            "provider_never_started_receipt_mismatch",
            "never-started receipt is not bound to the exact operation, request, attempt, fence, generation, and absence of all mutation-enabling effects",
        ));
    }
    Ok(())
}

fn validate_durable_replay_start_capability(
    capability: &DurableReplayStartCapability,
    config: &RootOwnedResponseObservationV2Config,
    request_sha256: &str,
    operation: &str,
    attempt_id: &str,
    fencing_token: u64,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    let pin = config
        .role_identities
        .iter()
        .find(|pin| pin.role == "linearizable-store")
        .ok_or_else(|| {
            V2RuntimeError::new(
                "durable_start_authority_unconfigured",
                "linearizable store is not root-pinned",
            )
        })?;
    let role_operation = format!(
        "{operation}:linearizable-store:{:?}",
        ProviderSubchannelOperation::ReplayClaim
    );
    let provider_operation_id = provider_operation_id(
        request_sha256,
        &role_operation,
        attempt_id,
        fencing_token,
        pin,
    );
    validate_provider_operation_binding(
        &capability.adapter_binding,
        pin,
        &provider_operation_id,
        request_sha256,
        attempt_id,
        fencing_token,
        deadline,
    )?;
    if capability.authority_lease.is_empty()
        || capability.authority_lease.len() > 4096
        || capability.authority_revision == 0
        || capability.authority_revision > MAX_SAFE_INTEGER
        || capability.key.request_sha256 != request_sha256
        || capability.key.stable.operation != operation
        || capability.key.stable.attempt_id != attempt_id
        || capability.key.stable.fencing_token != fencing_token
    {
        return Err(V2RuntimeError::new(
            "durable_start_capability_mismatch",
            "durable start capability does not match the reserved stable request and store lease",
        ));
    }
    Ok(())
}

fn validate_provider_termination(
    binding: &VerifiedProviderOperationBinding,
    termination: &VerifiedProviderTermination,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    validate_digest(&termination.kernel_process_identity_sha256)?;
    validate_digest(&termination.durable_fence_receipt_sha256)?;
    validate_digest(
        &termination.namespace_quarantine_receipt_sha256,
    )?;
    validate_digest(&termination.cgroup_kill_receipt_sha256)?;
    validate_digest(&termination.pidfd_kill_receipt_sha256)?;
    validate_digest(
        &termination.process_group_kill_receipt_sha256,
    )?;
    validate_digest(&termination.process_reap_receipt_sha256)?;
    validate_digest(&termination.verification_receipt_sha256)?;
    if termination.provider_operation_id
        != binding.provider_operation_id
        || termination.kernel_process_identity_sha256
            != binding.kernel_process_identity_sha256
        || termination.provider_generation
            != binding.provider_generation
        || !termination.namespace_quarantined
        || !termination.fence_revocation_attempted
        || !termination.fence_quiescent
        || !termination.process_killed_if_required
        || !termination.process_reaped
        || termination.independently_verified_at_epoch_ms == 0
        || termination.independently_verified_at_epoch_ms
            < binding.issued_at_epoch_ms
        || termination.independently_verified_at_epoch_ms
            > deadline.absolute_epoch_ms
    {
        return Err(V2RuntimeError::new(
            "provider_termination_binding_mismatch",
            "termination does not prove the exact measured process is fence-quiescent, dead, and reaped",
        ));
    }
    Ok(())
}

pub(crate) struct SupervisedReadOnlyRpcRequest<'a> {
    provider_binding: VerifiedProviderOperationBinding,
    pub operation: &'static str,
    pub request_sha256: &'a str,
    pub deadline_at_epoch_ms: u64,
    pub canonical_control: &'a [u8],
    pub exact_objects: &'a ValidatedExactObjects,
    pub authorization: VerifiedReadOnlyAuthorization,
}

pub(crate) enum VerifiedReadOnlyAuthorization {
    Retrieve(VerifiedPublicReleaseCapability),
    VerifyArchive(VerifiedArchiveProof),
}

pub(crate) trait ResponseObservationV2ArchiveProvider: Send + Sync {
    fn retrieve(
        &self,
        context: &OperationContext<'_>,
        params: V2RetrieveParams,
        objects: &ValidatedExactObjects,
        capability: VerifiedPublicReleaseCapability,
    ) -> Result<ProviderResult<V2RetrieveResult>, V2RuntimeError>;

    fn verify_archive(
        &self,
        context: &OperationContext<'_>,
        params: V2ArchiveVerifyParams,
        objects: &ValidatedExactObjects,
        capability: VerifiedArchiveProof,
    ) -> Result<ProviderResult<V2ArchiveVerifyResult>, V2RuntimeError>;
}

pub(crate) struct ConfiguredProviderAggregate {
    installed: Arc<InstalledProviderGeneration>,
    live_verifiers: VerifiedContractVerifierAdapter,
    archive_verifiers: VerifiedContractVerifierAdapter,
    supervisor: Arc<RuntimeOwnedProviderSupervisor>,
    proof_independent_pins: ProofIndependentPins,
    verified_construction: VerifiedProviderConstruction,
}

pub(crate) struct BoundLiveProofVerifier<'a> {
    providers: &'a ConfiguredProviderAggregate,
    adapter_binding: VerifiedProviderOperationBinding,
    _seal: BoundLiveProofVerifierSeal,
}

struct BoundLiveProofVerifierSeal;

impl BoundLiveProofVerifier<'_> {
    pub(crate) fn verify(
        self,
        proof: super::CanonicalResponseObservationProofV2,
        context: &super::VerificationContext<'_>,
        request_sha256: &str,
        binding: &V2OperationBinding,
        client_identity: &AuthenticatedClientIdentity,
        target_provider_operation_id: &str,
    ) -> Result<OpaqueLiveOperationCapability, V2RuntimeError> {
        if self.adapter_binding.role != "live-proof-verifier"
            || self.adapter_binding.request_sha256 != request_sha256
        {
            return Err(V2RuntimeError::new(
                "live_verifier_binding_mismatch",
                "live verifier capability is not bound to the exact measured verifier operation",
            ));
        }
        let adapter_binding = self.adapter_binding;
        self.providers.verify_live_proof(
            proof,
            context,
            request_sha256,
            binding,
            client_identity,
            &adapter_binding,
            target_provider_operation_id,
        )
    }
}

pub(crate) struct BoundArchiveProofVerifier<'a> {
    providers: &'a ConfiguredProviderAggregate,
    adapter_binding: VerifiedProviderOperationBinding,
    _seal: BoundArchiveProofVerifierSeal,
}

struct BoundArchiveProofVerifierSeal;

impl BoundArchiveProofVerifier<'_> {
    pub(crate) fn verify(
        self,
        proof: super::CanonicalResponseObservationProofV2,
        context: &super::VerificationContext<'_>,
        request_sha256: &str,
        binding: &V2ReadBinding,
        client_identity: &AuthenticatedClientIdentity,
        archive_store_binding: &VerifiedProviderOperationBinding,
    ) -> Result<VerifiedArchiveProof, V2RuntimeError> {
        if self.adapter_binding.role != "archive-proof-verifier"
            || self.adapter_binding.request_sha256 != request_sha256
        {
            return Err(V2RuntimeError::new(
                "archive_verifier_binding_mismatch",
                "archive verifier capability is not bound to the exact measured verifier operation",
            ));
        }
        let adapter_binding = self.adapter_binding;
        self.providers.verify_archive_proof(
            proof,
            context,
            request_sha256,
            binding,
            client_identity,
            &adapter_binding,
            archive_store_binding,
        )
    }
}

