pub(crate) trait DurableOutcomeUnknownVerifier: Send + Sync {
    fn durable_start_receipt_exists(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        provider_operation_id: &str,
        receipt_sha256: &str,
        binding: &DurableStartReceiptBinding<'_>,
        deadline: &OperationDeadline,
    ) -> Result<bool, V2RuntimeError>;

    fn reconciliation_record_is_durable(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        reference: &EvidenceReference,
        deadline: &OperationDeadline,
    ) -> Result<bool, V2RuntimeError>;

    fn verify_outcome_unknown_ed25519(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool;
}

