fn validate_public_attestation_signer_key(
    key: &V2AttestationSignerKeyV1,
    expected_key_sha256: &str,
    expected_inline_key: &[u8],
) -> Result<(), V2RuntimeError> {
    match key {
        V2AttestationSignerKeyV1::InlineEd25519PublicKey {
            public_key_base64,
            public_key_sha256,
        } => {
            let bytes = base64::engine::general_purpose::STANDARD
                .decode(public_key_base64)
                .map_err(|_| {
                    V2RuntimeError::new(
                        "fresh_attestation_signer_key_invalid",
                        "inline response signer key is not canonical base64",
                    )
                })?;
            if bytes.len() != 32
                || bytes != expected_inline_key
                || base64::engine::general_purpose::STANDARD
                    .encode(&bytes)
                    != *public_key_base64
                || format!(
                    "sha256:{:x}",
                    Sha256::digest(&bytes)
                ) != *public_key_sha256
                || public_key_sha256 != expected_key_sha256
            {
                return Err(V2RuntimeError::new(
                    "fresh_attestation_signer_key_mismatch",
                    "inline response signer key does not match the exact measured Ed25519 authority key",
                ));
            }
        }
        V2AttestationSignerKeyV1::ImmutableKeyReference {
            retrieval_id,
            public_key_sha256,
            persistence_receipt_sha256,
        } => {
            validate_identifier(retrieval_id)?;
            validate_digest(public_key_sha256)?;
            validate_digest(persistence_receipt_sha256)?;
            if public_key_sha256 != expected_key_sha256 {
                return Err(V2RuntimeError::new(
                    "fresh_attestation_signer_key_mismatch",
                    "immutable response signer key reference does not match the measured authority key",
                ));
            }
        }
    }
    Ok(())
}

fn validate_attestation_trust_artifact(
    artifact: &V2AttestationTrustArtifactV1,
) -> Result<String, V2RuntimeError> {
    match artifact {
        V2AttestationTrustArtifactV1::InlineDerBundle {
            der_bundle_base64,
            der_bundle_sha256,
        } => {
            let bytes = base64::engine::general_purpose::STANDARD
                .decode(der_bundle_base64)
                .map_err(|_| {
                    V2RuntimeError::new(
                        "fresh_attestation_trust_artifact_invalid",
                        "inline trust artifact is not canonical base64",
                    )
                })?;
            if bytes.is_empty()
                || bytes.len()
                    > RESPONSE_OBSERVATION_V2_MAX_ATTESTATION_EVIDENCE_BYTES
                || base64::engine::general_purpose::STANDARD
                    .encode(&bytes)
                    != *der_bundle_base64
                || format!(
                    "sha256:{:x}",
                    Sha256::digest(&bytes)
                ) != *der_bundle_sha256
            {
                return Err(V2RuntimeError::new(
                    "fresh_attestation_trust_artifact_mismatch",
                    "inline trust artifact is empty, overbound, non-canonical, or digest-mismatched",
                ));
            }
            Ok(der_bundle_sha256.clone())
        }
        V2AttestationTrustArtifactV1::ImmutableTrustReference {
            retrieval_id,
            artifact_sha256,
            persistence_receipt_sha256,
        } => {
            validate_identifier(retrieval_id)?;
            validate_digest(artifact_sha256)?;
            validate_digest(persistence_receipt_sha256)?;
            Ok(artifact_sha256.clone())
        }
    }
}

fn fresh_tee_report_data_sha256(
    unsigned_response_sha256: &str,
    output_manifest_sha256: &str,
    authenticated_session_sha256: &str,
    challenge_nonce: &str,
    signer_key_sha256: &str,
    custody_measurement_sha256: &str,
    provider_generation: u64,
) -> String {
    let mut hasher = Sha256::new();
    append_hash_frame(
        &mut hasher,
        b"serverware.response-v2/fresh-tee-report-data/v1",
    );
    for value in [
        unsigned_response_sha256,
        output_manifest_sha256,
        authenticated_session_sha256,
        challenge_nonce,
        signer_key_sha256,
        custody_measurement_sha256,
    ] {
        append_hash_frame(&mut hasher, value.as_bytes());
    }
    append_hash_frame(
        &mut hasher,
        &provider_generation.to_be_bytes(),
    );
    format!("sha256:{:x}", hasher.finalize())
}

impl ConfiguredProviderAggregate {
    fn from_installed_generation(
        config: &RootOwnedResponseObservationV2Config,
        supervisor: Arc<RuntimeOwnedProviderSupervisor>,
    ) -> Result<Self, V2RuntimeError> {
        let verified_construction =
            supervisor.launcher.verify_construction()?;
        validate_verified_provider_construction(
            config,
            &verified_construction,
        )?;
        let installed = Arc::clone(
            &supervisor.launcher.installed,
        );
        if !installed.provider_ready()
            || installed.generation
                != verified_construction.mutation.provider_generation
        {
            return Err(V2RuntimeError::new(
                "provider_generation_not_ready",
                "the concrete measured provider generation did not complete every role preflight",
            ));
        }
        let live_verifiers = VerifiedContractVerifierAdapter {
            measured_identity: RuntimeMeasuredIdentityBinding {
                identity_sha256: provider_identity_digest(
                    &verified_construction.live_verifier,
                ),
                _seal: RuntimeMeasuredIdentityBindingSeal,
            },
            installed: Arc::clone(&installed),
            role: "live-proof-verifier",
            request_binding: None,
            _seal: VerifiedContractVerifierAdapterSeal,
        };
        let archive_verifiers = VerifiedContractVerifierAdapter {
            measured_identity: RuntimeMeasuredIdentityBinding {
                identity_sha256: provider_identity_digest(
                    &verified_construction.archive_verifier,
                ),
                _seal: RuntimeMeasuredIdentityBindingSeal,
            },
            installed: Arc::clone(&installed),
            role: "archive-proof-verifier",
            request_binding: None,
            _seal: VerifiedContractVerifierAdapterSeal,
        };
        if live_verifiers.measured_identity.identity_sha256
            != provider_identity_digest(
                &verified_construction.live_verifier,
            )
            || archive_verifiers.measured_identity.identity_sha256
                != provider_identity_digest(
                    &verified_construction.archive_verifier,
                )
            || live_verifiers.measured_identity.identity_sha256
                == archive_verifiers
                    .measured_identity
                    .identity_sha256
        {
            return Err(V2RuntimeError::new(
                "contract_verifier_identity_mismatch",
                "live and archive contract verifier adapters must match distinct root-pinned identities",
            ));
        }
        supervisor
            .generation_ready
            .store(true, Ordering::Release);
        Ok(Self {
            installed,
            live_verifiers,
            archive_verifiers,
            supervisor,
            proof_independent_pins: config.proof_independent_pins.clone(),
            verified_construction,
        })
    }

    fn bind_authority_call(
        &self,
        role: &'static str,
        subchannel: ProviderSubchannelOperation,
        request_sha256: &str,
        operation: &str,
        attempt_id: &str,
        fencing_token: u64,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedProviderOperationBinding, V2RuntimeError> {
        let pin = self
            .supervisor
            .launcher
            .config
            .role_identities
            .iter()
            .find(|pin| pin.role == role)
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "authority_adapter_role_unconfigured",
                    "authority adapter role is not root-pinned",
                )
            })?;
        let role_operation =
            format!("{operation}:{role}:{subchannel:?}");
        let provider_operation_id = provider_operation_id(
            request_sha256,
            &role_operation,
            attempt_id,
            fencing_token,
            pin,
        );
        let binding = self
            .supervisor
            .launcher
            .installed
            .bind_authority_call_nonblocking(
                role,
                subchannel,
                pin,
                &provider_operation_id,
                request_sha256,
                attempt_id,
                fencing_token,
                deadline,
            )?;
        if let Err(error) = validate_provider_operation_binding(
            &binding,
            pin,
            &provider_operation_id,
            request_sha256,
            attempt_id,
            fencing_token,
            deadline,
        ) {
            return match self
                .supervisor
                .launcher
                .installed
                .terminate_started_call(
                    &binding,
                    deadline,
                    ProviderCleanupMode::Normal,
                )
            {
                Ok(_) => Err(error.suppress_response()),
                Err(_) => Err(self.installed.quarantine(
                    "provider_cleanup_unverified",
                    "invalid authority binding could not be fenced, killed, and reaped",
                )),
            };
        }
        Ok(binding)
    }

    fn verify_same_boot_replay_record(
        &self,
        record: &DurableTerminalRecord,
        replay_binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        let receipt = &record.signed_authority_receipt;
        let signer = &self.verified_construction.durable_replay;
        let time_binding = self.bind_authority_call(
            "trusted-time",
            ProviderSubchannelOperation::TrustedTime,
            &record.key.request_sha256,
            &record.key.stable.operation,
            &record.key.stable.attempt_id,
            record.key.stable.fencing_token,
            deadline,
        )?;
        let trusted_now = self
            .installed
            .trusted_now_epoch_ms(&time_binding, deadline)?;
        validate_signed_replay_record_receipt(
            receipt,
            record,
            replay_binding,
            &self.proof_independent_pins,
            signer,
            trusted_now,
        )?;
        let revocation_binding = self.bind_authority_call(
            "evidence-trust",
            ProviderSubchannelOperation::Revocation,
            &record.key.request_sha256,
            &record.key.stable.operation,
            &record.key.stable.attempt_id,
            record.key.stable.fencing_token,
            deadline,
        )?;
        let revoked = match self
            .installed
            .authorization_is_revoked(
                &revocation_binding,
                &receipt.authority_receipt_sha256,
                receipt.revocation_epoch,
                deadline,
            ) {
            Ok(revoked) => revoked,
            Err(_) => {
                return Err(self
                    .supervisor
                    .quarantine_failed_authority_call(
                        &revocation_binding,
                        deadline,
                    ));
            }
        };
        if revoked {
            return Err(V2RuntimeError::new(
                "durable_replay_authority_revoked",
                "same-boot replay authority receipt is currently revoked",
            ));
        }
        let mut unsigned = receipt.clone();
        let signature = receipt.signature.clone();
        unsigned.signature.clear();
        let canonical =
            crate::canonical_json_bytes(&unsigned).map_err(|_| {
                V2RuntimeError::new(
                    "durable_replay_authority_invalid",
                    "same-boot replay authority receipt cannot be canonicalized",
                )
            })?;
        let mut message =
            b"serverware.response-v2/replay-authority-receipt/v1\0"
                .to_vec();
        message.extend_from_slice(&canonical);
        if signature.is_empty()
            || signature.len() > 4096
            || !self.installed.verify_replay_record_ed25519(
                replay_binding,
                &receipt.signer_key_id,
                &message,
                &signature,
            )
        {
            return Err(V2RuntimeError::new(
                "durable_replay_authority_signature_invalid",
                "same-boot replay authority receipt signature is invalid",
            ));
        }
        Ok(())
    }

    fn verify_same_boot_replay_retrieval(
        &self,
        record: &DurableTerminalRecord,
        rehydrated: &RehydratedDurableTerminal,
        replay_binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        let receipt = &rehydrated.signed_retrieval_receipt;
        let signer = &self.verified_construction.durable_replay;
        let time_binding = self.bind_authority_call(
            "trusted-time",
            ProviderSubchannelOperation::TrustedTime,
            &record.key.request_sha256,
            &record.key.stable.operation,
            &record.key.stable.attempt_id,
            record.key.stable.fencing_token,
            deadline,
        )?;
        let trusted_now = self
            .installed
            .trusted_now_epoch_ms(&time_binding, deadline)?;
        validate_signed_replay_retrieval_receipt(
            receipt,
            record,
            rehydrated,
            replay_binding,
            &self.proof_independent_pins,
            signer,
            trusted_now,
        )?;
        let revocation_binding = self.bind_authority_call(
            "evidence-trust",
            ProviderSubchannelOperation::Revocation,
            &record.key.request_sha256,
            &record.key.stable.operation,
            &record.key.stable.attempt_id,
            record.key.stable.fencing_token,
            deadline,
        )?;
        let revoked = match self
            .installed
            .authorization_is_revoked(
                &revocation_binding,
                &receipt.retrieval_receipt_sha256,
                receipt.revocation_epoch,
                deadline,
            ) {
            Ok(revoked) => revoked,
            Err(_) => {
                return Err(self
                    .supervisor
                    .quarantine_failed_authority_call(
                        &revocation_binding,
                        deadline,
                    ));
            }
        };
        if revoked {
            return Err(V2RuntimeError::new(
                "durable_replay_retrieval_revoked",
                "same-boot replay retrieval receipt is currently revoked",
            ));
        }
        let mut unsigned = receipt.clone();
        let signature = receipt.signature.clone();
        unsigned.signature.clear();
        let canonical =
            crate::canonical_json_bytes(&unsigned).map_err(|_| {
                V2RuntimeError::new(
                    "durable_replay_retrieval_invalid",
                    "same-boot replay retrieval receipt cannot be canonicalized",
                )
            })?;
        let mut message =
            b"serverware.response-v2/replay-retrieval-receipt/v1\0"
                .to_vec();
        message.extend_from_slice(&canonical);
        if signature.is_empty()
            || signature.len() > 4096
            || !self.installed.verify_replay_record_ed25519(
                replay_binding,
                &receipt.signer_key_id,
                &message,
                &signature,
            )
        {
            return Err(V2RuntimeError::new(
                "durable_replay_retrieval_signature_invalid",
                "same-boot replay retrieval receipt signature is invalid",
            ));
        }
        Ok(())
    }

    pub(crate) fn verify_live_proof(
        &self,
        proof: super::CanonicalResponseObservationProofV2,
        context: &super::VerificationContext<'_>,
        request_sha256: &str,
        binding: &V2OperationBinding,
        client_identity: &AuthenticatedClientIdentity,
        verifier_binding: &VerifiedProviderOperationBinding,
        target_provider_operation_id: &str,
    ) -> Result<OpaqueLiveOperationCapability, V2RuntimeError> {
        if context.purpose() != super::VerificationPurpose::LiveAuthorization {
            return Err(V2RuntimeError::new(
                "live_context_required",
                "live proof verification requires a live authorization context",
            ));
        }
        if context.current_trust_checkpoint_sha256()
            != self
                .proof_independent_pins
                .trust_checkpoint_sha256
            || context.current_revocation_epoch()
                != self.proof_independent_pins.revocation_epoch
        {
            return Err(V2RuntimeError::new(
                "live_context_pin_mismatch",
                "live verification context does not match proof-independent trust and revocation pins",
            ));
        }
        let verifier_adapter = VerifiedContractVerifierAdapter {
            measured_identity: RuntimeMeasuredIdentityBinding {
                identity_sha256: provider_identity_digest(
                    &self.verified_construction.live_verifier,
                ),
                _seal: RuntimeMeasuredIdentityBindingSeal,
            },
            installed: Arc::clone(&self.installed),
            role: "live-proof-verifier",
            request_binding: Some(verifier_binding.clone()),
            _seal: VerifiedContractVerifierAdapterSeal,
        };
        let verified = super::validate_and_verify(
            proof,
            context,
            &verifier_adapter,
            &verifier_adapter,
            &verifier_adapter,
        )
        .map_err(contract_error)?;
        if verified.live_authorization().is_none() {
            return Err(V2RuntimeError::new(
                "live_capability_missing",
                "verified proof did not produce the private live capability",
            ));
        }
        validate_digest(request_sha256)?;
        validate_operation_capability_binding(
            binding,
            client_identity.identity_sha256(),
        )?;
        Ok(OpaqueLiveOperationCapability {
            verified: Some(verified),
            request_sha256: request_sha256.to_owned(),
            client_identity_sha256: client_identity
                .identity_sha256()
                .to_owned(),
            attempt_id: binding.attempt_id.clone(),
            predecessor_lifecycle_state:
                binding.predecessor_lifecycle_state,
            predecessor_state_sha256:
                binding.predecessor_state_sha256.clone(),
            attempt_revision: binding.attempt_revision,
            fencing_token: binding.fencing_token,
            monotonic_deadline:
                binding.monotonic_deadline.clone(),
            deadline_at_epoch_ms: binding.deadline_at_epoch_ms,
            mutation_provider_identity_sha256:
                provider_identity_digest(
                    &self.verified_construction.mutation,
                ),
            verifier_operation_binding_sha256:
                provider_operation_binding_sha256(
                    verifier_binding,
                ),
            verifier_provider_generation:
                verifier_binding.provider_generation,
            mutation_provider_generation:
                self.verified_construction
                    .mutation
                    .provider_generation,
            mutation_provider_operation_id:
                target_provider_operation_id.to_owned(),
            transition_authorization: None,
        })
    }

    pub(crate) fn verify_archive_proof(
        &self,
        proof: super::CanonicalResponseObservationProofV2,
        context: &super::VerificationContext<'_>,
        request_sha256: &str,
        binding: &V2ReadBinding,
        client_identity: &AuthenticatedClientIdentity,
        verifier_binding: &VerifiedProviderOperationBinding,
        archive_store_binding: &VerifiedProviderOperationBinding,
    ) -> Result<VerifiedArchiveProof, V2RuntimeError> {
        if context.purpose()
            != super::VerificationPurpose::ArchivalVerification
        {
            return Err(V2RuntimeError::new(
                "archive_context_required",
                "archive proof verification requires an archival context",
            ));
        }
        let verifier_adapter = VerifiedContractVerifierAdapter {
            measured_identity: RuntimeMeasuredIdentityBinding {
                identity_sha256: provider_identity_digest(
                    &self.verified_construction.archive_verifier,
                ),
                _seal: RuntimeMeasuredIdentityBindingSeal,
            },
            installed: Arc::clone(&self.installed),
            role: "archive-proof-verifier",
            request_binding: Some(verifier_binding.clone()),
            _seal: VerifiedContractVerifierAdapterSeal,
        };
        let verified = super::validate_and_verify(
            proof,
            context,
            &verifier_adapter,
            &verifier_adapter,
            &verifier_adapter,
        )
        .map_err(contract_error)?;
        if verified.live_authorization().is_some() {
            return Err(V2RuntimeError::new(
                "archive_capability_violation",
                "archival verification produced a mutation capability",
            ));
        }
        validate_digest(request_sha256)?;
        validate_identifier(&binding.request_id)?;
        validate_identifier(&binding.attempt_id)?;
        validate_digest(&binding.client_identity_sha256)?;
        validate_digest(&binding.state_sha256)?;
        parse_monotonic_deadline(
            &binding.monotonic_deadline,
            &binding.custody_boot_id,
        )?;
        if binding.attempt_revision > MAX_SAFE_INTEGER
            || binding.fencing_token == 0
            || binding.fencing_token > MAX_SAFE_INTEGER
            || binding.deadline_at_epoch_ms == 0
            || binding.deadline_at_epoch_ms > MAX_SAFE_INTEGER
        {
            return Err(V2RuntimeError::new(
                "archive_capability_binding_invalid",
                "archive capability revision, fence, or deadline is invalid",
            ));
        }
        if binding.client_identity_sha256
            != client_identity.identity_sha256()
        {
            return Err(V2RuntimeError::new(
                "archive_capability_binding_mismatch",
                "verified archive capability is not bound to the authenticated client",
            ));
        }
        Ok(VerifiedArchiveProof {
            verified,
            archive_provider_id: self
                .verified_construction
                .archive
                .provider_id
                .clone(),
            request_sha256: request_sha256.to_owned(),
            client_identity_sha256: client_identity
                .identity_sha256()
                .to_owned(),
            attempt_id: binding.attempt_id.clone(),
            state_sha256: binding.state_sha256.clone(),
            attempt_revision: binding.attempt_revision,
            fencing_token: binding.fencing_token,
            monotonic_deadline:
                binding.monotonic_deadline.clone(),
            deadline_at_epoch_ms: binding.deadline_at_epoch_ms,
            verifier_operation_binding_sha256:
                provider_operation_binding_sha256(
                    verifier_binding,
                ),
            verifier_provider_generation:
                verifier_binding.provider_generation,
            archive_provider_generation:
                self.verified_construction
                    .archive
                    .provider_generation,
            archive_store_operation_binding_sha256:
                provider_operation_binding_sha256(
                    archive_store_binding,
                ),
        })
    }

    fn verify_public_release_authorization(
        &self,
        request_sha256: &str,
        descriptor_manifest_sha256: &str,
        archive_store_binding: &VerifiedProviderOperationBinding,
        params: &V2RetrieveParams,
        objects: &ValidatedExactObjects,
        client_identity: &AuthenticatedClientIdentity,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedPublicReleaseDecision, V2RuntimeError> {
        let exact = objects
            .get(params.public_release_authorization.fd_index)
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "public_release_missing",
                    "public release authorization exact object is missing",
                )
            })?;
        let bytes = read_bounded_exact_object(exact, deadline)?;
        let authorization: SignedPublicReleaseAuthorizationV1 =
            crate::decode_canonical_json(&bytes).map_err(|_| {
                V2RuntimeError::new(
                    "public_release_invalid",
                    "public release authorization violates its closed canonical DTO",
                )
            })?;
        validate_identifier(&authorization.one_use_nonce)?;
        let release_request_commitment =
            public_release_request_commitment(
                params,
                client_identity.identity_sha256(),
                &authorization.one_use_nonce,
            )?;
        let time_binding = self.bind_authority_call(
            "trusted-time",
            ProviderSubchannelOperation::TrustedTime,
            request_sha256,
            V2_RETRIEVE_OPERATION,
            &params.binding.attempt_id,
            params.binding.fencing_token,
            deadline,
        )?;
        let now = self
            .installed
            .trusted_now_epoch_ms(&time_binding, deadline)?;
        let signature = authorization.signature.clone();
        let mut unsigned_authorization = authorization.clone();
        unsigned_authorization.signature.clear();
        let unsigned = crate::canonical_json_bytes(&unsigned_authorization).map_err(
            |_| {
                V2RuntimeError::new(
                    "public_release_invalid",
                    "public release authorization cannot be canonicalized",
                )
            },
        )?;
        let mut signing_message =
            b"serverware.public-release-authorization/v1\0".to_vec();
        signing_message.extend_from_slice(&unsigned);
        let signature_binding = self.bind_authority_call(
            "public-release",
            ProviderSubchannelOperation::PublicReleaseSignature,
            request_sha256,
            V2_RETRIEVE_OPERATION,
            &params.binding.attempt_id,
            params.binding.fencing_token,
            deadline,
        )?;
        if !self
            .installed
            .verify_public_release_ed25519(
                &signature_binding,
                &authorization.signer_key_id,
                &signing_message,
                &signature,
            )
        {
            return Err(V2RuntimeError::new(
                "public_release_signature_invalid",
                "public release authorization signature is invalid",
            ));
        }
        validate_public_release_claims(
            &authorization,
            params,
            client_identity,
            &self.proof_independent_pins,
            &self.verified_construction,
            &release_request_commitment.commitment_sha256,
            &signature_binding,
            now,
        )?;
        let revocation_binding = self.bind_authority_call(
            "evidence-trust",
            ProviderSubchannelOperation::Revocation,
            request_sha256,
            V2_RETRIEVE_OPERATION,
            &params.binding.attempt_id,
            params.binding.fencing_token,
            deadline,
        )?;
        let release_revoked = match self
            .installed
            .authorization_is_revoked(
            &revocation_binding,
            &authorization.authorization_id,
            authorization.revocation_epoch,
            deadline,
        ) {
            Ok(revoked) => revoked,
            Err(_) => {
                return Err(self
                    .supervisor
                    .quarantine_failed_authority_call(
                        &revocation_binding,
                        deadline,
                    ));
            }
        };
        if release_revoked {
            return Err(V2RuntimeError::new(
                "public_release_revoked",
                "public release authorization is revoked",
            ));
        }
        let consumption_binding = self.bind_authority_call(
            "public-release-consumption",
            ProviderSubchannelOperation::ConsumePublicRelease,
            request_sha256,
            V2_RETRIEVE_OPERATION,
            &params.binding.attempt_id,
            params.binding.fencing_token,
            deadline,
        )?;
        let consumption = self
            .installed
            .consume_once_cas(
                &consumption_binding,
                &PublicReleaseConsumeBinding {
                    authorization_id: &authorization.authorization_id,
                    one_use_nonce: &authorization.one_use_nonce,
                    request_id: &params.binding.request_id,
                    request_sha256,
                    descriptor_manifest_sha256,
                    release_request_commitment:
                        &release_request_commitment,
                    client_identity_sha256:
                        client_identity.identity_sha256(),
                    object: &params.object,
                    attempt_id: &params.binding.attempt_id,
                    state_sha256: &params.binding.state_sha256,
                    attempt_revision:
                        params.binding.attempt_revision,
                    fencing_token: params.binding.fencing_token,
                    expires_at_epoch_ms:
                        authorization.expires_at_epoch_ms,
                    expected_authority_revision:
                        params
                            .release_cas_expectation
                            .expected_authority_revision,
                    expected_unconsumed_state_sha256:
                        &params
                            .release_cas_expectation
                            .expected_unconsumed_state_sha256,
                },
                deadline,
            )?;
        let (receipt, signed_consume_outcome) = match consumption {
            PublicReleaseConsumeDecision::Acquired {
                receipt,
                signed_outcome,
            } => {
                validate_release_consume_outcome(
                    &signed_outcome,
                    ExpectedReleaseConsumeOutcome::Consumed,
                    &release_request_commitment,
                    request_sha256,
                    descriptor_manifest_sha256,
                    &authorization.one_use_nonce,
                    client_identity.identity_sha256(),
                    &params.object,
                    &params.binding.attempt_id,
                    params.binding.fencing_token,
                    &authorization.authorization_id,
                    &params.release_cas_expectation,
                    &self.proof_independent_pins,
                    &self
                        .verified_construction
                        .public_release_consumption,
                    &self.installed,
                    &consumption_binding,
                )?;
                (receipt, signed_outcome)
            }
            PublicReleaseConsumeDecision::Exact {
                record,
                signed_outcome,
            } => {
                validate_release_consume_outcome(
                    &signed_outcome,
                    ExpectedReleaseConsumeOutcome::ExactReplay,
                    &release_request_commitment,
                    request_sha256,
                    descriptor_manifest_sha256,
                    &authorization.one_use_nonce,
                    client_identity.identity_sha256(),
                    &params.object,
                    &params.binding.attempt_id,
                    params.binding.fencing_token,
                    &authorization.authorization_id,
                    &params.release_cas_expectation,
                    &self.proof_independent_pins,
                    &self
                        .verified_construction
                        .public_release_consumption,
                    &self.installed,
                    &consumption_binding,
                )?;
                validate_durable_terminal_record_self_consistency(
                    &record,
                )?;
                validate_release_exact_replay(
                    &signed_outcome,
                    &record,
                    &release_request_commitment,
                )?;
                return Ok(VerifiedPublicReleaseDecision::Exact(record));
            }
            PublicReleaseConsumeDecision::Denied {
                signed_outcome,
            } => {
                validate_release_consume_outcome(
                    &signed_outcome,
                    ExpectedReleaseConsumeOutcome::Denied,
                    &release_request_commitment,
                    request_sha256,
                    descriptor_manifest_sha256,
                    &authorization.one_use_nonce,
                    client_identity.identity_sha256(),
                    &params.object,
                    &params.binding.attempt_id,
                    params.binding.fencing_token,
                    &authorization.authorization_id,
                    &params.release_cas_expectation,
                    &self.proof_independent_pins,
                    &self
                        .verified_construction
                        .public_release_consumption,
                    &self.installed,
                    &consumption_binding,
                )?;
                return Err(V2RuntimeError::new(
                    "public_release_already_consumed",
                    "public release authorization was consumed by a different stable request",
                ));
            }
        };
        validate_digest(&receipt.authority_receipt_sha256)?;
        if receipt.authority_revision == 0
            || receipt.authority_revision > MAX_SAFE_INTEGER
        {
            return Err(V2RuntimeError::new(
                "public_release_consume_receipt_invalid",
                "public release authority returned an invalid CAS receipt",
            ));
        }
        let V2ReleaseAuthorizationConsumeOutcomeV1::ConsumedBeforeRelease {
            authority_revision,
            consumption_receipt_sha256,
            ..
        } = &signed_consume_outcome.outcome
        else {
            return Err(V2RuntimeError::new(
                "public_release_consume_receipt_mismatch",
                "release consumption receipt is not a consumed-before-release outcome",
            ));
        };
        if *authority_revision != receipt.authority_revision
            || consumption_receipt_sha256
                != &receipt.authority_receipt_sha256
        {
            return Err(V2RuntimeError::new(
                "public_release_consume_receipt_mismatch",
                "private release CAS receipt does not match the signed consumption outcome",
            ));
        }
        Ok(VerifiedPublicReleaseDecision::Acquired(
            VerifiedPublicReleaseCapability {
            authorization_id: authorization.authorization_id,
            one_use_nonce: authorization.one_use_nonce,
            subject_client_identity_sha256:
                authorization.subject_client_identity_sha256,
            object: authorization.object,
            policy_sha256: authorization.policy_sha256,
            expires_at_epoch_ms: authorization.expires_at_epoch_ms,
            release_request_commitment,
            request_id: params.binding.request_id.clone(),
            attempt_id: params.binding.attempt_id.clone(),
            state_sha256: params.binding.state_sha256.clone(),
            attempt_revision: params.binding.attempt_revision,
            fencing_token: params.binding.fencing_token,
            monotonic_deadline:
                params.binding.monotonic_deadline.clone(),
            deadline_at_epoch_ms: params.binding.deadline_at_epoch_ms,
            archive_provider_id: self
                .verified_construction
                .archive
                .provider_id
                .clone(),
            archive_provider_generation:
                archive_store_binding.provider_generation,
            archive_store_operation_binding_sha256:
                provider_operation_binding_sha256(
                    archive_store_binding,
                ),
            signature_operation_binding_sha256:
                provider_operation_binding_sha256(
                    &signature_binding,
                ),
            trusted_time_operation_binding_sha256:
                provider_operation_binding_sha256(
                    &time_binding,
                ),
            revocation_operation_binding_sha256:
                provider_operation_binding_sha256(
                    &revocation_binding,
                ),
            consumption_operation_binding_sha256:
                provider_operation_binding_sha256(
                    &consumption_binding,
                ),
            consumption_receipt_sha256:
                receipt.authority_receipt_sha256,
            consumption_authority_revision:
                receipt.authority_revision,
            signed_consumption_outcome: signed_consume_outcome,
            _seal: VerifiedPublicReleaseCapabilitySeal,
        }))
    }

    fn recover_stable_request(
        &self,
        recovery_request_id: &str,
        request_sha256: &str,
        params: &V2RecoverParams,
        objects: &ValidatedExactObjects,
        client_identity: &AuthenticatedClientIdentity,
        deadline: &OperationDeadline,
    ) -> Result<DurableRecoveryDecision, V2RuntimeError> {
        validate_identifier(recovery_request_id)?;
        validate_api_replay_key(&params.stable_request)?;
        let recovery_binding = self.bind_authority_call(
            "recovery",
            ProviderSubchannelOperation::RecoveryAuthorization,
            request_sha256,
            V2_RECOVER_OPERATION,
            &params.stable_request.attempt_id,
            params.stable_request.fencing_token,
            deadline,
        )?;
        #[derive(Serialize)]
        #[serde(
            tag = "kind",
            rename_all = "SCREAMING_SNAKE_CASE",
            rename_all_fields = "camelCase"
        )]
        enum RecoveryAuthorizationVerificationRequest<'a> {
            SameBootAuthenticatedClient {
                recovery_request_id: &'a str,
                request_sha256: &'a str,
                client_identity_sha256: &'a str,
                original_custody_boot_id: &'a str,
                authorization_id: &'a str,
                one_use_nonce: &'a str,
                stable_request: &'a V2DurableReplayKeyV1,
                monotonic_deadline:
                    &'a V2MonotonicDeadlineV1,
                deadline_at_epoch_ms: u64,
            },
            CrossBootSigned {
                recovery_request_id: &'a str,
                request_sha256: &'a str,
                client_identity_sha256: &'a str,
                trusted_now_epoch_ms: u64,
                authorization:
                    &'a SignedV2CrossBootRecoveryAuthorizationV1,
            },
        }
        let (
            authorization_id,
            authorization_client_identity_sha256,
            authorization_recovery_request_id,
            one_use_nonce,
            authorized_stable,
        ) = match &params.recovery_authorization {
            V2RecoveryAuthorizationV1::SameBootAuthenticatedClient {
                authorization_id,
                one_use_nonce,
                original_custody_boot_id,
                subject_client_identity_sha256,
            } => {
                if !objects.by_fd_index.is_empty()
                    || original_custody_boot_id
                        != &deadline.monotonic.custody_boot_id
                    || subject_client_identity_sha256
                        != client_identity.identity_sha256()
                    || params.monotonic_deadline
                        != deadline.monotonic
                    || params.deadline_at_epoch_ms
                        != deadline.absolute_epoch_ms
                {
                    return Err(V2RuntimeError::new(
                        "same_boot_recovery_binding_mismatch",
                        "same-boot recovery is not bound to the authenticated original client and immutable custody clock domain",
                    ));
                }
                let semantic_decision: ProviderBooleanDecision =
                    self.installed.invoke_bound(
                        &recovery_binding,
                        ProviderSubchannelOperation::RecoveryAuthorization,
                        &RecoveryAuthorizationVerificationRequest::
                            SameBootAuthenticatedClient {
                                recovery_request_id,
                                request_sha256,
                                client_identity_sha256:
                                    client_identity
                                        .identity_sha256(),
                                original_custody_boot_id,
                                authorization_id,
                                one_use_nonce,
                                stable_request:
                                    &params.stable_request,
                                monotonic_deadline:
                                    &params.monotonic_deadline,
                                deadline_at_epoch_ms:
                                    params.deadline_at_epoch_ms,
                            },
                        &ValidatedExactObjects::empty(),
                        deadline,
                    )?;
                if !semantic_decision.accepted {
                    return Err(V2RuntimeError::new(
                        "same_boot_recovery_authorization_rejected",
                        "measured recovery authority rejected authenticated same-boot reconciliation",
                    ));
                }
                (
                    authorization_id.clone(),
                    subject_client_identity_sha256.clone(),
                    recovery_request_id.to_owned(),
                    one_use_nonce.clone(),
                    params.stable_request.clone(),
                )
            }
            V2RecoveryAuthorizationV1::CrossBootSigned {
                authorization: descriptor,
            } => {
                let exact = objects
                    .get(descriptor.fd_index)
                    .ok_or_else(|| {
                        V2RuntimeError::new(
                            "recovery_authorization_missing",
                            "cross-boot recovery authorization exact object is missing",
                        )
                    })?;
                let bytes =
                    read_bounded_exact_object(exact, deadline)?;
                let authorization:
                    SignedV2CrossBootRecoveryAuthorizationV1 =
                    crate::decode_canonical_json(&bytes).map_err(
                        |_| {
                            V2RuntimeError::new(
                                "recovery_authorization_invalid",
                                "recovery authorization violates its closed canonical DTO",
                            )
                        },
                    )?;
                validate_identifier(
                    &authorization.authorization_id,
                )?;
                validate_identifier(
                    &authorization.recovery_request_id,
                )?;
                validate_identifier(
                    &authorization.one_use_nonce,
                )?;
                validate_api_replay_key(
                    &authorization.stable_request,
                )?;
                validate_digest(
                    &authorization
                        .subject_client_identity_sha256,
                )?;
                validate_digest(
                    &authorization.trust_root_sha256,
                )?;
                validate_digest(
                    &authorization.trust_checkpoint_sha256,
                )?;
                validate_identifier(
                    &authorization.signer_provider_id,
                )?;
                validate_digest(
                    &authorization
                        .provider_operation_binding_sha256,
                )?;
                validate_digest(&authorization.signer_key_id)?;
                validate_digest(
                    &authorization.signer_key_material_sha256,
                )?;
                let signer =
                    &self.verified_construction.recovery;
                let trusted_time_binding =
                    self.bind_authority_call(
                        "trusted-time",
                        ProviderSubchannelOperation::TrustedTime,
                        request_sha256,
                        V2_RECOVER_OPERATION,
                        &params.stable_request.attempt_id,
                        params.stable_request.fencing_token,
                        deadline,
                    )?;
                let trusted_now = self
                    .installed
                    .trusted_now_epoch_ms(
                        &trusted_time_binding,
                        deadline,
                    )?;
                let semantic_decision: ProviderBooleanDecision =
                    self.installed.invoke_bound(
                        &recovery_binding,
                        ProviderSubchannelOperation::RecoveryAuthorization,
                        &RecoveryAuthorizationVerificationRequest::
                            CrossBootSigned {
                                recovery_request_id,
                                request_sha256,
                                client_identity_sha256:
                                    client_identity
                                        .identity_sha256(),
                                trusted_now_epoch_ms: trusted_now,
                                authorization: &authorization,
                            },
                        &ValidatedExactObjects::empty(),
                        deadline,
                    )?;
                if !semantic_decision.accepted {
                    return Err(V2RuntimeError::new(
                        "recovery_authorization_rejected",
                        "measured recovery authority rejected the signed authorization",
                    ));
                }
                if authorization.api_version
                    != V2_CROSS_BOOT_RECOVERY_AUTHORIZATION_VERSION
                    || authorization.recovery_request_id
                        != recovery_request_id
                    || authorization.stable_request
                        != params.stable_request
                    || authorization
                        .subject_client_identity_sha256
                        != client_identity.identity_sha256()
                    || authorization.trust_root_sha256
                        != self
                            .proof_independent_pins
                            .trust_root_sha256
                    || authorization.trust_checkpoint_sha256
                        != self
                            .proof_independent_pins
                            .trust_checkpoint_sha256
                    || authorization.revocation_epoch
                        != self
                            .proof_independent_pins
                            .revocation_epoch
                    || authorization.issued_at_epoch_ms == 0
                    || authorization.issued_at_epoch_ms
                        > trusted_now
                    || authorization.expires_at_epoch_ms
                        <= trusted_now
                    || authorization.expires_at_epoch_ms
                        > MAX_SAFE_INTEGER
                    || authorization.signer_provider_id
                        != signer.provider_id
                    || authorization.provider_generation
                        != signer.provider_generation
                    || authorization.provider_generation
                        != recovery_binding.provider_generation
                    || authorization
                        .provider_operation_binding_sha256
                        != provider_authority_scope_sha256(
                            &recovery_binding,
                        )
                    || authorization.signer_key_id
                        != signer.key_id
                    || authorization.signer_key_material_sha256
                        != signer.key_material_sha256
                    || authorization.signer_role
                        != V2RecoveryAuthorityRole::RecoveryLookup
                {
                    return Err(V2RuntimeError::new(
                        "recovery_authorization_binding_mismatch",
                        "recovery authorization is not bound to the stable request, client, trust pins, and distinct recovery authority",
                    ));
                }
                let signature = authorization.signature.clone();
                let mut unsigned_authorization =
                    authorization.clone();
                unsigned_authorization.signature.clear();
                let unsigned = crate::canonical_json_bytes(
                    &unsigned_authorization,
                )
                .map_err(|_| {
                    V2RuntimeError::new(
                        "recovery_authorization_invalid",
                        "recovery authorization cannot be canonicalized",
                    )
                })?;
                let mut signing_message =
                    b"serverware.response-v2/recovery-authorization/v1\0"
                        .to_vec();
                signing_message.extend_from_slice(&unsigned);
                if signature.is_empty()
                    || signature.len() > 1024
                    || !self
                        .installed
                        .verify_authorization_ed25519(
                            &recovery_binding,
                            &authorization.signer_key_id,
                            &signing_message,
                            &signature,
                        )
                {
                    return Err(V2RuntimeError::new(
                        "recovery_authorization_signature_invalid",
                        "recovery authorization signature is invalid",
                    ));
                }
                let revocation_binding =
                    self.bind_authority_call(
                        "evidence-trust",
                        ProviderSubchannelOperation::Revocation,
                        request_sha256,
                        V2_RECOVER_OPERATION,
                        &params.stable_request.attempt_id,
                        params.stable_request.fencing_token,
                        deadline,
                    )?;
                let recovery_revoked = match self
                    .installed
                    .authorization_is_revoked(
                        &revocation_binding,
                        &authorization.authorization_id,
                        authorization.revocation_epoch,
                        deadline,
                    ) {
                    Ok(revoked) => revoked,
                    Err(_) => {
                        return Err(self
                            .supervisor
                            .quarantine_failed_authority_call(
                                &revocation_binding,
                                deadline,
                            ));
                    }
                };
                if recovery_revoked {
                    return Err(V2RuntimeError::new(
                        "recovery_authorization_revoked",
                        "recovery authorization is revoked",
                    ));
                }
                (
                    authorization.authorization_id,
                    authorization
                        .subject_client_identity_sha256,
                    authorization.recovery_request_id,
                    authorization.one_use_nonce,
                    authorization.stable_request,
                )
            }
        };
        let replay_binding = self.bind_authority_call(
            "linearizable-store",
            ProviderSubchannelOperation::ReplayRecover,
            request_sha256,
            V2_RECOVER_OPERATION,
            &params.stable_request.attempt_id,
            params.stable_request.fencing_token,
            deadline,
        )?;
        let capability = VerifiedRecoveryCapability {
            authorization_id,
            subject_client_identity_sha256:
                authorization_client_identity_sha256,
            recovery_request_id:
                authorization_recovery_request_id,
            one_use_nonce,
            stable: authorized_stable,
            recovery_operation_binding_sha256:
                provider_operation_binding_sha256(
                    &recovery_binding,
                ),
            recovery_provider_generation:
                recovery_binding.provider_generation,
            replay_operation_binding_sha256:
                provider_operation_binding_sha256(
                    &replay_binding,
                ),
            replay_provider_generation:
                replay_binding.provider_generation,
            _seal: VerifiedRecoveryCapabilitySeal,
        };
        let lookup = StableRecoveryLookup {
            recovery_request_id: recovery_request_id.to_owned(),
            stable: params.stable_request.clone(),
        };
        let mut decision = self
            .installed
            .recover(
                &replay_binding,
                &lookup,
                capability,
                deadline,
            )?;
        validate_recovered_original_client_binding(
            &decision.terminal,
            client_identity.identity_sha256(),
            matches!(
                &params.recovery_authorization,
                V2RecoveryAuthorizationV1::SameBootAuthenticatedClient {
                    ..
                }
            ),
            deadline,
        )?;
        let resolution_binding = self.bind_authority_call(
            "recovery",
            ProviderSubchannelOperation::RecoveryResolution,
            request_sha256,
            V2_RECOVER_OPERATION,
            &params.stable_request.attempt_id,
            params.stable_request.fencing_token,
            deadline,
        )?;
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct RecoveryResolutionRequest<'a> {
            lookup: &'a StableRecoveryLookup,
            terminal: &'a DurableTerminalRecord,
            replay_result: &'a V2RecoverResult,
            client_identity_sha256: &'a str,
            authorization_operation_binding_sha256: String,
            replay_operation_binding_sha256: String,
        }
        let signed_resolution:
            SignedV2CrossBootRecoveryOutcomeV1 =
            self.installed.invoke_bound(
                &resolution_binding,
                ProviderSubchannelOperation::RecoveryResolution,
                &RecoveryResolutionRequest {
                    lookup: &lookup,
                    terminal: &decision.terminal,
                    replay_result: &decision.result,
                    client_identity_sha256:
                        client_identity.identity_sha256(),
                    authorization_operation_binding_sha256:
                        provider_operation_binding_sha256(
                            &recovery_binding,
                        ),
                    replay_operation_binding_sha256:
                        provider_operation_binding_sha256(
                            &replay_binding,
                        ),
                },
                &ValidatedExactObjects::empty(),
                deadline,
            )?;
        match &mut decision.result {
            V2RecoverResult::Success { signed_outcome, .. }
            | V2RecoverResult::Denied { signed_outcome, .. }
            | V2RecoverResult::OutcomeUnknown {
                signed_outcome, ..
            } => *signed_outcome = signed_resolution,
        }
        let current_time_binding = self.bind_authority_call(
            "trusted-time",
            ProviderSubchannelOperation::TrustedTime,
            request_sha256,
            V2_RECOVER_OPERATION,
            &params.stable_request.attempt_id,
            params.stable_request.fencing_token,
            deadline,
        )?;
        let current_trusted_now = self.installed.trusted_now_epoch_ms(
            &current_time_binding,
            deadline,
        )?;
        let terminal_revocation_binding = self.bind_authority_call(
            "evidence-trust",
            ProviderSubchannelOperation::Revocation,
            request_sha256,
            V2_RECOVER_OPERATION,
            &params.stable_request.attempt_id,
            params.stable_request.fencing_token,
            deadline,
        )?;
        let terminal_receipt_revoked = self
            .installed
            .authorization_is_revoked(
                &terminal_revocation_binding,
                &decision.terminal.authority_receipt_sha256,
                self.proof_independent_pins.revocation_epoch,
                deadline,
            )?;
        let resolution = match &decision.result {
            V2RecoverResult::Success { signed_outcome, .. }
            | V2RecoverResult::Denied { signed_outcome, .. }
            | V2RecoverResult::OutcomeUnknown {
                signed_outcome, ..
            } => signed_outcome,
        };
        let resolution_revocation_binding =
            self.bind_authority_call(
                "evidence-trust",
                ProviderSubchannelOperation::Revocation,
                request_sha256,
                V2_RECOVER_OPERATION,
                &params.stable_request.attempt_id,
                params.stable_request.fencing_token,
                deadline,
            )?;
        let resolution_revoked = self
            .installed
            .authorization_is_revoked(
                &resolution_revocation_binding,
                &resolution.reconciliation.retrieval_id,
                self.proof_independent_pins.revocation_epoch,
                deadline,
            )?;
        validate_durable_recovery_decision(
            &decision,
            &lookup,
            client_identity.identity_sha256(),
            current_trusted_now,
            terminal_receipt_revoked,
            resolution_revoked,
            &self.proof_independent_pins,
            signer,
            &self.installed,
            &resolution_binding,
            &self.verified_construction.durable_replay,
            &self.installed,
            &replay_binding,
        )?;
        let recomputed_record_sha256 =
            durable_terminal_record_sha256(&decision.terminal)?;
        let replay_verify_binding = self.bind_authority_call(
            "linearizable-store",
            ProviderSubchannelOperation::ReplayVerifyRecord,
            request_sha256,
            V2_RECOVER_OPERATION,
            &params.stable_request.attempt_id,
            params.stable_request.fencing_token,
            deadline,
        )?;
        self.installed.verify_terminal_record_authority(
            &replay_verify_binding,
            &decision.terminal,
            &recomputed_record_sha256,
            deadline,
        )?;
        Ok(decision)
    }

    #[allow(clippy::too_many_arguments)]
    fn verify_fresh_attestation(
        &self,
        request_sha256: &str,
        response_sha256: &str,
        output_manifest_sha256: &str,
        custody_boot_id: &str,
        authenticated_session_sha256: &str,
        client_identity_sha256: &str,
        deadline: &OperationDeadline,
    ) -> Result<V2FreshResponseAttestationV1, V2RuntimeError> {
        match self
            .supervisor
            .launcher
            .config
            .attestation_mode()
        {
            V2AttestationMode::TrustedHost => {
                self.verify_fresh_trusted_host_attestation(
                    request_sha256,
                    response_sha256,
                    output_manifest_sha256,
                    custody_boot_id,
                    authenticated_session_sha256,
                    client_identity_sha256,
                    deadline,
                )
            }
            V2AttestationMode::TeeHardware => {
                self.verify_fresh_hardware_proof(
                    request_sha256,
                    response_sha256,
                    output_manifest_sha256,
                    custody_boot_id,
                    authenticated_session_sha256,
                    client_identity_sha256,
                    deadline,
                )
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn verify_fresh_trusted_host_attestation(
        &self,
        request_sha256: &str,
        response_sha256: &str,
        output_manifest_sha256: &str,
        custody_boot_id: &str,
        authenticated_session_sha256: &str,
        client_identity_sha256: &str,
        deadline: &OperationDeadline,
    ) -> Result<V2FreshResponseAttestationV1, V2RuntimeError> {
        validate_digest(request_sha256)?;
        validate_digest(response_sha256)?;
        validate_digest(output_manifest_sha256)?;
        validate_identifier(custody_boot_id)?;
        validate_digest(authenticated_session_sha256)?;
        validate_digest(client_identity_sha256)?;
        let challenge_nonce = generate_hardware_proof_challenge()?;
        let role_root =
            &self.verified_construction.role_identity_root_sha256;
        let pin_root = &self
            .verified_construction
            .proof_independent_pins_root_sha256;
        let custody_pin = self
            .supervisor
            .launcher
            .config
            .role_identities
            .iter()
            .find(|pin| pin.role == "custody")
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "custody_measurement_unconfigured",
                    "custody executable, configuration, key, and generation pins are missing",
                )
            })?;
        let signer = &self.verified_construction.runtime_attestation;
        let expected_report_data_sha256 =
            fresh_tee_report_data_sha256(
                response_sha256,
                output_manifest_sha256,
                authenticated_session_sha256,
                &challenge_nonce,
                &signer.key_material_sha256,
                &custody_pin.executable_measurement_sha256,
                custody_pin.provider_generation,
            );
        let binding = FreshHardwareProofBinding {
            request_sha256,
            response_sha256,
            output_manifest_sha256,
            custody_boot_id,
            authenticated_session_sha256,
            client_identity_sha256,
            role_identity_root_sha256: role_root,
            proof_independent_pins_root_sha256: pin_root,
            trust_checkpoint_sha256: &self
                .proof_independent_pins
                .trust_checkpoint_sha256,
            revocation_epoch:
                self.proof_independent_pins.revocation_epoch,
            custody_executable_measurement_sha256:
                &custody_pin.executable_measurement_sha256,
            custody_provider_config_sha256:
                &custody_pin.provider_config_sha256,
            custody_key_material_sha256:
                &custody_pin.key_material_sha256,
            custody_tee_measurement_sha256:
                &custody_pin.tee_measurement_sha256,
            provider_generation:
                custody_pin.provider_generation,
            challenge_nonce: &challenge_nonce,
            response_signer_key_sha256:
                &signer.key_material_sha256,
            expected_report_data_sha256:
                &expected_report_data_sha256,
            trust_root_sha256:
                &self.proof_independent_pins.trust_root_sha256,
            monotonic_deadline: &deadline.monotonic,
            deadline_at_epoch_ms: deadline.absolute_epoch_ms,
        };
        let attestation_binding = self.bind_authority_call(
            "runtime-attestation",
            ProviderSubchannelOperation::FreshResponseAttestation,
            request_sha256,
            "responseObservationV2.trustedHostAttestation/v1",
            &challenge_nonce,
            1,
            deadline,
        )?;
        let proof = self.installed.fresh_response_attestation(
            &attestation_binding,
            &binding,
            deadline,
        )?;
        let evidence = base64::engine::general_purpose::STANDARD
            .decode(&proof.attestation_evidence_base64)
            .map_err(|_| {
                V2RuntimeError::new(
                    "fresh_trusted_host_evidence_invalid",
                    "trusted-host evidence is not canonical base64",
                )
            })?;
        let expected_report_binding = V2TeeReportBindingV1 {
            report_data_sha256:
                expected_report_data_sha256.clone(),
            unsigned_response_sha256:
                response_sha256.to_owned(),
            output_manifest_sha256:
                output_manifest_sha256.to_owned(),
            authenticated_session_sha256:
                authenticated_session_sha256.to_owned(),
            challenge_nonce: challenge_nonce.clone(),
            signer_key_sha256:
                signer.key_material_sha256.clone(),
            custody_measurement_sha256:
                custody_pin.executable_measurement_sha256.clone(),
            provider_generation:
                custody_pin.provider_generation,
        };
        let local_now = system_time_epoch_ms()?;
        if proof.api_version
            != V2_FRESH_RESPONSE_ATTESTATION_VERSION
            || proof.attestation_mode
                != V2AttestationMode::TrustedHost
            || proof.attestation_evidence_format
                != V2FreshAttestationEvidenceFormat::TrustedHostMeasurementBundleJsonV1
            || proof.request_sha256 != request_sha256
            || proof.unsigned_response_sha256 != response_sha256
            || proof.output_manifest_sha256
                != output_manifest_sha256
            || proof.custody_boot_id != custody_boot_id
            || proof.authenticated_session_sha256
                != authenticated_session_sha256
            || proof.client_identity_sha256 != client_identity_sha256
            || proof.role_identity_root_sha256 != *role_root
            || proof.proof_independent_pins_root_sha256 != *pin_root
            || proof.trust_checkpoint_sha256
                != self
                    .proof_independent_pins
                    .trust_checkpoint_sha256
            || proof.revocation_epoch
                != self.proof_independent_pins.revocation_epoch
            || proof.custody_executable_measurement_sha256
                != custody_pin.executable_measurement_sha256
            || proof.custody_provider_config_sha256
                != custody_pin.provider_config_sha256
            || proof.custody_key_material_sha256
                != custody_pin.key_material_sha256
            || proof.provider_generation
                != custody_pin.provider_generation
            || proof.monotonic_deadline != deadline.monotonic
            || proof.deadline_at_epoch_ms
                != deadline.absolute_epoch_ms
            || proof.challenge_nonce != challenge_nonce
            || proof.signer_provider_id != signer.provider_id
            || proof.signer_key_id != signer.key_id
            || proof.signer_key_material_sha256
                != signer.key_material_sha256
            || proof.tee_report_binding
                != expected_report_binding
            || proof.signature_algorithm
                != V2FreshAttestationSignatureAlgorithm::Ed25519
            || evidence.is_empty()
            || evidence.len()
                > RESPONSE_OBSERVATION_V2_MAX_ATTESTATION_EVIDENCE_BYTES
            || base64::engine::general_purpose::STANDARD
                .encode(&evidence)
                != proof.attestation_evidence_base64
            || format!(
                "sha256:{:x}",
                Sha256::digest(&evidence)
            ) != proof.attestation_evidence_sha256
            || proof.issued_at_epoch_ms == 0
            || proof.issued_at_epoch_ms > local_now
            || proof.expires_at_epoch_ms <= local_now
            || proof.expires_at_epoch_ms > deadline.absolute_epoch_ms
            || proof
                .expires_at_epoch_ms
                .saturating_sub(proof.issued_at_epoch_ms)
                > RESPONSE_OBSERVATION_V2_MAX_OPERATION_MS
        {
            return Err(V2RuntimeError::new(
                "fresh_trusted_host_attestation_binding_mismatch",
                "trusted-host attestation is not bound to the exact response, session, measured signer, and configured trust pins",
            ));
        }
        validate_public_attestation_signer_key(
            &proof.signer_key,
            &signer.key_material_sha256,
            self.installed
                .role("runtime-attestation")?
                .verification_key
                .as_ref(),
        )?;
        validate_attestation_trust_artifact(
            &proof.trust_evidence.trust_chain,
        )?;
        validate_attestation_trust_artifact(
            &proof.trust_evidence.endorsements,
        )?;
        validate_identifier(
            &proof
                .trust_evidence
                .signer_revocation_receipt_retrieval_id,
        )?;
        validate_identifier(
            &proof
                .trust_evidence
                .evidence_verification_receipt_retrieval_id,
        )?;
        if proof.trust_evidence.trust_root_sha256
            != self.proof_independent_pins.trust_root_sha256
            || proof.trust_evidence.trust_checkpoint_sha256
                != self
                    .proof_independent_pins
                    .trust_checkpoint_sha256
            || proof.trust_evidence.revocation_epoch
                != self.proof_independent_pins.revocation_epoch
            || proof
                .trust_evidence
                .signer_revocation_receipt_sha256
                != proof.current_revocation_receipt_sha256
        {
            return Err(V2RuntimeError::new(
                "fresh_trusted_host_trust_binding_mismatch",
                "trusted-host attestation does not match the root-owned trust and revocation pins",
            ));
        }
        let signature = proof.signature.clone();
        let mut unsigned = proof.clone();
        unsigned.signature.clear();
        let canonical = crate::canonical_json_bytes(&unsigned)
            .map_err(|_| {
                V2RuntimeError::new(
                    "fresh_trusted_host_attestation_invalid",
                    "trusted-host attestation cannot be canonicalized",
                )
            })?;
        let mut message =
            V2_FRESH_RESPONSE_ATTESTATION_SIGNATURE_DOMAIN.to_vec();
        message.extend_from_slice(&canonical);
        if signature.is_empty()
            || signature.len() > 4096
            || !self
                .installed
                .verify_fresh_response_attestation_ed25519(
                    &attestation_binding,
                    &proof.signer_key_id,
                    &message,
                    &signature,
                )
        {
            return Err(V2RuntimeError::new(
                "fresh_trusted_host_attestation_signature_invalid",
                "trusted-host response attestation signature is invalid",
            ));
        }
        Ok(proof)
    }

    fn verify_fresh_hardware_proof(
        &self,
        request_sha256: &str,
        response_sha256: &str,
        output_manifest_sha256: &str,
        custody_boot_id: &str,
        authenticated_session_sha256: &str,
        client_identity_sha256: &str,
        deadline: &OperationDeadline,
    ) -> Result<V2FreshResponseAttestationV1, V2RuntimeError> {
        validate_digest(request_sha256)?;
        validate_digest(response_sha256)?;
        validate_digest(output_manifest_sha256)?;
        validate_identifier(custody_boot_id)?;
        validate_digest(authenticated_session_sha256)?;
        validate_digest(client_identity_sha256)?;
        let challenge_nonce = generate_hardware_proof_challenge()?;
        let role_root = &self
            .verified_construction
            .role_identity_root_sha256;
        let pin_root = &self
            .verified_construction
            .proof_independent_pins_root_sha256;
        let custody_pin = self
            .supervisor
            .launcher
            .config
            .role_identities
            .iter()
            .find(|pin| pin.role == "custody")
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "custody_measurement_unconfigured",
                    "custody executable, configuration, key, TEE, and generation pins are missing",
                )
            })?;
        let signer =
            &self.verified_construction.runtime_attestation;
        let expected_report_data_sha256 =
            fresh_tee_report_data_sha256(
                response_sha256,
                output_manifest_sha256,
                authenticated_session_sha256,
                &challenge_nonce,
                &signer.key_material_sha256,
                &custody_pin.tee_measurement_sha256,
                custody_pin.provider_generation,
            );
        let binding = FreshHardwareProofBinding {
            request_sha256,
            response_sha256,
            output_manifest_sha256,
            custody_boot_id,
            authenticated_session_sha256,
            client_identity_sha256,
            role_identity_root_sha256: role_root,
            proof_independent_pins_root_sha256: pin_root,
            trust_checkpoint_sha256: &self
                .proof_independent_pins
                .trust_checkpoint_sha256,
            revocation_epoch:
                self.proof_independent_pins.revocation_epoch,
            custody_executable_measurement_sha256:
                &custody_pin.executable_measurement_sha256,
            custody_provider_config_sha256:
                &custody_pin.provider_config_sha256,
            custody_key_material_sha256:
                &custody_pin.key_material_sha256,
            custody_tee_measurement_sha256:
                &custody_pin.tee_measurement_sha256,
            provider_generation:
                custody_pin.provider_generation,
            challenge_nonce: &challenge_nonce,
            response_signer_key_sha256:
                &signer.key_material_sha256,
            expected_report_data_sha256:
                &expected_report_data_sha256,
            trust_root_sha256:
                &self.proof_independent_pins.trust_root_sha256,
            monotonic_deadline: &deadline.monotonic,
            deadline_at_epoch_ms: deadline.absolute_epoch_ms,
        };
        let attestation_binding = self.bind_authority_call(
            "runtime-attestation",
            ProviderSubchannelOperation::FreshResponseAttestation,
            request_sha256,
            "responseObservationV2.hardwareProof/v1",
            &challenge_nonce,
            1,
            deadline,
        )?;
        let proof = self
            .installed
            .fresh_response_attestation(
                &attestation_binding,
                &binding,
                deadline,
            )?;
        let trusted_time_binding = self.bind_authority_call(
            "trusted-time",
            ProviderSubchannelOperation::TrustedTime,
            request_sha256,
            "responseObservationV2.hardwareProof/v1",
            &challenge_nonce,
            1,
            deadline,
        )?;
        let trusted_now = self
            .installed
            .trusted_now_epoch_ms(
                &trusted_time_binding,
                deadline,
            )?;
        validate_identifier(&proof.challenge_nonce)?;
        validate_digest(&proof.attestation_evidence_sha256)?;
        let attestation_evidence =
            base64::engine::general_purpose::STANDARD
                .decode(&proof.attestation_evidence_base64)
                .map_err(|_| {
                    V2RuntimeError::new(
                        "fresh_hardware_evidence_encoding_invalid",
                        "fresh TEE evidence is not canonical base64",
                    )
                })?;
        if attestation_evidence.is_empty()
            || attestation_evidence.len()
                > RESPONSE_OBSERVATION_V2_MAX_ATTESTATION_EVIDENCE_BYTES
            || base64::engine::general_purpose::STANDARD
                .encode(&attestation_evidence)
                != proof.attestation_evidence_base64
            || format!(
                "sha256:{:x}",
                Sha256::digest(&attestation_evidence)
            ) != proof.attestation_evidence_sha256
        {
            return Err(V2RuntimeError::new(
                "fresh_hardware_evidence_bytes_invalid",
                "fresh TEE evidence bytes are empty, overbound, non-canonical, or do not match the signed digest",
            ));
        }
        validate_identifier(
            &proof.attestation_evidence_retrieval_id,
        )?;
        validate_digest(
            &proof.current_revocation_receipt_sha256,
        )?;
        validate_identifier(&proof.signer_provider_id)?;
        validate_digest(&proof.signer_key_id)?;
        validate_digest(&proof.signer_key_material_sha256)?;
        validate_public_attestation_signer_key(
            &proof.signer_key,
            &signer.key_material_sha256,
            self.installed
                .role("runtime-attestation")?
                .verification_key
                .as_ref(),
        )?;
        let trust_chain_sha256 =
            validate_attestation_trust_artifact(
                &proof.trust_evidence.trust_chain,
            )?;
        let endorsements_sha256 =
            validate_attestation_trust_artifact(
                &proof.trust_evidence.endorsements,
            )?;
        validate_digest(
            &proof.tee_report_binding.report_data_sha256,
        )?;
        validate_digest(
            &proof
                .trust_evidence
                .signer_revocation_receipt_sha256,
        )?;
        validate_digest(
            &proof
                .trust_evidence
                .evidence_verification_receipt_sha256,
        )?;
        validate_identifier(
            &proof
                .trust_evidence
                .signer_revocation_receipt_retrieval_id,
        )?;
        validate_identifier(
            &proof
                .trust_evidence
                .evidence_verification_receipt_retrieval_id,
        )?;
        let expected_tee_report_binding =
            V2TeeReportBindingV1 {
                report_data_sha256:
                    expected_report_data_sha256.clone(),
                unsigned_response_sha256:
                    response_sha256.to_owned(),
                output_manifest_sha256:
                    output_manifest_sha256.to_owned(),
                authenticated_session_sha256:
                    authenticated_session_sha256.to_owned(),
                challenge_nonce: challenge_nonce.clone(),
                signer_key_sha256:
                    signer.key_material_sha256.clone(),
                custody_measurement_sha256:
                    custody_pin.tee_measurement_sha256.clone(),
                provider_generation:
                    custody_pin.provider_generation,
            };
        if proof.api_version
            != V2_FRESH_RESPONSE_ATTESTATION_VERSION
            || proof.request_sha256 != request_sha256
            || proof.unsigned_response_sha256 != response_sha256
            || proof.output_manifest_sha256
                != output_manifest_sha256
            || proof.custody_boot_id != custody_boot_id
            || proof.authenticated_session_sha256
                != authenticated_session_sha256
            || proof.client_identity_sha256 != client_identity_sha256
            || proof.role_identity_root_sha256 != *role_root
            || proof.proof_independent_pins_root_sha256 != *pin_root
            || proof.trust_checkpoint_sha256
                != self
                    .proof_independent_pins
                    .trust_checkpoint_sha256
            || proof.revocation_epoch
                != self.proof_independent_pins.revocation_epoch
            || proof.custody_executable_measurement_sha256
                != custody_pin.executable_measurement_sha256
            || proof.custody_provider_config_sha256
                != custody_pin.provider_config_sha256
            || proof.custody_key_material_sha256
                != custody_pin.key_material_sha256
            || proof.custody_tee_measurement_sha256
                != custody_pin.tee_measurement_sha256
            || proof.provider_generation
                != custody_pin.provider_generation
            || proof.monotonic_deadline != deadline.monotonic
            || proof.deadline_at_epoch_ms
                != deadline.absolute_epoch_ms
            || proof.challenge_nonce != challenge_nonce
            || proof.signature_algorithm
                != V2FreshAttestationSignatureAlgorithm::Ed25519
            || proof.signer_provider_id != signer.provider_id
            || proof.signer_key_id != signer.key_id
            || proof.signer_key_material_sha256
                != signer.key_material_sha256
            || proof.tee_report_binding
                != expected_tee_report_binding
            || proof.trust_evidence.trust_root_sha256
                != self.proof_independent_pins.trust_root_sha256
            || proof.trust_evidence.trust_checkpoint_sha256
                != self
                    .proof_independent_pins
                    .trust_checkpoint_sha256
            || proof.trust_evidence.revocation_epoch
                != self.proof_independent_pins.revocation_epoch
            || proof
                .trust_evidence
                .signer_revocation_receipt_sha256
                != proof.current_revocation_receipt_sha256
            || proof.trust_evidence.verified_at_epoch_ms
                < proof.issued_at_epoch_ms
            || proof.trust_evidence.verified_at_epoch_ms
                > trusted_now
            || proof.issued_at_epoch_ms == 0
            || proof.issued_at_epoch_ms > trusted_now
            || proof.expires_at_epoch_ms <= trusted_now
            || proof.expires_at_epoch_ms
                > deadline.absolute_epoch_ms
            || proof.expires_at_epoch_ms
                .saturating_sub(proof.issued_at_epoch_ms)
                > RESPONSE_OBSERVATION_V2_MAX_OPERATION_MS
        {
            return Err(V2RuntimeError::new(
                "fresh_hardware_proof_binding_mismatch",
                "per-response hardware attestation is not fresh or bound to the exact request, client, boot, pin roots, and attestation authority",
            ));
        }
        let signature = proof.signature.clone();
        let mut unsigned_proof = proof.clone();
        unsigned_proof.signature.clear();
        let unsigned = crate::canonical_json_bytes(&unsigned_proof).map_err(|_| {
            V2RuntimeError::new(
                "fresh_hardware_proof_invalid",
                "per-response hardware attestation cannot be canonicalized",
            )
        })?;
        let mut signing_message =
            V2_FRESH_RESPONSE_ATTESTATION_SIGNATURE_DOMAIN.to_vec();
        signing_message.extend_from_slice(&unsigned);
        if signature.is_empty()
            || signature.len() > 4096
            || !self
                .installed
                .verify_fresh_response_attestation_ed25519(
                    &attestation_binding,
                    &proof.signer_key_id,
                    &signing_message,
                    &signature,
                )
        {
            return Err(V2RuntimeError::new(
                "fresh_hardware_proof_signature_invalid",
                "per-response hardware attestation signature is invalid",
            ));
        }
        let evidence_binding = self.bind_authority_call(
            "runtime-attestation",
            ProviderSubchannelOperation::VerifyFreshResponseAttestation,
            request_sha256,
            "responseObservationV2.hardwareProofEvidence/v1",
            &challenge_nonce,
            1,
            deadline,
        )?;
        let evidence = self
            .installed
            .verify_fresh_response_attestation_evidence(
                &evidence_binding,
                &binding,
                &proof,
                deadline,
            )?;
        validate_digest(&evidence.attestation_evidence_sha256)?;
        validate_digest(
            &evidence.current_revocation_receipt_sha256,
        )?;
        validate_identifier(
            &evidence.signer_revocation_receipt_retrieval_id,
        )?;
        validate_identifier(
            &evidence
                .evidence_verification_receipt_retrieval_id,
        )?;
        for digest in [
            &evidence.report_data_sha256,
            &evidence.signer_key_sha256,
            &evidence.trust_chain_sha256,
            &evidence.endorsements_sha256,
            &evidence.trust_root_sha256,
            &evidence.signer_revocation_receipt_sha256,
            &evidence.evidence_verification_receipt_sha256,
        ] {
            validate_digest(digest)?;
        }
        let verification_time_binding = self.bind_authority_call(
            "trusted-time",
            ProviderSubchannelOperation::TrustedTime,
            request_sha256,
            "responseObservationV2.hardwareProofEvidence/v1",
            &challenge_nonce,
            1,
            deadline,
        )?;
        let verified_now = self
            .installed
            .trusted_now_epoch_ms(
                &verification_time_binding,
                deadline,
            )?;
        let signer_revocation_binding =
            self.bind_authority_call(
                "evidence-trust",
                ProviderSubchannelOperation::Revocation,
                request_sha256,
                "responseObservationV2.hardwareProofEvidence/v1",
                &challenge_nonce,
                1,
                deadline,
            )?;
        let signer_revoked = self
            .installed
            .authorization_is_revoked(
                &signer_revocation_binding,
                &proof.signer_key_id,
                self.proof_independent_pins.revocation_epoch,
                deadline,
            )?;
        if evidence.attestation_evidence_sha256
            != proof.attestation_evidence_sha256
            || evidence.response_sha256 != response_sha256
            || evidence.output_manifest_sha256
                != output_manifest_sha256
            || evidence.authenticated_session_sha256
                != authenticated_session_sha256
            || evidence.challenge_nonce != challenge_nonce
            || evidence.attestation_evidence_retrieval_id
                != proof.attestation_evidence_retrieval_id
            || evidence.current_revocation_receipt_sha256
                != proof.current_revocation_receipt_sha256
            || evidence.report_data_sha256
                != expected_report_data_sha256
            || evidence.report_data_sha256
                != proof.tee_report_binding.report_data_sha256
            || evidence.signer_key_sha256
                != signer.key_material_sha256
            || evidence.trust_chain_sha256
                != trust_chain_sha256
            || evidence.endorsements_sha256
                != endorsements_sha256
            || evidence.trust_root_sha256
                != self.proof_independent_pins.trust_root_sha256
            || evidence.signer_revocation_receipt_sha256
                != proof
                    .trust_evidence
                    .signer_revocation_receipt_sha256
            || evidence.signer_revocation_receipt_retrieval_id
                != proof
                    .trust_evidence
                    .signer_revocation_receipt_retrieval_id
            || evidence.evidence_verification_receipt_sha256
                != proof
                    .trust_evidence
                    .evidence_verification_receipt_sha256
            || evidence
                .evidence_verification_receipt_retrieval_id
                != proof
                    .trust_evidence
                    .evidence_verification_receipt_retrieval_id
            || evidence.custody_executable_measurement_sha256
                != custody_pin.executable_measurement_sha256
            || evidence.custody_provider_config_sha256
                != custody_pin.provider_config_sha256
            || evidence.custody_key_material_sha256
                != custody_pin.key_material_sha256
            || evidence.custody_tee_measurement_sha256
                != custody_pin.tee_measurement_sha256
            || evidence.trust_checkpoint_sha256
                != self
                    .proof_independent_pins
                    .trust_checkpoint_sha256
            || evidence.revocation_epoch
                != self.proof_independent_pins.revocation_epoch
            || evidence.provider_generation
                != custody_pin.provider_generation
            || evidence.verified_at_epoch_ms < proof.issued_at_epoch_ms
            || evidence.verified_at_epoch_ms > verified_now
            || proof.expires_at_epoch_ms <= verified_now
            || signer_revoked
        {
            return Err(V2RuntimeError::new(
                "fresh_hardware_evidence_invalid",
                "fresh response evidence does not independently verify the exact response, session, measurements, trust checkpoint, provider generation, and current revocation state",
            ));
        }
        Ok(proof)
    }

    fn verify_durable_outcome_unknown(
        &self,
        request: &V2ControlRequest,
        result: V2OutcomeUnknownResult,
        replay: &ReplayReservation,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedOutcomeUnknown, V2RuntimeError> {
        validate_outcome_unknown(request, &result, replay)?;
        let binding = request.mutation_binding().ok_or_else(|| {
            V2RuntimeError::new(
                "outcome_unknown_read_forbidden",
                "read-only operations cannot produce outcome unknown",
            )
        })?;
        let replay_key = replay.key()?;
        let signer = &self
            .verified_construction
            .outcome_reconciliation;
        validate_digest(
            &result.provider_operation_binding_sha256,
        )?;
        if result.trust_checkpoint_sha256
            != self
                .proof_independent_pins
                .trust_checkpoint_sha256
            || result.revocation_epoch
                != self.proof_independent_pins.revocation_epoch
            || result.signer_provider_id != signer.provider_id
            || result.provider_generation
                != signer.provider_generation
            || result.provider_generation
                != self.installed.generation
            || result.signer_key_id != signer.key_id
            || result.signer_key_material_sha256
                != signer.key_material_sha256
        {
            return Err(V2RuntimeError::new(
                "outcome_unknown_authority_mismatch",
                "outcome unknown does not match trust pins and the distinct reconciliation authority",
            ));
        }
        let durable_start_binding = self.bind_authority_call(
            "outcome-reconciliation",
            ProviderSubchannelOperation::VerifyDurableStart,
            &replay_key.request_sha256,
            request.operation(),
            &binding.attempt_id,
            binding.fencing_token,
            deadline,
        )?;
        if !self.installed.durable_start_receipt_exists(
            &durable_start_binding,
            &result.provider_operation_id,
            &result.durable_start_receipt_sha256,
            &DurableStartReceiptBinding {
                request_sha256: &result.request_sha256,
                descriptor_manifest_sha256:
                    &result.descriptor_manifest_sha256,
                attempt_id: &binding.attempt_id,
                predecessor_lifecycle_state:
                    binding.predecessor_lifecycle_state,
                predecessor_state_sha256:
                    &binding.predecessor_state_sha256,
                attempt_revision: binding.attempt_revision,
                fencing_token: binding.fencing_token,
                monotonic_deadline:
                    &binding.monotonic_deadline,
                deadline_at_epoch_ms: binding.deadline_at_epoch_ms,
            },
            deadline,
        )? {
            return Err(V2RuntimeError::new(
                "outcome_unknown_start_not_durable",
                "outcome unknown lacks a durable start receipt",
            ));
        }
        let reconciliation_binding = self.bind_authority_call(
            "outcome-reconciliation",
            ProviderSubchannelOperation::VerifyReconciliationRecord,
            &replay_key.request_sha256,
            request.operation(),
            &binding.attempt_id,
            binding.fencing_token,
            deadline,
        )?;
        if !self
            .installed
            .reconciliation_record_is_durable(
                &reconciliation_binding,
                &result.reconciliation,
                deadline,
            )?
        {
            return Err(V2RuntimeError::new(
                "outcome_unknown_not_durable",
                "outcome unknown lacks a durable start receipt or reconciliation record",
            ));
        }
        let signature = result.signature.clone();
        let mut unsigned_result = result.clone();
        unsigned_result.signature.clear();
        let unsigned = crate::canonical_json_bytes(&unsigned_result).map_err(|_| {
            V2RuntimeError::new(
                "outcome_unknown_invalid",
                "outcome unknown cannot be canonicalized",
            )
        })?;
        let mut signing_message =
            b"serverware.outcome-unknown/v1\0".to_vec();
        signing_message.extend_from_slice(&unsigned);
        if !self.installed.verify_outcome_unknown_ed25519(
            &durable_start_binding,
            &result.signer_key_id,
            &signing_message,
            &signature,
        ) {
            return Err(V2RuntimeError::new(
                "outcome_unknown_signature_invalid",
                "outcome unknown signature is invalid",
            ));
        }
        Ok(VerifiedOutcomeUnknown {
            result,
            _seal: VerifiedOutcomeUnknownSeal,
        })
    }

    fn reconcile_started_failure(
        &self,
        request: &V2ControlRequest,
        started: &VerifiedStartedProviderCapability,
        replay: &ReplayReservation,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedOutcomeUnknown, V2RuntimeError> {
        validate_provider_termination(
            &started.binding,
            &started.termination,
            deadline,
        )
        .map_err(V2RuntimeError::suppress_response)?;
        let result = self
            .installed
            .issue_durable_outcome_unknown(
                &started.binding,
                &started.termination,
                deadline,
                ProviderCleanupMode::Normal,
            )
            .map_err(V2RuntimeError::suppress_response)?;
        self.verify_durable_outcome_unknown(
            request,
            result,
            replay,
            deadline,
        )
        .map_err(V2RuntimeError::suppress_response)
    }

    fn verify_replayed_outcome_unknown_authority(
        &self,
        request: &V2ControlRequest,
        result: V2OutcomeUnknownResult,
        record: &DurableTerminalRecord,
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        validate_replayed_outcome_unknown(request, &result, record)?;
        let binding = request.mutation_binding().ok_or_else(|| {
            V2RuntimeError::new(
                "outcome_unknown_read_forbidden",
                "read-only operations cannot replay outcome unknown",
            )
        })?;
        let signer = &self
            .verified_construction
            .outcome_reconciliation;
        validate_digest(
            &result.provider_operation_binding_sha256,
        )?;
        if result.trust_checkpoint_sha256
            != self
                .proof_independent_pins
                .trust_checkpoint_sha256
            || result.revocation_epoch
                != self.proof_independent_pins.revocation_epoch
            || result.signer_provider_id != signer.provider_id
            || result.provider_generation
                != signer.provider_generation
            || result.provider_generation
                != self.installed.generation
            || result.signer_key_id != signer.key_id
            || result.signer_key_material_sha256
                != signer.key_material_sha256
        {
            return Err(V2RuntimeError::new(
                "durable_replay_unknown_authority_mismatch",
                "replayed outcome unknown does not match the pinned signer and trust state",
            ));
        }
        let durable_start_binding = self.bind_authority_call(
            "outcome-reconciliation",
            ProviderSubchannelOperation::VerifyDurableStart,
            &record.key.request_sha256,
            request.operation(),
            &binding.attempt_id,
            binding.fencing_token,
            deadline,
        )?;
        if !self.installed.durable_start_receipt_exists(
            &durable_start_binding,
                &result.provider_operation_id,
                &result.durable_start_receipt_sha256,
                &DurableStartReceiptBinding {
                    request_sha256: &record.key.request_sha256,
                    descriptor_manifest_sha256:
                        &record.key.descriptor_manifest_sha256,
                    attempt_id: &binding.attempt_id,
                    predecessor_lifecycle_state:
                        binding.predecessor_lifecycle_state,
                    predecessor_state_sha256:
                        &binding.predecessor_state_sha256,
                    attempt_revision: binding.attempt_revision,
                    fencing_token: binding.fencing_token,
                    monotonic_deadline:
                        &binding.monotonic_deadline,
                    deadline_at_epoch_ms:
                        binding.deadline_at_epoch_ms,
                },
                deadline,
            )?
        {
            return Err(V2RuntimeError::new(
                "durable_replay_unknown_start_missing",
                "replayed outcome unknown lacks a durable start receipt",
            ));
        }
        let reconciliation_binding = self.bind_authority_call(
            "outcome-reconciliation",
            ProviderSubchannelOperation::VerifyReconciliationRecord,
            &record.key.request_sha256,
            request.operation(),
            &binding.attempt_id,
            binding.fencing_token,
            deadline,
        )?;
        if !self
            .installed
            .reconciliation_record_is_durable(
                &reconciliation_binding,
                &result.reconciliation,
                deadline,
            )?
        {
            return Err(V2RuntimeError::new(
                "durable_replay_unknown_reconciliation_missing",
                "replayed outcome unknown lacks a durable reconciliation record",
            ));
        }
        let signature = result.signature.clone();
        let mut unsigned_result = result.clone();
        unsigned_result.signature.clear();
        let unsigned = crate::canonical_json_bytes(&unsigned_result).map_err(
            |_| {
                V2RuntimeError::new(
                    "outcome_unknown_invalid",
                    "replayed outcome unknown cannot be canonicalized",
                )
            },
        )?;
        let mut signing_message =
            b"serverware.outcome-unknown/v1\0".to_vec();
        signing_message.extend_from_slice(&unsigned);
        if signature.is_empty()
            || signature.len() > 1024
            || !self.installed.verify_outcome_unknown_ed25519(
                &durable_start_binding,
                &result.signer_key_id,
                &signing_message,
                &signature,
            )
        {
            return Err(V2RuntimeError::new(
                "durable_replay_unknown_signature_invalid",
                "replayed outcome-unknown signature is invalid",
            ));
        }
        Ok(())
    }

}

fn contract_error(error: ContractError) -> V2RuntimeError {
    V2RuntimeError::new(
        error.code,
        format!("{}: {}", error.path, error.message),
    )
}

enum ProviderMode {
    Unconfigured(FailClosedProviderSet),
    Configured(Arc<ConfiguredProviderAggregate>),
}

impl ProviderMode {
    fn providers_ready(&self) -> bool {
        match self {
            Self::Unconfigured(_) => false,
            Self::Configured(providers) => {
                providers.installed.provider_ready()
                    && providers
                        .installed
                        .capabilities_ready
                        .load(Ordering::Acquire)
                    && providers
                        .supervisor
                    .generation_ready
                    .load(Ordering::Acquire)
                    && !providers
                    .supervisor
                    .quarantined
                    .load(Ordering::Acquire)
            }
        }
    }

    fn configured(&self) -> Option<&ConfiguredProviderAggregate> {
        match self {
            Self::Unconfigured(_) => None,
            Self::Configured(providers) => Some(providers.as_ref()),
        }
    }

    fn configured_arc(&self) -> Option<Arc<ConfiguredProviderAggregate>> {
        match self {
            Self::Unconfigured(_) => None,
            Self::Configured(providers) => Some(Arc::clone(providers)),
        }
    }
}

pub struct ResponseObservationV2Runtime {
    boot_id: String,
    config: Arc<RootOwnedResponseObservationV2Config>,
    providers: Arc<ProviderMode>,
    operation_state: Arc<RuntimeOperationState>,
}

impl ResponseObservationV2Runtime {
    pub fn new(
        config: RootOwnedResponseObservationV2Config,
    ) -> Result<Self, V2RuntimeError> {
        validate_config(&config)?;
        let config = Arc::new(config);
        let providers = if config.provider_router.is_some() {
            let installed =
                InstalledProviderGeneration::install(Arc::clone(
                    &config,
                ))?;
            let supervisor =
                Arc::new(RuntimeOwnedProviderSupervisor {
                    launcher: RuntimeOwnedProviderLauncher {
                        config: Arc::clone(&config),
                        installed: Arc::clone(&installed),
                    },
                    active_provider_operations:
                        Mutex::new(HashSet::new()),
                    generation_ready: AtomicBool::new(true),
                    quarantined: AtomicBool::new(false),
                });
            let aggregate =
                ConfiguredProviderAggregate::from_installed_generation(
                    &config,
                    supervisor,
                )?;
            ProviderMode::Configured(Arc::new(aggregate))
        } else {
            ProviderMode::Unconfigured(FailClosedProviderSet)
        };
        Ok(Self {
            boot_id: generate_boot_id()?,
            config,
            providers: Arc::new(providers),
            operation_state: Arc::new(RuntimeOperationState {
                active_attempts: Mutex::new(HashSet::new()),
                active_operations: AtomicUsize::new(0),
            }),
        })
    }

    pub fn boot_id(&self) -> &str {
        &self.boot_id
    }

    pub fn providers_ready(&self) -> bool {
        self.providers.providers_ready()
    }

    pub fn begin_authenticated_session(
        &self,
        client_identity: &AuthenticatedClientIdentity,
    ) -> Result<AuthenticatedSessionIdentity, V2RuntimeError> {
        let nonce = generate_hardware_proof_challenge()?;
        let mut hasher = Sha256::new();
        append_hash_frame(
            &mut hasher,
            b"serverware.response-v2/authenticated-session/v1",
        );
        append_hash_frame(&mut hasher, self.boot_id.as_bytes());
        append_hash_frame(
            &mut hasher,
            client_identity.identity_sha256().as_bytes(),
        );
        append_hash_frame(&mut hasher, nonce.as_bytes());
        Ok(AuthenticatedSessionIdentity {
            session_sha256: format!(
                "sha256:{:x}",
                hasher.finalize()
            ),
            client_identity_sha256: client_identity
                .identity_sha256()
                .to_owned(),
            _seal: AuthenticatedSessionIdentitySeal,
        })
    }

    pub fn handle_control_packet(
        &self,
        control_bytes: &[u8],
        exact_object_files: Vec<File>,
        accepted_at: Instant,
        client_identity: &AuthenticatedClientIdentity,
        session_identity: &AuthenticatedSessionIdentity,
    ) -> Result<V2ServerPacket, V2RuntimeError> {
        if session_identity.client_identity_sha256
            != client_identity.identity_sha256()
        {
            return Err(V2RuntimeError::new(
                "authenticated_session_mismatch",
                "session identity is not bound to the authenticated client",
            ));
        }
        if control_bytes.is_empty()
            || control_bytes.len() > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES
        {
            return Err(V2RuntimeError::new(
                "control_frame_out_of_bounds",
                "control packet is empty or exceeds 256 KiB",
            ));
        }
        let request: V2ControlRequest =
            crate::decode_canonical_json(control_bytes).map_err(|error| {
                V2RuntimeError::new(
                    "invalid_control_request",
                    format!(
                        "request must be duplicate-free canonical JSON satisfying the closed control envelope: {error}"
                    ),
                )
            })?;
        validate_identifier(request.request_id())?;
        let request_sha256 =
            format!("sha256:{:x}", Sha256::digest(control_bytes));
        match self.handle_valid_request(
            &request,
            &request_sha256,
            exact_object_files,
            accepted_at,
            client_identity,
            session_identity,
        ) {
            Ok(packet) => Ok(packet),
            Err(error) => {
                if error.response_is_suppressed() {
                    return Err(error);
                }
                let mut packet = self.serialize_error(
                    &request,
                    error.code,
                    error.retryable(),
                    None,
                )?;
                if let (Some(providers), Ok(binding)) = (
                    self.providers.configured(),
                    operation_binding(&request),
                ) {
                    let deadline = deadline_from_operation_binding(
                        &binding,
                        &self.boot_id,
                        accepted_at,
                        self.config.whole_operation_timeout(),
                    )?;
                    let attestation = providers
                        .verify_fresh_attestation(
                            &request_sha256,
                            &packet.response_sha256,
                            &packet.output_manifest_sha256,
                            &self.boot_id,
                            session_identity.session_sha256(),
                            client_identity.identity_sha256(),
                            &deadline,
                        )
                        .map_err(
                            V2RuntimeError::suppress_response,
                        )?;
                    packet
                        .attach_fresh_attestation(attestation)
                        .map_err(
                            V2RuntimeError::suppress_response,
                        )?;
                }
                Ok(packet)
            }
        }
    }

    fn handle_valid_request(
        &self,
        request: &V2ControlRequest,
        request_sha256: &str,
        exact_object_files: Vec<File>,
        accepted_at: Instant,
        client_identity: &AuthenticatedClientIdentity,
        session_identity: &AuthenticatedSessionIdentity,
    ) -> Result<V2ServerPacket, V2RuntimeError> {
        if request.api_version() != RESPONSE_OBSERVATION_V2_API_VERSION {
            return Err(V2RuntimeError::new(
                "unsupported_api_version",
                "request apiVersion is not response-observation custody v2",
            ));
        }
        let descriptors = request.exact_object_descriptors();

        if matches!(request, V2OperationRequest::Hello { .. }) {
            let validated = validate_exact_object_files(
                &descriptors,
                exact_object_files,
                None,
            )?;
            if !validated.by_fd_index.is_empty() {
                return Err(V2RuntimeError::new(
                    "hello_exact_objects_forbidden",
                    "hello may not carry exact objects",
                ));
            }
            if accepted_at.elapsed() >= self.config.whole_operation_timeout() {
                return Err(V2RuntimeError::new(
                    "operation_deadline_exceeded",
                    "whole-operation deadline elapsed before hello handling",
                ));
            }
            if request.boot_id().is_some() {
                return Err(V2RuntimeError::new(
                    "unexpected_boot_id",
                    "hello requires bootId to be null",
                ));
            }
            let mut hello_deadline = operation_deadline_from_now(
                self.config.whole_operation_timeout_ms,
                "operation_deadline_invalid",
            )?;
            hello_deadline.started = accepted_at;
            let providers_ready =
                self.providers.providers_ready();
            let attestation_present =
                self.providers.configured().is_some();
            let hardware_proof = attestation_present
                && self.config.attestation_mode()
                    == V2AttestationMode::TeeHardware;
            let result = V2HelloResult {
                api_version:
                    RESPONSE_OBSERVATION_V2_API_VERSION.to_string(),
                boot_id: self.boot_id.clone(),
                authenticated_client_identity_sha256: client_identity
                    .identity_sha256()
                    .to_owned(),
                pinned_genesis_state_sha256: self
                    .config
                    .proof_independent_pins
                    .pinned_genesis_state_sha256
                    .clone(),
                capabilities: RESPONSE_OBSERVATION_V2_CAPABILITIES
                    .iter()
                    .map(|capability| (*capability).to_string())
                    .collect(),
                transport: V2TransportLimits {
                    socket_type: "SOCK_SEQPACKET".to_string(),
                    max_control_bytes:
                        RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES,
                    max_exact_objects: RESPONSE_OBSERVATION_V2_MAX_OBJECTS,
                    max_exact_object_bytes:
                        RESPONSE_OBSERVATION_V2_MAX_OBJECT_BYTES,
                    whole_operation_timeout_ms: self
                        .config
                        .whole_operation_timeout_ms,
                    bulk_transfer: "sealed-memfd+SCM_RIGHTS".to_string(),
                    insecure_fallback_available: false,
                },
                providers_ready,
                attestation_mode: self.config.attestation_mode(),
                attestation_present,
                hardware_proof,
            };
            let mut packet = self.serialize_success(
                request,
                V2OperationResult::Hello(result),
                Vec::new(),
                None,
            )?;
            if let Some(providers) = self.providers.configured() {
                let attestation =
                    providers.verify_fresh_attestation(
                    request_sha256,
                    &packet.response_sha256,
                    &packet.output_manifest_sha256,
                    &self.boot_id,
                    session_identity.session_sha256(),
                    client_identity.identity_sha256(),
                    &hello_deadline,
                )
                .map_err(V2RuntimeError::suppress_response)?;
                packet
                    .attach_fresh_attestation(attestation)
                    .map_err(V2RuntimeError::suppress_response)?;
            }
            return Ok(packet);
        }

        if let V2OperationRequest::Recover { params, .. } = request {
            validate_operation_references(request)?;
            return self.handle_recovery_request(
                request,
                request_sha256,
                params,
                descriptors,
                exact_object_files,
                accepted_at,
                client_identity,
                session_identity,
            );
        }

        let binding = operation_binding(&request)?;
        validate_request_binding(
            &request,
            &self.boot_id,
            &binding,
            client_identity,
        )?;
        if matches!(request, V2OperationRequest::Reserve { .. })
            && binding.predecessor_state_sha256
                != self
                    .config
                    .proof_independent_pins
                    .pinned_genesis_state_sha256
        {
            return Err(V2RuntimeError::new(
                "genesis_state_pin_mismatch",
                "reserve predecessor digest does not match the root-owned genesis pin",
            ));
        }
        validate_operation_references(&request)?;
        let descriptor_manifest_sha256 =
            descriptor_manifest_sha256(&descriptors);
        let wall_now = system_time_epoch_ms()?;
        if binding.deadline_at_epoch_ms <= wall_now
            || binding.deadline_at_epoch_ms - wall_now
                > self.config.whole_operation_timeout_ms
        {
            return Err(V2RuntimeError::new(
                "operation_deadline_invalid",
                "deadline is expired or exceeds the configured whole-operation bound",
            ));
        }
        let deadline = deadline_from_operation_binding(
            &binding,
            &self.boot_id,
            accepted_at,
            self.config.whole_operation_timeout(),
        )?;
        if !self.providers.providers_ready() {
            return Err(V2RuntimeError::new(
                "providers_unconfigured",
                "external TEE/store/quorum/transparency/attestation providers are not configured",
            ));
        }
        let replay_key = DurableReplayKey {
            stable: StableRequestIdentity {
                request_id: request.request_id().to_owned(),
                attempt_id: binding.attempt_id.clone(),
                operation: request.operation().to_owned(),
                fencing_token: binding.fencing_token,
            },
            request_sha256: request_sha256.to_owned(),
            descriptor_manifest_sha256:
                descriptor_manifest_sha256.clone(),
        };
        let mut replay = {
            let canonical_request =
                crate::canonical_json_bytes(request).map_err(|_| {
                    V2RuntimeError::new(
                        "request_canonicalization_failed",
                        "validated request cannot be canonically encoded for durable replay",
                    )
                })?;
            match self.replay_precheck(
                replay_key,
                &canonical_request,
                &deadline,
            )? {
                ReplayPrecheck::Proceed(reservation) => reservation,
                ReplayPrecheck::Cached(record) => {
                    drop(exact_object_files);
                    let mut packet = self
                        .rehydrate_replay(request, record, &deadline)
                        .map_err(V2RuntimeError::suppress_response)?;
                    self.verify_packet_release_attestation(
                        request_sha256,
                        &mut packet,
                        client_identity,
                        session_identity,
                        &deadline,
                    )?;
                    return Ok(packet);
                }
            }
        };
        let mut completion_lease = None;
        let mut started_capability = None;
        let mut provider_process_started = false;
        let operation_result = (|| {
            if deadline.expired()? {
                return Err(V2RuntimeError::new(
                    "operation_deadline_exceeded",
                    "whole-operation deadline elapsed before provider dispatch",
                ));
            }
            completion_lease =
                Some(self.acquire_operation(&binding.attempt_id)?);
            let validated_objects = validate_exact_object_files(
                &descriptors,
                exact_object_files,
                Some(&deadline),
            )?;
            let context = OperationContext {
                binding: &binding,
                deadline: &deadline,
                _seal: OperationContextSeal,
            };
            context.ensure_live()?;
            let execution = self.execute_provider_operation(
                request,
                request_sha256,
                &descriptor_manifest_sha256,
                &context,
                &validated_objects,
                client_identity,
                &mut replay,
            )?;
            let (result, output_files) = match execution {
                ProviderExecutionOutcome::Committed {
                    result,
                    exact_objects,
                    started,
                    provider_process_started:
                        execution_provider_process_started,
                } => {
                    started_capability = started;
                    provider_process_started =
                        execution_provider_process_started;
                    context.ensure_live()?;
                    (result, exact_objects)
                }
                ProviderExecutionOutcome::OutcomeUnknown(verified) => {
                    return self.serialize_outcome_unknown(
                        request,
                        verified,
                        &mut replay,
                        completion_lease.take().ok_or_else(|| {
                            V2RuntimeError::new(
                                "runtime_state_unavailable",
                                "outcome-unknown completion lease is unavailable",
                            )
                        })?,
                        &deadline,
                    )
                    .map_err(V2RuntimeError::suppress_response);
                }
            };
            let output_references =
                durable_output_references(&result);
            let packet = self.serialize_success(
                request,
                result,
                output_files,
                Some(&deadline),
            )?;
            replay.record_terminal(
                DurableTerminalKind::Success,
                &packet.control,
                &output_references,
                &packet.exact_objects,
                &deadline,
            )
            .map_err(V2RuntimeError::suppress_response)?;
            Ok(packet.with_completion_lease(
                completion_lease.take().ok_or_else(|| {
                    V2RuntimeError::new(
                        "runtime_state_unavailable",
                        "operation completion lease is unavailable",
                    )
                })?,
            ))
        })();
        match operation_result {
            Ok(mut packet) => {
                let attestation_result =
                    self.verify_packet_release_attestation(
                    request_sha256,
                    &mut packet,
                    client_identity,
                    session_identity,
                    &deadline,
                );
                if let Err(error) = attestation_result {
                    return Err(if provider_process_started
                        || started_capability.is_some()
                    {
                        error.suppress_response()
                    } else {
                        error
                    });
                }
                Ok(packet)
            }
            Err(error) => {
                if let Some(started) =
                    started_capability.as_ref()
                {
                    let providers = self
                        .providers
                        .configured()
                        .ok_or_else(|| {
                            V2RuntimeError::new(
                                "provider_runtime_unavailable",
                                "started provider cannot be reconciled because the measured generation is unavailable",
                            )
                            .suppress_response()
                        })?;
                    let verified = providers
                        .reconcile_started_failure(
                            request,
                            started,
                            &replay,
                            &deadline,
                        )?;
                    let mut packet =
                        self.serialize_outcome_unknown(
                            request,
                            verified,
                            &mut replay,
                            completion_lease.take().ok_or_else(
                                || {
                                    V2RuntimeError::new(
                                        "runtime_state_unavailable",
                                        "started provider reconciliation completion lease is unavailable",
                                    )
                                    .suppress_response()
                                },
                            )?,
                            &deadline,
                        )?;
                    self.verify_packet_release_attestation(
                        request_sha256,
                        &mut packet,
                        client_identity,
                        session_identity,
                        &deadline,
                    )?;
                    return Ok(packet);
                }
                if provider_process_started {
                    return Err(error.suppress_response());
                }
                if error.response_is_suppressed() {
                    return Err(error);
                }
                let mut packet = self.serialize_error(
                    request,
                    error.code,
                    error.retryable(),
                    completion_lease.take(),
                )?;
                replay.record_terminal(
                    DurableTerminalKind::Denied,
                    &packet.control,
                    &[],
                    &[],
                    &deadline,
                )
                .map_err(V2RuntimeError::suppress_response)?;
                self.verify_packet_release_attestation(
                    request_sha256,
                    &mut packet,
                    client_identity,
                    session_identity,
                    &deadline,
                )
                .map_err(V2RuntimeError::suppress_response)?;
                Ok(packet)
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn handle_recovery_request(
        &self,
        request: &V2ControlRequest,
        request_sha256: &str,
        params: &V2RecoverParams,
        descriptors: Vec<ExactByteObjectDescriptor>,
        exact_object_files: Vec<File>,
        accepted_at: Instant,
        client_identity: &AuthenticatedClientIdentity,
        session_identity: &AuthenticatedSessionIdentity,
    ) -> Result<V2ServerPacket, V2RuntimeError> {
        if request.boot_id() != Some(self.boot_id.as_str()) {
            return Err(V2RuntimeError::new(
                "request_binding_mismatch",
                "recovery control envelope must bind the current custody boot while its stable replay key remains cross-boot",
            ));
        }
        validate_api_replay_key(&params.stable_request)?;
        let deadline = deadline_from_monotonic_binding(
            &params.monotonic_deadline,
            params.deadline_at_epoch_ms,
            &self.boot_id,
            accepted_at,
            self.config.whole_operation_timeout(),
        )?;
        let providers =
            self.providers.configured_arc().ok_or_else(|| {
                V2RuntimeError::new(
                    "providers_unconfigured",
                    "durable replay and recovery authorities are not configured",
                )
            })?;
        let replay_key = DurableReplayKey {
            stable: StableRequestIdentity {
                request_id: request.request_id().to_owned(),
                attempt_id: params.stable_request.attempt_id.clone(),
                operation: V2_RECOVER_OPERATION.to_owned(),
                fencing_token: params.stable_request.fencing_token,
            },
            request_sha256: request_sha256.to_owned(),
            descriptor_manifest_sha256:
                descriptor_manifest_sha256(&descriptors),
        };
        let mut replay = {
            let canonical_request =
                crate::canonical_json_bytes(request).map_err(|_| {
                    V2RuntimeError::new(
                        "request_canonicalization_failed",
                        "validated recovery request cannot be canonically encoded for durable replay",
                    )
                })?;
            match self.replay_precheck(
                replay_key,
                &canonical_request,
                &deadline,
            )? {
                ReplayPrecheck::Proceed(reservation) => reservation,
                ReplayPrecheck::Cached(record) => {
                    drop(exact_object_files);
                    let mut packet = self
                        .rehydrate_replay(request, record, &deadline)
                        .map_err(V2RuntimeError::suppress_response)?;
                    self.verify_packet_release_attestation(
                        request_sha256,
                        &mut packet,
                        client_identity,
                        session_identity,
                        &deadline,
                    )?;
                    return Ok(packet);
                }
            }
        };
        let mut completion_lease = None;
        let operation_result = (|| {
            if deadline.expired()? {
                return Err(V2RuntimeError::new(
                    "operation_deadline_exceeded",
                    "whole-operation deadline elapsed before recovery lookup",
                ));
            }
            completion_lease = Some(
                self.acquire_operation(
                    &params.stable_request.attempt_id,
                )?,
            );
            let validated_objects = validate_exact_object_files(
                &descriptors,
                exact_object_files,
                Some(&deadline),
            )?;
            let decision = providers.recover_stable_request(
                request.request_id(),
                request_sha256,
                params,
                &validated_objects,
                client_identity,
                &deadline,
            )
            .map_err(V2RuntimeError::suppress_response)?;
            let result = V2OperationResult::Recover(decision.result);
            let packet = self.serialize_success(
                request,
                result,
                Vec::new(),
                Some(&deadline),
            )
            .map_err(V2RuntimeError::suppress_response)?;
            replay
                .record_terminal(
                    DurableTerminalKind::Success,
                    &packet.control,
                    &[],
                    &[],
                    &deadline,
                )
                .map_err(V2RuntimeError::suppress_response)?;
            Ok(packet.with_completion_lease(
                completion_lease.take().ok_or_else(|| {
                    V2RuntimeError::new(
                        "runtime_state_unavailable",
                        "recovery completion lease is unavailable",
                    )
                    .suppress_response()
                })?,
            ))
        })();
        match operation_result {
            Ok(mut packet) => {
                self.verify_packet_release_attestation(
                    request_sha256,
                    &mut packet,
                    client_identity,
                    session_identity,
                    &deadline,
                )?;
                Ok(packet)
            }
            Err(error) => {
                if error.response_is_suppressed() {
                    return Err(error);
                }
                let mut packet = self.serialize_error(
                    request,
                    error.code,
                    error.retryable(),
                    completion_lease.take(),
                )?;
                replay
                    .record_terminal(
                        DurableTerminalKind::Denied,
                        &packet.control,
                        &[],
                        &[],
                        &deadline,
                    )
                    .map_err(V2RuntimeError::suppress_response)?;
                self.verify_packet_release_attestation(
                    request_sha256,
                    &mut packet,
                    client_identity,
                    session_identity,
                    &deadline,
                )?;
                Ok(packet)
            }
        }
    }

    fn replay_precheck(
        &self,
        key: DurableReplayKey,
        canonical_request: &[u8],
        deadline: &OperationDeadline,
    ) -> Result<ReplayPrecheck, V2RuntimeError> {
        if canonical_request.is_empty()
            || canonical_request.len()
                > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES
            || format!(
                "sha256:{:x}",
                Sha256::digest(canonical_request)
            ) != key.request_sha256
        {
            return Err(V2RuntimeError::new(
                "durable_replay_request_commitment_mismatch",
                "durable replay request bytes do not match the stable request digest",
            ));
        }
        let providers =
            self.providers.configured().ok_or_else(|| {
                V2RuntimeError::new(
                    "providers_unconfigured",
                    "durable replay authority is not configured",
                )
            })?;
        let adapter_binding = providers.bind_authority_call(
            "linearizable-store",
            ProviderSubchannelOperation::ReplayClaim,
            &key.request_sha256,
            &key.stable.operation,
            &key.stable.attempt_id,
            key.stable.fencing_token,
            deadline,
        )?;
        match providers
            .installed
            .claim(&adapter_binding, &key, deadline)
            .map_err(V2RuntimeError::suppress_response)?
        {
            DurableReplayDecision::Reserved(reservation) => {
                validate_replay_reservation(&reservation, &key)?;
                Ok(ReplayPrecheck::Proceed(ReplayReservation {
                    providers: Arc::clone(&providers),
                    adapter_binding,
                    reservation: Some(reservation),
                    canonical_request:
                        canonical_request.to_vec(),
                    durable_start_receipt_sha256: None,
                    retained: false,
                }))
            }
            DurableReplayDecision::Exact(record) => {
                validate_durable_terminal_record(&record, &key)?;
                if record.canonical_request != canonical_request {
                    return Err(V2RuntimeError::new(
                        "durable_replay_original_request_mismatch",
                        "durable replay record does not retain the exact original typed request",
                    ));
                }
                Ok(ReplayPrecheck::Cached(record))
            }
            DurableReplayDecision::InProgress => Err(V2RuntimeError::new(
                "request_replay_conflict",
                "an identical request is durably in progress",
            )),
            DurableReplayDecision::Conflict => Err(V2RuntimeError::new(
                "request_id_reuse",
                "stable request identity is bound to different control, attempt, operation, or fence commitments",
            )),
        }
    }

    fn rehydrate_replay(
        &self,
        request: &V2ControlRequest,
        record: DurableTerminalRecord,
        deadline: &OperationDeadline,
    ) -> Result<V2ServerPacket, V2RuntimeError> {
        validate_durable_terminal_record_self_consistency(&record)?;
        let providers =
            self.providers.configured().ok_or_else(|| {
                V2RuntimeError::new(
                    "providers_unconfigured",
                    "durable replay authority is not configured",
                )
            })?;
        let record_verify_binding = providers.bind_authority_call(
            "linearizable-store",
            ProviderSubchannelOperation::ReplayVerifyRecord,
            &record.key.request_sha256,
            &record.key.stable.operation,
            &record.key.stable.attempt_id,
            record.key.stable.fencing_token,
            deadline,
        )?;
        let recomputed_record_sha256 =
            durable_terminal_record_sha256(&record)?;
        providers
            .installed
            .verify_terminal_record_authority(
                &record_verify_binding,
                &record,
                &recomputed_record_sha256,
                deadline,
            )?;
        providers.verify_same_boot_replay_record(
            &record,
            &record_verify_binding,
            deadline,
        )?;
        let rehydrate_binding = providers.bind_authority_call(
            "linearizable-store",
            ProviderSubchannelOperation::ReplayRehydrate,
            &record.key.request_sha256,
            &record.key.stable.operation,
            &record.key.stable.attempt_id,
            record.key.stable.fencing_token,
            deadline,
        )?;
        let rehydrated = providers
            .installed
            .rehydrate_terminal_exact(
                &rehydrate_binding,
                &record,
                deadline,
            )?;
        validate_digest(&rehydrated.authority_receipt_sha256)?;
        validate_digest(&rehydrated.persistence_receipt_sha256)?;
        validate_digest(&rehydrated.retrieval_receipt_sha256)?;
        if rehydrated.authority_receipt_sha256
            != record.authority_receipt_sha256
            || rehydrated.persistence_receipt_sha256
                != record.control_persistence_receipt_sha256
            || rehydrated.canonical_response
                != record.canonical_response
            || format!(
                "sha256:{:x}",
                Sha256::digest(&rehydrated.canonical_response)
            ) != record.response_sha256
        {
            return Err(V2RuntimeError::new(
                "durable_replay_retrieval_mismatch",
                "retrieved terminal bytes and authority/persistence receipts do not match the committed replay record",
            ));
        }
        let retrieval_verify_binding =
            providers.bind_authority_call(
                "linearizable-store",
                ProviderSubchannelOperation::ReplayVerifyRetrieval,
                &record.key.request_sha256,
                &record.key.stable.operation,
                &record.key.stable.attempt_id,
                record.key.stable.fencing_token,
                deadline,
            )?;
        providers
            .installed
            .verify_terminal_retrieval_authority(
                &retrieval_verify_binding,
                &record,
                &rehydrated,
                deadline,
            )?;
        providers.verify_same_boot_replay_retrieval(
            &record,
            &rehydrated,
            &rehydrate_binding,
            deadline,
        )?;
        validate_replayed_response_for_request(request, &record)?;
        let replayed_response: V2ControlResponse =
            crate::decode_canonical_json(
                &rehydrated.canonical_response,
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "durable_replay_response_invalid",
                    "retrieved replay response is not canonical v2 control",
                )
            })?;
        if let V2ControlResponse::OutcomeUnknown { result, .. } =
            replayed_response
        {
            self.providers
                .configured()
                .ok_or_else(|| {
                    V2RuntimeError::new(
                        "providers_unconfigured",
                        "outcome-unknown replay requires configured reconciliation authorities",
                    )
                })?
                .verify_replayed_outcome_unknown_authority(
                    request,
                    result,
                    &record,
                    deadline,
                )?;
        }
        let descriptors = record
            .output_references
            .iter()
            .map(|reference| reference.descriptor.clone())
            .collect::<Vec<_>>();
        let validated = validate_exact_object_files(
            &descriptors,
            rehydrated.exact_objects,
            Some(deadline),
        )?;
        Ok(V2ServerPacket {
            response_sha256: record.response_sha256.clone(),
            control: rehydrated.canonical_response,
            exact_objects: validated.into_files(),
            output_manifest_sha256:
                descriptor_manifest_sha256(&descriptors),
            completion_lease: None,
        })
    }

    fn acquire_operation(
        &self,
        attempt_id: &str,
    ) -> Result<OperationCompletionLease, V2RuntimeError> {
        let prior = self
            .operation_state
            .active_operations
            .fetch_add(1, Ordering::AcqRel);
        if prior >= self.config.max_concurrent_operations {
            self.operation_state
                .active_operations
                .fetch_sub(1, Ordering::AcqRel);
            return Err(V2RuntimeError::new(
                "operation_capacity_exhausted",
                "bounded operation capacity is exhausted",
            ));
        }
        let mut active =
            self.operation_state.active_attempts.lock().map_err(|_| {
                self.operation_state
                    .active_operations
                    .fetch_sub(1, Ordering::AcqRel);
                V2RuntimeError::new(
                    "runtime_state_unavailable",
                    "attempt serialization state is unavailable",
                )
            })?;
        if !active.insert(attempt_id.to_owned()) {
            self.operation_state
                .active_operations
                .fetch_sub(1, Ordering::AcqRel);
            return Err(V2RuntimeError::new(
                "attempt_operation_in_progress",
                "another operation is already active for this attempt",
            ));
        }
        drop(active);
        Ok(OperationCompletionLease {
            state: Arc::clone(&self.operation_state),
            attempt_id: attempt_id.to_owned(),
        })
    }

    fn verify_packet_release_attestation(
        &self,
        request_sha256: &str,
        packet: &mut V2ServerPacket,
        client_identity: &AuthenticatedClientIdentity,
        session_identity: &AuthenticatedSessionIdentity,
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        let attestation = self.providers
            .configured()
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "providers_unconfigured",
                    "response release requires the complete measured provider generation",
                )
            })?
            .verify_fresh_hardware_proof(
                request_sha256,
                &packet.response_sha256,
                &packet.output_manifest_sha256,
                &self.boot_id,
                session_identity.session_sha256(),
                client_identity.identity_sha256(),
                deadline,
            )
            .map_err(V2RuntimeError::suppress_response)?;
        packet
            .attach_fresh_attestation(attestation)
            .map_err(V2RuntimeError::suppress_response)
    }

    fn serialize_error(
        &self,
        request: &V2ControlRequest,
        code: &str,
        retryable: bool,
        completion_lease: Option<OperationCompletionLease>,
    ) -> Result<V2ServerPacket, V2RuntimeError> {
        self.serialize_response(
            V2ControlResponse::Error {
                api_version:
                    RESPONSE_OBSERVATION_V2_API_VERSION.to_string(),
                request_id: request.request_id().to_owned(),
                boot_id: self.boot_id.clone(),
                operation: request.error_operation(),
                error: V2ErrorBody {
                    code: public_error_code(code),
                    retryable,
                },
                attestation: None,
            },
            Vec::new(),
            completion_lease,
        )
    }

    fn serialize_outcome_unknown(
        &self,
        request: &V2ControlRequest,
        verified: VerifiedOutcomeUnknown,
        replay: &mut ReplayReservation,
        completion_lease: OperationCompletionLease,
        deadline: &OperationDeadline,
    ) -> Result<V2ServerPacket, V2RuntimeError> {
        let result = verified.result;
        validate_outcome_unknown(request, &result, replay)?;
        let packet = self.serialize_response(
            V2ControlResponse::OutcomeUnknown {
                api_version:
                    RESPONSE_OBSERVATION_V2_API_VERSION.to_string(),
                request_id: request.request_id().to_owned(),
                boot_id: self.boot_id.clone(),
                operation: request.error_operation(),
                result,
                attestation: None,
            },
            Vec::new(),
            Some(completion_lease),
        )?;
        replay
            .record_outcome_unknown(&packet.control, deadline)
            .map_err(V2RuntimeError::suppress_response)?;
        Ok(packet)
    }

    fn execute_provider_operation(
        &self,
        request: &V2ControlRequest,
        request_sha256: &str,
        descriptor_manifest_sha256: &str,
        context: &OperationContext<'_>,
        objects: &ValidatedExactObjects,
        client_identity: &AuthenticatedClientIdentity,
        replay: &mut ReplayReservation,
    ) -> Result<ProviderExecutionOutcome, V2RuntimeError> {
        validate_canonical_final_envelope_input(
            &self.config,
            request,
            objects,
            context.deadline,
        )?;
        let providers =
            self.providers.configured().ok_or_else(|| {
                V2RuntimeError::new(
                    "providers_unconfigured",
                    "configured provider set is unavailable",
                )
            })?;
        if providers
            .supervisor
            .quarantined
            .load(Ordering::Acquire)
        {
            return Err(V2RuntimeError::new(
                "provider_runtime_quarantined",
                "a configured provider supervisor is hard-unready",
            )
            .suppress_response());
        }
        let canonical_control =
            crate::canonical_json_bytes(request).map_err(|_| {
                V2RuntimeError::new(
                    "provider_request_invalid",
                    "typed provider request cannot be canonicalized",
                )
            })?;
        let mutation_pin = self
            .config
            .role_identities
            .iter()
            .find(|pin| pin.role == "mutation-supervisor")
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "provider_role_unconfigured",
                    "mutation supervisor is not root-pinned",
                )
            })?;
        let provider_operation_id = provider_operation_id(
            request_sha256,
            request.operation(),
            &context.binding.attempt_id,
            context.binding.fencing_token,
            mutation_pin,
        );

        if request.mutation_binding().is_some() {
            let transition_input_sha256 = format!(
                "sha256:{:x}",
                Sha256::digest(&canonical_control)
            );
            let transition_request =
                protocol::TransitionAuthorizationRequestV1 {
                    api_version:
                        protocol::TRANSITION_AUTHORIZATION_API_VERSION
                            .to_owned(),
                    generation_id: self
                        .config
                        .custody_topology
                        .generation_id
                        .clone(),
                    generation: self
                        .config
                        .custody_topology
                        .generation,
                    request_id: request.request_id().to_owned(),
                    request_sha256: request_sha256.to_owned(),
                    attempt_id:
                        context.binding.attempt_id.clone(),
                    stable_resume_id:
                        protocol::stable_resume_id_sha256(
                            &self
                                .config
                                .custody_topology
                                .generation_id,
                            self
                                .config
                                .custody_topology
                                .generation,
                            request_sha256,
                            &context.binding.attempt_id,
                        ),
                    expected_revision:
                        context.binding.attempt_revision,
                    expected_state: String::from_utf8_lossy(
                        lifecycle_state_tag(
                            context
                                .binding
                                .predecessor_lifecycle_state,
                        ),
                    )
                    .into_owned(),
                    expected_state_sha256: context
                        .binding
                        .predecessor_state_sha256
                        .clone(),
                    fencing_token:
                        context.binding.fencing_token,
                    transition:
                        lifecycle_transition_for_request(request)?,
                    transition_input_sha256,
                    policy_decision_sha256: Some(
                        context
                            .binding
                            .transaction
                            .policy_sha256
                            .clone(),
                    ),
                    deadline_boottime_ns:
                        context.deadline.absolute_boottime_ns,
                };
            let transition_authorization =
                state::StateAuthorityClient::new(
                    &self.config.custody_topology,
                )
                .authorize_transition(&transition_request)
                .map_err(V2RuntimeError::suppress_response)?;
            let expected_live_verifier_binding_sha256 = {
                let bytes = crate::canonical_json_bytes(
                    &transition_authorization,
                )
                .map_err(|_| {
                    V2RuntimeError::new(
                        "transition_authorization_invalid",
                        "signed transition authorization cannot be canonicalized",
                    )
                })?;
                format!("sha256:{:x}", Sha256::digest(bytes))
            };
            let live_capability = OpaqueLiveOperationCapability {
                verified: None,
                request_sha256: request_sha256.to_owned(),
                client_identity_sha256:
                    client_identity.identity_sha256().to_owned(),
                attempt_id: context.binding.attempt_id.clone(),
                predecessor_lifecycle_state: context
                    .binding
                    .predecessor_lifecycle_state,
                predecessor_state_sha256: context
                    .binding
                    .predecessor_state_sha256
                    .clone(),
                attempt_revision:
                    context.binding.attempt_revision,
                fencing_token:
                    context.binding.fencing_token,
                monotonic_deadline:
                    context.binding.monotonic_deadline.clone(),
                deadline_at_epoch_ms:
                    context.binding.deadline_at_epoch_ms,
                mutation_provider_identity_sha256:
                    provider_identity_digest(
                        &providers.verified_construction.mutation,
                    ),
                mutation_provider_generation:
                    mutation_pin.provider_generation,
                mutation_provider_operation_id:
                    provider_operation_id.clone(),
                verifier_operation_binding_sha256:
                    expected_live_verifier_binding_sha256.clone(),
                verifier_provider_generation: self
                    .config
                    .custody_topology
                    .generation,
                transition_authorization:
                    Some(transition_authorization),
            };
            if live_capability.request_sha256 != request_sha256
                || live_capability.client_identity_sha256
                    != client_identity.identity_sha256()
                || live_capability.attempt_id
                    != context.binding.attempt_id
                || live_capability.predecessor_state_sha256
                    != context.binding.predecessor_state_sha256
                || live_capability.attempt_revision
                    != context.binding.attempt_revision
                || live_capability.fencing_token
                    != context.binding.fencing_token
                || live_capability.monotonic_deadline
                    != context.binding.monotonic_deadline
                || live_capability.deadline_at_epoch_ms
                    != context.binding.deadline_at_epoch_ms
                || live_capability.mutation_provider_identity_sha256
                    != provider_identity_digest(
                        &providers.verified_construction.mutation,
                    )
                || live_capability.mutation_provider_generation
                    != mutation_pin.provider_generation
                || live_capability.mutation_provider_operation_id
                    != provider_operation_id
                || live_capability.verifier_provider_generation
                    != self.config.custody_topology.generation
                || live_capability
                    .verifier_operation_binding_sha256
                    != expected_live_verifier_binding_sha256
            {
                return Err(V2RuntimeError::new(
                    "live_capability_binding_mismatch",
                    "live capability is not bound to the exact request, client, attempt, fence, deadline, and measured mutation provider",
                )
                .suppress_response());
            }
            let durable_replay_start = replay
                .start_capability()
                .map_err(V2RuntimeError::suppress_response)?;
            let terminal = providers
                .supervisor
                .supervise_bounded_seqpacket_rpc(
                    SupervisedProviderRpcRequest {
                        provider_operation_id:
                            &provider_operation_id,
                        operation: request.operation(),
                        request_sha256,
                        descriptor_manifest_sha256,
                        attempt_id:
                            &context.binding.attempt_id,
                        predecessor_state_sha256:
                            &context
                                .binding
                                .predecessor_state_sha256,
                        attempt_revision:
                            context.binding.attempt_revision,
                        fencing_token:
                            context.binding.fencing_token,
                        deadline_at_epoch_ms:
                            context.binding.deadline_at_epoch_ms,
                        canonical_control: &canonical_control,
                        exact_objects: objects,
                        live_capability,
                        durable_replay_start,
                        deadline: context.deadline,
                    },
                    replay,
                );
            return match terminal {
                SupervisedProviderRpcTerminal::Committed {
                    canonical_response,
                    exact_objects,
                    started,
                } => {
                    let result = match parse_committed_provider_response(
                        request,
                        &self.boot_id,
                        &canonical_response,
                    ) {
                        Ok(result) => result,
                        Err(_) => {
                            return Ok(
                                ProviderExecutionOutcome::OutcomeUnknown(
                                    providers
                                        .reconcile_started_failure(
                                            request,
                                            &started,
                                            replay,
                                            context.deadline,
                                        )?,
                                ),
                            );
                        }
                    };
                    Ok(ProviderExecutionOutcome::Committed {
                        result,
                        exact_objects,
                        started: Some(started),
                        provider_process_started: true,
                    })
                }
                SupervisedProviderRpcTerminal::OutcomeUnknown(result) => {
                    let verified =
                        providers.verify_durable_outcome_unknown(
                            request,
                            result,
                            replay,
                            context.deadline,
                        )
                        .map_err(
                            V2RuntimeError::suppress_response,
                        )?;
                    Ok(ProviderExecutionOutcome::OutcomeUnknown(
                        verified,
                    ))
                }
                SupervisedProviderRpcTerminal::RejectedBeforeStart(
                    error,
                ) => {
                    if error.code
                        == "provider_rejected_before_start"
                    {
                        Err(error)
                    } else {
                        Err(error.suppress_response())
                    }
                }
                SupervisedProviderRpcTerminal::HardUnready(error) => {
                    Err(error.suppress_response())
                }
            };
        }

        let archive_store_binding = providers.bind_authority_call(
            "archive-store",
            match request {
                V2OperationRequest::Retrieve { .. } => {
                    ProviderSubchannelOperation::ArchiveRetrieve
                }
                V2OperationRequest::VerifyArchive { .. } => {
                    ProviderSubchannelOperation::ArchiveVerify
                }
                _ => {
                    return Err(V2RuntimeError::new(
                        "unsupported_archive_operation",
                        "archive-store channel is allowed only for retrieve or verifyArchive",
                    ));
                }
            },
            request_sha256,
            request.operation(),
            &context.binding.attempt_id,
            context.binding.fencing_token,
            context.deadline,
        )?;
        let expected_archive_store_binding_sha256 =
            provider_operation_binding_sha256(
                &archive_store_binding,
            );
        let authorization = match request {
            V2OperationRequest::Retrieve { params, .. } => {
                let release_decision =
                    match providers.verify_public_release_authorization(
                    request_sha256,
                    descriptor_manifest_sha256,
                    &archive_store_binding,
                    params,
                    objects,
                    client_identity,
                    context.deadline,
                ) {
                    Ok(decision) => decision,
                    Err(error) => {
                        return match providers
                            .installed
                            .terminate_started_call(
                                &archive_store_binding,
                                context.deadline,
                                ProviderCleanupMode::Normal,
                            ) {
                            Ok(_) => Err(error.suppress_response()),
                            Err(_) => Err(providers
                                .installed
                                .quarantine(
                                    "provider_cleanup_unverified",
                                    "archive process could not be fenced, killed, and reaped after release authorization failure",
                                )),
                        };
                    }
                };
                match release_decision {
                    VerifiedPublicReleaseDecision::Acquired(capability) => {
                        VerifiedReadOnlyAuthorization::Retrieve(
                            capability,
                        )
                    }
                    VerifiedPublicReleaseDecision::Exact(record) => {
                        if providers
                            .installed
                            .terminate_started_call(
                                &archive_store_binding,
                                context.deadline,
                                ProviderCleanupMode::Normal,
                            )
                            .is_err()
                        {
                            return Err(providers
                                .installed
                                .quarantine(
                                    "provider_cleanup_unverified",
                                    "unused archive process could not be fenced, killed, and reaped before exact replay",
                                ));
                        }
                        let packet = self.rehydrate_replay(
                            request,
                            record,
                            context.deadline,
                        )
                        .map_err(
                            V2RuntimeError::suppress_response,
                        )?;
                        let result = parse_committed_provider_response(
                            request,
                            &self.boot_id,
                            &packet.control,
                        )
                        .map_err(
                            V2RuntimeError::suppress_response,
                        )?;
                        return Ok(
                            ProviderExecutionOutcome::Committed {
                                result,
                                exact_objects:
                                    packet.exact_objects,
                                started: None,
                                provider_process_started: true,
                            },
                        );
                    }
                }
            }
            V2OperationRequest::VerifyArchive { .. } => {
                let archive_verifier_binding =
                    match providers.bind_authority_call(
                        "archive-proof-verifier",
                        ProviderSubchannelOperation::VerifyArchiveContract,
                        request_sha256,
                        request.operation(),
                        &context.binding.attempt_id,
                        context.binding.fencing_token,
                        context.deadline,
                    ) {
                        Ok(binding) => binding,
                        Err(error) => {
                            return match providers
                                .installed
                                .terminate_started_call(
                                    &archive_store_binding,
                                    context.deadline,
                                    ProviderCleanupMode::Normal,
                                ) {
                                Ok(_) => Err(error.suppress_response()),
                                Err(_) => Err(providers
                                    .installed
                                    .quarantine(
                                        "provider_cleanup_unverified",
                                        "archive process could not be fenced, killed, and reaped after verifier launch failure",
                                    )),
                            };
                        }
                    };
                let capability = match providers
                    .installed
                    .verify_archive_capability(
                            BoundArchiveProofVerifier {
                                providers,
                                adapter_binding:
                                    archive_verifier_binding,
                                _seal: BoundArchiveProofVerifierSeal,
                            },
                            &archive_store_binding,
                            request,
                            request_sha256,
                            context,
                            objects,
                            client_identity,
                        ) {
                    Ok(capability) => capability,
                    Err(error) => {
                        return match providers
                            .installed
                            .terminate_started_call(
                                &archive_store_binding,
                                context.deadline,
                                ProviderCleanupMode::Normal,
                            ) {
                            Ok(_) => Err(error.suppress_response()),
                            Err(_) => Err(providers
                                .installed
                                .quarantine(
                                    "provider_cleanup_unverified",
                                    "archive process could not be fenced, killed, and reaped after proof verification failure",
                                )),
                        };
                    }
                };
                VerifiedReadOnlyAuthorization::VerifyArchive(
                    capability,
                )
            }
            _ => {
                return Err(V2RuntimeError::new(
                    "unsupported_provider_operation",
                    "configured provider dispatch supports only the fixed mutation, retrieve, and verifyArchive operations",
                ));
            }
        };
        match &authorization {
            VerifiedReadOnlyAuthorization::Retrieve(capability) => {
                if capability.archive_provider_generation
                    != archive_store_binding.provider_generation
                    || capability.monotonic_deadline
                        != context.binding.monotonic_deadline
                    || capability.deadline_at_epoch_ms
                        != context.binding.deadline_at_epoch_ms
                    || capability
                        .archive_store_operation_binding_sha256
                        != expected_archive_store_binding_sha256
                {
                    let error = V2RuntimeError::new(
                        "public_release_archive_binding_mismatch",
                        "release capability is not bound to the exact measured archive-store process, operation, fence, and generation",
                    );
                    return match providers
                        .installed
                        .terminate_started_call(
                            &archive_store_binding,
                            context.deadline,
                            ProviderCleanupMode::Normal,
                        )
                    {
                        Ok(_) => Err(error.suppress_response()),
                        Err(_) => Err(providers.installed.quarantine(
                            "provider_cleanup_unverified",
                            "archive process could not be fenced, killed, and reaped after release capability binding rejection",
                        )),
                    };
                }
            }
            VerifiedReadOnlyAuthorization::VerifyArchive(capability) => {
                if capability.archive_provider_generation
                    != archive_store_binding.provider_generation
                    || capability.monotonic_deadline
                        != context.binding.monotonic_deadline
                    || capability.deadline_at_epoch_ms
                        != context.binding.deadline_at_epoch_ms
                    || capability
                        .archive_store_operation_binding_sha256
                        != expected_archive_store_binding_sha256
                {
                    let error = V2RuntimeError::new(
                        "archive_capability_store_binding_mismatch",
                        "archive capability is not bound to the exact measured archive-store process, operation, fence, and generation",
                    );
                    return match providers
                        .installed
                        .terminate_started_call(
                            &archive_store_binding,
                            context.deadline,
                            ProviderCleanupMode::Normal,
                        )
                    {
                        Ok(_) => Err(error.suppress_response()),
                        Err(_) => Err(providers.installed.quarantine(
                            "provider_cleanup_unverified",
                            "archive process could not be fenced, killed, and reaped after archive capability binding rejection",
                        )),
                    };
                }
            }
        }
        let (canonical_response, exact_objects) = providers
            .supervisor
            .supervise_bounded_read_only_rpc(
                SupervisedReadOnlyRpcRequest {
                provider_binding: archive_store_binding,
                operation: request.operation(),
                request_sha256,
                deadline_at_epoch_ms:
                    context.binding.deadline_at_epoch_ms,
                canonical_control: &canonical_control,
                exact_objects: objects,
                authorization,
                },
                context.deadline,
            )
            .map_err(V2RuntimeError::suppress_response)?;
        let result = parse_committed_provider_response(
            request,
            &self.boot_id,
            &canonical_response,
        )
        .map_err(V2RuntimeError::suppress_response)?;
        Ok(ProviderExecutionOutcome::Committed {
            result,
            exact_objects,
            started: None,
            provider_process_started: true,
        })
    }

    fn serialize_success(
        &self,
        request: &V2ControlRequest,
        result: V2OperationResult,
        exact_object_files: Vec<File>,
        deadline: Option<&OperationDeadline>,
    ) -> Result<V2ServerPacket, V2RuntimeError> {
        if result.operation() != request.operation() {
            return Err(V2RuntimeError::new(
                "operation_result_mismatch",
                "provider result does not match the requested operation",
            ));
        }
        validate_result_semantics(&result, request)?;
        let output_descriptors = result_exact_object_descriptors(&result);
        let validated_outputs = validate_exact_object_files(
            &output_descriptors,
            exact_object_files,
            deadline,
        )?;
        self.serialize_response(
            V2ControlResponse::Success {
                api_version:
                    RESPONSE_OBSERVATION_V2_API_VERSION.to_string(),
                request_id: request.request_id().to_owned(),
                boot_id: self.boot_id.clone(),
                result,
                attestation: None,
            },
            validated_outputs.into_files(),
            None,
        )
    }

    fn serialize_response(
        &self,
        response: V2ControlResponse,
        exact_objects: Vec<File>,
        completion_lease: Option<OperationCompletionLease>,
    ) -> Result<V2ServerPacket, V2RuntimeError> {
        let output_manifest_sha256 = match &response {
            V2ControlResponse::Success { result, .. } => {
                descriptor_manifest_sha256(
                    &result_exact_object_descriptors(result),
                )
            }
            V2ControlResponse::Error { .. }
            | V2ControlResponse::OutcomeUnknown { .. } => {
                descriptor_manifest_sha256(&[])
            }
        };
        let bytes = crate::canonical_json_bytes(&response).map_err(|_| {
            V2RuntimeError::new(
                "serialization_failed",
                "serialize control response",
            )
        })?;
        if bytes.len() > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES {
            return Err(V2RuntimeError::new(
                "response_frame_out_of_bounds",
                "serialized control response exceeds 256 KiB",
            ));
        }
        Ok(V2ServerPacket {
            response_sha256: format!(
                "sha256:{:x}",
                Sha256::digest(&bytes)
            ),
            control: bytes,
            exact_objects,
            output_manifest_sha256,
            completion_lease,
        })
    }
}

fn validate_canonical_final_envelope_input(
    config: &RootOwnedResponseObservationV2Config,
    request: &V2ControlRequest,
    objects: &ValidatedExactObjects,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    let V2OperationRequest::Finalize { params, .. } = request else {
        return Ok(());
    };
    let object = objects
        .get(params.proof_document.fd_index)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "final_envelope_object_missing",
                "finalize requires the declared canonical final-envelope object",
            )
        })?;
    if object.descriptor.sha256
        != params.proof_document.sha256
        || object.descriptor.byte_length
            != params.proof_document.byte_length
        || object.descriptor.media_type
            != ExactObjectMediaType::CanonicalJson
    {
        return Err(V2RuntimeError::new(
            "final_envelope_object_mismatch",
            "finalize object does not match its exact canonical descriptor",
        ));
    }
    let bytes = read_bounded_exact_object(object, deadline)?;
    let envelope:
        protocol::CanonicalFinalEnvelopeDescriptorV1 =
        crate::decode_canonical_json(&bytes).map_err(|_| {
            V2RuntimeError::new(
                "final_envelope_invalid",
                "finalize accepts only the closed canonical final-envelope DTO",
            )
        })?;
    let expected_stable_resume_id =
        protocol::stable_resume_id_sha256(
            &config.custody_topology.generation_id,
            config.custody_topology.generation,
            &envelope.request_sha256,
            &envelope.attempt_id,
        );
    if envelope.api_version
            != protocol::CANONICAL_FINAL_ENVELOPE_API_VERSION
        || envelope.request_id != params.binding.request_id
        || envelope.attempt_id != params.binding.attempt_id
        || envelope.stable_resume_id
            != expected_stable_resume_id
        || envelope.terminal_revision
            != params.binding.attempt_revision
        || envelope.fencing_token != params.binding.fencing_token
        || envelope.generation_id
            != config.custody_topology.generation_id
        || envelope.generation
            != config.custody_topology.generation
    {
        return Err(V2RuntimeError::new(
            "final_envelope_binding_mismatch",
            "canonical final envelope is not bound to the exact request, attempt, revision, fence, and generation",
        ));
    }
    for digest in [
        &envelope.request_sha256,
        &envelope.transition_chain_root_sha256,
        &envelope.raw_response_object_sha256,
        &envelope.framing_validation_sha256,
        &envelope.parsed_response_sha256,
        &envelope.exact_policy_decision_sha256,
        &envelope.released_projection_sha256,
        &envelope.release_authorization_sha256,
        &envelope.evidence_root_sha256,
        &envelope.final_envelope_sha256,
    ] {
        validate_digest(digest)?;
    }
    if envelope.raw_response_byte_length == 0
        || envelope.raw_response_byte_length
            > RESPONSE_OBSERVATION_V2_MAX_OBJECT_BYTES
    {
        return Err(V2RuntimeError::new(
            "final_envelope_response_bounds_invalid",
            "canonical final envelope raw response length is invalid",
        ));
    }
    let verification_request =
        protocol::FinalEnvelopeVerificationRequestV1 {
            api_version:
                protocol::FINAL_ENVELOPE_VERIFICATION_API_VERSION
                    .to_owned(),
            operation_id: format!(
                "final-envelope-verify:{}",
                request.request_id()
            ),
            envelope: envelope.clone(),
            canonical_envelope_bytes_sha256:
                params.proof_document.sha256.clone(),
            // The policy-proof-verifier reconstructs the complete signed
            // transition chain from state-authority and immutable-ledger
            // custody. Supplying caller-selected transition records here
            // would reintroduce the reviewed authority-bypass class.
            transition_authorizations: Vec::new(),
            deadline_boottime_ns:
                deadline.absolute_boottime_ns,
        };
    services::verify_final_envelope(
        config,
        request.request_id(),
        &verification_request,
    )
    .map_err(V2RuntimeError::suppress_response)?;
    Ok(())
}

fn provider_operation_id(
    request_sha256: &str,
    operation: &str,
    attempt_id: &str,
    fencing_token: u64,
    pin: &RoleIdentityPin,
) -> String {
    let mut hasher = Sha256::new();
    append_hash_frame(
        &mut hasher,
        b"serverware.response-v2/provider-operation-id/v1",
    );
    append_hash_frame(&mut hasher, request_sha256.as_bytes());
    append_hash_frame(&mut hasher, operation.as_bytes());
    append_hash_frame(&mut hasher, attempt_id.as_bytes());
    append_hash_frame(&mut hasher, &fencing_token.to_be_bytes());
    append_hash_frame(&mut hasher, pin.role.as_bytes());
    append_hash_frame(&mut hasher, pin.provider_id.as_bytes());
    append_hash_frame(
        &mut hasher,
        &pin.provider_generation.to_be_bytes(),
    );
    append_hash_frame(
        &mut hasher,
        pin.executable_measurement_sha256.as_bytes(),
    );
    append_hash_frame(
        &mut hasher,
        pin.provider_config_sha256.as_bytes(),
    );
    format!("provider-op-{:x}", hasher.finalize())
}

fn provider_operation_id_from_scope(
    request_sha256: &str,
    operation: &str,
    attempt_id: &str,
    fencing_token: u64,
    scope: &V2ProviderAuthorityScopeV1,
) -> String {
    let mut hasher = Sha256::new();
    append_hash_frame(
        &mut hasher,
        b"serverware.response-v2/provider-operation-id/v1",
    );
    append_hash_frame(&mut hasher, request_sha256.as_bytes());
    append_hash_frame(&mut hasher, operation.as_bytes());
    append_hash_frame(&mut hasher, attempt_id.as_bytes());
    append_hash_frame(&mut hasher, &fencing_token.to_be_bytes());
    append_hash_frame(&mut hasher, scope.role.as_bytes());
    append_hash_frame(&mut hasher, scope.provider_id.as_bytes());
    append_hash_frame(
        &mut hasher,
        &scope.provider_generation.to_be_bytes(),
    );
    append_hash_frame(
        &mut hasher,
        scope.executable_measurement_sha256.as_bytes(),
    );
    append_hash_frame(
        &mut hasher,
        scope.provider_config_sha256.as_bytes(),
    );
    format!("provider-op-{:x}", hasher.finalize())
}

fn parse_committed_provider_response(
    request: &V2ControlRequest,
    custody_boot_id: &str,
    canonical_response: &[u8],
) -> Result<V2OperationResult, V2RuntimeError> {
    if canonical_response.is_empty()
        || canonical_response.len()
            > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES
    {
        return Err(V2RuntimeError::new(
            "provider_response_out_of_bounds",
            "provider response is empty or exceeds the v2 control bound",
        ));
    }
    let response: V2ControlResponse =
        crate::decode_canonical_json(canonical_response).map_err(|_| {
            V2RuntimeError::new(
                "provider_response_invalid",
                "measured provider returned noncanonical or untyped control",
            )
        })?;
    let V2ControlResponse::Success {
        api_version,
        request_id,
        boot_id,
        result,
        attestation,
    } = response
    else {
        return Err(V2RuntimeError::new(
            "provider_terminal_class_invalid",
            "committed provider terminal must be a typed success; denied and outcome-unknown use distinct channels",
        ));
    };
    if api_version != RESPONSE_OBSERVATION_V2_API_VERSION
        || request_id != request.request_id()
        || boot_id != custody_boot_id
        || result.operation() != request.operation()
        || attestation.is_some()
    {
        return Err(V2RuntimeError::new(
            "provider_response_binding_mismatch",
            "provider success is not bound to the exact request, boot, API, and operation",
        ));
    }
    validate_result_semantics(&result, request)?;
    Ok(result)
}

impl ReplayReservation {
    fn key(&self) -> Result<&DurableReplayKey, V2RuntimeError> {
        self.reservation
            .as_ref()
            .map(|reservation| &reservation.key)
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "request_ledger_transition_invalid",
                    "durable replay reservation is no longer live",
                )
            })
    }

    fn start_capability(
        &self,
    ) -> Result<DurableReplayStartCapability, V2RuntimeError> {
        let reservation = self.reservation.as_ref().ok_or_else(|| {
            V2RuntimeError::new(
                "request_ledger_transition_invalid",
                "durable replay reservation is no longer live",
            )
        })?;
        Ok(DurableReplayStartCapability {
            authority_lease: reservation.authority_lease.clone(),
            key: reservation.key.clone(),
            authority_revision: reservation.authority_revision,
            adapter_binding: self.adapter_binding.clone(),
            _seal: DurableReplayStartCapabilitySeal,
        })
    }

    fn durable_start_receipt_sha256(
        &self,
    ) -> Result<&str, V2RuntimeError> {
        self.durable_start_receipt_sha256
            .as_deref()
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "durable_start_receipt_missing",
                    "watchdog did not bind the started mutation to a durable start receipt",
                )
            })
    }

    fn acknowledge_watchdog_start(
        &mut self,
        durable_start_receipt_sha256: &str,
    ) {
        // A returned watchdog job means credentials, a process, or a durable
        // start may exist. Retain the reservation even when the returned
        // receipt is malformed so Drop can never abandon a possibly started
        // mutation.
        self.retained = true;
        self.durable_start_receipt_sha256 =
            Some(durable_start_receipt_sha256.to_owned());
    }

    fn record_outcome_unknown(
        &mut self,
        canonical_response: &[u8],
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        self.record_terminal(
            DurableTerminalKind::OutcomeUnknown,
            canonical_response,
            &[],
            &[],
            deadline,
        )
    }

    fn record_terminal(
        &mut self,
        terminal_kind: DurableTerminalKind,
        canonical_response: &[u8],
        output_references: &[DurableOutputReference],
        exact_objects: &[File],
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        if output_references.len() != exact_objects.len() {
            return Err(V2RuntimeError::new(
                "durable_terminal_output_count_mismatch",
                "every terminal output file must have one durable output reference",
            ));
        }
        let reservation = self.reservation.take().ok_or_else(|| {
            V2RuntimeError::new(
                "request_ledger_transition_invalid",
                "durable replay reservation is no longer live",
            )
        })?;
        let expected_key = reservation.key.clone();
        let expected_boot_id =
            expected_original_boot_id(canonical_response)?;
        let persist_binding = self.providers.bind_authority_call(
            "linearizable-store",
            ProviderSubchannelOperation::ReplayPersist,
            &expected_key.request_sha256,
            &expected_key.stable.operation,
            &expected_key.stable.attempt_id,
            expected_key.stable.fencing_token,
            deadline,
        )?;
        let record = self
            .providers
            .installed
            .persist_terminal_atomic(
            &persist_binding,
            reservation,
            DurableTerminalWrite {
                original_boot_id: &expected_boot_id,
                canonical_request: &self.canonical_request,
                terminal_kind,
                canonical_response,
                output_references,
            },
            exact_objects,
            deadline,
        )?;
        validate_durable_terminal_record(&record, &expected_key)?;
        validate_persisted_terminal(
            &record,
            &expected_boot_id,
            &self.canonical_request,
            terminal_kind,
            canonical_response,
            output_references,
        )?;
        let recomputed_record_sha256 =
            durable_terminal_record_sha256(&record)?;
        let verify_binding = self.providers.bind_authority_call(
            "linearizable-store",
            ProviderSubchannelOperation::ReplayVerifyRecord,
            &expected_key.request_sha256,
            &expected_key.stable.operation,
            &expected_key.stable.attempt_id,
            expected_key.stable.fencing_token,
            deadline,
        )?;
        self.providers
            .installed
            .verify_terminal_record_authority(
                &verify_binding,
                &record,
                &recomputed_record_sha256,
                deadline,
            )?;
        self.providers.verify_same_boot_replay_record(
            &record,
            &persist_binding,
            deadline,
        )?;
        self.retained = true;
        Ok(())
    }
}

impl Drop for ReplayReservation {
    fn drop(&mut self) {
        // Drop must never call an external authority: destructors cannot
        // enforce a deadline or kill a blocked provider process. An unused
        // lease remains durably reserved until its bounded authority expiry
        // and is reconciled through the normal replay/recovery path.
        let _ = self.reservation.take();
    }
}

fn stable_request_identity_matches(
    left: &StableRequestIdentity,
    right: &StableRequestIdentity,
) -> bool {
    left.request_id == right.request_id
        && left.attempt_id == right.attempt_id
        && left.operation == right.operation
        && left.fencing_token == right.fencing_token
}

fn validate_stable_request_identity(
    identity: &StableRequestIdentity,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&identity.request_id)?;
    validate_identifier(&identity.attempt_id)?;
    validate_identifier(&identity.operation)?;
    if !RESPONSE_OBSERVATION_V2_CAPABILITIES
        .contains(&identity.operation.as_str())
        || identity.operation == V2_HELLO_OPERATION
        || identity.fencing_token == 0
        || identity.fencing_token > MAX_SAFE_INTEGER
    {
        return Err(V2RuntimeError::new(
            "stable_recovery_identity_invalid",
            "stable recovery identity has an unsupported operation or fence",
        ));
    }
    Ok(())
}

fn validate_api_replay_key(
    key: &V2DurableReplayKeyV1,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&key.original_request_id)?;
    validate_digest(&key.request_sha256)?;
    validate_digest(&key.descriptor_manifest_sha256)?;
    validate_identifier(&key.attempt_id)?;
    if key.fencing_token == 0
        || key.fencing_token > MAX_SAFE_INTEGER
    {
        return Err(V2RuntimeError::new(
            "durable_replay_key_invalid",
            "durable replay key fence is invalid",
        ));
    }
    Ok(())
}

fn durable_replay_operation_label(
    operation: V2DurableReplayOperation,
) -> &'static str {
    match operation {
        V2DurableReplayOperation::Reserve => V2_RESERVE_OPERATION,
        V2DurableReplayOperation::Authority => V2_AUTHORITY_OPERATION,
        V2DurableReplayOperation::Stage => V2_STAGE_OPERATION,
        V2DurableReplayOperation::Dispatch => V2_DISPATCH_OPERATION,
        V2DurableReplayOperation::Terminal => V2_TERMINAL_OPERATION,
        V2DurableReplayOperation::Finalize => V2_FINALIZE_OPERATION,
        V2DurableReplayOperation::Attest => V2_ATTEST_OPERATION,
        V2DurableReplayOperation::Publish => V2_PUBLISH_OPERATION,
        V2DurableReplayOperation::Retrieve => V2_RETRIEVE_OPERATION,
        V2DurableReplayOperation::Recover => V2_RECOVER_OPERATION,
        V2DurableReplayOperation::VerifyArchive => {
            V2_VERIFY_ARCHIVE_OPERATION
        }
    }
}

fn durable_replay_operation(
    operation: &str,
) -> Result<V2DurableReplayOperation, V2RuntimeError> {
    match operation {
        V2_RESERVE_OPERATION => Ok(V2DurableReplayOperation::Reserve),
        V2_AUTHORITY_OPERATION => {
            Ok(V2DurableReplayOperation::Authority)
        }
        V2_STAGE_OPERATION => Ok(V2DurableReplayOperation::Stage),
        V2_DISPATCH_OPERATION => {
            Ok(V2DurableReplayOperation::Dispatch)
        }
        V2_TERMINAL_OPERATION => {
            Ok(V2DurableReplayOperation::Terminal)
        }
        V2_FINALIZE_OPERATION => {
            Ok(V2DurableReplayOperation::Finalize)
        }
        V2_ATTEST_OPERATION => Ok(V2DurableReplayOperation::Attest),
        V2_PUBLISH_OPERATION => {
            Ok(V2DurableReplayOperation::Publish)
        }
        V2_RETRIEVE_OPERATION => {
            Ok(V2DurableReplayOperation::Retrieve)
        }
        V2_RECOVER_OPERATION => Ok(V2DurableReplayOperation::Recover),
        V2_VERIFY_ARCHIVE_OPERATION => {
            Ok(V2DurableReplayOperation::VerifyArchive)
        }
        _ => Err(V2RuntimeError::new(
            "durable_replay_operation_invalid",
            "operation cannot be represented by the closed durable replay key",
        )),
    }
}

fn api_replay_key(
    key: &DurableReplayKey,
) -> Result<V2DurableReplayKeyV1, V2RuntimeError> {
    Ok(V2DurableReplayKeyV1 {
        original_request_id: key.stable.request_id.clone(),
        request_sha256: key.request_sha256.clone(),
        descriptor_manifest_sha256:
            key.descriptor_manifest_sha256.clone(),
        attempt_id: key.stable.attempt_id.clone(),
        operation: durable_replay_operation(
            &key.stable.operation,
        )?,
        fencing_token: key.stable.fencing_token,
    })
}

fn validate_durable_recovery_decision(
    decision: &DurableRecoveryDecision,
    lookup: &StableRecoveryLookup,
    client_identity_sha256: &str,
    current_trusted_now: u64,
    terminal_receipt_revoked: bool,
    resolution_revoked: bool,
    pins: &ProofIndependentPins,
    recovery_signer: &VerifiedProviderIdentity,
    recovery_verifier: &Arc<InstalledProviderGeneration>,
    recovery_adapter_binding: &VerifiedProviderOperationBinding,
    replay_signer: &VerifiedProviderIdentity,
    replay_verifier: &Arc<InstalledProviderGeneration>,
    replay_adapter_binding: &VerifiedProviderOperationBinding,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&lookup.recovery_request_id)?;
    validate_api_replay_key(&lookup.stable)?;
    validate_durable_terminal_record_self_consistency(
        &decision.terminal,
    )?;
    let recovered_receipt =
        &decision.terminal.signed_authority_receipt;
    validate_digest(
        &recovered_receipt.current_revocation_receipt_sha256,
    )?;
    if recovered_receipt.trust_root_sha256
        != pins.trust_root_sha256
        || recovered_receipt.trust_checkpoint_sha256
            != pins.trust_checkpoint_sha256
        || recovered_receipt.revocation_epoch
            != pins.revocation_epoch
        || recovered_receipt.issued_at_epoch_ms == 0
        || recovered_receipt.issued_at_epoch_ms
            > current_trusted_now
        || recovered_receipt.expires_at_epoch_ms
            <= current_trusted_now
        || terminal_receipt_revoked
        || resolution_revoked
    {
        return Err(V2RuntimeError::new(
            "durable_recovery_current_trust_invalid",
            "recovered authority artifacts are expired, revoked, or outside the current pinned trust checkpoint",
        ));
    }
    if api_replay_key(&decision.terminal.key)? != lookup.stable {
        return Err(V2RuntimeError::new(
            "durable_recovery_terminal_mismatch",
            "recovered terminal does not match the boot-independent durable replay key",
        ));
    }
    let (record, authority_evidence, resolution, expected_kind) =
        match &decision.result {
            V2RecoverResult::Success {
                replay_record,
                recovery_authority_evidence,
                signed_outcome,
            } => (
                replay_record,
                recovery_authority_evidence,
                signed_outcome,
                DurableTerminalKind::Success,
            ),
            V2RecoverResult::Denied {
                replay_record,
                recovery_authority_evidence,
                signed_outcome,
            } => (
                replay_record,
                recovery_authority_evidence,
                signed_outcome,
                DurableTerminalKind::Denied,
            ),
            V2RecoverResult::OutcomeUnknown {
                replay_record,
                recovery_authority_evidence,
                signed_outcome,
            } => (
                replay_record,
                recovery_authority_evidence,
                signed_outcome,
                DurableTerminalKind::OutcomeUnknown,
            ),
        };
    validate_evidence_reference(
        authority_evidence,
        &[V2EvidenceType::CrossBootRecoveryAuthority],
    )?;
    validate_api_durable_replay_record(
        record,
        &decision.terminal,
        &lookup.stable,
        expected_kind,
        pins,
        replay_signer,
        replay_verifier,
        replay_adapter_binding,
    )?;
    validate_identifier(&resolution.recovery_request_id)?;
    validate_digest(&resolution.subject_client_identity_sha256)?;
    validate_api_replay_key(&resolution.stable_request)?;
    validate_evidence_reference(
        &resolution.reconciliation,
        &[V2EvidenceType::CrossBootRecoveryReconciliation],
    )?;
    validate_digest(&resolution.trust_root_sha256)?;
    validate_digest(&resolution.trust_checkpoint_sha256)?;
    validate_identifier(&resolution.signer_provider_id)?;
    validate_digest(
        &resolution.provider_operation_binding_sha256,
    )?;
    validate_digest(&resolution.signer_key_id)?;
    validate_digest(&resolution.signer_key_material_sha256)?;
    if resolution.api_version
        != V2_CROSS_BOOT_RECOVERY_OUTCOME_VERSION
        || resolution.recovery_request_id
            != lookup.recovery_request_id
        || resolution.subject_client_identity_sha256
            != client_identity_sha256
        || resolution.stable_request != lookup.stable
        || resolution.output_references != record.output_references
        || resolution.trust_root_sha256 != pins.trust_root_sha256
        || resolution.trust_checkpoint_sha256
            != pins.trust_checkpoint_sha256
        || resolution.revocation_epoch != pins.revocation_epoch
        || resolution.recorded_at_epoch_ms == 0
        || resolution.recorded_at_epoch_ms > current_trusted_now
        || resolution.signer_role
            != V2RecoveryOutcomeAuthorityRole::RecoveryOutcome
        || resolution.signer_provider_id
            != recovery_signer.provider_id
        || resolution.provider_generation
            != recovery_signer.provider_generation
        || resolution.provider_generation
            != recovery_adapter_binding.provider_generation
        || resolution.provider_operation_binding_sha256
            != provider_authority_scope_sha256(
                recovery_adapter_binding,
            )
        || resolution.signer_key_id != recovery_signer.key_id
        || resolution.signer_key_material_sha256
            != recovery_signer.key_material_sha256
        || !recovery_statement_matches(
            &resolution.statement,
            record,
            &decision.terminal,
            expected_kind,
        )?
    {
        return Err(V2RuntimeError::new(
            "durable_recovery_resolution_mismatch",
            "signed recovery resolution is not bound to the exact durable terminal and recovery authority",
        ));
    }
    let signature = resolution.signature.clone();
    let mut unsigned_resolution = resolution.clone();
    unsigned_resolution.signature.clear();
    let unsigned =
        crate::canonical_json_bytes(&unsigned_resolution).map_err(|_| {
            V2RuntimeError::new(
                "durable_recovery_resolution_invalid",
                "signed recovery resolution cannot be canonicalized",
            )
        })?;
    let mut signing_message =
        b"serverware.response-v2/recovery-resolution/v1\0".to_vec();
    signing_message.extend_from_slice(&unsigned);
    if signature.is_empty()
        || signature.len() > 1024
        || !recovery_verifier.verify_resolution_ed25519(
            recovery_adapter_binding,
            &resolution.signer_key_id,
            &signing_message,
            &signature,
        )
    {
        return Err(V2RuntimeError::new(
            "durable_recovery_signature_invalid",
            "signed recovery resolution signature is invalid",
        ));
    }
    Ok(())
}

fn validate_api_durable_replay_record(
    record: &V2CanonicalDurableReplayRecordV1,
    terminal: &DurableTerminalRecord,
    expected_key: &V2DurableReplayKeyV1,
    expected_kind: DurableTerminalKind,
    pins: &ProofIndependentPins,
    signer: &VerifiedProviderIdentity,
    verifier: &Arc<InstalledProviderGeneration>,
    adapter_binding: &VerifiedProviderOperationBinding,
) -> Result<(), V2RuntimeError> {
    validate_api_replay_key(&record.key)?;
    validate_digest(&record.exact_canonical_response.sha256)?;
    validate_identifier(
        &record.exact_canonical_response.storage_reference_id,
    )?;
    validate_digest(
        &record
            .exact_canonical_response
            .persistence_receipt_sha256,
    )?;
    validate_digest(&record.output_manifest_sha256)?;
    validate_identifier(&record.commit.durable_store_id)?;
    validate_identifier(&record.commit.transaction_id)?;
    validate_digest(&record.commit.record_sha256)?;
    validate_digest(&record.commit.persistence_receipt_sha256)?;
    validate_digest(
        &record.commit.provider_operation_binding_sha256,
    )?;
    let persisted_commit_scope_sha256 =
        provider_authority_scope_sha256_from_scope(
            &record.commit.provider_operation_scope,
        );
    validate_identifier(&record.signer_provider_id)?;
    validate_digest(&record.signer_key_id)?;
    validate_digest(&record.signer_key_material_sha256)?;
    let observed_kind = match record.outcome {
        V2DurableReplayOutcome::Success => {
            DurableTerminalKind::Success
        }
        V2DurableReplayOutcome::Denied => {
            DurableTerminalKind::Denied
        }
        V2DurableReplayOutcome::OutcomeUnknown => {
            DurableTerminalKind::OutcomeUnknown
        }
    };
    if record.api_version != V2_DURABLE_REPLAY_RECORD_VERSION
        || record.key != *expected_key
        || observed_kind != expected_kind
        || terminal.terminal_kind != expected_kind
        || record.exact_canonical_response.encoding
            != V2CanonicalControlResponseEncoding::CanonicalJsonUtf8
        || record.exact_canonical_response.byte_length
            != terminal.canonical_response.len() as u64
        || record.exact_canonical_response.sha256
            != terminal.response_sha256
        || record.exact_canonical_response.storage_reference_id
            != terminal.control_storage_reference_id
        || record
            .exact_canonical_response
            .persistence_receipt_sha256
            != terminal.control_persistence_receipt_sha256
        || record.commit.commit_order
            != V2DurableReplayCommitOrder::CommittedBeforeResponseSend
        || record.commit.durable_store_id
            != pins.linearizable_store_id
        || record.commit.record_sha256 != terminal.record_sha256
        || record.commit.durable_index_revision == 0
        || record.commit.durable_index_revision > MAX_SAFE_INTEGER
        || record.commit.durable_index_revision
            != terminal.authority_revision
        || record.commit.committed_at_epoch_ms == 0
        || record.commit.committed_at_epoch_ms > MAX_SAFE_INTEGER
        || record.commit.provider_generation
            != signer.provider_generation
        || record.commit.provider_operation_scope
            != terminal
                .signed_authority_receipt
                .provider_operation_scope
        || record.commit.provider_operation_binding_sha256
            != persisted_commit_scope_sha256
        || record.signer_role
            != V2DurableReplayAuthorityRole::DurableReplayStore
        || record.signer_provider_id != signer.provider_id
        || record.signer_key_id != signer.key_id
        || record.signer_key_material_sha256
            != signer.key_material_sha256
    {
        return Err(V2RuntimeError::new(
            "durable_replay_public_record_mismatch",
            "public durable replay record is not bound to the exact terminal, store, commit order, and replay authority",
        ));
    }
    validate_api_output_references(
        &record.output_references,
        &terminal.output_references,
    )?;
    if record.output_manifest_sha256
        != durable_output_manifest_sha256(
            &record.output_references,
        )?
    {
        return Err(V2RuntimeError::new(
            "durable_output_manifest_mismatch",
            "durable output manifest digest does not match its closed output references",
        ));
    }
    let signature = record.signature.clone();
    let mut unsigned_record = record.clone();
    unsigned_record.signature.clear();
    let unsigned = crate::canonical_json_bytes(&unsigned_record).map_err(|_| {
        V2RuntimeError::new(
            "durable_replay_public_record_invalid",
            "public durable replay record cannot be canonicalized",
        )
    })?;
    let mut signing_message =
        b"serverware.response-v2/durable-replay-record/v1\0"
            .to_vec();
    signing_message.extend_from_slice(&unsigned);
    if signature.is_empty()
        || signature.len() > 1024
        || !verifier.verify_replay_record_ed25519(
            adapter_binding,
            &record.signer_key_id,
            &signing_message,
            &signature,
        )
    {
        return Err(V2RuntimeError::new(
            "durable_replay_public_record_signature_invalid",
            "public durable replay record signature is invalid",
        ));
    }
    Ok(())
}

fn validate_api_output_references(
    public: &[V2DurableReplayOutputReferenceV1],
    internal: &[DurableOutputReference],
) -> Result<(), V2RuntimeError> {
    if public.len() > RESPONSE_OBSERVATION_V2_MAX_OBJECTS * 3 {
        return Err(V2RuntimeError::new(
            "durable_output_reference_count_invalid",
            "public durable output reference count is overbound",
        ));
    }
    let exact = public
        .iter()
        .filter_map(|reference| match reference {
            V2DurableReplayOutputReferenceV1::ExactBytes(value) => {
                Some(value)
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    if exact.len() != internal.len() {
        return Err(V2RuntimeError::new(
            "durable_output_reference_count_mismatch",
            "public replay record does not contain every exact output",
        ));
    }
    for expected in internal {
        let matches = exact.iter().filter(|reference| {
            reference.media_type == expected.descriptor.media_type
                && reference.byte_length
                    == expected.descriptor.byte_length
                && reference.sha256 == expected.descriptor.sha256
                && expected.storage_reference_id.as_ref()
                    == Some(&reference.storage_reference_id)
                && expected
                    .persistence_receipt_sha256
                    .as_ref()
                    == Some(
                        &reference.persistence_receipt_sha256,
                    )
        });
        if matches.count() != 1 {
            return Err(V2RuntimeError::new(
                "durable_output_reference_mismatch",
                "public replay record does not uniquely bind an exact output descriptor",
            ));
        }
        if let Some(object) = &expected.object {
            let immutable_matches = public.iter().filter(|reference| {
                matches!(
                    reference,
                    V2DurableReplayOutputReferenceV1::ImmutableObject(
                        candidate
                    ) if candidate == object
                )
            });
            if immutable_matches.count() != 1 {
                return Err(V2RuntimeError::new(
                    "durable_immutable_output_reference_mismatch",
                    "public replay record does not uniquely bind the immutable output reference",
                ));
            }
        }
    }
    for reference in public {
        match reference {
            V2DurableReplayOutputReferenceV1::ExactBytes(reference) => {
                validate_digest(&reference.sha256)?;
                validate_identifier(&reference.storage_reference_id)?;
                validate_digest(
                    &reference.persistence_receipt_sha256,
                )?;
                if reference.byte_length == 0
                    || reference.byte_length
                        > RESPONSE_OBSERVATION_V2_MAX_OBJECT_BYTES
                {
                    return Err(V2RuntimeError::new(
                        "durable_stored_output_invalid",
                        "durable stored exact output length is invalid",
                    ));
                }
            }
            V2DurableReplayOutputReferenceV1::ImmutableObject(
                reference,
            ) => validate_immutable_reference(reference)?,
            V2DurableReplayOutputReferenceV1::Evidence(reference) => {
                validate_evidence_reference(
                    reference,
                    &[
                        V2EvidenceType::Persistence,
                        V2EvidenceType::Retrieval,
                        V2EvidenceType::ReleaseAuthorizationConsumption,
                        V2EvidenceType::OutcomeUnknownReconciliation,
                    ],
                )?;
            }
        }
    }
    Ok(())
}

fn durable_output_manifest_sha256(
    references: &[V2DurableReplayOutputReferenceV1],
) -> Result<String, V2RuntimeError> {
    let canonical =
        crate::canonical_json_bytes(&references.to_vec()).map_err(|_| {
            V2RuntimeError::new(
                "durable_output_manifest_invalid",
                "durable output references cannot be canonicalized",
            )
        })?;
    let mut hasher = Sha256::new();
    append_hash_frame(
        &mut hasher,
        b"serverware.response-v2/durable-output-manifest/v1",
    );
    append_hash_frame(&mut hasher, &canonical);
    Ok(format!("sha256:{:x}", hasher.finalize()))
}

fn recovery_statement_matches(
    statement: &V2CrossBootRecoveryStatementV1,
    record: &V2CanonicalDurableReplayRecordV1,
    terminal: &DurableTerminalRecord,
    expected_kind: DurableTerminalKind,
) -> Result<bool, V2RuntimeError> {
    let common_matches =
        |replay_record_sha256: &str,
         canonical_response_sha256: &str,
         output_manifest_sha256: &str| {
            replay_record_sha256 == record.commit.record_sha256
                && canonical_response_sha256
                    == record.exact_canonical_response.sha256
                && output_manifest_sha256
                    == record.output_manifest_sha256
        };
    Ok(match (statement, expected_kind) {
        (
            V2CrossBootRecoveryStatementV1::Success {
                replay_record_sha256,
                canonical_response_sha256,
                output_manifest_sha256,
            },
            DurableTerminalKind::Success,
        )
        | (
            V2CrossBootRecoveryStatementV1::Denied {
                replay_record_sha256,
                canonical_response_sha256,
                output_manifest_sha256,
            },
            DurableTerminalKind::Denied,
        ) => common_matches(
            replay_record_sha256,
            canonical_response_sha256,
            output_manifest_sha256,
        ),
        (
            V2CrossBootRecoveryStatementV1::OutcomeUnknown {
                replay_record_sha256,
                canonical_response_sha256,
                output_manifest_sha256,
                provider_operation_id,
                durable_start_receipt_sha256,
            },
            DurableTerminalKind::OutcomeUnknown,
        ) => {
            validate_identifier(provider_operation_id)?;
            validate_digest(durable_start_receipt_sha256)?;
            let response: V2ControlResponse =
                crate::decode_canonical_json(
                    &terminal.canonical_response,
                )
                .map_err(|_| {
                    V2RuntimeError::new(
                        "durable_recovery_unknown_invalid",
                        "outcome-unknown terminal control is invalid",
                    )
                })?;
            let unknown_matches = matches!(
                response,
                V2ControlResponse::OutcomeUnknown {
                    result,
                    ..
                } if result.provider_operation_id
                    == *provider_operation_id
                    && result.durable_start_receipt_sha256
                        == *durable_start_receipt_sha256
            );
            common_matches(
                replay_record_sha256,
                canonical_response_sha256,
                output_manifest_sha256,
            ) && unknown_matches
        }
        _ => false,
    })
}

fn replay_key_matches(
    left: &DurableReplayKey,
    right: &DurableReplayKey,
) -> bool {
    stable_request_identity_matches(&left.stable, &right.stable)
        && left.request_sha256 == right.request_sha256
        && left.descriptor_manifest_sha256
            == right.descriptor_manifest_sha256
}

fn validate_replay_reservation(
    reservation: &DurableReplayReservation,
    expected: &DurableReplayKey,
) -> Result<(), V2RuntimeError> {
    if !replay_key_matches(&reservation.key, expected)
        || reservation.authority_lease.is_empty()
        || reservation.authority_lease.len() > 4096
        || reservation.authority_revision == 0
        || reservation.authority_revision > MAX_SAFE_INTEGER
    {
        return Err(V2RuntimeError::new(
            "durable_replay_claim_invalid",
            "external replay authority returned an invalid or mismatched reservation",
        ));
    }
    Ok(())
}

fn validate_durable_terminal_record(
    record: &DurableTerminalRecord,
    expected: &DurableReplayKey,
) -> Result<(), V2RuntimeError> {
    if !replay_key_matches(&record.key, expected) {
        return Err(V2RuntimeError::new(
            "durable_replay_record_mismatch",
            "external replay authority returned a terminal for a different stable request",
        ));
    }
    validate_durable_terminal_record_self_consistency(record)
}

fn validate_recovered_original_client_binding(
    record: &DurableTerminalRecord,
    authenticated_client_identity_sha256: &str,
    require_same_boot: bool,
    recovery_deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    let original: V2ControlRequest =
        crate::decode_canonical_json(&record.canonical_request)
            .map_err(|_| {
                V2RuntimeError::new(
                    "recovery_original_request_invalid",
                    "durable recovery record does not contain a closed canonical original request",
                )
            })?;
    let binding = original
        .mutation_binding()
        .map(|binding| {
            (
                &binding.client_identity_sha256,
                &binding.monotonic_deadline,
                binding.deadline_at_epoch_ms,
            )
        })
        .or_else(|| {
            original.read_binding().map(|binding| {
                (
                    &binding.client_identity_sha256,
                    &binding.monotonic_deadline,
                    binding.deadline_at_epoch_ms,
                )
            })
        })
        .ok_or_else(|| {
            V2RuntimeError::new(
                "recovery_original_client_binding_missing",
                "durable recovery is allowed only for an original authenticated v2 lifecycle operation",
            )
        })?;
    if binding.0 != authenticated_client_identity_sha256
        || original.boot_id() != Some(record.original_boot_id.as_str())
    {
        return Err(V2RuntimeError::new(
            "recovery_original_client_binding_mismatch",
            "durable recovery record is not bound to the authenticated original client and custody boot",
        ));
    }
    if require_same_boot
        && (record.original_boot_id
            != recovery_deadline.monotonic.custody_boot_id
            || binding.1 != &recovery_deadline.monotonic
            || binding.2 != recovery_deadline.absolute_epoch_ms)
    {
        return Err(V2RuntimeError::new(
            "same_boot_recovery_deadline_mismatch",
            "same-boot recovery does not carry the original immutable lifecycle deadline",
        ));
    }
    Ok(())
}

fn validate_signed_replay_record_receipt(
    receipt: &SignedDurableTerminalAuthorityReceipt,
    record: &DurableTerminalRecord,
    binding: &VerifiedProviderOperationBinding,
    pins: &ProofIndependentPins,
    signer: &VerifiedProviderIdentity,
    trusted_now: u64,
) -> Result<(), V2RuntimeError> {
    validate_digest(&receipt.record_sha256)?;
    validate_digest(&receipt.authority_receipt_sha256)?;
    validate_digest(
        &receipt.provider_operation_binding_sha256,
    )?;
    let persisted_scope_sha256 =
        provider_authority_scope_sha256_from_scope(
            &receipt.provider_operation_scope,
        );
    let expected_provider_operation_id =
        provider_operation_id_from_scope(
            &record.key.request_sha256,
            &format!(
                "{}:linearizable-store:{:?}",
                record.key.stable.operation,
                ProviderSubchannelOperation::ReplayPersist,
            ),
            &record.key.stable.attempt_id,
            record.key.stable.fencing_token,
            &receipt.provider_operation_scope,
        );
    let require_exact_live_persist_scope =
        binding.provider_operation_id
            == expected_provider_operation_id;
    let live_persist_scope = provider_authority_scope(binding);
    validate_digest(&receipt.trust_root_sha256)?;
    validate_digest(&receipt.trust_checkpoint_sha256)?;
    validate_digest(
        &receipt.current_revocation_receipt_sha256,
    )?;
    validate_identifier(&receipt.signer_provider_id)?;
    validate_digest(&receipt.signer_key_id)?;
    validate_digest(&receipt.signer_key_material_sha256)?;
    if receipt.record_sha256 != record.record_sha256
        || receipt.authority_receipt_sha256
            != record.authority_receipt_sha256
        || receipt.provider_operation_binding_sha256
            != persisted_scope_sha256
        || receipt.provider_operation_scope.role
            != "linearizable-store"
        || receipt.provider_operation_scope.provider_id
            != signer.provider_id
        || receipt.provider_operation_scope.provider_generation
            != signer.provider_generation
        || receipt.provider_operation_scope.provider_operation_id
            != expected_provider_operation_id
        || (require_exact_live_persist_scope
            && receipt.provider_operation_scope
                != live_persist_scope)
        || receipt.provider_operation_scope.request_sha256
            != record.key.request_sha256
        || receipt.provider_operation_scope.attempt_id
            != record.key.stable.attempt_id
        || receipt.provider_operation_scope.fencing_token
            != record.key.stable.fencing_token
        || receipt
            .provider_operation_scope
            .executable_measurement_sha256
            != signer.executable_measurement_sha256
        || receipt.provider_operation_scope.provider_config_sha256
            != signer.provider_config_sha256
        || receipt.provider_operation_scope.key_material_sha256
            != signer.key_material_sha256
        || receipt.provider_operation_scope.tee_measurement_sha256
            != signer.tee_measurement_sha256
        || receipt.provider_generation
            != binding.provider_generation
        || receipt.provider_generation
            != signer.provider_generation
        || receipt.trust_root_sha256 != pins.trust_root_sha256
        || receipt.trust_checkpoint_sha256
            != pins.trust_checkpoint_sha256
        || receipt.revocation_epoch != pins.revocation_epoch
        || receipt.issued_at_epoch_ms == 0
        || receipt.issued_at_epoch_ms > trusted_now
        || receipt.expires_at_epoch_ms <= trusted_now
        || receipt.signer_provider_id != signer.provider_id
        || receipt.signer_key_id != signer.key_id
        || receipt.signer_key_material_sha256
            != signer.key_material_sha256
    {
        return Err(V2RuntimeError::new(
            "durable_replay_authority_receipt_mismatch",
            "same-boot replay receipt is not bound to the record, provider generation, current trust, and revocation state",
        ));
    }
    Ok(())
}

fn validate_signed_replay_retrieval_receipt(
    receipt: &SignedDurableTerminalRetrievalReceipt,
    record: &DurableTerminalRecord,
    rehydrated: &RehydratedDurableTerminal,
    binding: &VerifiedProviderOperationBinding,
    pins: &ProofIndependentPins,
    signer: &VerifiedProviderIdentity,
    trusted_now: u64,
) -> Result<(), V2RuntimeError> {
    validate_digest(&receipt.record_sha256)?;
    validate_digest(&receipt.response_sha256)?;
    validate_digest(&receipt.retrieval_receipt_sha256)?;
    validate_digest(
        &receipt.provider_operation_binding_sha256,
    )?;
    validate_digest(&receipt.trust_root_sha256)?;
    validate_digest(&receipt.trust_checkpoint_sha256)?;
    validate_digest(
        &receipt.current_revocation_receipt_sha256,
    )?;
    validate_identifier(&receipt.signer_provider_id)?;
    validate_digest(&receipt.signer_key_id)?;
    validate_digest(&receipt.signer_key_material_sha256)?;
    if receipt.record_sha256 != record.record_sha256
        || receipt.response_sha256 != record.response_sha256
        || receipt.retrieval_receipt_sha256
            != rehydrated.retrieval_receipt_sha256
        || receipt.provider_operation_binding_sha256
            != provider_authority_scope_sha256(binding)
        || receipt.provider_generation
            != binding.provider_generation
        || receipt.provider_generation
            != signer.provider_generation
        || receipt.trust_root_sha256 != pins.trust_root_sha256
        || receipt.trust_checkpoint_sha256
            != pins.trust_checkpoint_sha256
        || receipt.revocation_epoch != pins.revocation_epoch
        || receipt.retrieved_at_epoch_ms == 0
        || receipt.retrieved_at_epoch_ms > trusted_now
        || receipt.expires_at_epoch_ms <= trusted_now
        || receipt.expires_at_epoch_ms
            > binding.expires_at_epoch_ms
        || receipt.signer_provider_id != signer.provider_id
        || receipt.signer_key_id != signer.key_id
        || receipt.signer_key_material_sha256
            != signer.key_material_sha256
    {
        return Err(V2RuntimeError::new(
            "durable_replay_retrieval_receipt_mismatch",
            "same-boot replay retrieval is not bound to the exact record bytes, measured store operation, provider generation, current trust, and revocation state",
        ));
    }
    Ok(())
}

fn validate_durable_terminal_record_self_consistency(
    record: &DurableTerminalRecord,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&record.key.stable.request_id)?;
    validate_identifier(&record.key.stable.attempt_id)?;
    validate_identifier(&record.key.stable.operation)?;
    validate_identifier(&record.original_boot_id)?;
    validate_digest(&record.key.request_sha256)?;
    validate_digest(&record.key.descriptor_manifest_sha256)?;
    validate_digest(&record.response_sha256)?;
    validate_identifier(&record.control_storage_reference_id)?;
    validate_digest(
        &record.control_persistence_receipt_sha256,
    )?;
    validate_digest(&record.record_sha256)?;
    validate_digest(&record.authority_receipt_sha256)?;
    validate_digest(
        &record.signed_authority_receipt.record_sha256,
    )?;
    validate_digest(
        &record
            .signed_authority_receipt
            .authority_receipt_sha256,
    )?;
    validate_digest(
        &record
            .signed_authority_receipt
            .provider_operation_binding_sha256,
    )?;
    let recomputed_record_sha256 =
        durable_terminal_record_sha256(record)?;
    if record.key.stable.fencing_token == 0
        || record.key.stable.fencing_token > MAX_SAFE_INTEGER
        || record.authority_revision == 0
        || record.authority_revision > MAX_SAFE_INTEGER
        || record.canonical_request.is_empty()
        || record.canonical_request.len()
            > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES
        || record.key.request_sha256
            != format!(
                "sha256:{:x}",
                Sha256::digest(&record.canonical_request)
            )
        || record.canonical_response.is_empty()
        || record.canonical_response.len()
            > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES
        || record.response_sha256
            != format!(
                "sha256:{:x}",
                Sha256::digest(&record.canonical_response)
            )
        || record.output_references.len()
            > RESPONSE_OBSERVATION_V2_MAX_OBJECTS
        || record
            .signed_authority_receipt
            .provider_operation_binding_sha256
            != provider_authority_scope_sha256_from_scope(
                &record
                    .signed_authority_receipt
                    .provider_operation_scope,
            )
        || record.record_sha256 != recomputed_record_sha256
    {
        return Err(V2RuntimeError::new(
            "durable_replay_record_invalid",
            "external replay record violates its bounded exact-byte commitments",
        ));
    }
    let original_request: V2ControlRequest =
        crate::decode_canonical_json(&record.canonical_request).map_err(
            |_| {
                V2RuntimeError::new(
                    "durable_replay_original_request_invalid",
                    "stored original request is not canonical closed v2 control",
                )
            },
        )?;
    let original_descriptor_manifest_sha256 =
        descriptor_manifest_sha256(
            &original_request.exact_object_descriptors(),
        );
    let original_binding_matches = match &original_request {
        V2OperationRequest::Recover { params, .. } => {
            params.stable_request.attempt_id
                == record.key.stable.attempt_id
                && params.stable_request.fencing_token
                    == record.key.stable.fencing_token
        }
        _ => operation_binding(&original_request)
            .map(|binding| {
                binding.attempt_id
                    == record.key.stable.attempt_id
                    && binding.fencing_token
                        == record.key.stable.fencing_token
            })
            .unwrap_or(false),
    };
    if original_request.request_id()
        != record.key.stable.request_id
        || original_request.operation()
            != record.key.stable.operation
        || original_descriptor_manifest_sha256
            != record.key.descriptor_manifest_sha256
        || !original_binding_matches
    {
        return Err(V2RuntimeError::new(
            "durable_replay_original_request_binding_mismatch",
            "stored original typed request does not match the stable request, descriptor manifest, attempt, operation, and fence",
        ));
    }
    let response: V2ControlResponse =
        crate::decode_canonical_json(&record.canonical_response).map_err(
            |_| {
                V2RuntimeError::new(
                    "durable_replay_response_invalid",
                    "stored replay control is not a canonical closed v2 response",
                )
            },
        )?;
    let (
        request_id,
        boot_id,
        operation,
        terminal_kind,
        descriptors,
    ) = match response {
        V2ControlResponse::Success {
            request_id,
            boot_id,
            result,
            attestation,
            ..
        } => {
            if attestation.is_some() {
                return Err(V2RuntimeError::new(
                    "durable_replay_attestation_forbidden",
                    "durable replay stores the exact unsigned response and never stale session attestation",
                ));
            }
            let operation = result.operation();
            let descriptors = result_exact_object_descriptors(&result);
            (
                request_id,
                boot_id,
                operation,
                DurableTerminalKind::Success,
                descriptors,
            )
        }
        V2ControlResponse::Error {
            request_id,
            boot_id,
            operation,
            attestation,
            ..
        } => {
            if attestation.is_some() {
                return Err(V2RuntimeError::new(
                    "durable_replay_attestation_forbidden",
                    "durable replay stores the exact unsigned response and never stale session attestation",
                ));
            }
            (
                request_id,
                boot_id,
                error_operation_label(operation),
                DurableTerminalKind::Denied,
                Vec::new(),
            )
        }
        V2ControlResponse::OutcomeUnknown {
            request_id,
            boot_id,
            operation,
            attestation,
            ..
        } => {
            if attestation.is_some() {
                return Err(V2RuntimeError::new(
                    "durable_replay_attestation_forbidden",
                    "durable replay stores the exact unsigned response and never stale session attestation",
                ));
            }
            (
                request_id,
                boot_id,
                error_operation_label(operation),
                DurableTerminalKind::OutcomeUnknown,
                Vec::new(),
            )
        }
    };
    let stored_descriptors = record
        .output_references
        .iter()
        .map(|reference| reference.descriptor.clone())
        .collect::<Vec<_>>();
    if request_id != record.key.stable.request_id
        || boot_id != record.original_boot_id
        || operation != record.key.stable.operation
        || terminal_kind != record.terminal_kind
        || descriptors != stored_descriptors
    {
        return Err(V2RuntimeError::new(
            "durable_replay_response_binding_mismatch",
            "stored control, stable identity, terminal kind, and output references do not match",
        ));
    }
    validate_replayed_response_for_request(
        &original_request,
        record,
    )?;
    for reference in &record.output_references {
        validate_identifier(&reference.descriptor.object_id)?;
        validate_digest(&reference.descriptor.sha256)?;
        let storage_reference_id = reference
            .storage_reference_id
            .as_ref()
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "durable_output_storage_reference_missing",
                    "committed durable output is missing its storage reference",
                )
            })?;
        let persistence_receipt_sha256 = reference
            .persistence_receipt_sha256
            .as_ref()
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "durable_output_persistence_receipt_missing",
                    "committed durable output is missing its persistence receipt",
                )
            })?;
        validate_identifier(storage_reference_id)?;
        validate_digest(persistence_receipt_sha256)?;
        if reference.descriptor.byte_length == 0
            || reference.descriptor.byte_length
                > RESPONSE_OBSERVATION_V2_MAX_OBJECT_BYTES
        {
            return Err(V2RuntimeError::new(
                "durable_output_reference_invalid",
                "durable output descriptor length is invalid",
            ));
        }
        if let Some(object) = &reference.object {
            validate_immutable_reference(object)?;
            if object.object_sha256 != reference.descriptor.sha256
                || object.byte_length != reference.descriptor.byte_length
            {
                return Err(V2RuntimeError::new(
                    "durable_output_reference_mismatch",
                    "durable immutable output reference does not match its exact-byte descriptor",
                ));
            }
        }
    }
    Ok(())
}

fn durable_terminal_record_sha256(
    record: &DurableTerminalRecord,
) -> Result<String, V2RuntimeError> {
    let mut hasher = Sha256::new();
    append_hash_frame(
        &mut hasher,
        b"serverware.response-v2/durable-terminal-record/v1",
    );
    for value in [
        record.key.stable.request_id.as_bytes(),
        record.key.stable.attempt_id.as_bytes(),
        record.key.stable.operation.as_bytes(),
        record.key.request_sha256.as_bytes(),
        record.key.descriptor_manifest_sha256.as_bytes(),
        record.original_boot_id.as_bytes(),
        record.response_sha256.as_bytes(),
        record.control_storage_reference_id.as_bytes(),
        record
            .control_persistence_receipt_sha256
            .as_bytes(),
    ] {
        append_hash_frame(&mut hasher, value);
    }
    append_hash_frame(
        &mut hasher,
        &record.key.stable.fencing_token.to_be_bytes(),
    );
    append_hash_frame(
        &mut hasher,
        match record.terminal_kind {
            DurableTerminalKind::Success => b"SUCCESS",
            DurableTerminalKind::Denied => b"DENIED",
            DurableTerminalKind::OutcomeUnknown => b"OUTCOME_UNKNOWN",
        },
    );
    append_hash_frame(
        &mut hasher,
        &(record.canonical_request.len() as u64).to_be_bytes(),
    );
    append_hash_frame(
        &mut hasher,
        &record.canonical_request,
    );
    append_hash_frame(
        &mut hasher,
        &(record.canonical_response.len() as u64).to_be_bytes(),
    );
    for reference in &record.output_references {
        let descriptor =
            crate::canonical_json_bytes(&reference.descriptor).map_err(
                |_| {
                    V2RuntimeError::new(
                        "durable_replay_record_invalid",
                        "durable output descriptor cannot be canonicalized",
                    )
                },
            )?;
        append_hash_frame(&mut hasher, &descriptor);
        if let Some(object) = &reference.object {
            let object =
                crate::canonical_json_bytes(object).map_err(|_| {
                    V2RuntimeError::new(
                        "durable_replay_record_invalid",
                        "durable immutable output cannot be canonicalized",
                    )
                })?;
            append_hash_frame(&mut hasher, &object);
        } else {
            append_hash_frame(&mut hasher, b"NONE");
        }
        append_hash_frame(
            &mut hasher,
            reference
                .storage_reference_id
                .as_deref()
                .unwrap_or("")
                .as_bytes(),
        );
        append_hash_frame(
            &mut hasher,
            reference
                .persistence_receipt_sha256
                .as_deref()
                .unwrap_or("")
                .as_bytes(),
        );
    }
    append_hash_frame(
        &mut hasher,
        &record.authority_revision.to_be_bytes(),
    );
    Ok(format!("sha256:{:x}", hasher.finalize()))
}

fn validate_replayed_response_for_request(
    request: &V2ControlRequest,
    record: &DurableTerminalRecord,
) -> Result<(), V2RuntimeError> {
    let response: V2ControlResponse =
        crate::decode_canonical_json(&record.canonical_response).map_err(
            |_| {
                V2RuntimeError::new(
                    "durable_replay_response_invalid",
                    "retrieved replay response is not exact canonical v2 control",
                )
            },
        )?;
    match &response {
        V2ControlResponse::Success {
            request_id,
            boot_id,
            result,
            ..
        } => {
            if request_id != request.request_id()
                || boot_id != &record.original_boot_id
                || result.operation() != request.operation()
            {
                return Err(V2RuntimeError::new(
                    "durable_replay_success_mismatch",
                    "replayed success is not bound to the exact request, boot, and operation",
                ));
            }
            validate_result_semantics(result, request)?;
        }
        V2ControlResponse::Error {
            request_id,
            boot_id,
            operation,
            ..
        } => {
            if request_id != request.request_id()
                || boot_id != &record.original_boot_id
                || error_operation_label(*operation)
                    != request.operation()
            {
                return Err(V2RuntimeError::new(
                    "durable_replay_denial_mismatch",
                    "replayed denial is not bound to the exact request, boot, and operation",
                ));
            }
        }
        V2ControlResponse::OutcomeUnknown {
            request_id,
            boot_id,
            operation,
            result,
            ..
        } => {
            if request_id != request.request_id()
                || boot_id != &record.original_boot_id
                || error_operation_label(*operation)
                    != request.operation()
            {
                return Err(V2RuntimeError::new(
                    "durable_replay_unknown_mismatch",
                    "replayed outcome-unknown is not bound to the exact request, boot, and operation",
                ));
            }
            validate_replayed_outcome_unknown(request, result, record)?;
        }
    }
    Ok(())
}

fn validate_replayed_outcome_unknown(
    request: &V2ControlRequest,
    result: &V2OutcomeUnknownResult,
    record: &DurableTerminalRecord,
) -> Result<(), V2RuntimeError> {
    let binding = request.mutation_binding().ok_or_else(|| {
        V2RuntimeError::new(
            "outcome_unknown_read_forbidden",
            "read-only operations cannot replay outcome unknown",
        )
    })?;
    let expected_revision = binding
        .attempt_revision
        .checked_add(1)
        .filter(|revision| *revision <= MAX_SAFE_INTEGER)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "attempt_revision_overflow",
                "outcome-unknown revision cannot advance",
            )
        })?;
    validate_identifier(&result.provider_operation_id)?;
    validate_digest(&result.durable_start_receipt_sha256)?;
    validate_evidence_reference(
        &result.reconciliation,
        &[V2EvidenceType::OutcomeUnknownReconciliation],
    )?;
    if result.attempt.attempt_id != binding.attempt_id
        || result.attempt.state != V2AttemptState::OutcomeUnknown
        || result.attempt.attempt_revision != expected_revision
        || result.attempt.fencing_token != binding.fencing_token
        || result.request_sha256 != record.key.request_sha256
        || result.descriptor_manifest_sha256
            != record.key.descriptor_manifest_sha256
        || result.signature.is_empty()
        || result.signature.len() > 1024
    {
        return Err(V2RuntimeError::new(
            "durable_replay_unknown_binding_mismatch",
            "replayed outcome unknown is not bound to the original request, attempt, revision, and fence",
        ));
    }
    Ok(())
}

fn validate_persisted_terminal(
    record: &DurableTerminalRecord,
    expected_boot_id: &str,
    canonical_request: &[u8],
    terminal_kind: DurableTerminalKind,
    canonical_response: &[u8],
    output_references: &[DurableOutputReference],
) -> Result<(), V2RuntimeError> {
    let output_commitments_match =
        record.output_references.len() == output_references.len()
            && record
                .output_references
                .iter()
                .zip(output_references)
                .all(|(stored, expected)| {
                    stored.descriptor == expected.descriptor
                        && stored.object == expected.object
                });
    if record.original_boot_id != expected_boot_id
        || record.canonical_request != canonical_request
        || record.terminal_kind != terminal_kind
        || record.canonical_response != canonical_response
        || !output_commitments_match
    {
        return Err(V2RuntimeError::new(
            "durable_terminal_commit_mismatch",
            "external replay authority did not atomically retain the exact terminal bytes and output references",
        ));
    }
    Ok(())
}

fn expected_original_boot_id(
    canonical_response: &[u8],
) -> Result<String, V2RuntimeError> {
    let response: V2ControlResponse =
        crate::decode_canonical_json(canonical_response).map_err(|_| {
            V2RuntimeError::new(
                "durable_terminal_response_invalid",
                "terminal response is not canonical closed v2 control",
            )
        })?;
    Ok(match response {
        V2ControlResponse::Success { boot_id, .. }
        | V2ControlResponse::Error { boot_id, .. }
        | V2ControlResponse::OutcomeUnknown { boot_id, .. } => boot_id,
    })
}

fn durable_output_references(
    result: &V2OperationResult,
) -> Vec<DurableOutputReference> {
    let immutable = match result {
        V2OperationResult::Retrieve(result) => Some(result.object.clone()),
        _ => None,
    };
    result_exact_object_descriptors(result)
        .into_iter()
        .map(|descriptor| DurableOutputReference {
            descriptor,
            object: immutable.clone(),
            storage_reference_id: None,
            persistence_receipt_sha256: None,
        })
        .collect()
}

fn error_operation_label(operation: V2ErrorOperation) -> &'static str {
    match operation {
        V2ErrorOperation::Hello => V2_HELLO_OPERATION,
        V2ErrorOperation::Reserve => V2_RESERVE_OPERATION,
        V2ErrorOperation::Authority => V2_AUTHORITY_OPERATION,
        V2ErrorOperation::Stage => V2_STAGE_OPERATION,
        V2ErrorOperation::Dispatch => V2_DISPATCH_OPERATION,
        V2ErrorOperation::Terminal => V2_TERMINAL_OPERATION,
        V2ErrorOperation::Finalize => V2_FINALIZE_OPERATION,
        V2ErrorOperation::Attest => V2_ATTEST_OPERATION,
        V2ErrorOperation::Publish => V2_PUBLISH_OPERATION,
        V2ErrorOperation::Retrieve => V2_RETRIEVE_OPERATION,
        V2ErrorOperation::Recover => V2_RECOVER_OPERATION,
        V2ErrorOperation::VerifyArchive => {
            V2_VERIFY_ARCHIVE_OPERATION
        }
        V2ErrorOperation::Unknown => "UNKNOWN",
    }
}

fn descriptor_manifest_sha256(
    descriptors: &[ExactByteObjectDescriptor],
) -> String {
    let mut ordered = descriptors.iter().collect::<Vec<_>>();
    ordered.sort_by_key(|descriptor| descriptor.fd_index);
    let mut hasher = Sha256::new();
    append_hash_frame(
        &mut hasher,
        b"serverware.response-v2/exact-object-manifest/v1",
    );
    for descriptor in ordered {
        append_hash_frame(&mut hasher, &descriptor.fd_index.to_be_bytes());
        append_hash_frame(
            &mut hasher,
            &descriptor.byte_length.to_be_bytes(),
        );
        append_hash_frame(&mut hasher, descriptor.sha256.as_bytes());
        append_hash_frame(&mut hasher, descriptor.object_id.as_bytes());
        append_hash_frame(
            &mut hasher,
            exact_media_type_label(descriptor.media_type),
        );
        append_hash_frame(
            &mut hasher,
            memfd_seal_label(descriptor.required_seals),
        );
    }
    format!("sha256:{:x}", hasher.finalize())
}

fn memfd_seal_label(profile: MemfdSealProfile) -> &'static [u8] {
    match profile {
        MemfdSealProfile::ImmutableV1 => b"IMMUTABLE_V1",
    }
}

fn exact_media_type_label(media_type: ExactObjectMediaType) -> &'static [u8] {
    match media_type {
        ExactObjectMediaType::CanonicalJson => b"CANONICAL_JSON",
        ExactObjectMediaType::Http11Request => b"HTTP11_REQUEST",
        ExactObjectMediaType::Http11Response => b"HTTP11_RESPONSE",
        ExactObjectMediaType::EvidenceBundle => b"EVIDENCE_BUNDLE",
        ExactObjectMediaType::AttestationArtifact => {
            b"ATTESTATION_ARTIFACT"
        }
        ExactObjectMediaType::PublicationArtifact => {
            b"PUBLICATION_ARTIFACT"
        }
        ExactObjectMediaType::OpaqueProviderArtifact => {
            b"OPAQUE_PROVIDER_ARTIFACT"
        }
    }
}

fn validate_result_semantics(
    result: &V2OperationResult,
    request: &V2ControlRequest,
) -> Result<(), V2RuntimeError> {
    let binding = request.mutation_binding();
    if binding.is_some() {
        let observed_transition_evidence = match result {
            V2OperationResult::Reserve(
                V2ReserveResult::Denied {
                    terminal_evidence,
                    ..
                },
            ) => Some(terminal_evidence),
            V2OperationResult::Reserve(
                V2ReserveResult::Reserved {
                    reservation_evidence,
                    ..
                },
            ) => Some(reservation_evidence),
            V2OperationResult::Authority(
                V2AuthorityResult::Ready {
                    authority_state,
                    ..
                },
            ) => Some(authority_state),
            V2OperationResult::Authority(
                V2AuthorityResult::Terminalized {
                    terminal_evidence,
                    ..
                },
            ) => Some(terminal_evidence),
            V2OperationResult::Stage(result) => {
                Some(&result.staging_evidence)
            }
            V2OperationResult::Dispatch(result) => {
                Some(&result.dispatch_evidence)
            }
            V2OperationResult::Terminal(result) => {
                Some(&result.terminal_evidence)
            }
            V2OperationResult::Finalize(result) => {
                Some(&result.finalization_checkpoint)
            }
            V2OperationResult::Attest(result) => {
                Some(&result.artifact_time_checkpoint)
            }
            V2OperationResult::Publish(result) => {
                Some(&result.artifact_time_checkpoint)
            }
            _ => None,
        };
        let expected_transition_evidence =
            response_observation_v2_transition_evidence_sha256(
                request,
                result,
            );
        if observed_transition_evidence
            .map(|evidence| evidence.evidence_sha256.as_str())
            != expected_transition_evidence.as_deref()
        {
            return Err(V2RuntimeError::new(
                "transition_evidence_binding_mismatch",
                "transition evidence does not bind the exact typed result references and successor state",
            ));
        }
    }
    match result {
        V2OperationResult::Hello(result) => {
            validate_digest(
                &result.authenticated_client_identity_sha256,
            )?;
            if result.api_version != RESPONSE_OBSERVATION_V2_API_VERSION
                || result.capabilities
                    != RESPONSE_OBSERVATION_V2_CAPABILITIES
                        .iter()
                        .map(|value| (*value).to_string())
                        .collect::<Vec<_>>()
                || result.transport.insecure_fallback_available
            {
                return Err(V2RuntimeError::new(
                    "invalid_hello_result",
                    "hello result does not match the fixed v2 contract",
                ));
            }
        }
        V2OperationResult::Reserve(result) => match result {
            V2ReserveResult::Denied {
                attempt,
                terminal_evidence,
            } => {
                validate_attempt_transition(
                    request,
                    attempt,
                    result_binding(&binding)?,
                    &terminal_evidence.evidence_sha256,
                )?;
                validate_evidence_reference(
                    terminal_evidence,
                    &[V2EvidenceType::Terminal],
                )?;
            }
            V2ReserveResult::Reserved {
                attempt,
                reservation_evidence,
            } => {
                validate_attempt_transition(
                    request,
                    attempt,
                    result_binding(&binding)?,
                    &reservation_evidence.evidence_sha256,
                )?;
                validate_evidence_reference(
                    reservation_evidence,
                    &[V2EvidenceType::Reservation],
                )?;
            }
        },
        V2OperationResult::Authority(result) => match result {
            V2AuthorityResult::Ready {
                attempt,
                authority_evidence_root,
                authority_state,
            } => {
                validate_attempt_transition(
                    request,
                    attempt,
                    result_binding(&binding)?,
                    &authority_state.evidence_sha256,
                )?;
                validate_evidence_reference(
                    authority_evidence_root,
                    &[V2EvidenceType::AuthorityEvidenceRoot],
                )?;
                validate_evidence_reference(
                    authority_state,
                    &[V2EvidenceType::AuthorityState],
                )?;
            }
            V2AuthorityResult::Terminalized {
                attempt,
                terminal_evidence,
            } => {
                validate_attempt_transition(
                    request,
                    attempt,
                    result_binding(&binding)?,
                    &terminal_evidence.evidence_sha256,
                )?;
                validate_evidence_reference(
                    terminal_evidence,
                    &[V2EvidenceType::Terminal],
                )?;
            }
        },
        V2OperationResult::Stage(result) => {
            validate_attempt_transition(
                request,
                &result.attempt,
                result_binding(&binding)?,
                &result.staging_evidence.evidence_sha256,
            )?;
            validate_immutable_reference(&result.staged_request)?;
            expect_object_type(
                &result.staged_request,
                &[ImmutableObjectType::StagedRequest],
            )?;
            validate_evidence_reference(
                &result.staging_evidence,
                &[V2EvidenceType::Staging],
            )?;
        }
        V2OperationResult::Dispatch(result) => {
            validate_attempt_transition(
                request,
                &result.attempt,
                result_binding(&binding)?,
                &result.dispatch_evidence.evidence_sha256,
            )?;
            validate_evidence_reference(
                &result.dispatch_evidence,
                &[V2EvidenceType::Dispatch],
            )?;
            validate_immutable_reference(&result.upstream_response)?;
            expect_object_type(
                &result.upstream_response,
                &[ImmutableObjectType::UpstreamResponse],
            )?;
        }
        V2OperationResult::Terminal(result) => {
            let V2OperationRequest::Terminal { params, .. } = request else {
                return Err(V2RuntimeError::new(
                    "operation_result_mismatch",
                    "terminal result requires terminal request parameters",
                ));
            };
            let expected_state = match params.terminal_kind {
                V2TerminalKind::Cancelled => V2AttemptState::Cancelled,
                V2TerminalKind::Failed => V2AttemptState::Failed,
                V2TerminalKind::Completed => V2AttemptState::Completed,
                V2TerminalKind::OutcomeUnknown => {
                    V2AttemptState::OutcomeUnknown
                }
            };
            validate_attempt_transition(
                request,
                &result.attempt,
                result_binding(&binding)?,
                &result.terminal_evidence.evidence_sha256,
            )?;
            if result.attempt.state != expected_state {
                return Err(V2RuntimeError::new(
                    "terminal_result_state_mismatch",
                    "terminal result does not match the requested terminal kind",
                ));
            }
            validate_evidence_reference(
                &result.terminal_evidence,
                &[V2EvidenceType::Terminal],
            )?;
        }
        V2OperationResult::Finalize(result) => {
            validate_attempt_transition(
                request,
                &result.attempt,
                result_binding(&binding)?,
                &result.finalization_checkpoint.evidence_sha256,
            )?;
            validate_immutable_reference(&result.envelope)?;
            expect_object_type(
                &result.envelope,
                &[ImmutableObjectType::ResponseObservationEnvelope],
            )?;
            validate_evidence_reference(
                &result.persistence_evidence,
                &[V2EvidenceType::Persistence],
            )?;
            validate_evidence_reference(
                &result.finalization_checkpoint,
                &[V2EvidenceType::FinalizationCheckpoint],
            )?;
            if let Some(finalized) = &result.finalized_response {
                validate_immutable_reference(finalized)?;
                expect_object_type(
                    finalized,
                    &[ImmutableObjectType::ReleasedResponse],
                )?;
            }
            if result.finalized_response.is_some()
                != result.release_cas_expectation.is_some()
            {
                return Err(V2RuntimeError::new(
                    "finalized_release_state_mismatch",
                    "finalized response and release CAS predecessor must be returned together",
                ));
            }
            if let Some(expectation) =
                &result.release_cas_expectation
            {
                validate_digest(
                    &expectation.expected_unconsumed_state_sha256,
                )?;
                if expectation.expected_authority_revision == 0
                    || expectation.expected_authority_revision
                        > MAX_SAFE_INTEGER
                {
                    return Err(V2RuntimeError::new(
                        "finalized_release_cas_invalid",
                        "finalized release CAS predecessor is invalid",
                    ));
                }
            }
        }
        V2OperationResult::Attest(result) => {
            validate_attempt_transition(
                request,
                &result.attempt,
                result_binding(&binding)?,
                &result.artifact_time_checkpoint.evidence_sha256,
            )?;
            validate_immutable_reference(&result.attestation_artifact)?;
            expect_object_type(
                &result.attestation_artifact,
                &[ImmutableObjectType::AttestationArtifact],
            )?;
            validate_evidence_reference(
                &result.artifact_time_checkpoint,
                &[V2EvidenceType::ArtifactTimeCheckpoint],
            )?;
        }
        V2OperationResult::Publish(result) => {
            let V2OperationRequest::Publish { params, .. } = request else {
                return Err(V2RuntimeError::new(
                    "operation_result_mismatch",
                    "publish result requires publish request parameters",
                ));
            };
            validate_attempt_transition(
                request,
                &result.attempt,
                result_binding(&binding)?,
                &result.artifact_time_checkpoint.evidence_sha256,
            )?;
            validate_immutable_reference(&result.publication_artifact)?;
            expect_object_type(
                &result.publication_artifact,
                &[ImmutableObjectType::PublicationArtifact],
            )?;
            validate_evidence_reference(
                &result.artifact_time_checkpoint,
                &[V2EvidenceType::ArtifactTimeCheckpoint],
            )?;
            validate_immutable_reference(&result.released_object)?;
            expect_object_type(
                &result.released_object,
                &[ImmutableObjectType::ReleasedResponse],
            )?;
            expect_media(
                &result.public_release_authorization,
                &[ExactObjectMediaType::EvidenceBundle],
            )?;
            if result.released_object != params.release_intent.object
                || result.release_cas_expectation
                    != params.release_intent.release_cas_expectation
            {
                return Err(V2RuntimeError::new(
                    "publish_release_intent_mismatch",
                    "publish result does not match the exact future retrieve intent",
                ));
            }
        }
        V2OperationResult::Retrieve(result) => {
            let V2OperationRequest::Retrieve { params, .. } = request else {
                return Err(V2RuntimeError::new(
                    "operation_result_mismatch",
                    "retrieve result requires retrieve request parameters",
                ));
            };
            validate_immutable_reference(&result.object)?;
            validate_evidence_reference(
                &result.retrieval_evidence,
                &[V2EvidenceType::Retrieval],
            )?;
            validate_retrievable_object(&result.object)?;
            let expected_media =
                retrievable_media_type(result.object.object_type)?;
            if result.object != params.object
                || result.exact_bytes.object_id != result.object.retrieval_id
                || result.exact_bytes.media_type != expected_media
                || result.exact_bytes.sha256 != result.object.object_sha256
                || result.exact_bytes.byte_length != result.object.byte_length
                || result.exact_bytes.fd_index != 0
                || result.exact_bytes.required_seals
                    != MemfdSealProfile::ImmutableV1
            {
                return Err(V2RuntimeError::new(
                    "retrieval_result_mismatch",
                    "retrieved exact bytes do not match the immutable object reference",
                ));
            }
            validate_retrieve_result_commitments(
                request,
                params,
                result,
            )?;
        }
        V2OperationResult::Recover(result) => {
            let V2OperationRequest::Recover {
                request_id,
                params,
                ..
            } = request
            else {
                return Err(V2RuntimeError::new(
                    "operation_result_mismatch",
                    "recover result requires recover request parameters",
                ));
            };
            validate_recover_result_basic(result, params, request_id)?;
        }
        V2OperationResult::VerifyArchive(result) => {
            let binding = request.read_binding().ok_or_else(|| {
                V2RuntimeError::new(
                    "archive_result_binding_missing",
                    "archive result is missing its read binding",
                )
            })?;
            validate_identifier(&result.attempt_id)?;
            if result.attempt_id != binding.attempt_id {
                return Err(V2RuntimeError::new(
                    "archive_result_binding_mismatch",
                    "archive result attempt does not match the read binding",
                ));
            }
            validate_immutable_reference(&result.envelope)?;
            expect_object_type(
                &result.envelope,
                &[ImmutableObjectType::ResponseObservationEnvelope],
            )?;
            validate_evidence_reference(
                &result.verification_evidence,
                &[V2EvidenceType::ArchiveVerification],
            )?;
        }
    }
    Ok(())
}

fn validate_retrieve_result_commitments(
    request: &V2ControlRequest,
    params: &V2RetrieveParams,
    result: &V2RetrieveResult,
) -> Result<(), V2RuntimeError> {
    let canonical_request =
        crate::canonical_json_bytes(request).map_err(|_| {
            V2RuntimeError::new(
                "retrieval_request_binding_invalid",
                "retrieve request cannot be canonically bound",
            )
        })?;
    let request_sha256 = format!(
        "sha256:{:x}",
        Sha256::digest(&canonical_request)
    );
    let descriptor_manifest_sha256 =
        descriptor_manifest_sha256(
            &request.exact_object_descriptors(),
        );
    let signed =
        &result.release_authorization_consumption;
    let consume = &signed.consume;
    validate_identifier(&consume.authorization_id)?;
    validate_identifier(&consume.one_use_nonce)?;
    validate_digest(&consume.request_sha256)?;
    validate_digest(&consume.descriptor_manifest_sha256)?;
    validate_digest(
        &consume.subject_client_identity_sha256,
    )?;
    validate_digest(
        &consume.expected_unconsumed_state_sha256,
    )?;
    let expected_commitment = V2ReleaseRequestCommitmentV1 {
        api_version:
            V2_RELEASE_REQUEST_COMMITMENT_VERSION.to_owned(),
        request_id: params.binding.request_id.clone(),
        subject_client_identity_sha256:
            params.binding.client_identity_sha256.clone(),
        object: params.object.clone(),
        attempt_id: params.binding.attempt_id.clone(),
        lifecycle_state: params.binding.lifecycle_state,
        state_sha256: params.binding.state_sha256.clone(),
        attempt_revision: params.binding.attempt_revision,
        fencing_token: params.binding.fencing_token,
        monotonic_deadline:
            params.binding.monotonic_deadline.clone(),
        deadline_at_epoch_ms:
            params.binding.deadline_at_epoch_ms,
        one_use_nonce: consume.one_use_nonce.clone(),
        release_cas_expectation:
            params.release_cas_expectation.clone(),
    };
    let expected_commitment_sha256 =
        response_observation_v2_release_request_commitment_sha256(
            &expected_commitment,
        )
        .ok_or_else(|| {
            V2RuntimeError::new(
                "retrieval_release_commitment_invalid",
                "retrieve release commitment cannot be canonically bound",
            )
        })?;
    let expected_consume_binding_sha256 =
        response_observation_v2_release_consume_binding_sha256(
            consume,
        )
        .ok_or_else(|| {
            V2RuntimeError::new(
                "retrieval_consume_binding_invalid",
                "retrieve consumption CAS cannot be canonically bound",
            )
        })?;
    let expected_authority_revision = params
        .release_cas_expectation
        .expected_authority_revision
        .checked_add(1)
        .filter(|revision| *revision <= MAX_SAFE_INTEGER)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "retrieval_consume_revision_invalid",
                "retrieve consumption revision cannot advance",
            )
        })?;
    let (authority_revision, consume_binding_sha256, receipt) =
        match &signed.outcome {
            V2ReleaseAuthorizationConsumeOutcomeV1::
                ConsumedBeforeRelease {
                    authority_revision,
                    consume_binding_sha256,
                    consumption_receipt_sha256,
                } => (
                    *authority_revision,
                    consume_binding_sha256,
                    consumption_receipt_sha256,
                ),
            V2ReleaseAuthorizationConsumeOutcomeV1::ExactReplay {
                authority_revision,
                consume_binding_sha256,
                consumption_receipt_sha256,
                replay_record_sha256,
                replay_key,
                exact_canonical_response,
            } => {
                validate_digest(replay_record_sha256)?;
                validate_api_replay_key(replay_key)?;
                validate_digest(
                    &exact_canonical_response.sha256,
                )?;
                validate_identifier(
                    &exact_canonical_response
                        .storage_reference_id,
                )?;
                validate_digest(
                    &exact_canonical_response
                        .persistence_receipt_sha256,
                )?;
                if replay_key.original_request_id
                    != params.binding.request_id
                    || replay_key.request_sha256 != request_sha256
                    || replay_key.descriptor_manifest_sha256
                        != descriptor_manifest_sha256
                    || replay_key.attempt_id
                        != params.binding.attempt_id
                    || replay_key.operation
                        != V2DurableReplayOperation::Retrieve
                    || replay_key.fencing_token
                        != params.binding.fencing_token
                    || exact_canonical_response.encoding
                        != V2CanonicalControlResponseEncoding::
                            CanonicalJsonUtf8
                {
                    return Err(V2RuntimeError::new(
                        "retrieval_exact_replay_mismatch",
                        "retrieve exact replay is not bound to the original canonical request and durable terminal",
                    ));
                }
                (
                    *authority_revision,
                    consume_binding_sha256,
                    consumption_receipt_sha256,
                )
            }
            V2ReleaseAuthorizationConsumeOutcomeV1::Denied {
                ..
            } => {
                return Err(V2RuntimeError::new(
                    "retrieval_denied_result_forbidden",
                    "a denied release consumption can never accompany retrieved bytes",
                ))
            }
        };
    if signed.api_version
        != V2_RELEASE_AUTHORIZATION_CONSUME_OUTCOME_VERSION
        || consume.request_sha256 != request_sha256
        || consume.descriptor_manifest_sha256
            != descriptor_manifest_sha256
        || consume.subject_client_identity_sha256
            != params.binding.client_identity_sha256
        || consume.object != params.object
        || consume.attempt_id != params.binding.attempt_id
        || consume.fencing_token != params.binding.fencing_token
        || consume.expected_authority_revision
            != params
                .release_cas_expectation
                .expected_authority_revision
        || consume.expected_unconsumed_state_sha256
            != params
                .release_cas_expectation
                .expected_unconsumed_state_sha256
        || consume.release_request_commitment.commitment
            != expected_commitment
        || consume
            .release_request_commitment
            .canonicalization
            != V2ReleaseRequestCommitmentCanonicalization::
                JcsRfc8785
        || consume
            .release_request_commitment
            .digest_algorithm
            != V2ReleaseRequestCommitmentDigestAlgorithm::Sha256
        || consume
            .release_request_commitment
            .commitment_sha256
            != expected_commitment_sha256
        || authority_revision != expected_authority_revision
        || consume_binding_sha256
            != &expected_consume_binding_sha256
        || !is_sha256_digest(receipt)
        || !is_sha256_digest(&signed.trust_root_sha256)
        || !is_sha256_digest(&signed.trust_checkpoint_sha256)
        || signed.recorded_at_epoch_ms == 0
        || signed.recorded_at_epoch_ms
            > params.binding.deadline_at_epoch_ms
        || signed.signer_role
            != V2ReleaseConsumeAuthorityRole::
                PublicReleaseConsumption
        || signed.signer_provider_id.is_empty()
        || signed.provider_generation == 0
        || !is_sha256_digest(
            &signed.provider_operation_binding_sha256,
        )
        || !is_sha256_digest(&signed.signer_key_id)
        || !is_sha256_digest(
            &signed.signer_key_material_sha256,
        )
        || signed.signature.is_empty()
    {
        return Err(V2RuntimeError::new(
            "retrieval_release_consumption_mismatch",
            "retrieve result is not bound to the exact request, client, object, lifecycle, fence, release CAS, and signed consumption receipt",
        ));
    }
    let evidence_binding = V2RetrievalEvidenceBindingV1 {
        api_version:
            V2_RETRIEVAL_EVIDENCE_BINDING_VERSION.to_owned(),
        request_sha256,
        descriptor_manifest_sha256,
        request_id: params.binding.request_id.clone(),
        client_identity_sha256:
            params.binding.client_identity_sha256.clone(),
        object: result.object.clone(),
        exact_bytes: result.exact_bytes.clone(),
        attempt_id: params.binding.attempt_id.clone(),
        lifecycle_state: params.binding.lifecycle_state,
        state_sha256: params.binding.state_sha256.clone(),
        attempt_revision: params.binding.attempt_revision,
        fencing_token: params.binding.fencing_token,
        monotonic_deadline:
            params.binding.monotonic_deadline.clone(),
        deadline_at_epoch_ms:
            params.binding.deadline_at_epoch_ms,
        release_consume_binding_sha256:
            expected_consume_binding_sha256,
        consumption_receipt_sha256: receipt.clone(),
        retrieval_id:
            result.retrieval_evidence.retrieval_id.clone(),
    };
    if response_observation_v2_retrieval_evidence_sha256(
        &evidence_binding,
    )
    .as_deref()
        != Some(
            result
                .retrieval_evidence
                .evidence_sha256
                .as_str(),
        )
    {
        return Err(V2RuntimeError::new(
            "retrieval_evidence_binding_mismatch",
            "retrieval evidence does not commit to the exact response bytes and signed release consumption receipt",
        ));
    }
    Ok(())
}

fn validate_recover_result_basic(
    result: &V2RecoverResult,
    params: &V2RecoverParams,
    recovery_request_id: &str,
) -> Result<(), V2RuntimeError> {
    let (record, authority_evidence, outcome, expected) = match result {
        V2RecoverResult::Success {
            replay_record,
            recovery_authority_evidence,
            signed_outcome,
        } => (
            replay_record,
            recovery_authority_evidence,
            signed_outcome,
            V2DurableReplayOutcome::Success,
        ),
        V2RecoverResult::Denied {
            replay_record,
            recovery_authority_evidence,
            signed_outcome,
        } => (
            replay_record,
            recovery_authority_evidence,
            signed_outcome,
            V2DurableReplayOutcome::Denied,
        ),
        V2RecoverResult::OutcomeUnknown {
            replay_record,
            recovery_authority_evidence,
            signed_outcome,
        } => (
            replay_record,
            recovery_authority_evidence,
            signed_outcome,
            V2DurableReplayOutcome::OutcomeUnknown,
        ),
    };
    validate_api_replay_key(&record.key)?;
    validate_api_replay_key(&outcome.stable_request)?;
    validate_evidence_reference(
        authority_evidence,
        &[V2EvidenceType::CrossBootRecoveryAuthority],
    )?;
    validate_evidence_reference(
        &outcome.reconciliation,
        &[V2EvidenceType::CrossBootRecoveryReconciliation],
    )?;
    if record.key != params.stable_request
        || outcome.stable_request != params.stable_request
        || outcome.recovery_request_id != recovery_request_id
        || record.outcome != expected
        || outcome.output_references != record.output_references
    {
        return Err(V2RuntimeError::new(
            "recovery_result_binding_mismatch",
            "recover result is not bound to the stable request and terminal class",
        ));
    }
    Ok(())
}

fn result_binding(
    binding: &Option<&V2OperationBinding>,
) -> Result<&V2OperationBinding, V2RuntimeError> {
    binding.as_ref().copied().ok_or_else(|| {
        V2RuntimeError::new(
            "operation_result_binding_missing",
            "non-hello result is missing its operation binding",
        )
    })
}

fn public_error_code(code: &str) -> V2PublicErrorCode {
    match code {
        "unauthorized_client_identity"
        | "request_binding_mismatch"
        | "public_release_subject_mismatch" => {
            V2PublicErrorCode::UnauthorizedClient
        }
        "public_release_revoked"
        | "public_release_signature_invalid"
        | "public_release_policy_mismatch"
        | "public_release_trust_mismatch"
        | "public_release_already_consumed"
        | "recovery_authorization_revoked"
        | "recovery_authorization_signature_invalid"
        | "recovery_authorization_binding_mismatch" => {
            V2PublicErrorCode::AuthorizationDenied
        }
        "request_replay_conflict"
        | "request_id_reuse"
        | "attempt_operation_in_progress" => V2PublicErrorCode::Conflict,
        "operation_capacity_exhausted" | "request_ledger_exhausted" => {
            V2PublicErrorCode::CapacityUnavailable
        }
        "operation_deadline_exceeded" | "operation_deadline_invalid" => {
            V2PublicErrorCode::DeadlineExceeded
        }
        "providers_unconfigured"
        | "configured_provider_activation_unavailable"
        | "durable_replay_unconfigured"
        | "recovery_provider_unavailable"
        | "public_release_consumption_unconfigured"
        | "runtime_state_unavailable" => V2PublicErrorCode::ProviderUnavailable,
        "serialization_failed" | "response_frame_out_of_bounds" => {
            V2PublicErrorCode::InternalFailure
        }
        _ => V2PublicErrorCode::InvalidRequest,
    }
}

fn validate_attempt_transition(
    request: &V2ControlRequest,
    attempt: &AttemptStateReference,
    binding: &V2OperationBinding,
    transition_evidence_sha256: &str,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&attempt.attempt_id)?;
    validate_digest(&attempt.state_sha256)?;
    validate_digest(transition_evidence_sha256)?;
    let expected_revision = binding
        .attempt_revision
        .checked_add(1)
        .filter(|revision| *revision <= MAX_SAFE_INTEGER)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "attempt_revision_overflow",
                "attempt revision cannot advance within the safe integer range",
            )
        })?;
    let expected_state_sha256 = lifecycle_state_digest(
        request,
        binding,
        attempt,
        transition_evidence_sha256,
    );
    if attempt.attempt_id != binding.attempt_id
        || attempt.attempt_revision != expected_revision
        || attempt.fencing_token != binding.fencing_token
        || attempt.state_sha256 != expected_state_sha256
        || !lifecycle_transition_allowed(
            request,
            binding.predecessor_lifecycle_state,
            attempt.state,
        )
    {
        return Err(V2RuntimeError::new(
            "attempt_result_binding_mismatch",
            "attempt result does not match the bound successor transition",
        ));
    }
    Ok(())
}

fn lifecycle_state_digest(
    request: &V2ControlRequest,
    binding: &V2OperationBinding,
    successor: &AttemptStateReference,
    transition_evidence_sha256: &str,
) -> String {
    response_observation_v2_lifecycle_state_sha256(
        request,
        binding,
        successor,
        transition_evidence_sha256,
    )
}

fn lifecycle_state_label(state: V2AttemptState) -> &'static [u8] {
    match state {
        V2AttemptState::Genesis => b"GENESIS",
        V2AttemptState::Denied => b"DENIED",
        V2AttemptState::Reserved => b"RESERVED",
        V2AttemptState::AuthorityReady => b"AUTHORITY_READY",
        V2AttemptState::Staged => b"STAGED",
        V2AttemptState::Dispatched => b"DISPATCHED",
        V2AttemptState::Cancelled => b"CANCELLED",
        V2AttemptState::Failed => b"FAILED",
        V2AttemptState::Completed => b"COMPLETED",
        V2AttemptState::OutcomeUnknown => b"OUTCOME_UNKNOWN",
        V2AttemptState::Terminalized => b"TERMINALIZED",
        V2AttemptState::Finalized => b"FINALIZED",
        V2AttemptState::Attested => b"ATTESTED",
        V2AttemptState::Published => b"PUBLISHED",
    }
}

fn lifecycle_transition_allowed(
    request: &V2ControlRequest,
    predecessor: V2AttemptState,
    successor: V2AttemptState,
) -> bool {
    match request {
        V2OperationRequest::Reserve { .. } => {
            predecessor == V2AttemptState::Genesis
                && matches!(
                    successor,
                    V2AttemptState::Denied | V2AttemptState::Reserved
                )
        }
        V2OperationRequest::Authority { .. } => {
            predecessor == V2AttemptState::Reserved
                && matches!(
                    successor,
                    V2AttemptState::AuthorityReady
                        | V2AttemptState::Terminalized
                )
        }
        V2OperationRequest::Stage { .. } => {
            predecessor == V2AttemptState::AuthorityReady
                && successor == V2AttemptState::Staged
        }
        V2OperationRequest::Dispatch { .. } => {
            predecessor == V2AttemptState::Staged
                && successor == V2AttemptState::Dispatched
        }
        V2OperationRequest::Terminal { .. } => {
            predecessor == V2AttemptState::Dispatched
                && matches!(
                    successor,
                    V2AttemptState::Cancelled
                        | V2AttemptState::Failed
                        | V2AttemptState::Completed
                        | V2AttemptState::OutcomeUnknown
                )
        }
        V2OperationRequest::Finalize { .. } => {
            matches!(
                predecessor,
                V2AttemptState::Denied
                    | V2AttemptState::Terminalized
                    | V2AttemptState::Cancelled
                    | V2AttemptState::Failed
                    | V2AttemptState::Completed
                    | V2AttemptState::OutcomeUnknown
            ) && successor == V2AttemptState::Finalized
        }
        V2OperationRequest::Attest { .. } => {
            predecessor == V2AttemptState::Finalized
                && successor == V2AttemptState::Attested
        }
        V2OperationRequest::Publish { .. } => {
            predecessor == V2AttemptState::Attested
                && successor == V2AttemptState::Published
        }
        V2OperationRequest::Hello { .. }
        | V2OperationRequest::Retrieve { .. }
        | V2OperationRequest::Recover { .. }
        | V2OperationRequest::VerifyArchive { .. } => false,
    }
}

fn lifecycle_transition_for_request(
    request: &V2ControlRequest,
) -> Result<protocol::LifecycleTransitionV1, V2RuntimeError> {
    Ok(match request {
        V2OperationRequest::Reserve { .. } => {
            protocol::LifecycleTransitionV1::Reserve
        }
        V2OperationRequest::Authority { .. } => {
            protocol::LifecycleTransitionV1::Authority
        }
        V2OperationRequest::Stage { .. } => {
            protocol::LifecycleTransitionV1::Stage
        }
        V2OperationRequest::Dispatch { .. } => {
            protocol::LifecycleTransitionV1::Dispatch
        }
        V2OperationRequest::Terminal { params, .. } => {
            match params.terminal_kind {
                V2TerminalKind::Completed => {
                    protocol::LifecycleTransitionV1::TerminalCompleted
                }
                V2TerminalKind::Failed
                | V2TerminalKind::Cancelled => {
                    protocol::LifecycleTransitionV1::TerminalFailed
                }
                V2TerminalKind::OutcomeUnknown => {
                    protocol::LifecycleTransitionV1::TerminalOutcomeUnknown
                }
            }
        }
        V2OperationRequest::Finalize { .. } => {
            protocol::LifecycleTransitionV1::Finalize
        }
        V2OperationRequest::Attest { .. } => {
            protocol::LifecycleTransitionV1::Attest
        }
        V2OperationRequest::Publish { .. } => {
            protocol::LifecycleTransitionV1::Publish
        }
        _ => {
            return Err(V2RuntimeError::new(
                "transition_authorization_operation_invalid",
                "state transition authorization is available only for lifecycle mutations",
            ))
        }
    })
}

#[derive(Clone)]
pub(crate) struct OperationDeadline {
    absolute_epoch_ms: u64,
    monotonic: V2MonotonicDeadlineV1,
    absolute_boottime_ns: u64,
    started: Instant,
    maximum_duration: Duration,
}

impl OperationDeadline {
    fn expired(&self) -> Result<bool, V2RuntimeError> {
        Ok(clock_boottime_ns()? >= self.absolute_boottime_ns
            || self.started.elapsed() >= self.maximum_duration
            || system_time_epoch_ms()? >= self.absolute_epoch_ms)
    }

    fn monotonic_expired(&self) -> bool {
        clock_boottime_ns()
            .map(|now| now >= self.absolute_boottime_ns)
            .unwrap_or(true)
            || self.started.elapsed() >= self.maximum_duration
    }
}

fn remaining_operation_deadline_ms(
    deadline: &OperationDeadline,
) -> Result<u64, V2RuntimeError> {
    let now_boottime_ns = clock_boottime_ns()?;
    let absolute_remaining = deadline
        .absolute_boottime_ns
        .checked_sub(now_boottime_ns)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_lifecycle_deadline_exceeded",
                "the boot-bound monotonic lifecycle deadline elapsed",
            )
            .suppress_response()
        })?
        / 1_000_000;
    let elapsed_remaining = deadline
        .maximum_duration
        .saturating_sub(deadline.started.elapsed());
    let elapsed_remaining =
        u64::try_from(elapsed_remaining.as_millis())
            .unwrap_or(u64::MAX);
    let monotonic_remaining =
        absolute_remaining.min(elapsed_remaining);
    if monotonic_remaining == 0 {
        return Err(V2RuntimeError::new(
            "provider_lifecycle_deadline_exceeded",
            "no inherited monotonic lifecycle deadline remains",
        )
        .suppress_response());
    }
    Ok(monotonic_remaining)
}

#[cfg(target_os = "linux")]
fn clock_boottime_ns() -> Result<u64, V2RuntimeError> {
    let mut observed = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: observed points to writable timespec storage and
    // CLOCK_BOOTTIME has no additional preconditions.
    if unsafe {
        libc::clock_gettime(libc::CLOCK_BOOTTIME, &mut observed)
    } != 0
        || observed.tv_sec < 0
        || observed.tv_nsec < 0
        || observed.tv_nsec >= 1_000_000_000
    {
        return Err(V2RuntimeError::new(
            "monotonic_clock_unavailable",
            "read CLOCK_BOOTTIME for the immutable lifecycle deadline",
        ));
    }
    u64::try_from(observed.tv_sec)
        .ok()
        .and_then(|seconds| {
            seconds
                .checked_mul(1_000_000_000)
                .and_then(|value| {
                    value.checked_add(observed.tv_nsec as u64)
                })
        })
        .ok_or_else(|| {
            V2RuntimeError::new(
                "monotonic_clock_overflow",
                "CLOCK_BOOTTIME is outside the supported u64 range",
            )
        })
}

#[cfg(not(target_os = "linux"))]
fn clock_boottime_ns() -> Result<u64, V2RuntimeError> {
    Err(V2RuntimeError::new(
        "monotonic_clock_unsupported",
        "response-observation v2 requires Linux CLOCK_BOOTTIME",
    ))
}

fn parse_monotonic_deadline(
    value: &V2MonotonicDeadlineV1,
    expected_custody_boot_id: &str,
) -> Result<u64, V2RuntimeError> {
    if value.api_version != V2_MONOTONIC_DEADLINE_VERSION
        || value.custody_boot_id != expected_custody_boot_id
        || value.clock_id != V2MonotonicClockId::ClockBoottime
        || value.absolute_boottime_ns.is_empty()
        || (value.absolute_boottime_ns.len() > 1
            && value.absolute_boottime_ns.starts_with('0'))
        || !value
            .absolute_boottime_ns
            .bytes()
            .all(|byte| byte.is_ascii_digit())
    {
        return Err(V2RuntimeError::new(
            "monotonic_deadline_binding_invalid",
            "deadline must bind the custody boot and canonical CLOCK_BOOTTIME nanoseconds",
        ));
    }
    value
        .absolute_boottime_ns
        .parse::<u64>()
        .ok()
        .filter(|deadline| *deadline > 0)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "monotonic_deadline_binding_invalid",
                "CLOCK_BOOTTIME deadline is outside the supported range",
            )
        })
}

fn deadline_from_operation_binding(
    binding: &V2OperationBinding,
    expected_custody_boot_id: &str,
    accepted_at: Instant,
    maximum_duration: Duration,
) -> Result<OperationDeadline, V2RuntimeError> {
    deadline_from_monotonic_binding(
        &binding.monotonic_deadline,
        binding.deadline_at_epoch_ms,
        expected_custody_boot_id,
        accepted_at,
        maximum_duration,
    )
}

fn deadline_from_monotonic_binding(
    monotonic_deadline: &V2MonotonicDeadlineV1,
    deadline_at_epoch_ms: u64,
    expected_custody_boot_id: &str,
    accepted_at: Instant,
    maximum_duration: Duration,
) -> Result<OperationDeadline, V2RuntimeError> {
    let absolute_boottime_ns = parse_monotonic_deadline(
        monotonic_deadline,
        expected_custody_boot_id,
    )?;
    let now_epoch_ms = system_time_epoch_ms()?;
    let maximum_ms =
        u64::try_from(maximum_duration.as_millis())
            .unwrap_or(u64::MAX);
    if deadline_at_epoch_ms <= now_epoch_ms
        || deadline_at_epoch_ms.saturating_sub(now_epoch_ms)
            > maximum_ms
    {
        return Err(V2RuntimeError::new(
            "operation_deadline_invalid",
            "informational authorization expiry is expired or exceeds the configured operation bound",
        ));
    }
    let now_boottime_ns = clock_boottime_ns()?;
    let maximum_ns = u64::try_from(
        maximum_duration.as_nanos(),
    )
    .unwrap_or(u64::MAX);
    if absolute_boottime_ns <= now_boottime_ns
        || absolute_boottime_ns
            .saturating_sub(now_boottime_ns)
            > maximum_ns
    {
        return Err(V2RuntimeError::new(
            "operation_monotonic_deadline_invalid",
            "boot-bound monotonic deadline is expired or exceeds the configured operation bound",
        ));
    }
    Ok(OperationDeadline {
        absolute_epoch_ms: deadline_at_epoch_ms,
        monotonic: monotonic_deadline.clone(),
        absolute_boottime_ns,
        started: accepted_at,
        maximum_duration,
    })
}

fn operation_binding(
    request: &V2ControlRequest,
) -> Result<V2OperationBinding, V2RuntimeError> {
    if let Some(binding) = request.mutation_binding() {
        return Ok(binding.clone());
    }
    request
        .read_binding()
        .cloned()
        .map(read_binding_as_operation)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "operation_binding_missing",
                "non-hello operation is missing its typed binding",
            )
        })
}

fn read_binding_as_operation(binding: V2ReadBinding) -> V2OperationBinding {
    V2OperationBinding {
        request_id: binding.request_id,
        custody_boot_id: binding.custody_boot_id,
        client_identity_sha256: binding.client_identity_sha256,
        transaction: binding.transaction,
        attempt_id: binding.attempt_id,
        predecessor_lifecycle_state: binding.lifecycle_state,
        predecessor_state_sha256: binding.state_sha256,
        attempt_revision: binding.attempt_revision,
        fencing_token: binding.fencing_token,
        monotonic_deadline: binding.monotonic_deadline,
        deadline_at_epoch_ms: binding.deadline_at_epoch_ms,
    }
}

fn validate_request_binding(
    request: &V2ControlRequest,
    boot_id: &str,
    binding: &V2OperationBinding,
    client_identity: &AuthenticatedClientIdentity,
) -> Result<(), V2RuntimeError> {
    if request.boot_id() != Some(boot_id)
        || binding.custody_boot_id != boot_id
        || binding.request_id != request.request_id()
        || binding.client_identity_sha256
            != client_identity.identity_sha256()
    {
        return Err(V2RuntimeError::new(
            "request_binding_mismatch",
            "requestId and custody boot bindings must match the control envelope",
        ));
    }
    validate_identifier(&binding.attempt_id)?;
    validate_digest(&binding.client_identity_sha256)?;
    validate_digest(&binding.predecessor_state_sha256)?;
    validate_transaction_binding(&binding.transaction)?;
    parse_monotonic_deadline(
        &binding.monotonic_deadline,
        boot_id,
    )?;
    if (binding.attempt_revision == 0
        && request.operation() != V2_RESERVE_OPERATION)
        || (request.operation() == V2_RESERVE_OPERATION
            && (binding.attempt_revision != 0
                || binding.predecessor_lifecycle_state
                    != V2AttemptState::Genesis))
        || !request_predecessor_allowed(
            request,
            binding.predecessor_lifecycle_state,
        )
        || binding.attempt_revision > MAX_SAFE_INTEGER
        || binding.fencing_token == 0
        || binding.fencing_token > MAX_SAFE_INTEGER
        || binding.deadline_at_epoch_ms == 0
        || binding.deadline_at_epoch_ms > MAX_SAFE_INTEGER
    {
        return Err(V2RuntimeError::new(
            "invalid_operation_binding",
            "only reserve may bind genesis revision zero; fence and deadline must be positive safe integers",
        ));
    }
    Ok(())
}

fn validate_transaction_binding(
    binding: &V2TransactionBindingV1,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&binding.principal_id)?;
    validate_identifier(&binding.route_id)?;
    validate_identifier(&binding.observation_session_id)?;
    validate_digest(&binding.connection_identity_sha256)?;
    validate_digest(&binding.client_request_sha256)?;
    validate_digest(&binding.decision_request_sha256)?;
    validate_digest(&binding.route_semantics_sha256)?;
    validate_digest(&binding.policy_sha256)?;
    validate_digest(&binding.tls_session_sha256)?;
    if let Some(digest) = &binding.credential_binding_sha256 {
        validate_digest(digest)?;
    }
    if let Some(digest) = &binding.upstream_response_sha256 {
        validate_digest(digest)?;
    }
    if binding
        .enrollment_session_id
        .as_deref()
        .is_some_and(|value| {
            value.is_empty()
                || value.len() > 256
                || !value.bytes().all(|byte| {
                    byte.is_ascii_alphanumeric()
                        || matches!(byte, b'-' | b'_' | b':' | b'.')
                })
        })
    {
        return Err(V2RuntimeError::new(
            "transaction_session_binding_invalid",
            "transaction enrollment session identifier is invalid",
        ));
    }
    Ok(())
}

fn validate_operation_capability_binding(
    binding: &V2OperationBinding,
    client_identity_sha256: &str,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&binding.request_id)?;
    validate_identifier(&binding.attempt_id)?;
    validate_digest(client_identity_sha256)?;
    validate_digest(&binding.client_identity_sha256)?;
    validate_digest(&binding.predecessor_state_sha256)?;
    parse_monotonic_deadline(
        &binding.monotonic_deadline,
        &binding.custody_boot_id,
    )?;
    if binding.client_identity_sha256 != client_identity_sha256 {
        return Err(V2RuntimeError::new(
            "live_capability_binding_mismatch",
            "verified live capability is not bound to the authenticated client",
        ));
    }
    if binding.attempt_revision > MAX_SAFE_INTEGER
        || binding.fencing_token == 0
        || binding.fencing_token > MAX_SAFE_INTEGER
        || binding.deadline_at_epoch_ms == 0
        || binding.deadline_at_epoch_ms > MAX_SAFE_INTEGER
    {
        return Err(V2RuntimeError::new(
            "live_capability_binding_invalid",
            "live capability revision, fence, or deadline is invalid",
        ));
    }
    Ok(())
}

fn request_predecessor_allowed(
    request: &V2ControlRequest,
    predecessor: V2AttemptState,
) -> bool {
    match request {
        V2OperationRequest::Reserve { .. } => {
            predecessor == V2AttemptState::Genesis
        }
        V2OperationRequest::Authority { .. } => {
            predecessor == V2AttemptState::Reserved
        }
        V2OperationRequest::Stage { .. } => {
            predecessor == V2AttemptState::AuthorityReady
        }
        V2OperationRequest::Dispatch { .. } => {
            predecessor == V2AttemptState::Staged
        }
        V2OperationRequest::Terminal { .. } => {
            predecessor == V2AttemptState::Dispatched
        }
        V2OperationRequest::Finalize { .. } => matches!(
            predecessor,
            V2AttemptState::Denied
                | V2AttemptState::Terminalized
                | V2AttemptState::Cancelled
                | V2AttemptState::Failed
                | V2AttemptState::Completed
                | V2AttemptState::OutcomeUnknown
        ),
        V2OperationRequest::Attest { .. } => {
            predecessor == V2AttemptState::Finalized
        }
        V2OperationRequest::Publish { .. } => {
            predecessor == V2AttemptState::Attested
        }
        V2OperationRequest::Retrieve { .. }
        | V2OperationRequest::VerifyArchive { .. } => {
            predecessor != V2AttemptState::Genesis
        }
        V2OperationRequest::Recover { .. } => false,
        V2OperationRequest::Hello { .. } => false,
    }
}

fn validate_operation_references(
    request: &V2ControlRequest,
) -> Result<(), V2RuntimeError> {
    match request {
        V2OperationRequest::Reserve { params, .. } => {
            expect_media(
                &params.route_semantics,
                &[ExactObjectMediaType::CanonicalJson],
            )?;
            expect_media(
                &params.policy_decision,
                &[ExactObjectMediaType::CanonicalJson],
            )?;
            expect_media(
                &params.runtime_attestation,
                &[ExactObjectMediaType::EvidenceBundle],
            )?;
        }
        V2OperationRequest::Authority { params, .. } => {
            validate_evidence_reference(
                &params.reservation_evidence,
                &[V2EvidenceType::Reservation],
            )?;
            expect_media(
                &params.authority_plan,
                &[ExactObjectMediaType::CanonicalJson],
            )?;
            expect_media(
                &params.authorization_evidence,
                &[ExactObjectMediaType::EvidenceBundle],
            )?;
        }
        V2OperationRequest::Stage { params, .. } => {
            validate_evidence_reference(
                &params.authority_state,
                &[V2EvidenceType::AuthorityState],
            )?;
            if let Some(credential) = &params.credential_reference {
                validate_identifier(&credential.credential_id)?;
                validate_digest(
                    &credential.credential_binding_sha256,
                )?;
                if credential.credential_generation == 0
                    || credential.credential_generation
                        > MAX_SAFE_INTEGER
                {
                    return Err(V2RuntimeError::new(
                        "invalid_credential_reference",
                        "credential generation must be a positive safe integer",
                    ));
                }
            }
            if params.credential_reference.is_some()
                != params
                    .binding
                    .transaction
                    .credential_binding_sha256
                    .is_some()
            {
                return Err(V2RuntimeError::new(
                    "credential_transaction_binding_mismatch",
                    "stage credential reference and transaction credential binding disagree",
                ));
            }
            expect_media(
                &params.credential_template,
                &[ExactObjectMediaType::CanonicalJson],
            )?;
            expect_media(
                &params.credential_free_request,
                &[ExactObjectMediaType::Http11Request],
            )?;
        }
        V2OperationRequest::Dispatch { params, .. } => {
            validate_immutable_reference(&params.staged_request)?;
            expect_object_type(
                &params.staged_request,
                &[ImmutableObjectType::StagedRequest],
            )?;
            validate_evidence_reference(
                &params.staging_evidence,
                &[V2EvidenceType::Staging],
            )?;
            expect_media(
                &params.live_policy_snapshot,
                &[ExactObjectMediaType::CanonicalJson],
            )?;
            expect_media(
                &params.authorization_evidence,
                &[ExactObjectMediaType::EvidenceBundle],
            )?;
        }
        V2OperationRequest::Terminal { params, .. } => {
            if let Some(response) = &params.upstream_response {
                validate_immutable_reference(response)?;
                expect_object_type(
                    response,
                    &[ImmutableObjectType::UpstreamResponse],
                )?;
            }
            expect_media(
                &params.lifecycle_state,
                &[ExactObjectMediaType::EvidenceBundle],
            )?;
        }
        V2OperationRequest::Finalize { params, .. } => {
            validate_evidence_reference(
                &params.terminal_evidence,
                &[V2EvidenceType::Terminal],
            )?;
            expect_media(
                &params.proof_document,
                &[ExactObjectMediaType::CanonicalJson],
            )?;
        }
        V2OperationRequest::Attest { params, .. } => {
            validate_immutable_reference(&params.envelope)?;
            expect_object_type(
                &params.envelope,
                &[ImmutableObjectType::ResponseObservationEnvelope],
            )?;
            validate_evidence_reference(
                &params.finalization_checkpoint,
                &[V2EvidenceType::FinalizationCheckpoint],
            )?;
            expect_media(
                &params.attestation_challenge,
                &[ExactObjectMediaType::CanonicalJson],
            )?;
        }
        V2OperationRequest::Publish { params, .. } => {
            validate_immutable_reference(&params.envelope)?;
            expect_object_type(
                &params.envelope,
                &[ImmutableObjectType::ResponseObservationEnvelope],
            )?;
            validate_immutable_reference(&params.attestation_artifact)?;
            expect_object_type(
                &params.attestation_artifact,
                &[ImmutableObjectType::AttestationArtifact],
            )?;
            validate_evidence_reference(
                &params.attestation_checkpoint,
                &[V2EvidenceType::ArtifactTimeCheckpoint],
            )?;
            validate_identifier(&params.publication_target.target_id)?;
            validate_digest(
                &params.publication_target.target_policy_sha256,
            )?;
            validate_identifier(
                &params.release_intent.retrieve_request_id,
            )?;
            validate_identifier(&params.release_intent.one_use_nonce)?;
            validate_immutable_reference(
                &params.release_intent.object,
            )?;
            expect_object_type(
                &params.release_intent.object,
                &[ImmutableObjectType::ReleasedResponse],
            )?;
            validate_digest(
                &params
                    .release_intent
                    .release_cas_expectation
                    .expected_unconsumed_state_sha256,
            )?;
            if params
                .release_intent
                .release_cas_expectation
                .expected_authority_revision
                == 0
                || params.release_intent.expires_at_epoch_ms == 0
                || params.release_intent.expires_at_epoch_ms
                    > params.binding.deadline_at_epoch_ms
            {
                return Err(V2RuntimeError::new(
                    "publish_release_intent_invalid",
                    "publish release intent CAS or expiry exceeds the shared lifecycle deadline",
                ));
            }
        }
        V2OperationRequest::Retrieve { params, .. } => {
            validate_immutable_reference(&params.object)?;
            validate_retrievable_object(&params.object)?;
            expect_media(
                &params.public_release_authorization,
                &[ExactObjectMediaType::EvidenceBundle],
            )?;
        }
        V2OperationRequest::Recover { params, .. } => {
            validate_api_replay_key(&params.stable_request)?;
            match &params.recovery_authorization {
                V2RecoveryAuthorizationV1::SameBootAuthenticatedClient {
                    authorization_id,
                    one_use_nonce,
                    original_custody_boot_id,
                    subject_client_identity_sha256,
                } => {
                    validate_identifier(authorization_id)?;
                    validate_identifier(one_use_nonce)?;
                    validate_identifier(original_custody_boot_id)?;
                    validate_digest(
                        subject_client_identity_sha256,
                    )?;
                    if original_custody_boot_id
                        != &params
                            .monotonic_deadline
                            .custody_boot_id
                    {
                        return Err(V2RuntimeError::new(
                            "same_boot_recovery_binding_mismatch",
                            "same-boot recovery authorization does not bind the immutable custody clock domain",
                        ));
                    }
                }
                V2RecoveryAuthorizationV1::CrossBootSigned {
                    authorization,
                } => {
                    expect_media(
                        authorization,
                        &[ExactObjectMediaType::EvidenceBundle],
                    )?;
                }
            }
        }
        V2OperationRequest::VerifyArchive { params, .. } => {
            expect_media(
                &params.proof_document,
                &[ExactObjectMediaType::CanonicalJson],
            )?;
            expect_media(
                &params.historical_runtime_attestation,
                &[ExactObjectMediaType::EvidenceBundle],
            )?;
            expect_media(
                &params.finalization_checkpoint,
                &[ExactObjectMediaType::EvidenceBundle],
            )?;
        }
        V2OperationRequest::Hello { .. } => {
            return Err(V2RuntimeError::new(
                "unsupported_operation",
                "operation is not in the fixed v2 capability set",
            ));
        }
    }
    Ok(())
}

fn expect_media(
    descriptor: &ExactByteObjectDescriptor,
    allowed: &[ExactObjectMediaType],
) -> Result<(), V2RuntimeError> {
    if !allowed.contains(&descriptor.media_type) {
        return Err(V2RuntimeError::new(
            "exact_object_media_type_mismatch",
            "exact object media type is invalid for this operation",
        ));
    }
    Ok(())
}

fn validate_evidence_reference(
    reference: &EvidenceReference,
    expected_types: &[V2EvidenceType],
) -> Result<(), V2RuntimeError> {
    validate_digest(&reference.evidence_sha256)?;
    validate_identifier(&reference.retrieval_id)?;
    if !expected_types.contains(&reference.evidence_type) {
        return Err(V2RuntimeError::new(
            "evidence_type_mismatch",
            "evidence reference type is invalid for this operation",
        ));
    }
    Ok(())
}

fn validate_outcome_unknown(
    request: &V2ControlRequest,
    result: &V2OutcomeUnknownResult,
    replay: &ReplayReservation,
) -> Result<(), V2RuntimeError> {
    let binding = request.mutation_binding().ok_or_else(|| {
        V2RuntimeError::new(
            "outcome_unknown_read_forbidden",
            "read-only and hello operations cannot produce outcome unknown",
        )
    })?;
    validate_identifier(&result.attempt.attempt_id)?;
    validate_digest(&result.attempt.state_sha256)?;
    validate_digest(&result.request_sha256)?;
    validate_digest(&result.descriptor_manifest_sha256)?;
    validate_identifier(&result.provider_operation_id)?;
    validate_digest(&result.durable_start_receipt_sha256)?;
    validate_evidence_reference(
        &result.reconciliation,
        &[V2EvidenceType::OutcomeUnknownReconciliation],
    )?;
    validate_digest(&result.trust_checkpoint_sha256)?;
    validate_identifier(&result.signer_provider_id)?;
    validate_digest(
        &result.provider_operation_binding_sha256,
    )?;
    validate_digest(&result.signer_key_id)?;
    validate_digest(&result.signer_key_material_sha256)?;
    let expected_revision = binding
        .attempt_revision
        .checked_add(1)
        .filter(|revision| *revision <= MAX_SAFE_INTEGER)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "attempt_revision_overflow",
                "outcome-unknown revision cannot advance",
            )
        })?;
    let replay_key = replay.key()?;
    if result.attempt.attempt_id != binding.attempt_id
        || result.attempt.state != V2AttemptState::OutcomeUnknown
        || result.attempt.attempt_revision != expected_revision
        || result.attempt.fencing_token != binding.fencing_token
        || result.attempt.state_sha256
            == binding.predecessor_state_sha256
        || result.request_sha256 != replay_key.request_sha256
        || result.descriptor_manifest_sha256
            != replay_key.descriptor_manifest_sha256
        || result.durable_start_receipt_sha256
            != replay.durable_start_receipt_sha256()?
        || result.revocation_epoch == 0
        || result.revocation_epoch > MAX_SAFE_INTEGER
        || result.provider_generation == 0
        || result.provider_generation > MAX_SAFE_INTEGER
        || result.recorded_at_epoch_ms == 0
        || result.recorded_at_epoch_ms > MAX_SAFE_INTEGER
        || result.signature.is_empty()
        || result.signature.len() > 1024
    {
        return Err(V2RuntimeError::new(
            "outcome_unknown_binding_mismatch",
            "signed outcome unknown is not durably bound to this request, predecessor, revision, and fence",
        ));
    }
    Ok(())
}

fn validate_immutable_reference(
    reference: &ImmutableObjectReference,
) -> Result<(), V2RuntimeError> {
    validate_digest(&reference.object_sha256)?;
    validate_identifier(&reference.retrieval_id)?;
    validate_digest(&reference.persistence_receipt_sha256)?;
    if reference.byte_length == 0
        || reference.byte_length > RESPONSE_OBSERVATION_V2_MAX_OBJECT_BYTES
        || reference.byte_length > MAX_SAFE_INTEGER
    {
        return Err(V2RuntimeError::new(
            "immutable_object_length_invalid",
            "immutable object length is empty or overbound",
        ));
    }
    Ok(())
}

fn expect_object_type(
    reference: &ImmutableObjectReference,
    allowed: &[ImmutableObjectType],
) -> Result<(), V2RuntimeError> {
    if !allowed.contains(&reference.object_type) {
        return Err(V2RuntimeError::new(
            "immutable_object_type_mismatch",
            "immutable object type is invalid for this operation",
        ));
    }
    Ok(())
}

fn validate_retrievable_object(
    reference: &ImmutableObjectReference,
) -> Result<(), V2RuntimeError> {
    expect_object_type(
        reference,
        &[
            ImmutableObjectType::ResponseObservationEnvelope,
            ImmutableObjectType::AttestationArtifact,
            ImmutableObjectType::PublicationArtifact,
            ImmutableObjectType::ReleasedResponse,
        ],
    )
}

fn read_bounded_exact_object(
    object: &ValidatedExactObject,
    deadline: &OperationDeadline,
) -> Result<Vec<u8>, V2RuntimeError> {
    let length = usize::try_from(object.descriptor.byte_length).map_err(
        |_| {
            V2RuntimeError::new(
                "exact_object_length_invalid",
                "exact object length cannot be represented",
            )
        },
    )?;
    let mut bytes = vec![0u8; length];
    let mut offset = 0usize;
    while offset < bytes.len() {
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "operation_deadline_exceeded",
                "whole-operation deadline elapsed while reading exact object",
            ));
        }
        let read = object.read_at(
            &mut bytes[offset..],
            u64::try_from(offset).map_err(|_| {
                V2RuntimeError::new(
                    "exact_object_offset_overflow",
                    "exact object offset cannot be represented",
                )
            })?,
        )?;
        if read == 0 {
            return Err(V2RuntimeError::new(
                "exact_object_truncated",
                "exact object ended before its declared length",
            ));
        }
        offset = offset.checked_add(read).ok_or_else(|| {
            V2RuntimeError::new(
                "exact_object_offset_overflow",
                "exact object offset overflowed",
            )
        })?;
    }
    Ok(bytes)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ExpectedReleaseConsumeOutcome {
    Consumed,
    ExactReplay,
    Denied,
}

fn validate_release_consume_outcome(
    signed: &SignedV2ReleaseAuthorizationConsumeOutcomeV1,
    expected_outcome: ExpectedReleaseConsumeOutcome,
    expected_commitment: &V2ReleaseRequestCommitmentDigestV1,
    request_sha256: &str,
    descriptor_manifest_sha256: &str,
    one_use_nonce: &str,
    client_identity_sha256: &str,
    object: &ImmutableObjectReference,
    attempt_id: &str,
    fencing_token: u64,
    authorization_id: &str,
    expected_cas: &V2ReleaseCasExpectationV1,
    pins: &ProofIndependentPins,
    signer: &VerifiedProviderIdentity,
    verifier: &Arc<InstalledProviderGeneration>,
    adapter_binding: &VerifiedProviderOperationBinding,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&signed.consume.authorization_id)?;
    validate_digest(&signed.consume.request_sha256)?;
    validate_digest(
        &signed.consume.descriptor_manifest_sha256,
    )?;
    validate_identifier(&signed.consume.one_use_nonce)?;
    validate_digest(
        &signed.consume.subject_client_identity_sha256,
    )?;
    validate_identifier(&signed.consume.attempt_id)?;
    validate_immutable_reference(&signed.consume.object)?;
    validate_digest(
        &signed
            .consume
            .release_request_commitment
            .commitment_sha256,
    )?;
    validate_digest(
        &signed.consume.expected_unconsumed_state_sha256,
    )?;
    validate_digest(&signed.trust_root_sha256)?;
    validate_digest(&signed.trust_checkpoint_sha256)?;
    validate_identifier(&signed.signer_provider_id)?;
    validate_digest(
        &signed.provider_operation_binding_sha256,
    )?;
    validate_digest(&signed.signer_key_id)?;
    validate_digest(&signed.signer_key_material_sha256)?;
    if signed.api_version
        != V2_RELEASE_AUTHORIZATION_CONSUME_OUTCOME_VERSION
        || signed.consume.authorization_id != authorization_id
        || signed.consume.request_sha256 != request_sha256
        || signed.consume.descriptor_manifest_sha256
            != descriptor_manifest_sha256
        || signed.consume.one_use_nonce != one_use_nonce
        || signed.consume.subject_client_identity_sha256
            != client_identity_sha256
        || signed.consume.object != *object
        || signed.consume.attempt_id != attempt_id
        || signed.consume.fencing_token != fencing_token
        || signed.consume.release_request_commitment
            != *expected_commitment
        || signed.consume.expected_authority_revision
            != expected_cas.expected_authority_revision
        || signed.consume.expected_unconsumed_state_sha256
            != expected_cas.expected_unconsumed_state_sha256
        || signed
            .consume
            .release_request_commitment
            .commitment
            .request_sha256
            != request_sha256
        || signed
            .consume
            .release_request_commitment
            .commitment
            .descriptor_manifest_sha256
            != descriptor_manifest_sha256
        || signed
            .consume
            .release_request_commitment
            .commitment
            .one_use_nonce
            != one_use_nonce
        || signed
            .consume
            .release_request_commitment
            .commitment
            .subject_client_identity_sha256
            != client_identity_sha256
        || signed
            .consume
            .release_request_commitment
            .commitment
            .object
            != *object
        || signed
            .consume
            .release_request_commitment
            .commitment
            .attempt_id
            != attempt_id
        || signed
            .consume
            .release_request_commitment
            .commitment
            .fencing_token
            != fencing_token
        || signed.consume.expected_authority_revision == 0
        || signed.consume.expected_authority_revision
            > MAX_SAFE_INTEGER
        || signed.trust_root_sha256 != pins.trust_root_sha256
        || signed.trust_checkpoint_sha256
            != pins.trust_checkpoint_sha256
        || signed.revocation_epoch != pins.revocation_epoch
        || signed.recorded_at_epoch_ms == 0
        || signed.recorded_at_epoch_ms > MAX_SAFE_INTEGER
        || signed.signer_role
            != V2ReleaseConsumeAuthorityRole::PublicReleaseConsumption
        || signed.signer_provider_id != signer.provider_id
        || signed.provider_generation
            != signer.provider_generation
        || signed.provider_generation
            != adapter_binding.provider_generation
        || signed.provider_operation_binding_sha256
            != provider_authority_scope_sha256(
                adapter_binding,
            )
        || signed.signer_key_id != signer.key_id
        || signed.signer_key_material_sha256
            != signer.key_material_sha256
    {
        return Err(V2RuntimeError::new(
            "public_release_consume_outcome_mismatch",
            "signed release consumption outcome is not bound to the CAS, trust pins, and distinct consumption authority",
        ));
    }
    let expected_consume_binding_sha256 =
        release_consume_binding_sha256(&signed.consume)?;
    let observed_outcome = match &signed.outcome {
        V2ReleaseAuthorizationConsumeOutcomeV1::ConsumedBeforeRelease {
            authority_revision,
            consume_binding_sha256,
            consumption_receipt_sha256,
        } => {
            validate_consume_terminal_fields(
                *authority_revision,
                consume_binding_sha256,
                Some(consumption_receipt_sha256),
            )?;
            if consume_binding_sha256
                != &expected_consume_binding_sha256
            {
                return Err(V2RuntimeError::new(
                    "public_release_consume_binding_mismatch",
                    "consumption terminal is not bound to the exact request, nonce, client, object, fence, and expected CAS state",
                ));
            }
            ExpectedReleaseConsumeOutcome::Consumed
        }
        V2ReleaseAuthorizationConsumeOutcomeV1::ExactReplay {
            authority_revision,
            consume_binding_sha256,
            consumption_receipt_sha256,
            replay_record_sha256,
            replay_key,
            exact_canonical_response,
        } => {
            validate_consume_terminal_fields(
                *authority_revision,
                consume_binding_sha256,
                Some(consumption_receipt_sha256),
            )?;
            if consume_binding_sha256
                != &expected_consume_binding_sha256
            {
                return Err(V2RuntimeError::new(
                    "public_release_consume_binding_mismatch",
                    "exact replay terminal is not bound to the exact request and expected CAS state",
                ));
            }
            validate_digest(replay_record_sha256)?;
            validate_api_replay_key(replay_key)?;
            validate_digest(&exact_canonical_response.sha256)?;
            validate_identifier(
                &exact_canonical_response.storage_reference_id,
            )?;
            validate_digest(
                &exact_canonical_response.persistence_receipt_sha256,
            )?;
            ExpectedReleaseConsumeOutcome::ExactReplay
        }
        V2ReleaseAuthorizationConsumeOutcomeV1::Denied {
            authority_revision,
            consume_binding_sha256,
            ..
        } => {
            validate_consume_terminal_fields(
                *authority_revision,
                consume_binding_sha256,
                None,
            )?;
            if consume_binding_sha256
                != &expected_consume_binding_sha256
            {
                return Err(V2RuntimeError::new(
                    "public_release_consume_binding_mismatch",
                    "denial terminal is not bound to the exact request and expected CAS state",
                ));
            }
            ExpectedReleaseConsumeOutcome::Denied
        }
    };
    if observed_outcome != expected_outcome {
        return Err(V2RuntimeError::new(
            "public_release_consume_class_mismatch",
            "release consumption authority returned the wrong terminal class",
        ));
    }
    let signature = signed.signature.clone();
    let mut unsigned_signed = signed.clone();
    unsigned_signed.signature.clear();
    let unsigned = crate::canonical_json_bytes(&unsigned_signed).map_err(|_| {
        V2RuntimeError::new(
            "public_release_consume_outcome_invalid",
            "release consumption outcome cannot be canonicalized",
        )
    })?;
    let mut signing_message =
        b"serverware.public-release-consume-outcome/v1\0".to_vec();
    signing_message.extend_from_slice(&unsigned);
    if signature.is_empty()
        || signature.len() > 1024
        || !verifier.verify_consume_outcome_ed25519(
            adapter_binding,
            &signed.signer_key_id,
            &signing_message,
            &signature,
        )
    {
        return Err(V2RuntimeError::new(
            "public_release_consume_signature_invalid",
            "release consumption outcome signature is invalid",
        ));
    }
    Ok(())
}

fn release_consume_binding_sha256(
    consume: &V2ReleaseAuthorizationConsumeCasV1,
) -> Result<String, V2RuntimeError> {
    response_observation_v2_release_consume_binding_sha256(consume)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "public_release_consume_binding_invalid",
                "release consumption CAS state cannot be canonicalized",
            )
        })
}

fn validate_consume_terminal_fields(
    authority_revision: u64,
    consume_binding_sha256: &str,
    consumption_receipt_sha256: Option<&String>,
) -> Result<(), V2RuntimeError> {
    validate_digest(consume_binding_sha256)?;
    if let Some(receipt) = consumption_receipt_sha256 {
        validate_digest(receipt)?;
    }
    if authority_revision == 0
        || authority_revision > MAX_SAFE_INTEGER
    {
        return Err(V2RuntimeError::new(
            "public_release_consume_revision_invalid",
            "release consumption authority revision is invalid",
        ));
    }
    Ok(())
}

fn validate_release_exact_replay(
    signed: &SignedV2ReleaseAuthorizationConsumeOutcomeV1,
    record: &DurableTerminalRecord,
    commitment: &V2ReleaseRequestCommitmentDigestV1,
) -> Result<(), V2RuntimeError> {
    let V2ReleaseAuthorizationConsumeOutcomeV1::ExactReplay {
        replay_record_sha256,
        replay_key,
        exact_canonical_response,
        ..
    } = &signed.outcome
    else {
        return Err(V2RuntimeError::new(
            "public_release_exact_replay_class_mismatch",
            "release CAS did not return its exact replay class",
        ));
    };
    let expected_key = api_replay_key(&record.key)?;
    if replay_key != &expected_key
        || replay_record_sha256 != &record.record_sha256
        || exact_canonical_response.sha256 != record.response_sha256
        || exact_canonical_response.storage_reference_id
            != record.control_storage_reference_id
        || exact_canonical_response.persistence_receipt_sha256
            != record.control_persistence_receipt_sha256
        || commitment.commitment.request_id
            != record.key.stable.request_id
        || commitment.commitment.attempt_id
            != record.key.stable.attempt_id
        || commitment.commitment.fencing_token
            != record.key.stable.fencing_token
        || record.key.stable.operation != V2_RETRIEVE_OPERATION
    {
        return Err(V2RuntimeError::new(
            "public_release_exact_replay_mismatch",
            "release CAS exact replay is not bound to the durable retrieve terminal and release commitment",
        ));
    }
    Ok(())
}

fn validate_public_release_claims(
    authorization: &SignedPublicReleaseAuthorizationV1,
    params: &V2RetrieveParams,
    client_identity: &AuthenticatedClientIdentity,
    pins: &ProofIndependentPins,
    construction: &VerifiedProviderConstruction,
    release_request_commitment_sha256: &str,
    signature_binding: &VerifiedProviderOperationBinding,
    trusted_now_epoch_ms: u64,
) -> Result<(), V2RuntimeError> {
    validate_identifier(&authorization.authorization_id)?;
    validate_identifier(&authorization.one_use_nonce)?;
    validate_identifier(&authorization.request_id)?;
    validate_digest(
        &authorization.release_request_commitment_sha256,
    )?;
    validate_digest(
        &authorization
            .release_cas_expectation
            .expected_unconsumed_state_sha256,
    )?;
    validate_digest(&authorization.subject_client_identity_sha256)?;
    validate_digest(&authorization.policy_sha256)?;
    validate_digest(&authorization.trust_root_sha256)?;
    validate_digest(&authorization.trust_checkpoint_sha256)?;
    validate_identifier(&authorization.signer_provider_id)?;
    validate_digest(
        &authorization.provider_operation_binding_sha256,
    )?;
    validate_digest(&authorization.signer_key_id)?;
    validate_digest(&authorization.signer_key_material_sha256)?;
    validate_immutable_reference(&authorization.object)?;
    if authorization.api_version
        != V2_PUBLIC_RELEASE_AUTHORIZATION_VERSION
        || authorization.subject_client_identity_sha256
            != client_identity.identity_sha256()
        || params.binding.client_identity_sha256
            != client_identity.identity_sha256()
        || authorization.request_id != params.binding.request_id
        || authorization.release_request_commitment_sha256
            != release_request_commitment_sha256
        || authorization.release_cas_expectation
            != params.release_cas_expectation
        || authorization
            .release_cas_expectation
            .expected_authority_revision
            == 0
        || authorization
            .release_cas_expectation
            .expected_authority_revision
            > MAX_SAFE_INTEGER
        || authorization.attempt_id != params.binding.attempt_id
        || authorization.fencing_token
            != params.binding.fencing_token
    {
        return Err(V2RuntimeError::new(
            "public_release_subject_mismatch",
            "public release authorization is not bound to this client and release intent",
        ));
    }
    if authorization.object != params.object {
        return Err(V2RuntimeError::new(
            "public_release_object_mismatch",
            "public release authorization is not bound to the requested exact object",
        ));
    }
    if authorization.policy_sha256 != pins.public_release_policy_sha256 {
        return Err(V2RuntimeError::new(
            "public_release_policy_mismatch",
            "public release authorization does not match the root-owned policy",
        ));
    }
    if authorization.trust_root_sha256 != pins.trust_root_sha256
        || authorization.trust_checkpoint_sha256
            != pins.trust_checkpoint_sha256
        || authorization.revocation_epoch != pins.revocation_epoch
    {
        return Err(V2RuntimeError::new(
            "public_release_trust_mismatch",
            "public release authorization does not match proof-independent trust and revocation pins",
        ));
    }
    if authorization.issued_at_epoch_ms == 0
        || authorization.issued_at_epoch_ms > trusted_now_epoch_ms
        || authorization.expires_at_epoch_ms <= trusted_now_epoch_ms
        || authorization.expires_at_epoch_ms > MAX_SAFE_INTEGER
        || authorization.signature.is_empty()
        || authorization.signature.len() > 1024
    {
        return Err(V2RuntimeError::new(
            "public_release_expired",
            "public release authorization time or signature bounds are invalid",
        ));
    }
    let signer = &construction.public_release;
    if authorization.signer_provider_id != signer.provider_id
        || authorization.provider_generation
            != signer.provider_generation
        || authorization.provider_generation
            != signature_binding.provider_generation
        || authorization.issuance_scope.role != "public-release"
        || authorization.issuance_scope.provider_id
            != signer.provider_id
        || authorization.issuance_scope.provider_generation
            != signer.provider_generation
        || authorization.issuance_scope.attempt_id
            != params.binding.attempt_id
        || authorization.issuance_scope.fencing_token
            != params.binding.fencing_token
        || authorization.issuance_scope.key_material_sha256
            != signer.key_material_sha256
        || authorization.issuance_scope.executable_measurement_sha256
            != signer.executable_measurement_sha256
        || authorization.issuance_scope.provider_config_sha256
            != signer.provider_config_sha256
        || authorization.issuance_scope.tee_measurement_sha256
            != signer.tee_measurement_sha256
        || authorization.provider_operation_binding_sha256
            != provider_authority_scope_sha256_from_scope(
                &authorization.issuance_scope,
            )
        || authorization.signer_key_id != signer.key_id
        || authorization.signer_key_material_sha256
            != signer.key_material_sha256
    {
        return Err(V2RuntimeError::new(
            "public_release_authority_mismatch",
            "public release authorization signer is not the distinct root-pinned release authority",
        ));
    }
    Ok(())
}

fn public_release_request_commitment(
    params: &V2RetrieveParams,
    client_identity_sha256: &str,
    one_use_nonce: &str,
) -> Result<V2ReleaseRequestCommitmentDigestV1, V2RuntimeError> {
    validate_identifier(&params.binding.request_id)?;
    validate_identifier(&params.binding.attempt_id)?;
    validate_identifier(one_use_nonce)?;
    validate_digest(client_identity_sha256)?;
    validate_digest(&params.binding.state_sha256)?;
    validate_digest(
        &params
            .release_cas_expectation
            .expected_unconsumed_state_sha256,
    )?;
    if params
        .release_cas_expectation
        .expected_authority_revision
        == 0
        || params
            .release_cas_expectation
            .expected_authority_revision
            > MAX_SAFE_INTEGER
    {
        return Err(V2RuntimeError::new(
            "public_release_cas_expectation_invalid",
            "release CAS predecessor revision is outside the safe integer range",
        ));
    }
    validate_immutable_reference(&params.object)?;
    let commitment = V2ReleaseRequestCommitmentV1 {
        api_version:
            V2_RELEASE_REQUEST_COMMITMENT_VERSION.to_owned(),
        request_id: params.binding.request_id.clone(),
        subject_client_identity_sha256:
            client_identity_sha256.to_owned(),
        object: params.object.clone(),
        attempt_id: params.binding.attempt_id.clone(),
        lifecycle_state: params.binding.lifecycle_state,
        state_sha256: params.binding.state_sha256.clone(),
        attempt_revision: params.binding.attempt_revision,
        fencing_token: params.binding.fencing_token,
        monotonic_deadline:
            params.binding.monotonic_deadline.clone(),
        deadline_at_epoch_ms: params.binding.deadline_at_epoch_ms,
        one_use_nonce: one_use_nonce.to_owned(),
        release_cas_expectation:
            params.release_cas_expectation.clone(),
    };
    let commitment_sha256 =
        response_observation_v2_release_request_commitment_sha256(
            &commitment,
        )
        .ok_or_else(|| {
            V2RuntimeError::new(
                "public_release_intent_invalid",
                "release request commitment cannot be canonically encoded",
            )
        })?;
    Ok(V2ReleaseRequestCommitmentDigestV1 {
        commitment,
        canonicalization:
            V2ReleaseRequestCommitmentCanonicalization::JcsRfc8785,
        digest_algorithm:
            V2ReleaseRequestCommitmentDigestAlgorithm::Sha256,
        commitment_sha256,
    })
}

fn retrievable_media_type(
    object_type: ImmutableObjectType,
) -> Result<ExactObjectMediaType, V2RuntimeError> {
    match object_type {
        ImmutableObjectType::ResponseObservationEnvelope => {
            Ok(ExactObjectMediaType::CanonicalJson)
        }
        ImmutableObjectType::AttestationArtifact => {
            Ok(ExactObjectMediaType::AttestationArtifact)
        }
        ImmutableObjectType::PublicationArtifact => {
            Ok(ExactObjectMediaType::PublicationArtifact)
        }
        ImmutableObjectType::ReleasedResponse => {
            Ok(ExactObjectMediaType::Http11Response)
        }
        ImmutableObjectType::StagedRequest
        | ImmutableObjectType::UpstreamResponse => {
            Err(V2RuntimeError::new(
                "non_retrievable_object_type",
                "staged requests and raw upstream responses are never retrievable",
            ))
        }
    }
}

fn validate_exact_object_files(
    descriptors: &[ExactByteObjectDescriptor],
    files: Vec<File>,
    deadline: Option<&OperationDeadline>,
) -> Result<ValidatedExactObjects, V2RuntimeError> {
    if descriptors.len() > RESPONSE_OBSERVATION_V2_MAX_OBJECTS
        || descriptors.len() != files.len()
    {
        return Err(V2RuntimeError::new(
            "exact_object_count_mismatch",
            "received file descriptor count does not match the closed operation DTO",
        ));
    }
    let mut by_index = BTreeMap::new();
    let mut aggregate_bytes = 0u64;
    for descriptor in descriptors {
        validate_identifier(&descriptor.object_id)?;
        validate_digest(&descriptor.sha256)?;
        aggregate_bytes = aggregate_bytes
            .checked_add(descriptor.byte_length)
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "exact_object_aggregate_overflow",
                    "exact object aggregate length overflowed",
                )
            })?;
        if descriptor.byte_length == 0
            || descriptor.byte_length > RESPONSE_OBSERVATION_V2_MAX_OBJECT_BYTES
            || aggregate_bytes > 64 * 1024 * 1024
            || usize::from(descriptor.fd_index) >= files.len()
            || by_index
                .insert(descriptor.fd_index, descriptor)
                .is_some()
        {
            return Err(V2RuntimeError::new(
                "invalid_exact_object_descriptor",
                "descriptor index, length, or uniqueness is invalid",
            ));
        }
    }
    let mut validated = BTreeMap::new();
    for (index, mut file) in files.into_iter().enumerate() {
        if deadline
            .map(OperationDeadline::expired)
            .transpose()?
            .unwrap_or(false)
        {
            return Err(V2RuntimeError::new(
                "operation_deadline_exceeded",
                "whole-operation deadline elapsed while validating exact objects",
            ));
        }
        let descriptor = by_index.get(&(index as u16)).ok_or_else(|| {
            V2RuntimeError::new(
                "unreferenced_file_descriptor",
                "every received file descriptor must be referenced exactly once",
            )
        })?;
        verify_sealed_memfd(descriptor, &mut file, deadline)?;
        validated.insert(
            index as u16,
            ValidatedExactObject {
                descriptor: (*descriptor).clone(),
                file,
            },
        );
    }
    Ok(ValidatedExactObjects {
        by_fd_index: validated,
    })
}

#[cfg(target_os = "linux")]
fn verify_sealed_memfd(
    descriptor: &ExactByteObjectDescriptor,
    file: &mut File,
    deadline: Option<&OperationDeadline>,
) -> Result<(), V2RuntimeError> {
    let required_seals =
        libc::F_SEAL_SEAL | libc::F_SEAL_SHRINK | libc::F_SEAL_GROW | libc::F_SEAL_WRITE;
    // SAFETY: fcntl reads seal metadata for a valid owned descriptor.
    let seals = unsafe { libc::fcntl(file.as_raw_fd(), libc::F_GET_SEALS) };
    if seals < 0 || seals & required_seals != required_seals {
        return Err(V2RuntimeError::new(
            "unsealed_exact_object",
            "bulk object is not an immutable sealed memfd",
        ));
    }
    let metadata = file.metadata().map_err(|error| {
        V2RuntimeError::new(
            "exact_object_metadata_failed",
            format!("inspect sealed memfd: {error}"),
        )
    })?;
    if !metadata.file_type().is_file()
        || metadata.len() != descriptor.byte_length
    {
        return Err(V2RuntimeError::new(
            "exact_object_length_mismatch",
            "sealed memfd length does not match its descriptor",
        ));
    }
    let mut hasher = Sha256::new();
    let mut remaining = descriptor.byte_length;
    let mut offset = 0u64;
    let mut buffer = [0u8; 64 * 1024];
    while remaining > 0 {
        if deadline
            .map(OperationDeadline::expired)
            .transpose()?
            .unwrap_or(false)
        {
            return Err(V2RuntimeError::new(
                "operation_deadline_exceeded",
                "whole-operation deadline elapsed while hashing a sealed memfd",
            ));
        }
        let wanted = usize::try_from(remaining.min(buffer.len() as u64))
            .unwrap_or(buffer.len());
        let read = file.read_at(&mut buffer[..wanted], offset).map_err(|error| {
            V2RuntimeError::new(
                "exact_object_read_failed",
                format!("positionally read sealed memfd: {error}"),
            )
        })?;
        if read == 0 {
            return Err(V2RuntimeError::new(
                "exact_object_truncated",
                "sealed memfd ended before its declared length",
            ));
        }
        hasher.update(&buffer[..read]);
        remaining -= read as u64;
        offset = offset.checked_add(read as u64).ok_or_else(|| {
            V2RuntimeError::new(
                "exact_object_offset_overflow",
                "sealed memfd read offset overflowed",
            )
        })?;
    }
    let observed = format!("sha256:{:x}", hasher.finalize());
    if observed != descriptor.sha256 {
        return Err(V2RuntimeError::new(
            "exact_object_digest_mismatch",
            "sealed memfd digest does not match its descriptor",
        ));
    }
    Ok(())
}

#[cfg(not(target_os = "linux"))]
fn verify_sealed_memfd(
    _descriptor: &ExactByteObjectDescriptor,
    _file: &mut File,
    _deadline: Option<&OperationDeadline>,
) -> Result<(), V2RuntimeError> {
    Err(V2RuntimeError::new(
        "sealed_memfd_unsupported",
        "this platform lacks the required sealed memfd primitive; no fallback is permitted",
    ))
}

fn validate_identifier(value: &str) -> Result<(), V2RuntimeError> {
    if value.len() < MIN_IDENTIFIER_BYTES
        || value.len() > MAX_IDENTIFIER_BYTES
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || b"._:/-".contains(&byte))
    {
        return Err(V2RuntimeError::new(
            "invalid_identifier",
            "identifier is empty, overbound, or contains unsafe characters",
        ));
    }
    Ok(())
}

fn validate_digest(value: &str) -> Result<(), V2RuntimeError> {
    let Some(hex) = value.strip_prefix("sha256:") else {
        return Err(V2RuntimeError::new(
            "invalid_digest",
            "digest must use sha256:<64 lowercase hex>",
        ));
    };
    if hex.len() != 64
        || !hex
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(V2RuntimeError::new(
            "invalid_digest",
            "digest must use sha256:<64 lowercase hex>",
        ));
    }
    Ok(())
}

fn is_sha256_digest(value: &str) -> bool {
    validate_digest(value).is_ok()
}

fn system_time_epoch_ms() -> Result<u64, V2RuntimeError> {
    let elapsed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| {
            V2RuntimeError::new(
                "system_time_unavailable",
                "system wall clock is before the Unix epoch",
            )
        })?;
    u64::try_from(elapsed.as_millis()).map_err(|_| {
        V2RuntimeError::new(
            "system_time_unavailable",
            "system wall clock exceeds supported range",
        )
    })
}

fn deadline_from_binding(
    binding: &VerifiedProviderOperationBinding,
) -> Result<OperationDeadline, V2RuntimeError> {
    let now = system_time_epoch_ms()?;
    if binding.deadline_at_epoch_ms <= now {
        return Err(V2RuntimeError::new(
            "provider_binding_expired",
            "provider operation binding deadline has elapsed",
        ));
    }
    let absolute_boottime_ns = parse_monotonic_deadline(
        &binding.monotonic_deadline,
        &binding.monotonic_deadline.custody_boot_id,
    )?;
    let remaining_boottime_ns = absolute_boottime_ns
        .checked_sub(clock_boottime_ns()?)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_binding_expired",
                "provider operation monotonic deadline has elapsed",
            )
        })?;
    let remaining = binding
        .deadline_at_epoch_ms
        .saturating_sub(now)
        .min(remaining_boottime_ns / 1_000_000);
    Ok(OperationDeadline {
        absolute_epoch_ms: binding.deadline_at_epoch_ms,
        monotonic: binding.monotonic_deadline.clone(),
        absolute_boottime_ns,
        started: Instant::now(),
        maximum_duration: Duration::from_millis(
            remaining.min(RESPONSE_OBSERVATION_V2_MAX_OPERATION_MS),
        ),
    })
}

fn generate_boot_id() -> Result<String, V2RuntimeError> {
    let mut bytes = [0u8; 32];
    let mut random = File::open("/dev/urandom").map_err(|error| {
        V2RuntimeError::new(
            "entropy_unavailable",
            format!("open operating-system entropy source: {error}"),
        )
    })?;
    random.read_exact(&mut bytes).map_err(|error| {
        V2RuntimeError::new(
            "entropy_unavailable",
            format!("read operating-system entropy source: {error}"),
        )
    })?;
    Ok(format!("boot-{}", hex::encode(bytes)))
}

fn generate_hardware_proof_challenge() -> Result<String, V2RuntimeError> {
    let mut bytes = [0u8; 32];
    let mut random = File::open("/dev/urandom").map_err(|error| {
        V2RuntimeError::new(
            "entropy_unavailable",
            format!("open operating-system entropy source: {error}"),
        )
    })?;
    random.read_exact(&mut bytes).map_err(|error| {
        V2RuntimeError::new(
            "entropy_unavailable",
            format!("read operating-system entropy source: {error}"),
        )
    })?;
    Ok(format!(
        "hardware-proof-challenge-{}",
        hex::encode(bytes)
    ))
}

impl Drop for OperationCompletionLease {
    fn drop(&mut self) {
        if let Ok(mut active) = self.state.active_attempts.lock() {
            active.remove(&self.attempt_id);
        }
        self.state
            .active_operations
            .fetch_sub(1, Ordering::AcqRel);
    }
}

