fn clone_validated_output_objects(
    references: &[DurableOutputReference],
    files: &[File],
    deadline: &OperationDeadline,
) -> Result<ValidatedExactObjects, V2RuntimeError> {
    if references.len() != files.len() {
        return Err(V2RuntimeError::new(
            "provider_output_reference_count_mismatch",
            "durable output references do not match exact files",
        ));
    }
    let descriptors = references
        .iter()
        .map(|reference| reference.descriptor.clone())
        .collect::<Vec<_>>();
    let cloned = files
        .iter()
        .map(File::try_clone)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_output_clone_failed",
                "duplicate sealed output descriptors for provider RPC",
            )
        })?;
    validate_exact_object_files(
        &descriptors,
        cloned,
        Some(deadline),
    )
}

impl PublicReleaseSignatureVerifier
    for Arc<InstalledProviderGeneration>
{
    fn verify_public_release_ed25519(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool {
        if adapter_binding.role != "public-release"
            || adapter_binding.provider_generation != self.generation
        {
            return false;
        }
        let Ok(deadline) = deadline_from_binding(adapter_binding)
        else {
            return false;
        };
        let externally_verified = self
            .invoke_bound::<_, ProviderBooleanDecision>(
                adapter_binding,
                ProviderSubchannelOperation::PublicReleaseSignature,
                &ProviderSignatureVerificationRequest {
                    signer_key_id,
                    domain_separated_message_base64:
                        base64::engine::general_purpose::STANDARD
                            .encode(domain_separated_message),
                    signature,
                },
                &ValidatedExactObjects::empty(),
                &deadline,
            )
            .map(|decision| decision.accepted)
            .unwrap_or(false);
        externally_verified
            && self.verify_role_signature(
                "public-release",
                signer_key_id,
                domain_separated_message,
                signature,
            )
    }
}

impl PublicReleaseTrustedTimeProvider
    for Arc<InstalledProviderGeneration>
{
    fn trusted_now_epoch_ms(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> Result<u64, V2RuntimeError> {
        let decision: ProviderTrustedTimeDecision =
            self.invoke_bound(
                adapter_binding,
                ProviderSubchannelOperation::TrustedTime,
                &ProviderBooleanDecision { accepted: true },
                &ValidatedExactObjects::empty(),
                deadline,
            )?;
        if decision.trusted_now_epoch_ms == 0
            || decision.trusted_now_epoch_ms > MAX_SAFE_INTEGER
        {
            return Err(V2RuntimeError::new(
                "provider_trusted_time_invalid",
                "trusted-time subchannel returned an invalid safe integer",
            ));
        }
        Ok(decision.trusted_now_epoch_ms)
    }
}

