impl DurableReplayAuthority for Arc<InstalledProviderGeneration> {
    fn claim(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        key: &DurableReplayKey,
        deadline: &OperationDeadline,
    ) -> Result<DurableReplayDecision, V2RuntimeError> {
        let decision: ProviderReplayClaimDecision =
            self.invoke_bound(
                adapter_binding,
                ProviderSubchannelOperation::ReplayClaim,
                key,
                &ValidatedExactObjects::empty(),
                deadline,
            )?;
        Ok(match decision {
            ProviderReplayClaimDecision::Reserved { reservation } => {
                DurableReplayDecision::Reserved(reservation)
            }
            ProviderReplayClaimDecision::Exact { record } => {
                DurableReplayDecision::Exact(record)
            }
            ProviderReplayClaimDecision::InProgress => {
                DurableReplayDecision::InProgress
            }
            ProviderReplayClaimDecision::Conflict => {
                DurableReplayDecision::Conflict
            }
        })
    }

    fn persist_terminal_atomic(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        reservation: DurableReplayReservation,
        write: DurableTerminalWrite<'_>,
        exact_objects: &[File],
        deadline: &OperationDeadline,
    ) -> Result<DurableTerminalRecord, V2RuntimeError> {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct Request<'a> {
            reservation: DurableReplayReservation,
            write: DurableTerminalWrite<'a>,
        }
        let objects = clone_validated_output_objects(
            write.output_references,
            exact_objects,
            deadline,
        )?;
        self.invoke_bound(
            adapter_binding,
            ProviderSubchannelOperation::ReplayPersist,
            &Request { reservation, write },
            &objects,
            deadline,
        )
    }

    fn rehydrate_terminal_exact(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        record: &DurableTerminalRecord,
        deadline: &OperationDeadline,
    ) -> Result<RehydratedDurableTerminal, V2RuntimeError> {
        let (result, exact_objects):
            (ProviderRehydratedTerminal, Vec<File>) =
            self.invoke_bound_with_files(
                adapter_binding,
                ProviderSubchannelOperation::ReplayRehydrate,
                record,
                &ValidatedExactObjects::empty(),
                deadline,
            )?;
        if result.output_descriptors
            != record
                .output_references
                .iter()
                .map(|reference| reference.descriptor.clone())
                .collect::<Vec<_>>()
            || result.output_descriptors.len() != exact_objects.len()
        {
            return Err(V2RuntimeError::new(
                "provider_rehydration_output_mismatch",
                "rehydrated output descriptors do not match the durable record",
            ));
        }
        Ok(RehydratedDurableTerminal {
            canonical_response: result.canonical_response,
            exact_objects,
            authority_receipt_sha256:
                result.authority_receipt_sha256,
            persistence_receipt_sha256:
                result.persistence_receipt_sha256,
            retrieval_receipt_sha256:
                result.retrieval_receipt_sha256,
            signed_retrieval_receipt:
                result.signed_retrieval_receipt,
        })
    }

    fn verify_terminal_record_authority(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        record: &DurableTerminalRecord,
        recomputed_record_sha256: &str,
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct Request<'a> {
            record: &'a DurableTerminalRecord,
            recomputed_record_sha256: &'a str,
        }
        let decision: ProviderBooleanDecision = self.invoke_bound(
            adapter_binding,
            ProviderSubchannelOperation::ReplayVerifyRecord,
            &Request {
                record,
                recomputed_record_sha256,
            },
            &ValidatedExactObjects::empty(),
            deadline,
        )?;
        if decision.accepted {
            Ok(())
        } else {
            Err(V2RuntimeError::new(
                "provider_replay_record_rejected",
                "replay authority rejected the durable terminal record",
            ))
        }
    }

    fn verify_terminal_retrieval_authority(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        record: &DurableTerminalRecord,
        rehydrated: &RehydratedDurableTerminal,
        deadline: &OperationDeadline,
    ) -> Result<(), V2RuntimeError> {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct Request<'a> {
            record: &'a DurableTerminalRecord,
            canonical_response_sha256: String,
            authority_receipt_sha256: &'a str,
            persistence_receipt_sha256: &'a str,
            retrieval_receipt_sha256: &'a str,
            signed_retrieval_receipt:
                &'a SignedDurableTerminalRetrievalReceipt,
        }
        let decision: ProviderBooleanDecision = self.invoke_bound(
            adapter_binding,
            ProviderSubchannelOperation::ReplayVerifyRetrieval,
            &Request {
                record,
                canonical_response_sha256: format!(
                    "sha256:{:x}",
                    Sha256::digest(
                        &rehydrated.canonical_response
                    )
                ),
                authority_receipt_sha256:
                    &rehydrated.authority_receipt_sha256,
                persistence_receipt_sha256:
                    &rehydrated.persistence_receipt_sha256,
                retrieval_receipt_sha256:
                    &rehydrated.retrieval_receipt_sha256,
                signed_retrieval_receipt:
                    &rehydrated.signed_retrieval_receipt,
            },
            &ValidatedExactObjects::empty(),
            deadline,
        )?;
        if decision.accepted {
            Ok(())
        } else {
            Err(V2RuntimeError::new(
                "provider_replay_retrieval_rejected",
                "replay authority rejected the authenticated retrieval",
            ))
        }
    }

    fn abandon_unstarted(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        reservation: DurableReplayReservation,
    ) {
        let Ok(deadline) = deadline_from_binding(adapter_binding)
        else {
            self.ready.store(false, Ordering::Release);
            self.quarantined.store(true, Ordering::Release);
            return;
        };
        if !matches!(
            self.invoke_bound::<_, ProviderBooleanDecision>(
                adapter_binding,
                ProviderSubchannelOperation::ReplayAbandon,
                &reservation,
                &ValidatedExactObjects::empty(),
                &deadline,
            )
            .map(|decision| decision.accepted),
            Ok(true)
        )
        {
            self.ready.store(false, Ordering::Release);
            self.quarantined.store(true, Ordering::Release);
        }
    }

    fn recover(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        lookup: &StableRecoveryLookup,
        capability: VerifiedRecoveryCapability,
        deadline: &OperationDeadline,
    ) -> Result<DurableRecoveryDecision, V2RuntimeError> {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct CapabilityRequest<'a> {
            authorization_id: &'a str,
            subject_client_identity_sha256: &'a str,
            recovery_request_id: &'a str,
            one_use_nonce: &'a str,
            stable: &'a V2DurableReplayKeyV1,
            recovery_operation_binding_sha256: &'a str,
            recovery_provider_generation: u64,
            replay_operation_binding_sha256: &'a str,
            replay_provider_generation: u64,
        }
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct Request<'a> {
            lookup: &'a StableRecoveryLookup,
            capability: CapabilityRequest<'a>,
        }
        let result: ProviderRecoveryDecision = self.invoke_bound(
            adapter_binding,
            ProviderSubchannelOperation::ReplayRecover,
            &Request {
                lookup,
                capability: CapabilityRequest {
                    authorization_id:
                        &capability.authorization_id,
                    subject_client_identity_sha256:
                        &capability.subject_client_identity_sha256,
                    recovery_request_id:
                        &capability.recovery_request_id,
                    one_use_nonce: &capability.one_use_nonce,
                    stable: &capability.stable,
                    recovery_operation_binding_sha256:
                        &capability
                            .recovery_operation_binding_sha256,
                    recovery_provider_generation:
                        capability.recovery_provider_generation,
                    replay_operation_binding_sha256:
                        &capability
                            .replay_operation_binding_sha256,
                    replay_provider_generation:
                        capability.replay_provider_generation,
                },
            },
            &ValidatedExactObjects::empty(),
            deadline,
        )?;
        Ok(DurableRecoveryDecision {
            terminal: result.terminal,
            result: result.result,
        })
    }

    fn verify_replay_record_ed25519(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool {
        adapter_binding.role == "linearizable-store"
            && adapter_binding.provider_generation == self.generation
            && self.verify_role_signature(
                "linearizable-store",
                signer_key_id,
                domain_separated_message,
                signature,
            )
    }
}

impl PublicReleaseConsumptionAuthority
    for Arc<InstalledProviderGeneration>
{
    fn consume_once_cas(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        binding: &PublicReleaseConsumeBinding<'_>,
        deadline: &OperationDeadline,
    ) -> Result<PublicReleaseConsumeDecision, V2RuntimeError> {
        let decision: ProviderReleaseConsumeDecision =
            self.invoke_bound(
                adapter_binding,
                ProviderSubchannelOperation::ConsumePublicRelease,
                binding,
                &ValidatedExactObjects::empty(),
                deadline,
            )?;
        Ok(match decision {
            ProviderReleaseConsumeDecision::Acquired {
                authority_receipt_sha256,
                authority_revision,
                signed_outcome,
            } => PublicReleaseConsumeDecision::Acquired {
                receipt: PublicReleaseConsumeReceipt {
                    authority_receipt_sha256,
                    authority_revision,
                    _seal: PublicReleaseConsumeReceiptSeal,
                },
                signed_outcome,
            },
            ProviderReleaseConsumeDecision::Exact {
                record,
                signed_outcome,
            } => PublicReleaseConsumeDecision::Exact {
                record,
                signed_outcome,
            },
            ProviderReleaseConsumeDecision::Denied {
                signed_outcome,
            } => PublicReleaseConsumeDecision::Denied {
                signed_outcome,
            },
        })
    }

    fn verify_consume_outcome_ed25519(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool {
        adapter_binding.role == "public-release-consumption"
            && adapter_binding.provider_generation == self.generation
            && self.verify_role_signature(
                "public-release-consumption",
                signer_key_id,
                domain_separated_message,
                signature,
            )
    }
}

impl RecoveryAuthorizationVerifier
    for Arc<InstalledProviderGeneration>
{
    fn trusted_now_epoch_ms(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
    ) -> Result<u64, V2RuntimeError> {
        PublicReleaseTrustedTimeProvider::trusted_now_epoch_ms(
            self,
            adapter_binding,
            deadline,
        )
    }

    fn authorization_is_revoked(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        authorization_id: &str,
        revocation_epoch: u64,
        deadline: &OperationDeadline,
    ) -> Result<bool, V2RuntimeError> {
        PublicReleaseRevocationProvider::authorization_is_revoked(
            self,
            adapter_binding,
            authorization_id,
            revocation_epoch,
            deadline,
        )
    }

    fn verify_authorization_ed25519(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool {
        verify_recovery_signature(
            self,
            adapter_binding,
            ProviderSubchannelOperation::RecoveryAuthorization,
            signer_key_id,
            domain_separated_message,
            signature,
        )
    }

    fn verify_resolution_ed25519(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool {
        verify_recovery_signature(
            self,
            adapter_binding,
            ProviderSubchannelOperation::RecoveryResolution,
            signer_key_id,
            domain_separated_message,
            signature,
        )
    }
}

fn verify_recovery_signature(
    installed: &Arc<InstalledProviderGeneration>,
    adapter_binding: &VerifiedProviderOperationBinding,
    operation: ProviderSubchannelOperation,
    signer_key_id: &str,
    domain_separated_message: &[u8],
    signature: &str,
) -> bool {
    matches!(
        operation,
        ProviderSubchannelOperation::RecoveryAuthorization
            | ProviderSubchannelOperation::RecoveryResolution
    ) && adapter_binding.role == "recovery"
        && adapter_binding.provider_generation == installed.generation
        && installed.verify_role_signature(
            "recovery",
            signer_key_id,
            domain_separated_message,
            signature,
        )
}

impl TeeRuntimeAttestationProvider
    for Arc<InstalledProviderGeneration>
{
    fn verify_runtime(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        deadline: &OperationDeadline,
        role_identity_root_sha256: &str,
        proof_independent_pins_root_sha256: &str,
    ) -> Result<(), V2RuntimeError> {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct Request<'a> {
            role_identity_root_sha256: &'a str,
            proof_independent_pins_root_sha256: &'a str,
        }
        let decision: ProviderBooleanDecision = self.invoke_bound(
            adapter_binding,
            ProviderSubchannelOperation::VerifyRuntimeAttestation,
            &Request {
                role_identity_root_sha256,
                proof_independent_pins_root_sha256,
            },
            &ValidatedExactObjects::empty(),
            deadline,
        )?;
        if decision.accepted {
            Ok(())
        } else {
            Err(V2RuntimeError::new(
                "runtime_attestation_rejected",
                "runtime-attestation subchannel rejected the measured generation",
            ))
        }
    }

    fn fresh_response_attestation(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        binding: &FreshHardwareProofBinding<'_>,
        deadline: &OperationDeadline,
    ) -> Result<SignedFreshHardwareProof, V2RuntimeError> {
        self.invoke_bound(
            adapter_binding,
            ProviderSubchannelOperation::FreshResponseAttestation,
            binding,
            &ValidatedExactObjects::empty(),
            deadline,
        )
    }

    fn verify_fresh_response_attestation_ed25519(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        signer_key_id: &str,
        domain_separated_message: &[u8],
        signature: &str,
    ) -> bool {
        if adapter_binding.role != "runtime-attestation"
            || signer_key_id
                != self
                    .role("runtime-attestation")
                    .map(|role| role.pin.key_id.as_str())
                    .unwrap_or_default()
        {
            return false;
        }
        let Ok(signature) =
            base64::engine::general_purpose::STANDARD
                .decode(signature)
        else {
            return false;
        };
        let Ok(role) = self.role("runtime-attestation") else {
            return false;
        };
        ring::signature::UnparsedPublicKey::new(
            &ring::signature::ED25519,
            role.verification_key.as_ref(),
        )
        .verify(domain_separated_message, &signature)
        .is_ok()
    }

    fn verify_fresh_response_attestation_evidence(
        &self,
        adapter_binding: &VerifiedProviderOperationBinding,
        binding: &FreshHardwareProofBinding<'_>,
        proof: &SignedFreshHardwareProof,
        deadline: &OperationDeadline,
    ) -> Result<VerifiedFreshHardwareEvidence, V2RuntimeError> {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct Request<'a> {
            binding: &'a FreshHardwareProofBinding<'a>,
            proof: &'a SignedFreshHardwareProof,
        }
        let decision: ProviderFreshEvidenceDecision =
            self.invoke_bound(
                adapter_binding,
                ProviderSubchannelOperation::VerifyFreshResponseAttestation,
                &Request { binding, proof },
                &ValidatedExactObjects::empty(),
                deadline,
            )?;
        Ok(VerifiedFreshHardwareEvidence {
            attestation_evidence_sha256:
                decision.attestation_evidence_sha256,
            response_sha256: decision.response_sha256,
            output_manifest_sha256:
                decision.output_manifest_sha256,
            authenticated_session_sha256:
                decision.authenticated_session_sha256,
            challenge_nonce: decision.challenge_nonce,
            custody_executable_measurement_sha256:
                decision
                    .custody_executable_measurement_sha256,
            custody_provider_config_sha256:
                decision.custody_provider_config_sha256,
            custody_key_material_sha256:
                decision.custody_key_material_sha256,
            custody_tee_measurement_sha256:
                decision.custody_tee_measurement_sha256,
            trust_checkpoint_sha256:
                decision.trust_checkpoint_sha256,
            revocation_epoch: decision.revocation_epoch,
            provider_generation: decision.provider_generation,
            verified_at_epoch_ms:
                decision.verified_at_epoch_ms,
            current_revocation_receipt_sha256:
                decision.current_revocation_receipt_sha256,
            attestation_evidence_retrieval_id:
                decision.attestation_evidence_retrieval_id,
            report_data_sha256: decision.report_data_sha256,
            signer_key_sha256: decision.signer_key_sha256,
            trust_chain_sha256: decision.trust_chain_sha256,
            endorsements_sha256: decision.endorsements_sha256,
            trust_root_sha256: decision.trust_root_sha256,
            signer_revocation_receipt_sha256:
                decision.signer_revocation_receipt_sha256,
            signer_revocation_receipt_retrieval_id:
                decision
                    .signer_revocation_receipt_retrieval_id,
            evidence_verification_receipt_sha256:
                decision.evidence_verification_receipt_sha256,
            evidence_verification_receipt_retrieval_id:
                decision
                    .evidence_verification_receipt_retrieval_id,
            _seal: VerifiedFreshHardwareEvidenceSeal,
        })
    }
}

