fn reject_unconfigured_lifecycle<T>(
    context: &OperationContext<'_>,
) -> SupervisedMutationResult<T> {
    let error = context.ensure_live().err().unwrap_or_else(|| {
        V2RuntimeError::new(
            "providers_unconfigured",
            "external TEE/store/quorum/transparency/attestation providers are not configured",
        )
    });
    SupervisedMutationResult::RejectedBeforeStart(error)
}

