#[cfg(target_os = "linux")]
fn contract_policy_exact_objects(
    parts: [&[u8]; 4],
) -> Result<
    (
        ValidatedExactObjects,
        [Option<ExactByteObjectDescriptor>; 4],
    ),
    V2RuntimeError,
> {
    let total = parts.iter().try_fold(0u64, |total, part| {
        total.checked_add(part.len() as u64).ok_or_else(|| {
            V2RuntimeError::new(
                "contract_policy_object_overflow",
                "contract policy exact-object total overflowed",
            )
        })
    })?;
    if total > 64 * 1024 * 1024
        || parts.iter().any(|part| {
            part.len() as u64
                > RESPONSE_OBSERVATION_V2_MAX_OBJECT_BYTES
        })
    {
        return Err(V2RuntimeError::new(
            "contract_policy_object_too_large",
            "contract policy exact objects exceed configured bounds",
        ));
    }
    let mut objects = BTreeMap::new();
    let mut descriptors: [Option<ExactByteObjectDescriptor>; 4] =
        std::array::from_fn(|_| None);
    for (part_index, part) in parts.into_iter().enumerate() {
        if part.is_empty() {
            continue;
        }
        let name = CString::new(format!(
            "serverware-contract-policy-{part_index}"
        ))
        .map_err(|_| {
            V2RuntimeError::new(
                "contract_policy_memfd_name_invalid",
                "contract policy memfd name contains NUL",
            )
        })?;
        // SAFETY: name is NUL terminated and flags request a new sealable
        // close-on-exec anonymous file.
        let raw = unsafe {
            libc::memfd_create(
                name.as_ptr(),
                libc::MFD_CLOEXEC | libc::MFD_ALLOW_SEALING,
            )
        };
        if raw < 0 {
            return Err(V2RuntimeError::new(
                "contract_policy_memfd_failed",
                "create contract policy sealed memfd",
            ));
        }
        // SAFETY: raw is newly returned and uniquely owned.
        let mut file =
            File::from(unsafe { OwnedFd::from_raw_fd(raw) });
        file.write_all(part).map_err(|_| {
            V2RuntimeError::new(
                "contract_policy_memfd_write_failed",
                "write exact contract policy object",
            )
        })?;
        file.sync_all().map_err(|_| {
            V2RuntimeError::new(
                "contract_policy_memfd_sync_failed",
                "synchronize exact contract policy object",
            )
        })?;
        let seals = libc::F_SEAL_SEAL
            | libc::F_SEAL_SHRINK
            | libc::F_SEAL_GROW
            | libc::F_SEAL_WRITE;
        // SAFETY: fcntl applies immutable seals to this owned memfd.
        if unsafe {
            libc::fcntl(file.as_raw_fd(), libc::F_ADD_SEALS, seals)
        } < 0
        {
            return Err(V2RuntimeError::new(
                "contract_policy_memfd_seal_failed",
                "seal exact contract policy object",
            ));
        }
        file.rewind().map_err(|_| {
            V2RuntimeError::new(
                "contract_policy_memfd_rewind_failed",
                "rewind exact contract policy object",
            )
        })?;
        let fd_index = u16::try_from(objects.len()).map_err(|_| {
            V2RuntimeError::new(
                "contract_policy_fd_index_overflow",
                "contract policy descriptor index overflowed",
            )
        })?;
        let descriptor = ExactByteObjectDescriptor {
            fd_index,
            object_id: format!(
                "contract-policy-object-{part_index:02}"
            ),
            byte_length: part.len() as u64,
            sha256: format!(
                "sha256:{:x}",
                Sha256::digest(part)
            ),
            media_type: ExactObjectMediaType::OpaqueProviderArtifact,
            required_seals: MemfdSealProfile::ImmutableV1,
        };
        objects.insert(
            fd_index,
            ValidatedExactObject {
                descriptor: descriptor.clone(),
                file,
            },
        );
        descriptors[part_index] = Some(descriptor);
    }
    Ok((
        ValidatedExactObjects {
            by_fd_index: objects,
        },
        descriptors,
    ))
}

#[cfg(not(target_os = "linux"))]
fn contract_policy_exact_objects(
    _parts: [&[u8]; 4],
) -> Result<
    (
        ValidatedExactObjects,
        [Option<ExactByteObjectDescriptor>; 4],
    ),
    V2RuntimeError,
> {
    Err(V2RuntimeError::new(
        "sealed_memfd_unsupported",
        "contract policy validation requires Linux sealed memfd; no fallback is permitted",
    ))
}

