#[cfg(target_os = "linux")]
fn verify_provider_operator_signature<T: ProviderSignedValue>(
    root_public_key: &[u8; 32],
    domain: &[u8],
    value: &T,
    signature: &str,
) -> Result<(), V2RuntimeError> {
    let signature =
        base64::engine::general_purpose::STANDARD
            .decode(signature)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_operator_signature_invalid",
                    "provider operator signature is not canonical base64",
                )
            })?;
    let unsigned =
        crate::canonical_json_bytes(&value.without_signature())
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_operator_statement_invalid",
                    "provider operator statement cannot be canonicalized",
                )
            })?;
    let mut message =
        Vec::with_capacity(domain.len() + unsigned.len());
    message.extend_from_slice(domain);
    message.extend_from_slice(&unsigned);
    ring::signature::UnparsedPublicKey::new(
        &ring::signature::ED25519,
        root_public_key,
    )
    .verify(&message, &signature)
    .map_err(|_| {
        V2RuntimeError::new(
            "provider_operator_signature_invalid",
            "provider operator statement signature is invalid",
        )
    })
}

#[cfg(target_os = "linux")]
fn verify_provider_operator_trust_bundle(
    config: &MeasuredProviderProcessConfig,
    deadline: &OperationDeadline,
) -> Result<VerifiedProviderOperatorTrust, V2RuntimeError> {
    let bundle = &config.trust_bundle;
    if bundle.api_version
        != PROVIDER_OPERATOR_TRUST_BUNDLE_API_VERSION
    {
        return Err(V2RuntimeError::new(
            "provider_operator_trust_bundle_invalid",
            "provider operator trust bundle API is unsupported",
        ));
    }
    let root = base64::engine::general_purpose::STANDARD
        .decode(&bundle.operator_root_public_key_base64)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_operator_trust_root_invalid",
                "operator trust root is not canonical base64",
            )
        })?;
    let root_public_key: [u8; 32] =
        root.try_into().map_err(|_| {
            V2RuntimeError::new(
                "provider_operator_trust_root_invalid",
                "operator trust root must be a raw Ed25519 public key",
            )
        })?;
    let root_sha256 =
        format!("sha256:{:x}", Sha256::digest(root_public_key));
    if root_sha256
        != config.proof_independent_pins.trust_root_sha256
        || bundle.checkpoint.api_version
            != PROVIDER_OPERATOR_TRUST_CHECKPOINT_API_VERSION
        || bundle.checkpoint.trust_root_sha256 != root_sha256
        || bundle.checkpoint.checkpoint_revision == 0
        || bundle.checkpoint.valid_from_epoch_ms == 0
        || bundle.checkpoint.valid_until_epoch_ms
            <= bundle.checkpoint.valid_from_epoch_ms
    {
        return Err(V2RuntimeError::new(
            "provider_operator_trust_checkpoint_invalid",
            "operator trust checkpoint is not bound to the pinned root and validity interval",
        ));
    }
    verify_provider_operator_signature(
        &root_public_key,
        b"serverware.response-v2/provider-trust-checkpoint/v1\0",
        &bundle.checkpoint,
        &bundle.checkpoint.signature,
    )?;
    let checkpoint_bytes =
        crate::canonical_json_bytes(&bundle.checkpoint)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_operator_trust_checkpoint_invalid",
                    "operator trust checkpoint cannot be canonicalized",
                )
            })?;
    let trust_checkpoint_sha256 = format!(
        "sha256:{:x}",
        Sha256::digest(&checkpoint_bytes)
    );
    if trust_checkpoint_sha256
        != config
            .proof_independent_pins
            .trust_checkpoint_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_operator_trust_checkpoint_mismatch",
            "operator trust checkpoint does not match the root-owned pin",
        ));
    }
    let mut roles = BTreeSet::new();
    let mut key_ids = BTreeSet::new();
    for role_key in &bundle.checkpoint.role_keys {
        let key = base64::engine::general_purpose::STANDARD
            .decode(&role_key.public_key_base64)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_operator_role_key_invalid",
                    "operator role key is not canonical base64",
                )
            })?;
        if key.len() != 32
            || format!("sha256:{:x}", Sha256::digest(&key))
                != role_key.key_material_sha256
            || role_key.key_id
                != role_key.key_material_sha256
            || role_key.provider_generation == 0
            || [
                &role_key.executable_measurement_sha256,
                &role_key.provider_config_sha256,
                &role_key.tee_measurement_sha256,
            ]
            .into_iter()
            .any(|digest| !is_sha256_digest(digest))
            || !REQUIRED_ROLE_IDENTITIES
                .contains(&role_key.role.as_str())
            || !roles.insert(role_key.role.as_str())
            || !key_ids.insert(role_key.key_id.as_str())
        {
            return Err(V2RuntimeError::new(
                "provider_operator_role_key_invalid",
                "operator role key set is incomplete, duplicated, or does not match its digest",
            ));
        }
    }
    if roles.len() != REQUIRED_ROLE_IDENTITIES.len()
        || !bundle.checkpoint.role_keys.iter().any(|role_key| {
            role_key.role == config.role
                && role_key.provider_id == config.provider_id
                && role_key.provider_generation
                    == config.provider_generation
                && role_key.key_id == config.key_id
                && role_key.key_material_sha256
                    == config.key_material_sha256
                && role_key.revoked_at_epoch_ms.is_none()
        })
    {
        return Err(V2RuntimeError::new(
            "provider_operator_role_set_invalid",
            "operator checkpoint does not contain the exact live role generation key",
        ));
    }
    let revocation = &bundle.revocation;
    if revocation.api_version
        != PROVIDER_OPERATOR_REVOCATION_API_VERSION
        || revocation.trust_checkpoint_sha256
            != trust_checkpoint_sha256
        || revocation.revocation_epoch
            != config.proof_independent_pins.revocation_epoch
        || revocation.valid_from_epoch_ms == 0
        || revocation.valid_until_epoch_ms
            <= revocation.valid_from_epoch_ms
    {
        return Err(V2RuntimeError::new(
            "provider_operator_revocation_invalid",
            "operator revocation checkpoint does not match the pinned trust state",
        ));
    }
    verify_provider_operator_signature(
        &root_public_key,
        b"serverware.response-v2/provider-revocation/v1\0",
        revocation,
        &revocation.signature,
    )?;
    let trusted_time = &bundle.trusted_time;
    if trusted_time.api_version
        != PROVIDER_OPERATOR_TRUSTED_TIME_API_VERSION
        || trusted_time.trust_checkpoint_sha256
            != trust_checkpoint_sha256
        || trusted_time.revocation_epoch
            != revocation.revocation_epoch
        || trusted_time.trusted_now_epoch_ms
            < trusted_time.valid_from_epoch_ms
        || trusted_time.trusted_now_epoch_ms
            > trusted_time.valid_until_epoch_ms
        || trusted_time.valid_until_epoch_ms
            > revocation.valid_until_epoch_ms
        || deadline.absolute_epoch_ms
            > trusted_time.valid_until_epoch_ms
    {
        return Err(V2RuntimeError::new(
            "provider_operator_trusted_time_invalid",
            "operator trusted-time statement is not current for the complete shared deadline",
        ));
    }
    validate_identifier(&trusted_time.statement_id)?;
    verify_provider_operator_signature(
        &root_public_key,
        b"serverware.response-v2/provider-trusted-time/v1\0",
        trusted_time,
        &trusted_time.signature,
    )?;
    let local_reject_only_now = system_time_epoch_ms()?;
    if local_reject_only_now < trusted_time.valid_from_epoch_ms
        || local_reject_only_now > trusted_time.valid_until_epoch_ms
        || local_reject_only_now
            < bundle.checkpoint.valid_from_epoch_ms
        || local_reject_only_now
            > bundle.checkpoint.valid_until_epoch_ms
    {
        return Err(V2RuntimeError::new(
            "provider_operator_trust_bundle_expired",
            "operator-signed trust material is outside its validity window",
        ));
    }
    match (
        config.attestation_mode,
        &bundle.trusted_host_runtime,
    ) {
        (
            V2AttestationMode::TrustedHost,
            Some(runtime),
        ) => {
            let claim = &runtime.claim;
            for digest in [
                &claim.runtime.runtime_measurement_sha256,
                &claim.runtime.release_sha256,
                &claim.runtime.data_plane_binary_sha256,
                &claim.runtime.rollback_state_head_sha256,
                &claim.attestation_evidence_sha256,
                &claim.verifier_key_id,
            ] {
                validate_digest(digest)?;
            }
            validate_identifier(&claim.runtime.boot_id)?;
            validate_identifier(
                &claim.runtime.runtime_instance_id,
            )?;
            let verifier_is_pinned = bundle
                .checkpoint
                .role_keys
                .iter()
                .any(|key| {
                    key.role == "runtime-attestation"
                        && key.key_id == claim.verifier_key_id
                        && key.revoked_at_epoch_ms.is_none()
                });
            if runtime.api_version
                    != PROVIDER_OPERATOR_TRUSTED_HOST_RUNTIME_API_VERSION
                || runtime.trust_checkpoint_sha256
                    != trust_checkpoint_sha256
                || runtime.revocation_epoch
                    != revocation.revocation_epoch
                || claim.runtime.rollback_state_epoch == 0
                || claim.verified_at_epoch_ms == 0
                || claim.expires_at_epoch_ms
                    <= claim.verified_at_epoch_ms
                || claim.verified_at_epoch_ms
                    > trusted_time.trusted_now_epoch_ms
                || claim.expires_at_epoch_ms
                    < deadline.absolute_epoch_ms
                || !verifier_is_pinned
            {
                return Err(V2RuntimeError::new(
                    "provider_operator_trusted_host_runtime_invalid",
                    "operator trusted-host runtime statement is not current and bound to the pinned runtime verifier",
                ));
            }
            verify_provider_operator_signature(
                &root_public_key,
                b"serverware.response-v2/provider-trusted-host-runtime/v1\0",
                runtime,
                &runtime.signature,
            )?;
        }
        (V2AttestationMode::TrustedHost, None) => {
            return Err(V2RuntimeError::new(
                "provider_operator_trusted_host_runtime_missing",
                "TrustedHostNoTee requires an operator-signed runtime statement",
            ))
        }
        (V2AttestationMode::TeeHardware, _) => {}
    }
    Ok(VerifiedProviderOperatorTrust {
        root_public_key,
        trust_checkpoint_sha256,
        trusted_now_epoch_ms:
            trusted_time.trusted_now_epoch_ms,
    })
}

#[cfg(target_os = "linux")]
fn provider_trusted_role_key<'a>(
    config: &'a MeasuredProviderProcessConfig,
    role: Option<&str>,
    key_id: &str,
) -> Option<&'a ProviderTrustedRoleKey> {
    config
        .trust_bundle
        .checkpoint
        .role_keys
        .iter()
        .find(|candidate| {
            candidate.key_id == key_id
                && role.is_none_or(|role| {
                    candidate.role == role
                })
                && candidate.revoked_at_epoch_ms.is_none()
        })
}

#[cfg(target_os = "linux")]
fn verify_provider_trusted_role_signature(
    config: &MeasuredProviderProcessConfig,
    role: Option<&str>,
    key_id: &str,
    message: &[u8],
    signature: &str,
) -> bool {
    let Some(key) =
        provider_trusted_role_key(config, role, key_id)
    else {
        return false;
    };
    let Ok(public_key) =
        base64::engine::general_purpose::STANDARD
            .decode(&key.public_key_base64)
    else {
        return false;
    };
    let Ok(signature) =
        base64::engine::general_purpose::STANDARD
            .decode(signature)
    else {
        return false;
    };
    ring::signature::UnparsedPublicKey::new(
        &ring::signature::ED25519,
        public_key,
    )
    .verify(message, &signature)
    .is_ok()
}

