#[cfg(target_os = "linux")]
fn validate_provider_private_state_directory(
    config: &MeasuredProviderProcessConfig,
) -> Result<(), V2RuntimeError> {
    let metadata = std::fs::symlink_metadata(
        &config.durable_state_directory,
    )
    .map_err(|_| {
        V2RuntimeError::new(
            "provider_process_state_directory_unavailable",
            "inspect provider durable state directory",
        )
    })?;
    if !metadata.file_type().is_dir()
        || metadata.uid() != unsafe { libc::geteuid() }
        || metadata.gid() != unsafe { libc::getegid() }
        || metadata.mode() & 0o777 != 0o700
    {
        return Err(V2RuntimeError::new(
            "provider_process_state_directory_unsafe",
            "provider private state must be owned by the exact role UID/GID and have mode 0700",
        ));
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn validate_provider_shared_state_directories(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
) -> Result<(), V2RuntimeError> {
    if !provider_role_uses_shared_state(&config.role) {
        return Ok(());
    }
    let mut group_count = unsafe {
        libc::getgroups(0, std::ptr::null_mut())
    };
    if group_count < 0 || group_count > 64 {
        return Err(V2RuntimeError::new(
            "provider_shared_group_invalid",
            "read provider supplementary group count",
        ));
    }
    let mut groups = vec![
        0 as libc::gid_t;
        usize::try_from(group_count).unwrap_or(0)
    ];
    if group_count > 0 {
        group_count = unsafe {
            libc::getgroups(group_count, groups.as_mut_ptr())
        };
    }
    if group_count < 0
        || !groups
            .iter()
            .any(|group| *group == environment.shared_state_gid)
    {
        return Err(V2RuntimeError::new(
            "provider_shared_group_missing",
            "provider role lacks its configured non-secret shared-state group",
        ));
    }
    for path in [
        &environment.coordination_state_directory,
        &environment.immutable_state_directory,
    ] {
        let metadata = std::fs::symlink_metadata(path).map_err(|_| {
            V2RuntimeError::new(
                "provider_shared_state_unavailable",
                "inspect provider shared state directory",
            )
        })?;
        if !metadata.file_type().is_dir()
            || metadata.uid() != 0
            || metadata.gid() != environment.shared_state_gid
            || metadata.mode() & 0o3777 != 0o3770
        {
            return Err(V2RuntimeError::new(
                "provider_shared_state_unsafe",
                "provider shared state ownership or sticky setgid mode does not match the custody provision",
            ));
        }
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn acquire_provider_process_state_lock(
    config: &MeasuredProviderProcessConfig,
    deadline: &OperationDeadline,
) -> Result<File, V2RuntimeError> {
    validate_provider_private_state_directory(config)?;
    let path =
        config.durable_state_directory.join(".role.lock");
    let file = OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .mode(0o600)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(path)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_state_lock_failed",
                "open provider role state lock",
            )
        })?;
    let metadata = file.metadata().map_err(|_| {
        V2RuntimeError::new(
            "provider_process_state_lock_failed",
            "inspect provider role state lock",
        )
    })?;
    if !metadata.file_type().is_file()
        || metadata.uid() != unsafe { libc::geteuid() }
        || metadata.gid() != unsafe { libc::getegid() }
        || metadata.mode() & 0o777 != 0o600
        || metadata.nlink() != 1
    {
        return Err(V2RuntimeError::new(
            "provider_process_state_lock_unsafe",
            "provider role state lock is not an owner-only single-link file",
        ));
    }
    loop {
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_process_state_lock_deadline",
                "provider role state lock was not acquired before the shared deadline",
            ));
        }
        if unsafe {
            libc::flock(
                file.as_raw_fd(),
                libc::LOCK_EX | libc::LOCK_NB,
            )
        } == 0
        {
            return Ok(file);
        }
        if io::Error::last_os_error().raw_os_error()
            != Some(libc::EWOULDBLOCK)
        {
            return Err(V2RuntimeError::new(
                "provider_process_state_lock_failed",
                "acquire provider role state lock",
            ));
        }
        std::thread::sleep(Duration::from_millis(1));
    }
}

#[cfg(target_os = "linux")]
fn reconcile_provider_process_pending_records(
    config: &MeasuredProviderProcessConfig,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    let entries = std::fs::read_dir(
        &config.durable_state_directory,
    )
    .map_err(|_| {
        V2RuntimeError::new(
            "provider_process_state_reconciliation_failed",
            "enumerate provider role state transactions",
        )
    })?;
    let mut count = 0usize;
    for entry in entries {
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_process_state_reconciliation_deadline",
                "provider role state reconciliation exceeded the shared deadline",
            ));
        }
        count = count.checked_add(1).ok_or_else(|| {
            V2RuntimeError::new(
                "provider_process_state_reconciliation_failed",
                "provider role state entry count overflowed",
            )
        })?;
        if count > MAX_PROVIDER_ORPHAN_RECORDS {
            return Err(V2RuntimeError::new(
                "provider_process_state_reconciliation_overbound",
                "provider role state contains too many records",
            ));
        }
        let entry = entry.map_err(|_| {
            V2RuntimeError::new(
                "provider_process_state_reconciliation_failed",
                "read provider role state entry",
            )
        })?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            return Err(V2RuntimeError::new(
                "provider_process_state_reconciliation_failed",
                "provider role state contains a non-UTF-8 name",
            ));
        };
        let Some(key) = name
            .strip_prefix('.')
            .and_then(|value| value.strip_suffix(".pending"))
        else {
            continue;
        };
        if key.len() != 64
            || !key.bytes().all(|byte| {
                byte.is_ascii_digit()
                    || (b'a'..=b'f').contains(&byte)
            })
        {
            return Err(V2RuntimeError::new(
                "provider_process_state_reconciliation_failed",
                "provider pending transaction name is not content-addressed",
            ));
        }
        let pending_path = entry.path();
        let metadata =
            std::fs::symlink_metadata(&pending_path).map_err(
                |_| {
                    V2RuntimeError::new(
                        "provider_process_state_reconciliation_failed",
                        "inspect provider pending transaction",
                    )
                },
            )?;
        if !metadata.file_type().is_file()
            || metadata.uid() != unsafe { libc::geteuid() }
            || metadata.mode() & 0o777 != 0o600
            || metadata.nlink() != 1
            || metadata.len() == 0
            || metadata.len() > MAX_PROVIDER_ORPHAN_RECORD_BYTES
        {
            return Err(V2RuntimeError::new(
                "provider_process_state_reconciliation_failed",
                "provider pending transaction has unsafe metadata",
            ));
        }
        let final_path = config
            .durable_state_directory
            .join(format!("{key}.json"));
        if final_path.exists() {
            if deadline.expired()? {
                return Err(V2RuntimeError::new(
                    "provider_process_state_reconciliation_deadline",
                    "provider role state reconciliation exceeded the shared deadline",
                ));
            }
            let pending = std::fs::read(&pending_path)
                .map_err(|_| {
                    V2RuntimeError::new(
                        "provider_process_state_reconciliation_failed",
                        "read provider pending transaction",
                    )
                })?;
            let committed = std::fs::read(&final_path)
                .map_err(|_| {
                    V2RuntimeError::new(
                        "provider_process_state_reconciliation_failed",
                        "read provider committed transaction",
                    )
                })?;
            if pending != committed {
                return Err(V2RuntimeError::new(
                    "provider_process_state_reconciliation_conflict",
                    "pending and committed provider transactions disagree",
                ));
            }
            remove_file(&pending_path).map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_state_reconciliation_failed",
                    "remove duplicate provider pending transaction",
                )
            })?;
        } else {
            std::fs::rename(&pending_path, &final_path)
                .map_err(|_| {
                    V2RuntimeError::new(
                        "provider_process_state_reconciliation_failed",
                        "commit recovered provider pending transaction",
                    )
                })?;
        }
    }
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_process_state_reconciliation_deadline",
            "provider role state reconciliation exceeded the shared deadline",
        ));
    }
    File::open(&config.durable_state_directory)
        .and_then(|directory| directory.sync_all())
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_state_reconciliation_failed",
                "synchronize reconciled provider role state",
            )
        })
}

#[cfg(target_os = "linux")]
fn acquire_provider_coordination_lock(
    environment: &ProviderProcessEnvironment,
    deadline: &OperationDeadline,
) -> Result<File, V2RuntimeError> {
    let path = environment
        .coordination_state_directory
        .join(PROVIDER_COORDINATION_LOCK_NAME);
    let file = OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .mode(0o660)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(path)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_coordination_lock_failed",
                "open provider coordination lock",
            )
        })?;
    let metadata = file.metadata().map_err(|_| {
        V2RuntimeError::new(
            "provider_coordination_lock_failed",
            "inspect provider coordination lock",
        )
    })?;
    if !metadata.file_type().is_file()
        || metadata.gid() != environment.shared_state_gid
        || metadata.mode() & 0o777 != 0o660
        || metadata.nlink() != 1
    {
        return Err(V2RuntimeError::new(
            "provider_coordination_lock_unsafe",
            "provider coordination lock is not a shared-group mode-0660 single-link file",
        ));
    }
    loop {
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_coordination_lock_deadline",
                "provider coordination lock was not acquired before the shared deadline",
            ));
        }
        if unsafe {
            libc::flock(
                file.as_raw_fd(),
                libc::LOCK_EX | libc::LOCK_NB,
            )
        } == 0
        {
            return Ok(file);
        }
        if io::Error::last_os_error().raw_os_error()
            != Some(libc::EWOULDBLOCK)
        {
            return Err(V2RuntimeError::new(
                "provider_coordination_lock_failed",
                "acquire provider coordination lock",
            ));
        }
        std::thread::sleep(Duration::from_millis(1));
    }
}

#[cfg(target_os = "linux")]
fn validate_provider_shared_file_name(
    name: &str,
) -> Result<(), V2RuntimeError> {
    if name.is_empty()
        || name.len() > 192
        || !name.bytes().all(|byte| {
            byte.is_ascii_lowercase()
                || byte.is_ascii_digit()
                || matches!(byte, b'.' | b'-' | b'_')
        })
        || name.starts_with('.')
        || name.ends_with(".pending")
    {
        return Err(V2RuntimeError::new(
            "provider_shared_state_name_invalid",
            "provider shared-state record name is unsafe",
        ));
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn atomic_replace_provider_shared_record(
    environment: &ProviderProcessEnvironment,
    directory: &Path,
    name: &str,
    bytes: &[u8],
    expected_owner_uid: u32,
    deadline: &OperationDeadline,
) -> Result<String, V2RuntimeError> {
    validate_provider_shared_file_name(name)?;
    if unsafe { libc::geteuid() } != expected_owner_uid
        || bytes.is_empty()
        || bytes.len() as u64 > MAX_PROVIDER_ORPHAN_RECORD_BYTES
        || deadline.expired()?
    {
        return Err(V2RuntimeError::new(
            "provider_shared_state_write_invalid",
            "provider shared-state write is not owned, bounded, and live",
        ));
    }
    let final_path = directory.join(name);
    let pending_path = directory.join(format!(".{name}.pending"));
    if final_path.exists() {
        let metadata =
            std::fs::symlink_metadata(&final_path).map_err(
                |_| {
                    V2RuntimeError::new(
                        "provider_shared_state_metadata_failed",
                        "inspect provider shared-state record",
                    )
                },
            )?;
        if !metadata.file_type().is_file()
            || metadata.uid() != expected_owner_uid
            || metadata.gid() != environment.shared_state_gid
            || metadata.mode() & 0o777 != 0o640
            || metadata.nlink() != 1
        {
            return Err(V2RuntimeError::new(
                "provider_shared_state_owner_mismatch",
                "provider shared-state record is not owned by its authority",
            ));
        }
    }
    let mut pending = OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o640)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(&pending_path)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_shared_state_pending_failed",
                "create provider shared-state transaction",
            )
        })?;
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_shared_state_deadline",
            "provider shared-state deadline elapsed before write",
        ));
    }
    pending.write_all(bytes).map_err(|_| {
        V2RuntimeError::new(
            "provider_shared_state_write_failed",
            "write provider shared-state transaction",
        )
    })?;
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_shared_state_deadline",
            "provider shared-state deadline elapsed before file synchronization",
        ));
    }
    pending.sync_all().map_err(|_| {
        V2RuntimeError::new(
            "provider_shared_state_sync_failed",
            "synchronize provider shared-state transaction",
        )
    })?;
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_shared_state_deadline",
            "provider shared-state deadline elapsed before commit",
        ));
    }
    std::fs::rename(&pending_path, &final_path).map_err(|_| {
        V2RuntimeError::new(
            "provider_shared_state_commit_failed",
            "commit provider shared-state transaction",
        )
    })?;
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_shared_state_deadline",
            "provider shared-state deadline elapsed before directory synchronization",
        ));
    }
    File::open(directory)
        .and_then(|state| state.sync_all())
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_shared_state_sync_failed",
                "synchronize provider shared-state directory",
            )
        })?;
    Ok(format!("sha256:{:x}", Sha256::digest(bytes)))
}

#[cfg(target_os = "linux")]
fn read_provider_shared_record(
    environment: &ProviderProcessEnvironment,
    directory: &Path,
    name: &str,
    expected_owner_uid: u32,
    deadline: &OperationDeadline,
) -> Result<Option<Vec<u8>>, V2RuntimeError> {
    validate_provider_shared_file_name(name)?;
    let path = directory.join(name);
    let metadata = match std::fs::symlink_metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            return Ok(None)
        }
        Err(_) => {
            return Err(V2RuntimeError::new(
                "provider_shared_state_metadata_failed",
                "inspect provider shared-state record",
            ))
        }
    };
    if !metadata.file_type().is_file()
        || metadata.uid() != expected_owner_uid
        || metadata.gid() != environment.shared_state_gid
        || metadata.mode() & 0o777 != 0o640
        || metadata.nlink() != 1
        || metadata.len() == 0
        || metadata.len() > MAX_PROVIDER_ORPHAN_RECORD_BYTES
        || deadline.expired()?
    {
        return Err(V2RuntimeError::new(
            "provider_shared_state_record_unsafe",
            "provider shared-state record metadata or deadline is invalid",
        ));
    }
    std::fs::read(path)
        .map(Some)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_shared_state_read_failed",
                "read provider shared-state record",
            )
        })
}

#[cfg(target_os = "linux")]
fn provider_immutable_retrieval_id(
    owner_role: &str,
    owner_provider_id: &str,
    provider_generation: u64,
    artifact_kind: &str,
    artifact_sha256: &str,
    source_operation_binding_sha256: &str,
) -> Result<String, V2RuntimeError> {
    if !REQUIRED_ROLE_IDENTITIES.contains(&owner_role)
        || artifact_kind.is_empty()
        || artifact_kind.len() > 64
        || !artifact_kind.bytes().all(|byte| {
            byte.is_ascii_lowercase()
                || byte.is_ascii_digit()
                || matches!(byte, b'-' | b'_')
        })
    {
        return Err(V2RuntimeError::new(
            "provider_immutable_artifact_kind_invalid",
            "immutable provider artifact kind or owner role is invalid",
        ));
    }
    validate_identifier(owner_provider_id)?;
    validate_digest(artifact_sha256)?;
    validate_digest(source_operation_binding_sha256)?;
    if provider_generation == 0 {
        return Err(V2RuntimeError::new(
            "provider_immutable_generation_invalid",
            "immutable provider artifact generation is invalid",
        ));
    }
    let binding = response_observation_v2_canonical_binding_sha256(
        b"serverware.response-v2/provider-immutable-artifact/v1",
        &serde_json::json!({
            "ownerRole":owner_role,
            "ownerProviderId":owner_provider_id,
            "providerGeneration":provider_generation,
            "artifactKind":artifact_kind,
            "artifactSha256":artifact_sha256,
            "sourceOperationBindingSha256":
                source_operation_binding_sha256,
        }),
    )
    .ok_or_else(|| {
        V2RuntimeError::new(
            "provider_immutable_binding_invalid",
            "immutable provider artifact binding cannot be canonicalized",
        )
    })?;
    Ok(format!(
        "provider-immutable-{owner_role}-{}",
        binding.trim_start_matches("sha256:")
    ))
}

#[cfg(target_os = "linux")]
fn provider_immutable_owner_role(
    retrieval_id: &str,
) -> Result<&'static str, V2RuntimeError> {
    let suffix = retrieval_id
        .strip_prefix("provider-immutable-")
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_immutable_retrieval_id_invalid",
                "immutable provider retrieval ID has an invalid domain",
            )
        })?;
    REQUIRED_ROLE_IDENTITIES
        .iter()
        .copied()
        .find(|role| {
            suffix
                .strip_prefix(*role)
                .and_then(|value| value.strip_prefix('-'))
                .is_some_and(|digest| {
                    digest.len() == 64
                        && digest.bytes().all(|byte| {
                            byte.is_ascii_digit()
                                || (b'a'..=b'f').contains(&byte)
                        })
                })
        })
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_immutable_retrieval_id_invalid",
                "immutable provider retrieval ID does not encode a known role and digest",
            )
        })
}

#[cfg(target_os = "linux")]
fn provider_immutable_file_stem(retrieval_id: &str) -> String {
    format!(
        "{:x}",
        Sha256::digest(retrieval_id.as_bytes())
    )
}

#[cfg(target_os = "linux")]
fn commit_provider_immutable_file(
    environment: &ProviderProcessEnvironment,
    name: &str,
    bytes: &[u8],
    maximum_bytes: u64,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    validate_provider_shared_file_name(name)?;
    if bytes.is_empty()
        || bytes.len() as u64 > maximum_bytes
        || deadline.expired()?
    {
        return Err(V2RuntimeError::new(
            "provider_immutable_write_invalid",
            "immutable provider artifact is empty, overbound, or past deadline",
        ));
    }
    let final_path =
        environment.immutable_state_directory.join(name);
    match std::fs::symlink_metadata(&final_path) {
        Ok(metadata) => {
            if !metadata.file_type().is_file()
                || metadata.uid() != unsafe { libc::geteuid() }
                || metadata.gid() != environment.shared_state_gid
                || metadata.mode() & 0o777 != 0o640
                || metadata.nlink() != 1
                || metadata.len() != bytes.len() as u64
            {
                return Err(V2RuntimeError::new(
                    "provider_immutable_existing_unsafe",
                    "existing immutable provider artifact has unsafe metadata",
                ));
            }
            if deadline.expired()?
                || std::fs::read(&final_path)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_immutable_read_failed",
                            "read existing immutable provider artifact",
                        )
                    })?
                    != bytes
            {
                return Err(V2RuntimeError::new(
                    "provider_immutable_existing_conflict",
                    "immutable provider artifact key already contains different bytes",
                ));
            }
            return Ok(());
        }
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(_) => {
            return Err(V2RuntimeError::new(
                "provider_immutable_metadata_failed",
                "inspect immutable provider artifact",
            ))
        }
    }
    let pending_path = environment
        .immutable_state_directory
        .join(format!(".{name}.pending"));
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o640)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(&pending_path)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_immutable_create_failed",
                "create immutable provider artifact transaction",
            )
        })?;
    if unsafe { libc::fchmod(file.as_raw_fd(), 0o640) } != 0 {
        return Err(V2RuntimeError::new(
            "provider_immutable_mode_failed",
            "set immutable provider artifact mode",
        ));
    }
    for chunk in bytes.chunks(64 * 1024) {
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_immutable_deadline",
                "immutable provider artifact write exceeded the shared deadline",
            ));
        }
        file.write_all(chunk).map_err(|_| {
            V2RuntimeError::new(
                "provider_immutable_write_failed",
                "write immutable provider artifact transaction",
            )
        })?;
    }
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_immutable_deadline",
            "immutable provider artifact exceeded the shared deadline before file synchronization",
        ));
    }
    file.sync_all().map_err(|_| {
        V2RuntimeError::new(
            "provider_immutable_sync_failed",
            "synchronize immutable provider artifact transaction",
        )
    })?;
    drop(file);
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_immutable_deadline",
            "immutable provider artifact exceeded the shared deadline before commit",
        ));
    }
    std::fs::rename(&pending_path, &final_path).map_err(|_| {
        V2RuntimeError::new(
            "provider_immutable_commit_failed",
            "commit immutable provider artifact transaction",
        )
    })?;
    Ok(())
}

#[cfg(target_os = "linux")]
fn persist_provider_immutable_artifact(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    artifact_kind: &str,
    bytes: &[u8],
    source_operation_binding_sha256: &str,
    signing_key: &ed25519_dalek::SigningKey,
    deadline: &OperationDeadline,
) -> Result<ProviderImmutableArtifactRecord, V2RuntimeError> {
    let _lock =
        acquire_provider_coordination_lock(environment, deadline)?;
    let artifact_sha256 =
        format!("sha256:{:x}", Sha256::digest(bytes));
    let retrieval_id = provider_immutable_retrieval_id(
        &config.role,
        &config.provider_id,
        config.provider_generation,
        artifact_kind,
        &artifact_sha256,
        source_operation_binding_sha256,
    )?;
    let mut record = ProviderImmutableArtifactRecord {
        api_version:
            PROVIDER_IMMUTABLE_ARTIFACT_API_VERSION.to_owned(),
        retrieval_id: retrieval_id.clone(),
        artifact_kind: artifact_kind.to_owned(),
        artifact_sha256,
        byte_length: bytes.len() as u64,
        owner_role: config.role.clone(),
        owner_provider_id: config.provider_id.clone(),
        provider_generation: config.provider_generation,
        source_operation_binding_sha256:
            source_operation_binding_sha256.to_owned(),
        trust_checkpoint_sha256:
            config
                .proof_independent_pins
                .trust_checkpoint_sha256
                .clone(),
        revocation_epoch:
            config.proof_independent_pins.revocation_epoch,
        signer_key_id: config.key_id.clone(),
        signer_key_material_sha256:
            config.key_material_sha256.clone(),
        signature: String::new(),
    };
    record.signature = sign_provider_process_value(
        signing_key,
        b"serverware.response-v2/provider-immutable-artifact-record/v1\0",
        &record,
    )?;
    let record_bytes =
        crate::canonical_json_bytes(&record).map_err(|_| {
            V2RuntimeError::new(
                "provider_immutable_record_invalid",
                "immutable provider artifact record cannot be canonicalized",
            )
        })?;
    let stem = provider_immutable_file_stem(&retrieval_id);
    commit_provider_immutable_file(
        environment,
        &format!("{stem}.blob"),
        bytes,
        MAX_PROVIDER_ARTIFACT_BYTES,
        deadline,
    )?;
    commit_provider_immutable_file(
        environment,
        &format!("{stem}.immutable.json"),
        &record_bytes,
        MAX_PROVIDER_ORPHAN_RECORD_BYTES,
        deadline,
    )?;
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_immutable_deadline",
            "immutable provider artifact exceeded the shared deadline before directory synchronization",
        ));
    }
    File::open(&environment.immutable_state_directory)
        .and_then(|directory| directory.sync_all())
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_immutable_sync_failed",
                "synchronize immutable provider artifact directory",
            )
        })?;
    Ok(record)
}

#[cfg(target_os = "linux")]
fn retrieve_provider_immutable_artifact(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    retrieval_id: &str,
    expected_kind: Option<&str>,
    deadline: &OperationDeadline,
) -> Result<RetrievedProviderImmutableArtifact, V2RuntimeError> {
    let owner_role = provider_immutable_owner_role(retrieval_id)?;
    let owner_uid =
        provider_role_uid_from_environment(environment, owner_role)?;
    let stem = provider_immutable_file_stem(retrieval_id);
    let record_bytes = read_provider_shared_record(
        environment,
        &environment.immutable_state_directory,
        &format!("{stem}.immutable.json"),
        owner_uid,
        deadline,
    )?
    .ok_or_else(|| {
        V2RuntimeError::new(
            "provider_immutable_record_missing",
            "immutable provider artifact record is unavailable",
        )
    })?;
    let record: ProviderImmutableArtifactRecord =
        crate::decode_canonical_json(&record_bytes).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_immutable_record_invalid",
                    "immutable provider artifact record is not a closed DTO",
                )
            },
        )?;
    let trusted_key = provider_trusted_role_key(
        config,
        Some(owner_role),
        &record.signer_key_id,
    )
    .ok_or_else(|| {
        V2RuntimeError::new(
            "provider_immutable_signer_untrusted",
            "immutable provider artifact signer is not current in the operator checkpoint",
        )
    })?;
    let unsigned =
        crate::canonical_json_bytes(&record.without_signature())
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_immutable_record_invalid",
                    "immutable provider artifact record cannot be canonicalized",
                )
            })?;
    let mut signature_message =
        b"serverware.response-v2/provider-immutable-artifact-record/v1\0"
            .to_vec();
    signature_message.extend_from_slice(&unsigned);
    if record.api_version
            != PROVIDER_IMMUTABLE_ARTIFACT_API_VERSION
        || record.retrieval_id != retrieval_id
        || record.owner_role != owner_role
        || record.owner_provider_id != trusted_key.provider_id
        || record.provider_generation
            != config.provider_generation
        || record.signer_key_material_sha256
            != trusted_key.key_material_sha256
        || record.trust_checkpoint_sha256
            != config
                .proof_independent_pins
                .trust_checkpoint_sha256
        || record.revocation_epoch
            != config.proof_independent_pins.revocation_epoch
        || record.byte_length == 0
        || record.byte_length > MAX_PROVIDER_ARTIFACT_BYTES
        || expected_kind
            .is_some_and(|kind| record.artifact_kind != kind)
        || provider_immutable_retrieval_id(
            &record.owner_role,
            &record.owner_provider_id,
            record.provider_generation,
            &record.artifact_kind,
            &record.artifact_sha256,
            &record.source_operation_binding_sha256,
        )?
            != retrieval_id
        || !verify_provider_trusted_role_signature(
            config,
            Some(owner_role),
            &record.signer_key_id,
            &signature_message,
            &record.signature,
        )
    {
        return Err(V2RuntimeError::new(
            "provider_immutable_record_mismatch",
            "immutable provider artifact record does not match its role, trust checkpoint, generation, or signature",
        ));
    }
    let blob_path = environment
        .immutable_state_directory
        .join(format!("{stem}.blob"));
    let metadata =
        std::fs::symlink_metadata(&blob_path).map_err(|_| {
            V2RuntimeError::new(
                "provider_immutable_blob_missing",
                "immutable provider artifact bytes are unavailable",
            )
        })?;
    if !metadata.file_type().is_file()
        || metadata.uid() != owner_uid
        || metadata.gid() != environment.shared_state_gid
        || metadata.mode() & 0o777 != 0o640
        || metadata.nlink() != 1
        || metadata.len() != record.byte_length
    {
        return Err(V2RuntimeError::new(
            "provider_immutable_blob_unsafe",
            "immutable provider artifact bytes have unsafe metadata",
        ));
    }
    let mut file = File::open(blob_path).map_err(|_| {
        V2RuntimeError::new(
            "provider_immutable_read_failed",
            "open immutable provider artifact bytes",
        )
    })?;
    let capacity =
        usize::try_from(record.byte_length).map_err(|_| {
            V2RuntimeError::new(
                "provider_immutable_length_invalid",
                "immutable provider artifact length is unsupported",
            )
        })?;
    let mut bytes = Vec::with_capacity(capacity);
    let mut buffer = [0u8; 64 * 1024];
    loop {
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_immutable_deadline",
                "immutable provider artifact read exceeded the shared deadline",
            ));
        }
        let count = file.read(&mut buffer).map_err(|_| {
            V2RuntimeError::new(
                "provider_immutable_read_failed",
                "read immutable provider artifact bytes",
            )
        })?;
        if count == 0 {
            break;
        }
        bytes.extend_from_slice(&buffer[..count]);
        if bytes.len() > capacity {
            return Err(V2RuntimeError::new(
                "provider_immutable_length_mismatch",
                "immutable provider artifact grew while being read",
            ));
        }
    }
    buffer.fill(0);
    if bytes.len() != capacity
        || format!("sha256:{:x}", Sha256::digest(&bytes))
            != record.artifact_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_immutable_digest_mismatch",
            "immutable provider artifact bytes do not match their signed record",
        ));
    }
    Ok(RetrievedProviderImmutableArtifact {
        record,
        bytes,
        persistence_receipt_sha256: format!(
            "sha256:{:x}",
            Sha256::digest(&record_bytes)
        ),
    })
}

#[cfg(target_os = "linux")]
fn reconcile_provider_shared_pending_records(
    environment: &ProviderProcessEnvironment,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    if !provider_role_uses_shared_state(&environment.role) {
        return Ok(());
    }
    let owner_uid = unsafe { libc::geteuid() };
    for directory in [
        &environment.coordination_state_directory,
        &environment.immutable_state_directory,
    ] {
        let maximum_pending_bytes =
            if directory == &environment.immutable_state_directory {
                MAX_PROVIDER_ARTIFACT_BYTES
            } else {
                MAX_PROVIDER_ORPHAN_RECORD_BYTES
            };
        let entries = std::fs::read_dir(directory).map_err(|_| {
            V2RuntimeError::new(
                "provider_shared_state_reconciliation_failed",
                "enumerate provider shared-state transactions",
            )
        })?;
        let mut count = 0usize;
        for entry in entries {
            if deadline.expired()? {
                return Err(V2RuntimeError::new(
                    "provider_shared_state_reconciliation_deadline",
                    "provider shared-state reconciliation exceeded the shared deadline",
                ));
            }
            count = count.saturating_add(1);
            if count > MAX_PROVIDER_ORPHAN_RECORDS {
                return Err(V2RuntimeError::new(
                    "provider_shared_state_reconciliation_overbound",
                    "provider shared state contains too many records",
                ));
            }
            let entry = entry.map_err(|_| {
                V2RuntimeError::new(
                    "provider_shared_state_reconciliation_failed",
                    "read provider shared-state entry",
                )
            })?;
            let metadata =
                std::fs::symlink_metadata(entry.path()).map_err(|_| {
                V2RuntimeError::new(
                    "provider_shared_state_reconciliation_failed",
                    "inspect provider shared-state entry",
                )
            })?;
            if metadata.uid() != owner_uid {
                continue;
            }
            let name = entry.file_name();
            let Some(name) = name.to_str() else {
                return Err(V2RuntimeError::new(
                    "provider_shared_state_reconciliation_failed",
                    "provider shared state contains a non-UTF-8 owned name",
                ));
            };
            let Some(final_name) = name
                .strip_prefix('.')
                .and_then(|value| value.strip_suffix(".pending"))
            else {
                continue;
            };
            validate_provider_shared_file_name(final_name)?;
            if !metadata.file_type().is_file()
                || metadata.gid() != environment.shared_state_gid
                || metadata.mode() & 0o777 != 0o640
                || metadata.nlink() != 1
                || metadata.len() == 0
                || metadata.len() > maximum_pending_bytes
            {
                return Err(V2RuntimeError::new(
                    "provider_shared_state_reconciliation_failed",
                    "owned provider shared-state transaction is unsafe",
                ));
            }
            let final_path = directory.join(final_name);
            if let Ok(final_metadata) =
                std::fs::symlink_metadata(&final_path)
            {
                if !final_metadata.file_type().is_file()
                    || final_metadata.uid() != owner_uid
                    || final_metadata.gid()
                        != environment.shared_state_gid
                    || final_metadata.mode() & 0o777 != 0o640
                    || final_metadata.nlink() != 1
                    || final_metadata.len() == 0
                    || final_metadata.len() > maximum_pending_bytes
                {
                    return Err(V2RuntimeError::new(
                        "provider_shared_state_reconciliation_conflict",
                        "provider shared-state target is owned by another authority",
                    ));
                }
                if deadline.expired()? {
                    return Err(V2RuntimeError::new(
                        "provider_shared_state_reconciliation_deadline",
                        "provider shared-state reconciliation exceeded the shared deadline",
                    ));
                }
                let pending =
                    std::fs::read(entry.path()).map_err(|_| {
                        V2RuntimeError::new(
                            "provider_shared_state_reconciliation_failed",
                            "read pending provider shared-state transaction",
                        )
                    })?;
                let committed =
                    std::fs::read(&final_path).map_err(|_| {
                        V2RuntimeError::new(
                            "provider_shared_state_reconciliation_failed",
                            "read committed provider shared-state transaction",
                        )
                    })?;
                if pending != committed {
                    return Err(V2RuntimeError::new(
                        "provider_shared_state_reconciliation_conflict",
                        "pending and committed provider shared-state transactions disagree",
                    ));
                }
                remove_file(entry.path()).map_err(|_| {
                    V2RuntimeError::new(
                        "provider_shared_state_reconciliation_failed",
                        "remove duplicate provider shared-state transaction",
                    )
                })?;
            } else {
                std::fs::rename(entry.path(), final_path)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_shared_state_reconciliation_failed",
                            "commit recovered provider shared-state transaction",
                        )
                    })?;
            }
        }
        File::open(directory)
            .and_then(|state| state.sync_all())
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_shared_state_reconciliation_failed",
                    "synchronize reconciled provider shared state",
                )
            })?;
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn provider_mutation_owner_record_name(
    provider_operation_id: &str,
) -> String {
    format!(
        "{}.mutation-owner.json",
        provider_process_record_name(
            b"mutation-owner",
            provider_operation_id,
            "v1",
        )
    )
}

#[cfg(target_os = "linux")]
fn provider_fence_authority_state_name() -> &'static str {
    "fence-authority.json"
}

#[cfg(target_os = "linux")]
fn provider_emergency_fence_authority_state_name() -> &'static str {
    "emergency-fence-authority.json"
}

#[cfg(target_os = "linux")]
fn load_provider_fence_authority_state_for(
    environment: &ProviderProcessEnvironment,
    state_name: &str,
    authority_uid: u32,
    deadline: &OperationDeadline,
) -> Result<ProviderFenceAuthorityState, V2RuntimeError> {
    let bytes = read_provider_shared_record(
        environment,
        &environment.coordination_state_directory,
        state_name,
        authority_uid,
        deadline,
    )?;
    let Some(bytes) = bytes else {
        return Ok(ProviderFenceAuthorityState {
            api_version:
                PROVIDER_FENCE_AUTHORITY_STATE_API_VERSION
                    .to_owned(),
            authority_revision: 0,
            revocations: BTreeMap::new(),
        });
    };
    let state: ProviderFenceAuthorityState =
        crate::decode_canonical_json(&bytes).map_err(|_| {
            V2RuntimeError::new(
                "provider_fence_authority_state_invalid",
                "fence authority state is not a canonical closed DTO",
            )
        })?;
    if state.api_version
        != PROVIDER_FENCE_AUTHORITY_STATE_API_VERSION
        || state.authority_revision > MAX_SAFE_INTEGER
        || state.revocations.values().any(|revocation| {
            revocation.authority_revision == 0
                || revocation.authority_revision
                    > state.authority_revision
                || !is_sha256_digest(
                    &revocation.revocation_record_sha256,
                )
        })
    {
        return Err(V2RuntimeError::new(
            "provider_fence_authority_state_invalid",
            "fence authority state has invalid revision or revocation bindings",
        ));
    }
    Ok(state)
}

#[cfg(target_os = "linux")]
fn load_provider_fence_authority_state(
    environment: &ProviderProcessEnvironment,
    deadline: &OperationDeadline,
) -> Result<ProviderFenceAuthorityState, V2RuntimeError> {
    load_provider_fence_authority_state_for(
        environment,
        provider_fence_authority_state_name(),
        environment.linearizable_store_uid,
        deadline,
    )
}

#[cfg(target_os = "linux")]
fn load_provider_emergency_fence_authority_state(
    environment: &ProviderProcessEnvironment,
    deadline: &OperationDeadline,
) -> Result<ProviderFenceAuthorityState, V2RuntimeError> {
    load_provider_fence_authority_state_for(
        environment,
        provider_emergency_fence_authority_state_name(),
        environment.emergency_fence_revoker_uid,
        deadline,
    )
}

#[cfg(target_os = "linux")]
fn persist_provider_fence_authority_state_for(
    environment: &ProviderProcessEnvironment,
    state_name: &str,
    authority_uid: u32,
    state: &ProviderFenceAuthorityState,
    deadline: &OperationDeadline,
) -> Result<String, V2RuntimeError> {
    let bytes = crate::canonical_json_bytes(state).map_err(|_| {
        V2RuntimeError::new(
            "provider_fence_authority_state_invalid",
            "fence authority state cannot be canonicalized",
        )
    })?;
    atomic_replace_provider_shared_record(
        environment,
        &environment.coordination_state_directory,
        state_name,
        &bytes,
        authority_uid,
        deadline,
    )
}

#[cfg(target_os = "linux")]
fn provider_mutation_is_revoked(
    environment: &ProviderProcessEnvironment,
    provider_operation_id: &str,
    deadline: &OperationDeadline,
) -> Result<bool, V2RuntimeError> {
    Ok(load_provider_fence_authority_state(
        environment,
        deadline,
    )?
    .revocations
    .contains_key(provider_operation_id)
        || load_provider_emergency_fence_authority_state(
            environment,
            deadline,
        )?
        .revocations
        .contains_key(provider_operation_id))
}

#[cfg(target_os = "linux")]
fn load_provider_mutation_owner(
    environment: &ProviderProcessEnvironment,
    provider_operation_id: &str,
    deadline: &OperationDeadline,
) -> Result<Option<ProviderMutationOwnerRecord>, V2RuntimeError> {
    let name =
        provider_mutation_owner_record_name(provider_operation_id);
    let bytes = read_provider_shared_record(
        environment,
        &environment.coordination_state_directory,
        &name,
        environment.mutation_supervisor_uid,
        deadline,
    )?;
    bytes
        .map(|bytes| {
            let record: ProviderMutationOwnerRecord =
                crate::decode_canonical_json(&bytes).map_err(
                    |_| {
                        V2RuntimeError::new(
                            "provider_mutation_owner_invalid",
                            "mutation owner is not a canonical closed DTO",
                        )
                    },
                )?;
            if record.api_version
                != PROVIDER_MUTATION_OWNER_API_VERSION
                || record.provider_operation_id
                    != provider_operation_id
                || record.authority_revision == 0
                || record.authority_revision > MAX_SAFE_INTEGER
                || !is_sha256_digest(
                    &record.durable_start_receipt_sha256,
                )
                || !is_sha256_digest(
                    &record.mutation_fence_permit_sha256,
                )
            {
                return Err(V2RuntimeError::new(
                    "provider_mutation_owner_invalid",
                    "mutation owner is not bound to its durable start, fence, and revision",
                ));
            }
            Ok(record)
        })
        .transpose()
}

#[cfg(target_os = "linux")]
fn persist_provider_mutation_owner(
    environment: &ProviderProcessEnvironment,
    owner: &ProviderMutationOwnerRecord,
    deadline: &OperationDeadline,
) -> Result<String, V2RuntimeError> {
    let bytes = crate::canonical_json_bytes(owner).map_err(|_| {
        V2RuntimeError::new(
            "provider_mutation_owner_invalid",
            "mutation owner cannot be canonicalized",
        )
    })?;
    atomic_replace_provider_shared_record(
        environment,
        &environment.coordination_state_directory,
        &provider_mutation_owner_record_name(
            &owner.provider_operation_id,
        ),
        &bytes,
        environment.mutation_supervisor_uid,
        deadline,
    )
}

#[cfg(target_os = "linux")]
fn register_provider_mutation_owner(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    durable_start_receipt_sha256: &str,
    mutation_fence_permit_sha256: &str,
    signing_key: &ed25519_dalek::SigningKey,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    if config.role != "mutation-supervisor"
        || unsafe { libc::geteuid() }
            != environment.mutation_supervisor_uid
    {
        return Err(V2RuntimeError::new(
            "provider_mutation_owner_role_mismatch",
            "only the measured mutation supervisor may register mutation ownership",
        ));
    }
    let _lock =
        acquire_provider_coordination_lock(environment, deadline)?;
    if provider_mutation_is_revoked(
        environment,
        &environment.provider_operation_id,
        deadline,
    )? {
        return Err(V2RuntimeError::new(
            "provider_mutation_fence_revoked",
            "mutation ownership was revoked before provider dispatch",
        ));
    }
    if let Some(existing) = load_provider_mutation_owner(
        environment,
        &environment.provider_operation_id,
        deadline,
    )? {
        if existing.provider_generation
                == environment.generation
            && existing.request_sha256
                == environment.request_sha256
            && existing.attempt_id == environment.attempt_id
            && existing.attempt_revision
                == environment.attempt_revision
            && existing.fencing_token
                == environment.fencing_token
            && existing.launch_nonce == environment.launch_nonce
            && existing.durable_start_receipt_sha256
                == durable_start_receipt_sha256
            && existing.mutation_fence_permit_sha256
                == mutation_fence_permit_sha256
            && existing.status
                == ProviderMutationOwnerStatus::Active
        {
            return Ok(());
        }
        return Err(V2RuntimeError::new(
            "provider_mutation_owner_conflict",
            "mutation ownership key already has a different durable owner",
        ));
    }
    let mut owner = ProviderMutationOwnerRecord {
        api_version:
            PROVIDER_MUTATION_OWNER_API_VERSION.to_owned(),
        provider_operation_id:
            environment.provider_operation_id.clone(),
        provider_generation: environment.generation,
        request_sha256: environment.request_sha256.clone(),
        attempt_id: environment.attempt_id.clone(),
        attempt_revision: environment.attempt_revision,
        fencing_token: environment.fencing_token,
        predecessor_state_sha256:
            environment.predecessor_state_sha256.clone(),
        launch_nonce: environment.launch_nonce.clone(),
        durable_start_receipt_sha256:
            durable_start_receipt_sha256.to_owned(),
        mutation_fence_permit_sha256:
            mutation_fence_permit_sha256.to_owned(),
        monotonic_deadline:
            environment.monotonic_deadline.clone(),
        deadline_at_epoch_ms:
            environment.deadline_at_epoch_ms,
        status: ProviderMutationOwnerStatus::Active,
        terminal_payload_sha256: None,
        authority_revision: 1,
        signer_key_id: config.key_id.clone(),
        signer_key_material_sha256:
            config.key_material_sha256.clone(),
        signature: String::new(),
    };
    owner.signature = sign_provider_process_value(
        signing_key,
        b"serverware.response-v2/mutation-owner/v1\0",
        &owner,
    )?;
    persist_provider_mutation_owner(
        environment,
        &owner,
        deadline,
    )?;
    Ok(())
}

#[cfg(target_os = "linux")]
fn ensure_provider_mutation_owner_live(
    environment: &ProviderProcessEnvironment,
    deadline: &OperationDeadline,
) -> Result<File, V2RuntimeError> {
    let lock =
        acquire_provider_coordination_lock(environment, deadline)?;
    let owner = load_provider_mutation_owner(
        environment,
        &environment.provider_operation_id,
        deadline,
    )?
    .ok_or_else(|| {
        V2RuntimeError::new(
            "provider_mutation_owner_missing",
            "mutation operation lacks a durable ownership record",
        )
    })?;
    let revoked = provider_mutation_is_revoked(
        environment,
        &environment.provider_operation_id,
        deadline,
    )?;
    if owner.provider_generation != environment.generation
        || owner.request_sha256 != environment.request_sha256
        || owner.attempt_id != environment.attempt_id
        || owner.attempt_revision
            != environment.attempt_revision
        || owner.fencing_token != environment.fencing_token
        || owner.launch_nonce != environment.launch_nonce
        || owner.status != ProviderMutationOwnerStatus::Active
        || revoked
    {
        return Err(V2RuntimeError::new(
            "provider_mutation_owner_not_live",
            "mutation operation no longer owns its exact durable fence",
        ));
    }
    Ok(lock)
}

#[cfg(target_os = "linux")]
fn mark_provider_mutation_terminal(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    terminal_payload: &[u8],
    signing_key: &ed25519_dalek::SigningKey,
    deadline: &OperationDeadline,
) -> Result<(), V2RuntimeError> {
    let _lock =
        acquire_provider_coordination_lock(environment, deadline)?;
    let mut owner = load_provider_mutation_owner(
        environment,
        &environment.provider_operation_id,
        deadline,
    )?
    .ok_or_else(|| {
        V2RuntimeError::new(
            "provider_mutation_owner_missing",
            "committed mutation lacks a durable ownership record",
        )
    })?;
    if provider_mutation_is_revoked(
        environment,
        &environment.provider_operation_id,
        deadline,
    )? {
        return Err(V2RuntimeError::new(
            "provider_mutation_fence_revoked",
            "mutation was revoked before terminal commitment",
        ));
    }
    let terminal_sha256 =
        format!("sha256:{:x}", Sha256::digest(terminal_payload));
    if owner.status == ProviderMutationOwnerStatus::TerminalCommitted
    {
        if owner.terminal_payload_sha256.as_deref()
            == Some(terminal_sha256.as_str())
        {
            return Ok(());
        }
        return Err(V2RuntimeError::new(
            "provider_mutation_terminal_conflict",
            "mutation terminal already commits different bytes",
        ));
    }
    owner.status = ProviderMutationOwnerStatus::TerminalCommitted;
    owner.terminal_payload_sha256 = Some(terminal_sha256);
    owner.authority_revision = owner
        .authority_revision
        .checked_add(1)
        .filter(|revision| *revision <= MAX_SAFE_INTEGER)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_mutation_revision_overflow",
                "mutation ownership revision overflowed",
            )
        })?;
    owner.signature.clear();
    owner.signature = sign_provider_process_value(
        signing_key,
        b"serverware.response-v2/mutation-owner/v1\0",
        &owner,
    )?;
    persist_provider_mutation_owner(
        environment,
        &owner,
        deadline,
    )?;
    Ok(())
}

#[cfg(target_os = "linux")]
fn revoke_provider_mutation_fence(
    environment: &ProviderProcessEnvironment,
    provider_operation_id: &str,
    provider_generation: u64,
    fencing_token: u64,
    durable_start_receipt_sha256: &str,
    mutation_fence_permit_sha256: &str,
    deadline: &OperationDeadline,
) -> Result<(String, u64, bool), V2RuntimeError> {
    let effective_uid = unsafe { libc::geteuid() };
    let (state_name, authority_uid) =
        if environment.role == "linearizable-store"
            && effective_uid
                == environment.linearizable_store_uid
        {
            (
                provider_fence_authority_state_name(),
                environment.linearizable_store_uid,
            )
        } else if environment.role
                == "emergency-fence-revoker"
            && effective_uid
                == environment.emergency_fence_revoker_uid
        {
            (
                provider_emergency_fence_authority_state_name(),
                environment.emergency_fence_revoker_uid,
            )
        } else {
            return Err(V2RuntimeError::new(
                "provider_fence_authority_role_mismatch",
                "fence revocation requires the measured fence authority",
            ));
        };
    if provider_generation == 0
        || fencing_token == 0
        || !is_sha256_digest(durable_start_receipt_sha256)
        || !is_sha256_digest(mutation_fence_permit_sha256)
    {
        return Err(V2RuntimeError::new(
            "provider_fence_request_invalid",
            "fence revocation binding is incomplete",
        ));
    }
    let _lock =
        acquire_provider_coordination_lock(environment, deadline)?;
    let owner = load_provider_mutation_owner(
        environment,
        provider_operation_id,
        deadline,
    )?;
    if owner.as_ref().is_some_and(|owner| {
        owner.provider_generation != provider_generation
            || owner.fencing_token != fencing_token
            || owner.durable_start_receipt_sha256
                != durable_start_receipt_sha256
            || owner.mutation_fence_permit_sha256
                != mutation_fence_permit_sha256
    }) {
        return Err(V2RuntimeError::new(
            "provider_fence_owner_binding_mismatch",
            "fence revocation does not match the durable mutation owner",
        ));
    }
    let mut state = load_provider_fence_authority_state_for(
        environment,
        state_name,
        authority_uid,
        deadline,
    )?;
    let revocation = if let Some(existing) =
        state.revocations.get(provider_operation_id)
    {
        if existing.provider_generation != provider_generation
            || existing.fencing_token != fencing_token
            || existing.durable_start_receipt_sha256
                != durable_start_receipt_sha256
            || existing.mutation_fence_permit_sha256
                != mutation_fence_permit_sha256
        {
            return Err(V2RuntimeError::new(
                "provider_fence_cas_conflict",
                "fence authority already contains a different revocation",
            ));
        }
        existing.clone()
    } else {
        let authority_revision = state
            .authority_revision
            .checked_add(1)
            .filter(|revision| *revision <= MAX_SAFE_INTEGER)
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "provider_fence_revision_overflow",
                    "fence authority revision overflowed",
                )
            })?;
        let revocation_record_sha256 =
            response_observation_v2_canonical_binding_sha256(
                b"serverware.response-v2/provider-fence-cas/v1",
                &serde_json::json!({
                    "providerOperationId":provider_operation_id,
                    "providerGeneration":provider_generation,
                    "fencingToken":fencing_token,
                    "durableStartReceiptSha256":
                        durable_start_receipt_sha256,
                    "mutationFencePermitSha256":
                        mutation_fence_permit_sha256,
                    "authorityRevision":authority_revision,
                }),
            )
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "provider_fence_record_invalid",
                    "fence authority record cannot be canonically bound",
                )
            })?;
        let revocation = ProviderFenceAuthorityRevocation {
            provider_operation_id:
                provider_operation_id.to_owned(),
            provider_generation,
            fencing_token,
            durable_start_receipt_sha256:
                durable_start_receipt_sha256.to_owned(),
            mutation_fence_permit_sha256:
                mutation_fence_permit_sha256.to_owned(),
            authority_revision,
            revocation_record_sha256,
        };
        state.authority_revision = authority_revision;
        state.revocations.insert(
            provider_operation_id.to_owned(),
            revocation.clone(),
        );
        persist_provider_fence_authority_state_for(
            environment,
            state_name,
            authority_uid,
            &state,
            deadline,
        )?;
        revocation
    };
    let persisted = load_provider_fence_authority_state_for(
        environment,
        state_name,
        authority_uid,
        deadline,
    )?;
    let observed = persisted
        .revocations
        .get(provider_operation_id)
        .filter(|observed| {
            observed.revocation_record_sha256
                == revocation.revocation_record_sha256
                && observed.authority_revision
                    == revocation.authority_revision
        });
    // The legacy local-file authority cannot observe pidfd exit and cgroup
    // emptiness, so it must never claim quiescence. The seven-process state
    // authority issues that claim only after a revoked fence and independent
    // cleanup-watchdog observations of owner death and an empty cgroup.
    let fence_quiescent = false;
    Ok((
        revocation.revocation_record_sha256,
        revocation.authority_revision,
        fence_quiescent,
    ))
}

#[cfg(target_os = "linux")]
fn run_legacy_provider_rpc_worker_from_env(
) -> Result<(), V2RuntimeError> {
    use ed25519_dalek::{Signer as _, SigningKey};

    let environment = read_provider_process_environment()?;
    let absolute_boottime_ns = parse_monotonic_deadline(
        &environment.monotonic_deadline,
        &environment.monotonic_deadline.custody_boot_id,
    )?;
    let deadline = OperationDeadline {
        absolute_epoch_ms: environment.deadline_at_epoch_ms,
        monotonic: environment.monotonic_deadline.clone(),
        absolute_boottime_ns,
        started: Instant::now(),
        maximum_duration: Duration::from_millis(
            absolute_boottime_ns
                .saturating_sub(clock_boottime_ns()?)
                .checked_div(1_000_000)
                .unwrap_or(0)
                .max(1),
        ),
    };
    let config_bytes =
        read_sealed_provider_process_config(environment.config_fd)?;
    if format!("sha256:{:x}", Sha256::digest(&config_bytes))
        != environment.config_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_process_config_measurement_mismatch",
            "sealed provider process config does not match the custody measurement",
        ));
    }
    let config: MeasuredProviderProcessConfig =
        crate::decode_canonical_json(&config_bytes).map_err(|_| {
            V2RuntimeError::new(
                "provider_process_config_invalid",
                "provider process config is not a canonical closed DTO",
            )
        })?;
    if config.api_version != PROVIDER_PROCESS_CONFIG_API_VERSION
        || config.role != environment.role
        || config.provider_generation != environment.generation
        || config.allowed_operations.is_empty()
        || !config.durable_state_directory.is_absolute()
        || config
            .credential_store_directory
            .as_ref()
            .is_some_and(|path| !path.is_absolute())
        || (config.role == "mutation-supervisor"
            && (config.credential_store_directory.is_none()
                || config
                    .tls_trust_anchors_der_base64
                    .is_empty()))
    {
        return Err(V2RuntimeError::new(
            "provider_process_config_binding_mismatch",
            "provider config is not bound to the launched role and generation",
        ));
    }
    validate_identifier(&config.provider_id)?;
    validate_digest(&config.key_id)?;
    validate_digest(&config.key_material_sha256)?;
    validate_digest(&config.tee_measurement_sha256)?;
    validate_digest(
        &config.custody_executable_measurement_sha256,
    )?;
    validate_digest(&config.role_identity_root_sha256)?;
    validate_digest(
        &config.proof_independent_pins_root_sha256,
    )?;
    for digest in [
        &config.proof_independent_pins.trust_root_sha256,
        &config
            .proof_independent_pins
            .trust_checkpoint_sha256,
        &config
            .proof_independent_pins
            .public_release_policy_sha256,
        &config
            .proof_independent_pins
            .pinned_genesis_state_sha256,
        &config
            .proof_independent_pins
            .quorum_membership_root_sha256,
        &config
            .proof_independent_pins
            .transparency_anchor_root_sha256,
        &config
            .proof_independent_pins
            .recovery_authority_key_id,
    ] {
        validate_digest(digest)?;
    }
    if config.proof_independent_pins_root_sha256
        != proof_independent_pins_root_from_pins(
            &config.proof_independent_pins,
        )
    {
        return Err(V2RuntimeError::new(
            "provider_process_proof_pins_root_mismatch",
            "provider process proof pins do not match their configured root",
        ));
    }
    let _operator_trust =
        verify_provider_operator_trust_bundle(
            &config,
            &deadline,
        )?;
    let measured_role = provider_trusted_role_key(
        &config,
        Some(&config.role),
        &config.key_id,
    )
    .ok_or_else(|| {
        V2RuntimeError::new(
            "provider_operator_role_measurement_missing",
            "operator checkpoint lacks the launched measured role",
        )
    })?;
    if measured_role.provider_generation
            != config.provider_generation
        || measured_role.executable_measurement_sha256
            != environment.executable_sha256
        || measured_role.provider_config_sha256
            != environment.config_sha256
        || measured_role.tee_measurement_sha256
            != config.tee_measurement_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_operator_role_measurement_mismatch",
            "launched provider measurements do not match the operator-signed role checkpoint",
        ));
    }
    let mut seed = base64::engine::general_purpose::STANDARD
        .decode(&config.signing_seed_base64)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_signing_seed_invalid",
                "provider signing seed is not canonical base64",
            )
        })?;
    if seed.len() != 32 {
        seed.fill(0);
        return Err(V2RuntimeError::new(
            "provider_process_signing_seed_invalid",
            "provider signing seed must contain exactly 32 bytes",
        ));
    }
    let mut seed_array = [0u8; 32];
    seed_array.copy_from_slice(&seed);
    seed.fill(0);
    let signing_key = SigningKey::from_bytes(&seed_array);
    seed_array.fill(0);
    let public_key = signing_key.verifying_key().to_bytes();
    if format!("sha256:{:x}", Sha256::digest(public_key))
        != config.key_material_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_process_signing_key_mismatch",
            "provider signing seed does not match the pinned verification key",
        ));
    }
    validate_provider_shared_state_directories(
        &config,
        &environment,
    )?;
    let _role_state_lock =
        acquire_provider_process_state_lock(&config, &deadline)?;
    reconcile_provider_process_pending_records(
        &config,
        &deadline,
    )?;
    if provider_role_uses_shared_state(&config.role) {
        let _coordination_lock =
            acquire_provider_coordination_lock(
                &environment,
                &deadline,
            )?;
        reconcile_provider_shared_pending_records(
            &environment,
            &deadline,
        )?;
    }
    let socket = connect_provider_process_socket(
        &environment.socket_path,
        &environment.monotonic_deadline,
    )?;
    authenticate_provider_custody_peer(
        socket.as_raw_fd(),
        &config,
    )?;
    let start_record = ProviderDurableStartRecord {
        api_version: PROVIDER_RPC_API_VERSION,
        role: &config.role,
        provider_id: &config.provider_id,
        provider_generation: config.provider_generation,
        provider_operation_id:
            &environment.provider_operation_id,
        request_sha256: &environment.request_sha256,
        attempt_id: &environment.attempt_id,
        attempt_revision: environment.attempt_revision,
        fencing_token: environment.fencing_token,
        predecessor_state_sha256:
            &environment.predecessor_state_sha256,
        monotonic_deadline:
            &environment.monotonic_deadline,
        deadline_at_epoch_ms:
            environment.deadline_at_epoch_ms,
        launch_nonce: &environment.launch_nonce,
        executable_measurement_sha256:
            &environment.executable_sha256,
        provider_config_sha256: &environment.config_sha256,
        tee_measurement_sha256:
            &config.tee_measurement_sha256,
    };
    let start_bytes =
        crate::canonical_json_bytes(&start_record).map_err(|_| {
            V2RuntimeError::new(
                "provider_durable_start_invalid",
                "provider durable-start record cannot be canonicalized",
            )
        })?;
    let durable_start_receipt_sha256 =
        persist_provider_process_record(
            &config,
            b"start",
            &environment.provider_operation_id,
            &environment.launch_nonce,
            &start_bytes,
            &deadline,
        )?;
    let mutation_fence_permit_sha256 =
        provider_fence_receipt_sha256(
            &environment.provider_operation_id,
            environment.generation,
            environment.fencing_token,
            &durable_start_receipt_sha256,
        );
    let launch_attestation_sha256 = {
        let mut hasher = Sha256::new();
        append_hash_frame(
            &mut hasher,
            b"serverware.response-v2/provider-launch-attestation/v1",
        );
        for value in [
            environment.executable_sha256.as_bytes(),
            environment.config_sha256.as_bytes(),
            config.tee_measurement_sha256.as_bytes(),
            environment.launch_nonce.as_bytes(),
            durable_start_receipt_sha256.as_bytes(),
        ] {
            append_hash_frame(&mut hasher, value);
        }
        format!("sha256:{:x}", hasher.finalize())
    };
    let issued_at_epoch_ms = system_time_epoch_ms()?;
    let mut hello = ProviderRpcLaunchHello {
        api_version: PROVIDER_RPC_API_VERSION.to_owned(),
        role: config.role.clone(),
        provider_id: config.provider_id.clone(),
        provider_generation: config.provider_generation,
        provider_operation_id:
            environment.provider_operation_id.clone(),
        request_sha256: environment.request_sha256.clone(),
        attempt_id: environment.attempt_id.clone(),
        attempt_revision: environment.attempt_revision,
        fencing_token: environment.fencing_token,
        predecessor_state_sha256:
            environment.predecessor_state_sha256.clone(),
        monotonic_deadline:
            environment.monotonic_deadline.clone(),
        deadline_at_epoch_ms: environment.deadline_at_epoch_ms,
        launch_nonce: environment.launch_nonce.clone(),
        durable_start_receipt_sha256:
            durable_start_receipt_sha256.clone(),
        mutation_fence_permit_sha256:
            mutation_fence_permit_sha256.clone(),
        launch_attestation_sha256,
        issued_at_epoch_ms,
        expires_at_epoch_ms:
            environment.deadline_at_epoch_ms,
        signer_key_id: config.key_id.clone(),
        signer_key_material_sha256:
            config.key_material_sha256.clone(),
        signature: String::new(),
    };
    hello.signature = sign_provider_process_value(
        &signing_key,
        b"serverware.response-v2/provider-launch-hello/v1\0",
        &hello,
    )?;
    let hello_bytes =
        crate::canonical_json_bytes(&hello).map_err(|_| {
            V2RuntimeError::new(
                "provider_launch_hello_invalid",
                "provider launch hello cannot be canonicalized",
            )
        })?;
    send_provider_frame_raw_fds(
        socket.as_raw_fd(),
        &hello_bytes,
        &[],
    )?;
    let parent_pidfd = provider_parent_pidfd()?;
    let provider_remaining_ms =
        remaining_operation_deadline_ms(&deadline)?;
    let (request_bytes, request_fds) = wait_for_provider_frame(
        socket.as_raw_fd(),
        parent_pidfd.as_raw_fd(),
        RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES,
        provider_remaining_ms,
        &deadline,
    )?;
    let request: ProviderRpcRequestEnvelope =
        crate::decode_canonical_json(&request_bytes).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_rpc_request_invalid",
                    "provider request does not satisfy its closed envelope",
                )
            },
        )?;
    validate_provider_process_request(
        &request,
        &environment,
        &config,
    )?;
    if request.operation
        == ProviderSubchannelOperation::LifecycleDispatch
    {
        register_provider_mutation_owner(
            &config,
            &environment,
            &durable_start_receipt_sha256,
            &mutation_fence_permit_sha256,
            &signing_key,
            &deadline,
        )?;
    }
    let canonical_payload =
        base64::engine::general_purpose::STANDARD
            .decode(&request.canonical_payload_base64)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_rpc_payload_invalid",
                    "provider request payload is not canonical base64",
                )
            })?;
    if format!("sha256:{:x}", Sha256::digest(&canonical_payload))
        != request.canonical_payload_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_rpc_payload_digest_mismatch",
            "provider request payload does not match its digest",
        ));
    }
    let mut operation_result = execute_provider_process_operation(
        &config,
        &environment,
        &request,
        &canonical_payload,
        request_fds,
        &signing_key,
        &deadline,
    );
    if request.operation
            == ProviderSubchannelOperation::LifecycleDispatch
        && let Ok(payload) = &operation_result
        && let Err(error) = mark_provider_mutation_terminal(
            &config,
            &environment,
            &payload.canonical_payload,
            &signing_key,
            &deadline,
        )
    {
        operation_result = Err(error);
    }
    let operation_observed_at_epoch_ms =
        system_time_epoch_ms()?;
    let (
        status,
        operation_output,
        reconciliation_reference,
    ) = match operation_result {
        Ok(output) => (
            ProviderRpcTerminalStatus::Committed,
            output,
            None,
        ),
        Err(_) => {
            let record = ProviderProcessOutcomeUnknownRecord {
                api_version: PROVIDER_RPC_API_VERSION,
                provider_operation_id:
                    &environment.provider_operation_id,
                request_sha256: &environment.request_sha256,
                operation: request.operation,
                attempt_id: &environment.attempt_id,
                attempt_revision:
                    environment.attempt_revision,
                fencing_token: environment.fencing_token,
                predecessor_state_sha256:
                    &environment.predecessor_state_sha256,
                monotonic_deadline:
                    &environment.monotonic_deadline,
                deadline_at_epoch_ms:
                    environment.deadline_at_epoch_ms,
                durable_start_receipt_sha256:
                    &durable_start_receipt_sha256,
                observed_at_epoch_ms:
                    operation_observed_at_epoch_ms,
                outcome: "OUTCOME_UNKNOWN",
            };
            let record_bytes =
                crate::canonical_json_bytes(&record).map_err(
                    |_| {
                        V2RuntimeError::new(
                            "provider_outcome_unknown_record_invalid",
                            "provider outcome-unknown record cannot be canonicalized",
                        )
                    },
                )?;
            let record_name = provider_process_record_name(
                b"outcome-unknown",
                &environment.provider_operation_id,
                &environment.launch_nonce,
            );
            let record_sha256 =
                persist_provider_process_record(
                    &config,
                    b"outcome-unknown",
                    &environment.provider_operation_id,
                    &environment.launch_nonce,
                    &record_bytes,
                    &deadline,
                )?;
            (
                ProviderRpcTerminalStatus::OutcomeUnknown,
                ProviderProcessOperationOutput::control(
                    b"null".to_vec(),
                ),
                Some(EvidenceReference {
                    evidence_type:
                        V2EvidenceType::OutcomeUnknownReconciliation,
                    evidence_sha256: record_sha256,
                    retrieval_id:
                        format!("provider-record-{record_name}"),
                }),
            )
        }
    };
    if operation_output.output_descriptors.len()
            != operation_output.output_files.len()
        || operation_output.output_descriptors.len()
            > PROVIDER_RPC_MAX_FDS
    {
        return Err(V2RuntimeError::new(
            "provider_process_output_manifest_invalid",
            "provider output descriptors do not match delivered exact objects",
        ));
    }
    let output_validation_files = operation_output
        .output_files
        .iter()
        .map(File::try_clone)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_output_clone_failed",
                "duplicate provider output descriptors for validation",
            )
        })?;
    validate_exact_object_files(
        &operation_output.output_descriptors,
        output_validation_files,
        Some(&deadline),
    )?;
    let now = system_time_epoch_ms()?;
    let mut terminal = ProviderRpcTerminalEnvelope {
        api_version: PROVIDER_RPC_API_VERSION.to_owned(),
        operation: request.operation,
        role: config.role.clone(),
        provider_id: config.provider_id.clone(),
        provider_generation: config.provider_generation,
        provider_operation_id:
            environment.provider_operation_id.clone(),
        provider_operation_binding_sha256:
            request.provider_operation_binding_sha256,
        request_sha256: environment.request_sha256,
        attempt_id: environment.attempt_id,
        attempt_revision: environment.attempt_revision,
        fencing_token: environment.fencing_token,
        predecessor_state_sha256:
            environment.predecessor_state_sha256,
        monotonic_deadline:
            environment.monotonic_deadline,
        deadline_at_epoch_ms: environment.deadline_at_epoch_ms,
        status,
        canonical_payload_base64:
            base64::engine::general_purpose::STANDARD
                .encode(&operation_output.canonical_payload),
        canonical_payload_sha256: format!(
            "sha256:{:x}",
            Sha256::digest(&operation_output.canonical_payload)
        ),
        output_manifest_sha256:
            descriptor_manifest_sha256(
                &operation_output.output_descriptors,
            ),
        output_descriptors:
            operation_output.output_descriptors.clone(),
        durable_start_receipt_sha256,
        durable_fence_receipt_sha256:
            mutation_fence_permit_sha256,
        reconciliation_reference,
        issued_at_epoch_ms: now,
        expires_at_epoch_ms: environment.deadline_at_epoch_ms,
        signer_key_id: config.key_id,
        signer_key_material_sha256:
            config.key_material_sha256,
        signature: String::new(),
    };
    terminal.signature = sign_provider_process_value(
        &signing_key,
        b"serverware.response-v2/provider-terminal/v1\0",
        &terminal,
    )?;
    let terminal_bytes =
        crate::canonical_json_bytes(&terminal).map_err(|_| {
            V2RuntimeError::new(
                "provider_rpc_terminal_invalid",
                "provider terminal cannot be canonicalized",
            )
        })?;
    let output_raw_fds = operation_output
        .output_files
        .iter()
        .map(AsRawFd::as_raw_fd)
        .collect::<Vec<_>>();
    send_provider_frame_raw_fds(
        socket.as_raw_fd(),
        &terminal_bytes,
        &output_raw_fds,
    )
}

#[cfg(not(target_os = "linux"))]
fn run_legacy_provider_rpc_worker_from_env(
) -> Result<(), V2RuntimeError> {
    Err(V2RuntimeError::new(
        "provider_router_unsupported",
        "measured provider process requires Linux; no fallback is permitted",
    ))
}

pub fn run_response_observation_v2_provider_from_env(
) -> Result<(), V2RuntimeError> {
    supervisor::dispatch_from_process_args()
}

#[cfg(target_os = "linux")]
fn provider_process_env(
    name: &'static str,
) -> Result<String, V2RuntimeError> {
    std::env::var(name).map_err(|_| {
        V2RuntimeError::new(
            "provider_process_environment_invalid",
            format!("missing required provider environment {name}"),
        )
    })
}

#[cfg(target_os = "linux")]
fn read_provider_process_environment(
) -> Result<ProviderProcessEnvironment, V2RuntimeError> {
    let parse_u64 = |name: &'static str| {
        provider_process_env(name)?.parse::<u64>().map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_process_environment_invalid",
                    format!("provider environment {name} is not a canonical u64"),
                )
            },
        )
    };
    let config_fd_u64 =
        parse_u64("SERVERWARE_PROVIDER_CONFIG_FD")?;
    let config_fd = RawFd::try_from(config_fd_u64).map_err(|_| {
        V2RuntimeError::new(
            "provider_process_environment_invalid",
            "provider config descriptor is outside RawFd",
        )
    })?;
    let environment = ProviderProcessEnvironment {
        socket_path: PathBuf::from(provider_process_env(
            "SERVERWARE_PROVIDER_RPC_SOCKET",
        )?),
        role: provider_process_env("SERVERWARE_PROVIDER_ROLE")?,
        provider_operation_id: provider_process_env(
            "SERVERWARE_PROVIDER_OPERATION_ID",
        )?,
        request_sha256: provider_process_env(
            "SERVERWARE_PROVIDER_REQUEST_SHA256",
        )?,
        attempt_id: provider_process_env(
            "SERVERWARE_PROVIDER_ATTEMPT_ID",
        )?,
        attempt_revision: parse_u64(
            "SERVERWARE_PROVIDER_ATTEMPT_REVISION",
        )?,
        fencing_token: parse_u64(
            "SERVERWARE_PROVIDER_FENCING_TOKEN",
        )?,
        predecessor_state_sha256: provider_process_env(
            "SERVERWARE_PROVIDER_PREDECESSOR_STATE_SHA256",
        )?,
        monotonic_deadline: V2MonotonicDeadlineV1 {
            api_version:
                V2_MONOTONIC_DEADLINE_VERSION.to_owned(),
            custody_boot_id: provider_process_env(
                "SERVERWARE_PROVIDER_DEADLINE_CUSTODY_BOOT_ID",
            )?,
            clock_id: V2MonotonicClockId::ClockBoottime,
            absolute_boottime_ns: provider_process_env(
                "SERVERWARE_PROVIDER_DEADLINE_AT_BOOTTIME_NS",
            )?,
        },
        deadline_at_epoch_ms: parse_u64(
            "SERVERWARE_PROVIDER_DEADLINE_AT_EPOCH_MS",
        )?,
        generation: parse_u64(
            "SERVERWARE_PROVIDER_GENERATION",
        )?,
        config_fd,
        config_sha256: provider_process_env(
            "SERVERWARE_PROVIDER_CONFIG_SHA256",
        )?,
        executable_sha256: provider_process_env(
            "SERVERWARE_PROVIDER_EXECUTABLE_SHA256",
        )?,
        launch_nonce: provider_process_env(
            "SERVERWARE_PROVIDER_LAUNCH_NONCE",
        )?,
        coordination_state_directory: PathBuf::from(
            provider_process_env(
                "SERVERWARE_PROVIDER_COORDINATION_STATE_DIRECTORY",
            )?,
        ),
        immutable_state_directory: PathBuf::from(
            provider_process_env(
                "SERVERWARE_PROVIDER_IMMUTABLE_STATE_DIRECTORY",
            )?,
        ),
        shared_state_gid: u32::try_from(parse_u64(
            "SERVERWARE_PROVIDER_SHARED_STATE_GID",
        )?)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_environment_invalid",
                "provider shared-state GID is outside u32",
            )
        })?,
        provider_uid_base: u32::try_from(parse_u64(
            "SERVERWARE_PROVIDER_UID_BASE",
        )?)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_environment_invalid",
                "provider UID base is outside u32",
            )
        })?,
        mutation_supervisor_uid: u32::try_from(parse_u64(
            "SERVERWARE_PROVIDER_MUTATION_SUPERVISOR_UID",
        )?)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_environment_invalid",
                "mutation-supervisor UID is outside u32",
            )
        })?,
        linearizable_store_uid: u32::try_from(parse_u64(
            "SERVERWARE_PROVIDER_LINEARIZABLE_STORE_UID",
        )?)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_environment_invalid",
                "linearizable-store UID is outside u32",
            )
        })?,
        emergency_fence_revoker_uid: u32::try_from(parse_u64(
            "SERVERWARE_PROVIDER_EMERGENCY_FENCE_REVOKER_UID",
        )?)
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_process_environment_invalid",
                "emergency-fence-revoker UID is outside u32",
            )
        })?,
    };
    if !environment.socket_path.is_absolute()
        || !environment
            .coordination_state_directory
            .is_absolute()
        || !environment.immutable_state_directory.is_absolute()
        || environment.shared_state_gid == 0
        || environment.provider_uid_base == 0
        || environment.mutation_supervisor_uid == 0
        || environment.linearizable_store_uid == 0
        || environment.emergency_fence_revoker_uid == 0
        || environment.mutation_supervisor_uid
            == environment.linearizable_store_uid
        || environment.emergency_fence_revoker_uid
            == environment.linearizable_store_uid
        || environment.emergency_fence_revoker_uid
            == environment.mutation_supervisor_uid
    {
        return Err(V2RuntimeError::new(
            "provider_process_environment_invalid",
            "provider socket and shared-state paths must be absolute and the shared GID must be nonzero",
        ));
    }
    validate_identifier(&environment.provider_operation_id)?;
    validate_identifier(&environment.attempt_id)?;
    validate_identifier(&environment.launch_nonce)?;
    for digest in [
        &environment.request_sha256,
        &environment.predecessor_state_sha256,
        &environment.config_sha256,
        &environment.executable_sha256,
    ] {
        validate_digest(digest)?;
    }
    Ok(environment)
}

#[cfg(target_os = "linux")]
fn provider_role_uid_from_environment(
    environment: &ProviderProcessEnvironment,
    role: &str,
) -> Result<u32, V2RuntimeError> {
    let offset = REQUIRED_ROLE_IDENTITIES
        .iter()
        .position(|candidate| *candidate == role)
        .and_then(|index| u32::try_from(index).ok())
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_role_unconfigured",
                "provider role has no isolated numeric identity",
            )
        })?;
    environment
        .provider_uid_base
        .checked_add(offset)
        .filter(|uid| *uid != 0)
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_uid_range_invalid",
                "provider UID base cannot represent the requested role",
            )
        })
}

#[cfg(target_os = "linux")]
fn read_sealed_provider_process_config(
    config_fd: RawFd,
) -> Result<Vec<u8>, V2RuntimeError> {
    if config_fd < 3 {
        return Err(V2RuntimeError::new(
            "provider_process_config_fd_invalid",
            "provider config descriptor may not alias a standard stream",
        ));
    }
    let seals = unsafe {
        libc::fcntl(config_fd, libc::F_GET_SEALS)
    };
    let required = libc::F_SEAL_SEAL
        | libc::F_SEAL_SHRINK
        | libc::F_SEAL_GROW
        | libc::F_SEAL_WRITE;
    if seals < 0 || seals & required != required {
        return Err(V2RuntimeError::new(
            "provider_process_config_unsealed",
            "provider config descriptor lacks every immutable memfd seal",
        ));
    }
    let mut stat: libc::stat = unsafe { std::mem::zeroed() };
    if unsafe { libc::fstat(config_fd, &mut stat) } != 0
        || stat.st_size <= 0
        || u64::try_from(stat.st_size).unwrap_or(u64::MAX)
            > MAX_CONFIG_BYTES
    {
        return Err(V2RuntimeError::new(
            "provider_process_config_bounds_invalid",
            "sealed provider config size is invalid",
        ));
    }
    let length = usize::try_from(stat.st_size).map_err(|_| {
        V2RuntimeError::new(
            "provider_process_config_bounds_invalid",
            "provider config length is unsupported",
        )
    })?;
    let mut bytes = vec![0u8; length];
    let mut offset = 0usize;
    while offset < bytes.len() {
        let count = unsafe {
            libc::pread(
                config_fd,
                bytes[offset..].as_mut_ptr().cast(),
                bytes.len() - offset,
                offset as libc::off_t,
            )
        };
        if count <= 0 {
            bytes.fill(0);
            return Err(V2RuntimeError::new(
                "provider_process_config_read_failed",
                "read exact sealed provider config bytes",
            ));
        }
        offset = offset
            .checked_add(usize::try_from(count).unwrap_or(usize::MAX))
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "provider_process_config_read_failed",
                    "provider config read offset overflowed",
                )
            })?;
    }
    Ok(bytes)
}

#[cfg(target_os = "linux")]
fn connect_provider_process_socket(
    path: &Path,
    monotonic_deadline: &V2MonotonicDeadlineV1,
) -> Result<OwnedFd, V2RuntimeError> {
    let absolute_boottime_ns = parse_monotonic_deadline(
        monotonic_deadline,
        &monotonic_deadline.custody_boot_id,
    )?;
    let path_bytes = path.as_os_str().as_bytes();
    let mut address: libc::sockaddr_un =
        unsafe { std::mem::zeroed() };
    if path_bytes.is_empty()
        || path_bytes.len() >= address.sun_path.len()
    {
        return Err(V2RuntimeError::new(
            "provider_process_socket_path_invalid",
            "provider rendezvous path exceeds sockaddr_un",
        ));
    }
    address.sun_family = libc::AF_UNIX as libc::sa_family_t;
    for (target, source) in address
        .sun_path
        .iter_mut()
        .zip(path_bytes.iter().copied())
    {
        *target = source as libc::c_char;
    }
    let raw = unsafe {
        libc::socket(
            libc::AF_UNIX,
            libc::SOCK_SEQPACKET
                | libc::SOCK_CLOEXEC
                | libc::SOCK_NONBLOCK,
            0,
        )
    };
    if raw < 0 {
        return Err(V2RuntimeError::new(
            "provider_process_socket_create_failed",
            "create provider process SOCK_SEQPACKET channel",
        ));
    }
    let socket = unsafe { OwnedFd::from_raw_fd(raw) };
    let length = std::mem::offset_of!(libc::sockaddr_un, sun_path)
        + path_bytes.len()
        + 1;
    let connect_result = unsafe {
        libc::connect(
            socket.as_raw_fd(),
            (&address as *const libc::sockaddr_un)
                .cast::<libc::sockaddr>(),
            libc::socklen_t::try_from(length).unwrap_or(0),
        )
    };
    if connect_result != 0 {
        let error = io::Error::last_os_error();
        if !matches!(
            error.raw_os_error(),
            Some(libc::EINPROGRESS) | Some(libc::EAGAIN)
        ) {
            return Err(V2RuntimeError::new(
                "provider_process_socket_connect_failed",
                "connect authenticated provider rendezvous",
            ));
        }
        let started = Instant::now();
        let remaining_ms = absolute_boottime_ns
            .saturating_sub(clock_boottime_ns()?)
            .checked_div(1_000_000)
            .unwrap_or(0)
            .min(RESPONSE_OBSERVATION_V2_MAX_OPERATION_MS);
        if remaining_ms == 0 {
            return Err(V2RuntimeError::new(
                "provider_process_socket_connect_deadline",
                "provider rendezvous deadline elapsed",
            ));
        }
        loop {
            let remaining = Duration::from_millis(remaining_ms)
                .saturating_sub(started.elapsed());
            if remaining.is_zero() {
                return Err(V2RuntimeError::new(
                    "provider_process_socket_connect_deadline",
                    "provider rendezvous did not connect before its monotonic deadline",
                ));
            }
            let mut pollfd = libc::pollfd {
                fd: socket.as_raw_fd(),
                events: libc::POLLOUT,
                revents: 0,
            };
            let timeout = i32::try_from(
                remaining.as_millis().min(i32::MAX as u128),
            )
            .unwrap_or(i32::MAX);
            let polled =
                unsafe { libc::poll(&mut pollfd, 1, timeout) };
            if polled < 0
                && io::Error::last_os_error().kind()
                    == io::ErrorKind::Interrupted
            {
                continue;
            }
            if polled <= 0 {
                return Err(V2RuntimeError::new(
                    "provider_process_socket_connect_deadline",
                    "provider rendezvous did not connect before its monotonic deadline",
                ));
            }
            let mut socket_error: libc::c_int = 0;
            let mut socket_error_length =
                std::mem::size_of::<libc::c_int>()
                    as libc::socklen_t;
            if unsafe {
                libc::getsockopt(
                    socket.as_raw_fd(),
                    libc::SOL_SOCKET,
                    libc::SO_ERROR,
                    (&mut socket_error as *mut libc::c_int)
                        .cast(),
                    &mut socket_error_length,
                )
            } != 0
                || socket_error_length as usize
                    != std::mem::size_of::<libc::c_int>()
                || socket_error != 0
            {
                return Err(V2RuntimeError::new(
                    "provider_process_socket_connect_failed",
                    "provider rendezvous reported a connection error",
                ));
            }
            break;
        }
    }
    Ok(socket)
}

#[cfg(target_os = "linux")]
fn authenticate_provider_custody_peer(
    socket: RawFd,
    config: &MeasuredProviderProcessConfig,
) -> Result<(), V2RuntimeError> {
    let peer = peer_credentials(socket)?;
    if peer.uid != config.custody_uid || peer.pid <= 0 {
        return Err(V2RuntimeError::new(
            "provider_process_custody_peer_mismatch",
            "provider channel peer UID does not match role-bound custody configuration",
        ));
    }
    let executable = PathBuf::from(format!(
        "/proc/{}/exe",
        peer.pid
    ));
    let mut file = File::open(executable).map_err(|_| {
        V2RuntimeError::new(
            "provider_process_custody_measurement_failed",
            "open custody peer executable through procfs",
        )
    })?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let count = file.read(&mut buffer).map_err(|_| {
            V2RuntimeError::new(
                "provider_process_custody_measurement_failed",
                "measure custody peer executable",
            )
        })?;
        if count == 0 {
            break;
        }
        hasher.update(&buffer[..count]);
        buffer[..count].fill(0);
    }
    buffer.fill(0);
    if format!("sha256:{:x}", hasher.finalize())
        != config.custody_executable_measurement_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_process_custody_measurement_mismatch",
            "custody peer executable does not match the role-bound measurement",
        ));
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn provider_parent_pidfd() -> Result<OwnedFd, V2RuntimeError> {
    let parent = unsafe { libc::getppid() };
    if parent <= 1 {
        return Err(V2RuntimeError::new(
            "provider_process_parent_invalid",
            "provider custody parent is unavailable",
        ));
    }
    let raw = unsafe {
        libc::syscall(libc::SYS_pidfd_open, parent, 0)
            as libc::c_int
    };
    if raw < 0 {
        return Err(V2RuntimeError::new(
            "provider_process_parent_pidfd_failed",
            "open exact custody parent pidfd",
        ));
    }
    Ok(unsafe { OwnedFd::from_raw_fd(raw) })
}

#[cfg(target_os = "linux")]
fn validate_provider_process_request(
    request: &ProviderRpcRequestEnvelope,
    environment: &ProviderProcessEnvironment,
    config: &MeasuredProviderProcessConfig,
) -> Result<(), V2RuntimeError> {
    if request.api_version != PROVIDER_RPC_API_VERSION
        || request.role != config.role
        || request.provider_id != config.provider_id
        || request.provider_generation != config.provider_generation
        || request.provider_operation_id
            != environment.provider_operation_id
        || request.provider_authority_scope.role != config.role
        || request.provider_authority_scope.provider_id
            != config.provider_id
        || request
            .provider_authority_scope
            .provider_generation
            != config.provider_generation
        || request
            .provider_authority_scope
            .provider_operation_id
            != environment.provider_operation_id
        || request.provider_authority_scope.request_sha256
            != environment.request_sha256
        || request.provider_authority_scope.attempt_id
            != environment.attempt_id
        || request
            .provider_authority_scope
            .attempt_revision
            != environment.attempt_revision
        || request
            .provider_authority_scope
            .predecessor_state_sha256
            != environment.predecessor_state_sha256
        || request.provider_authority_scope.launch_nonce
            != environment.launch_nonce
        || request.provider_authority_scope.fencing_token
            != environment.fencing_token
        || request
            .provider_authority_scope
            .executable_measurement_sha256
            != environment.executable_sha256
        || request
            .provider_authority_scope
            .provider_config_sha256
            != environment.config_sha256
        || request
            .provider_authority_scope
            .key_material_sha256
            != config.key_material_sha256
        || request
            .provider_authority_scope
            .tee_measurement_sha256
            != config.tee_measurement_sha256
        || request.request_sha256 != environment.request_sha256
        || request.attempt_id != environment.attempt_id
        || request.attempt_revision
            != environment.attempt_revision
        || request.fencing_token != environment.fencing_token
        || request.predecessor_state_sha256
            != environment.predecessor_state_sha256
        || request.monotonic_deadline
            != environment.monotonic_deadline
        || request.deadline_at_epoch_ms
            != environment.deadline_at_epoch_ms
        || request.launch_nonce != environment.launch_nonce
        || (request.operation
            != ProviderSubchannelOperation::Preflight
            && request.operation.required_role() != config.role)
        || !config.allowed_operations.contains(&request.operation)
        || !built_in_provider_operation_is_implemented(
            config,
            request.operation,
        )
        || request.exact_objects.len() > PROVIDER_RPC_MAX_FDS
    {
        return Err(V2RuntimeError::new(
            "provider_process_request_binding_mismatch",
            "provider request does not match the exact launched role, operation, generation, attempt, fence, predecessor, and deadline",
        ));
    }
    for digest in [
        &request.provider_operation_binding_sha256,
        &request
            .provider_authority_scope
            .kernel_process_identity_sha256,
        &request
            .provider_authority_scope
            .launch_attestation_sha256,
    ] {
        validate_digest(digest)?;
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn sign_provider_process_value<T: ProviderSignedValue>(
    signing_key: &ed25519_dalek::SigningKey,
    domain: &[u8],
    value: &T,
) -> Result<String, V2RuntimeError> {
    use ed25519_dalek::Signer as _;
    let unsigned =
        crate::canonical_json_bytes(&value.without_signature())
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_signature_message_invalid",
                    "provider signed DTO cannot be canonicalized",
                )
            })?;
    let mut message = Vec::with_capacity(domain.len() + unsigned.len());
    message.extend_from_slice(domain);
    message.extend_from_slice(&unsigned);
    Ok(base64::engine::general_purpose::STANDARD.encode(
        signing_key.sign(&message).to_bytes(),
    ))
}

#[cfg(target_os = "linux")]
fn provider_fence_receipt_sha256(
    provider_operation_id: &str,
    generation: u64,
    fencing_token: u64,
    durable_start_receipt_sha256: &str,
) -> String {
    let mut hasher = Sha256::new();
    append_hash_frame(
        &mut hasher,
        b"serverware.response-v2/provider-durable-fence/v1",
    );
    append_hash_frame(
        &mut hasher,
        provider_operation_id.as_bytes(),
    );
    append_hash_frame(&mut hasher, &generation.to_be_bytes());
    append_hash_frame(&mut hasher, &fencing_token.to_be_bytes());
    append_hash_frame(
        &mut hasher,
        durable_start_receipt_sha256.as_bytes(),
    );
    format!("sha256:{:x}", hasher.finalize())
}

#[cfg(target_os = "linux")]
fn provider_process_record_name(
    domain: &[u8],
    operation_id: &str,
    nonce: &str,
) -> String {
    let mut key = Sha256::new();
    append_hash_frame(&mut key, domain);
    append_hash_frame(&mut key, operation_id.as_bytes());
    append_hash_frame(&mut key, nonce.as_bytes());
    format!("{:x}", key.finalize())
}

#[cfg(target_os = "linux")]
fn persist_provider_process_record(
    config: &MeasuredProviderProcessConfig,
    domain: &[u8],
    operation_id: &str,
    nonce: &str,
    bytes: &[u8],
    deadline: &OperationDeadline,
) -> Result<String, V2RuntimeError> {
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_process_state_deadline",
            "provider state transaction began after the shared deadline",
        ));
    }
    validate_provider_private_state_directory(config)?;
    let name =
        provider_process_record_name(domain, operation_id, nonce);
    let final_path =
        config.durable_state_directory.join(format!("{name}.json"));
    let temporary_path = config
        .durable_state_directory
        .join(format!(".{name}.pending"));
    if final_path.exists() {
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_process_state_deadline",
                "provider state transaction exceeded the shared deadline before replay validation",
            ));
        }
        let existing =
            std::fs::read(&final_path).map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_state_read_failed",
                    "read existing durable provider state",
                )
            })?;
        if existing != bytes {
            return Err(V2RuntimeError::new(
                "provider_process_state_conflict",
                "durable provider state key already contains different bytes",
            ));
        }
    } else {
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&temporary_path)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_state_create_failed",
                    "create durable provider state transaction",
                )
            })?;
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_process_state_deadline",
                "provider state transaction exceeded the shared deadline before its write",
            ));
        }
        file.write_all(bytes)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_state_write_failed",
                    "write provider state transaction",
                )
            })?;
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_process_state_deadline",
                "provider state transaction exceeded the shared deadline before file synchronization",
            ));
        }
        file.sync_all().map_err(|_| {
            V2RuntimeError::new(
                "provider_process_state_write_failed",
                "synchronize provider state transaction",
            )
        })?;
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_process_state_deadline",
                "provider state transaction exceeded the shared deadline before commit",
            ));
        }
        std::fs::rename(&temporary_path, &final_path).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_process_state_commit_failed",
                    "atomically commit durable provider state",
                )
            },
        )?;
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_process_state_deadline",
                "provider state transaction exceeded the shared deadline before directory synchronization",
            ));
        }
        File::open(&config.durable_state_directory)
            .and_then(|directory| directory.sync_all())
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_state_sync_failed",
                    "synchronize durable provider state directory",
                )
            })?;
    }
    Ok(format!("sha256:{:x}", Sha256::digest(bytes)))
}

#[cfg(target_os = "linux")]
fn verify_provider_runtime_attestation_request(
    config: &MeasuredProviderProcessConfig,
    request: ProviderRuntimeAttestationRequestOwned,
    deadline: &OperationDeadline,
) -> Result<bool, V2RuntimeError> {
    if config.attestation_mode != V2AttestationMode::TrustedHost
        || deadline.expired()?
    {
        return Ok(false);
    }
    match request {
        ProviderRuntimeAttestationRequestOwned::Generation {
            role_identity_root_sha256,
            proof_independent_pins_root_sha256,
        } => Ok(
            role_identity_root_sha256
                == config.role_identity_root_sha256
                && proof_independent_pins_root_sha256
                    == config
                        .proof_independent_pins_root_sha256,
        ),
        ProviderRuntimeAttestationRequestOwned::Claim {
            verification_purpose,
            historical_inclusion,
            claim,
            request_scope_role,
        } => {
            let Some(statement) =
                &config.trust_bundle.trusted_host_runtime
            else {
                return Ok(false);
            };
            if !REQUIRED_ROLE_IDENTITIES
                .contains(&request_scope_role.as_str())
                || claim != statement.claim
                || claim.verified_at_epoch_ms
                    > config
                        .trust_bundle
                        .trusted_time
                        .trusted_now_epoch_ms
                || claim.expires_at_epoch_ms
                    < deadline.absolute_epoch_ms
            {
                return Ok(false);
            }
            Ok(match verification_purpose {
                super::VerificationPurpose::LiveAuthorization => {
                    historical_inclusion.is_none()
                }
                super::VerificationPurpose::ArchivalVerification => {
                    historical_inclusion.is_some_and(
                        |historical| {
                            historical.trust_checkpoint_sha256
                                == config
                                    .proof_independent_pins
                                    .trust_checkpoint_sha256
                                && historical.revocation_epoch
                                    == config
                                        .proof_independent_pins
                                        .revocation_epoch
                                && historical
                                    .trusted_time_epoch_ms
                                    >= claim.verified_at_epoch_ms
                                && historical
                                    .trusted_time_epoch_ms
                                    < claim.expires_at_epoch_ms
                                && [
                                    &historical
                                        .historical_trust_policy_sha256,
                                    &historical
                                        .historical_key_set_root_sha256,
                                    &historical
                                        .historical_key_inclusion_proof_sha256,
                                    &historical
                                        .historical_non_revocation_proof_sha256,
                                    &historical
                                        .runtime_attestation_inclusion_proof_sha256,
                                ]
                                .into_iter()
                                .all(|digest| {
                                    is_sha256_digest(digest)
                                })
                        },
                    )
                }
            })
        }
    }
}

#[cfg(target_os = "linux")]
fn verify_provider_signature_request(
    config: &MeasuredProviderProcessConfig,
    expected_role: &str,
    canonical_payload: &[u8],
) -> Result<ProviderBooleanDecision, V2RuntimeError> {
    let request: ProviderSignatureVerificationRequestOwned =
        crate::decode_canonical_json(canonical_payload).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_signature_request_invalid",
                    "provider signature request is not a closed DTO",
                )
            },
        )?;
    let message =
        base64::engine::general_purpose::STANDARD
            .decode(&request.domain_separated_message_base64)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_signature_request_invalid",
                    "provider signature message is not canonical base64",
                )
            })?;
    if message.is_empty()
        || message.len() > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES
        || base64::engine::general_purpose::STANDARD
            .encode(&message)
            != request.domain_separated_message_base64
    {
        return Ok(ProviderBooleanDecision { accepted: false });
    }
    Ok(ProviderBooleanDecision {
        accepted: verify_provider_trusted_role_signature(
            config,
            Some(expected_role),
            &request.signer_key_id,
            &message,
            &request.signature,
        ),
    })
}

#[cfg(target_os = "linux")]
fn provider_immutable_persistence_receipt_sha256(
    record: &ProviderImmutableArtifactRecord,
) -> Result<String, V2RuntimeError> {
    crate::canonical_json_bytes(record)
        .map(|bytes| {
            format!("sha256:{:x}", Sha256::digest(bytes))
        })
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_immutable_record_invalid",
                "immutable provider artifact record cannot be canonicalized",
            )
        })
}

#[cfg(target_os = "linux")]
fn validate_provider_fresh_attestation_binding<'a>(
    config: &'a MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    binding: &ProviderFreshAttestationRequest,
) -> Result<&'a ProviderTrustedRoleKey, V2RuntimeError> {
    for digest in [
        &binding.request_sha256,
        &binding.response_sha256,
        &binding.output_manifest_sha256,
        &binding.authenticated_session_sha256,
        &binding.client_identity_sha256,
        &binding.role_identity_root_sha256,
        &binding.proof_independent_pins_root_sha256,
        &binding.trust_checkpoint_sha256,
        &binding.custody_executable_measurement_sha256,
        &binding.custody_provider_config_sha256,
        &binding.custody_key_material_sha256,
        &binding.custody_tee_measurement_sha256,
        &binding.response_signer_key_sha256,
        &binding.expected_report_data_sha256,
        &binding.trust_root_sha256,
    ] {
        validate_digest(digest)?;
    }
    validate_identifier(&binding.custody_boot_id)?;
    validate_identifier(&binding.challenge_nonce)?;
    let custody = provider_trusted_role_key(
        config,
        Some("custody"),
        &binding.custody_key_material_sha256,
    )
    .ok_or_else(|| {
        V2RuntimeError::new(
            "provider_fresh_attestation_custody_untrusted",
            "trusted-host attestation custody identity is not in the signed checkpoint",
        )
    })?;
    let expected_report_data_sha256 =
        fresh_tee_report_data_sha256(
            &binding.response_sha256,
            &binding.output_manifest_sha256,
            &binding.authenticated_session_sha256,
            &binding.challenge_nonce,
            &binding.response_signer_key_sha256,
            &binding.custody_executable_measurement_sha256,
            binding.provider_generation,
        );
    if config.role != "runtime-attestation"
        || binding.provider_generation
            != config.provider_generation
        || binding.response_signer_key_sha256
            != config.key_material_sha256
        || binding.monotonic_deadline
            != environment.monotonic_deadline
        || binding.deadline_at_epoch_ms
            != environment.deadline_at_epoch_ms
        || binding.role_identity_root_sha256
            != config.role_identity_root_sha256
        || binding.proof_independent_pins_root_sha256
            != config.proof_independent_pins_root_sha256
        || binding.trust_root_sha256
            != config.proof_independent_pins.trust_root_sha256
        || binding.trust_checkpoint_sha256
            != config
                .proof_independent_pins
                .trust_checkpoint_sha256
        || binding.revocation_epoch
            != config.proof_independent_pins.revocation_epoch
        || custody.provider_generation
            != binding.provider_generation
        || custody.executable_measurement_sha256
            != binding.custody_executable_measurement_sha256
        || custody.provider_config_sha256
            != binding.custody_provider_config_sha256
        || custody.tee_measurement_sha256
            != binding.custody_tee_measurement_sha256
        || expected_report_data_sha256
            != binding.expected_report_data_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_fresh_attestation_binding_mismatch",
            "trusted-host attestation request is not bound to the signed custody measurements, exact response, signer, generation, and deadline",
        ));
    }
    Ok(custody)
}

#[cfg(target_os = "linux")]
fn execute_provider_trusted_host_fresh_attestation(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    request: &ProviderRpcRequestEnvelope,
    canonical_payload: &[u8],
    signing_key: &ed25519_dalek::SigningKey,
    deadline: &OperationDeadline,
) -> Result<Vec<u8>, V2RuntimeError> {
    let binding: ProviderFreshAttestationRequest =
        crate::decode_canonical_json(canonical_payload).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_fresh_attestation_request_invalid",
                    "trusted-host attestation request is not a closed DTO",
                )
            },
        )?;
    validate_provider_fresh_attestation_binding(
        config,
        environment,
        &binding,
    )?;
    let trust =
        verify_provider_operator_trust_bundle(config, deadline)?;
    let runtime_statement = config
        .trust_bundle
        .trusted_host_runtime
        .as_ref()
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_trusted_host_runtime_missing",
                "trusted-host attestation lacks its operator-signed runtime statement",
            )
        })?;
    let root_record = persist_provider_immutable_artifact(
        config,
        environment,
        "operator-root-key",
        &trust.root_public_key,
        &request.provider_operation_binding_sha256,
        signing_key,
        deadline,
    )?;
    let checkpoint_bytes =
        crate::canonical_json_bytes(
            &config.trust_bundle.checkpoint,
        )
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_trust_checkpoint_invalid",
                "operator trust checkpoint cannot be canonicalized",
            )
        })?;
    let checkpoint_record =
        persist_provider_immutable_artifact(
            config,
            environment,
            "operator-trust-checkpoint",
            &checkpoint_bytes,
            &request.provider_operation_binding_sha256,
            signing_key,
            deadline,
        )?;
    let revocation_bytes =
        crate::canonical_json_bytes(
            &config.trust_bundle.revocation,
        )
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_revocation_checkpoint_invalid",
                "operator revocation checkpoint cannot be canonicalized",
            )
        })?;
    let revocation_record =
        persist_provider_immutable_artifact(
            config,
            environment,
            "operator-revocation-checkpoint",
            &revocation_bytes,
            &request.provider_operation_binding_sha256,
            signing_key,
            deadline,
        )?;
    let runtime_statement_bytes =
        crate::canonical_json_bytes(runtime_statement).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_trusted_host_runtime_invalid",
                    "operator trusted-host runtime statement cannot be canonicalized",
                )
            },
        )?;
    let runtime_statement_sha256 = format!(
        "sha256:{:x}",
        Sha256::digest(&runtime_statement_bytes)
    );
    let root_persistence_receipt_sha256 =
        provider_immutable_persistence_receipt_sha256(
            &root_record,
        )?;
    let checkpoint_persistence_receipt_sha256 =
        provider_immutable_persistence_receipt_sha256(
            &checkpoint_record,
        )?;
    let revocation_persistence_receipt_sha256 =
        provider_immutable_persistence_receipt_sha256(
            &revocation_record,
        )?;
    let evidence_value =
        ProviderTrustedHostMeasurementEvidence {
            api_version:
                PROVIDER_TRUSTED_HOST_MEASUREMENT_EVIDENCE_API_VERSION
                    .to_owned(),
            provider_id: config.provider_id.clone(),
            provider_generation: config.provider_generation,
            request_sha256: binding.request_sha256.clone(),
            unsigned_response_sha256:
                binding.response_sha256.clone(),
            output_manifest_sha256:
                binding.output_manifest_sha256.clone(),
            custody_boot_id: binding.custody_boot_id.clone(),
            authenticated_session_sha256:
                binding.authenticated_session_sha256.clone(),
            client_identity_sha256:
                binding.client_identity_sha256.clone(),
            challenge_nonce: binding.challenge_nonce.clone(),
            custody_executable_measurement_sha256:
                binding
                    .custody_executable_measurement_sha256
                    .clone(),
            custody_provider_config_sha256:
                binding.custody_provider_config_sha256.clone(),
            custody_key_material_sha256:
                binding.custody_key_material_sha256.clone(),
            custody_tee_measurement_sha256:
                binding.custody_tee_measurement_sha256.clone(),
            response_signer_key_sha256:
                binding.response_signer_key_sha256.clone(),
            role_identity_root_sha256:
                binding.role_identity_root_sha256.clone(),
            proof_independent_pins_root_sha256:
                binding
                    .proof_independent_pins_root_sha256
                    .clone(),
            trust_root_sha256:
                binding.trust_root_sha256.clone(),
            trust_checkpoint_sha256:
                binding.trust_checkpoint_sha256.clone(),
            revocation_epoch: binding.revocation_epoch,
            runtime_statement_sha256,
            trusted_time_statement_id:
                config
                    .trust_bundle
                    .trusted_time
                    .statement_id
                    .clone(),
            monotonic_deadline:
                binding.monotonic_deadline.clone(),
            deadline_at_epoch_ms:
                binding.deadline_at_epoch_ms,
            report_data_sha256:
                binding.expected_report_data_sha256.clone(),
            trust_chain_retrieval_id:
                root_record.retrieval_id.clone(),
            trust_chain_persistence_receipt_sha256:
                root_persistence_receipt_sha256.clone(),
            endorsements_retrieval_id:
                checkpoint_record.retrieval_id.clone(),
            endorsements_persistence_receipt_sha256:
                checkpoint_persistence_receipt_sha256.clone(),
            revocation_receipt_retrieval_id:
                revocation_record.retrieval_id.clone(),
            revocation_persistence_receipt_sha256:
                revocation_persistence_receipt_sha256.clone(),
        };
    let evidence =
        crate::canonical_json_bytes(&evidence_value).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_fresh_attestation_evidence_invalid",
                    "trusted-host measurement evidence cannot be canonicalized",
                )
            },
        )?;
    let evidence_record = persist_provider_immutable_artifact(
        config,
        environment,
        "trusted-host-measurement-evidence",
        &evidence,
        &request.provider_operation_binding_sha256,
        signing_key,
        deadline,
    )?;
    let evidence_persistence_receipt_sha256 =
        provider_immutable_persistence_receipt_sha256(
            &evidence_record,
        )?;
    let mut verification_receipt =
        ProviderTrustedHostEvidenceVerificationReceipt {
            api_version:
                PROVIDER_TRUSTED_HOST_EVIDENCE_VERIFICATION_API_VERSION
                    .to_owned(),
            provider_operation_binding_sha256:
                request
                    .provider_operation_binding_sha256
                    .clone(),
            attestation_evidence_sha256:
                evidence_record.artifact_sha256.clone(),
            attestation_evidence_retrieval_id:
                evidence_record.retrieval_id.clone(),
            trust_chain_sha256:
                root_record.artifact_sha256.clone(),
            trust_chain_retrieval_id:
                root_record.retrieval_id.clone(),
            endorsements_sha256:
                checkpoint_record.artifact_sha256.clone(),
            endorsements_retrieval_id:
                checkpoint_record.retrieval_id.clone(),
            revocation_receipt_sha256:
                revocation_record.artifact_sha256.clone(),
            revocation_receipt_retrieval_id:
                revocation_record.retrieval_id.clone(),
            report_data_sha256:
                binding.expected_report_data_sha256.clone(),
            trust_checkpoint_sha256:
                binding.trust_checkpoint_sha256.clone(),
            revocation_epoch: binding.revocation_epoch,
            verified_at_epoch_ms:
                trust.trusted_now_epoch_ms,
            signer_key_id: config.key_id.clone(),
            signer_key_material_sha256:
                config.key_material_sha256.clone(),
            signature: String::new(),
        };
    verification_receipt.signature =
        sign_provider_process_value(
            signing_key,
            b"serverware.response-v2/trusted-host-evidence-verification/v1\0",
            &verification_receipt,
        )?;
    let verification_receipt_bytes =
        crate::canonical_json_bytes(&verification_receipt)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_fresh_attestation_verification_invalid",
                    "trusted-host evidence verification receipt cannot be canonicalized",
                )
            })?;
    let verification_record =
        persist_provider_immutable_artifact(
            config,
            environment,
            "trusted-host-verification-receipt",
            &verification_receipt_bytes,
            &request.provider_operation_binding_sha256,
            signing_key,
            deadline,
        )?;
    let now = trust.trusted_now_epoch_ms;
    let expires_at_epoch_ms = now
        .checked_add(RESPONSE_OBSERVATION_V2_MAX_OPERATION_MS)
        .unwrap_or(MAX_SAFE_INTEGER)
        .min(binding.deadline_at_epoch_ms)
        .min(
            config
                .trust_bundle
                .trusted_time
                .valid_until_epoch_ms,
        )
        .min(runtime_statement.claim.expires_at_epoch_ms);
    if expires_at_epoch_ms <= now || deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_fresh_attestation_deadline_elapsed",
            "trusted-host attestation deadline elapsed before signing",
        ));
    }
    let public_key = signing_key.verifying_key().to_bytes();
    let mut proof = V2FreshResponseAttestationV1 {
        api_version:
            V2_FRESH_RESPONSE_ATTESTATION_VERSION.to_owned(),
        attestation_mode: V2AttestationMode::TrustedHost,
        request_sha256: binding.request_sha256,
        unsigned_response_sha256:
            binding.response_sha256.clone(),
        output_manifest_sha256:
            binding.output_manifest_sha256.clone(),
        custody_boot_id: binding.custody_boot_id,
        authenticated_session_sha256:
            binding.authenticated_session_sha256.clone(),
        client_identity_sha256:
            binding.client_identity_sha256,
        role_identity_root_sha256:
            binding.role_identity_root_sha256,
        proof_independent_pins_root_sha256:
            binding.proof_independent_pins_root_sha256,
        trust_checkpoint_sha256:
            binding.trust_checkpoint_sha256.clone(),
        revocation_epoch: binding.revocation_epoch,
        custody_executable_measurement_sha256:
            binding
                .custody_executable_measurement_sha256
                .clone(),
        custody_provider_config_sha256:
            binding.custody_provider_config_sha256,
        custody_key_material_sha256:
            binding.custody_key_material_sha256,
        custody_tee_measurement_sha256:
            binding.custody_tee_measurement_sha256,
        provider_generation: binding.provider_generation,
        monotonic_deadline:
            binding.monotonic_deadline.clone(),
        deadline_at_epoch_ms: binding.deadline_at_epoch_ms,
        challenge_nonce: binding.challenge_nonce.clone(),
        attestation_evidence_format:
            V2FreshAttestationEvidenceFormat::
                TrustedHostMeasurementBundleJsonV1,
        attestation_evidence_base64:
            base64::engine::general_purpose::STANDARD
                .encode(&evidence),
        attestation_evidence_sha256:
            evidence_record.artifact_sha256,
        attestation_evidence_retrieval_id:
            evidence_record.retrieval_id,
        current_revocation_receipt_sha256:
            revocation_record.artifact_sha256.clone(),
        issued_at_epoch_ms: now,
        expires_at_epoch_ms,
        signature_algorithm:
            V2FreshAttestationSignatureAlgorithm::Ed25519,
        signer_provider_id: config.provider_id.clone(),
        signer_key_id: config.key_id.clone(),
        signer_key_material_sha256:
            config.key_material_sha256.clone(),
        signer_key:
            V2AttestationSignerKeyV1::InlineEd25519PublicKey {
                public_key_base64:
                    base64::engine::general_purpose::STANDARD
                        .encode(public_key),
                public_key_sha256:
                    config.key_material_sha256.clone(),
            },
        tee_report_binding: V2TeeReportBindingV1 {
            report_data_sha256:
                binding.expected_report_data_sha256,
            unsigned_response_sha256:
                binding.response_sha256,
            output_manifest_sha256:
                binding.output_manifest_sha256,
            authenticated_session_sha256:
                binding.authenticated_session_sha256,
            challenge_nonce: binding.challenge_nonce,
            signer_key_sha256:
                config.key_material_sha256.clone(),
            custody_measurement_sha256:
                binding.custody_executable_measurement_sha256,
            provider_generation: binding.provider_generation,
        },
        trust_evidence: V2AttestationTrustEvidenceV1 {
            trust_chain:
                V2AttestationTrustArtifactV1::
                    ImmutableTrustReference {
                        retrieval_id: root_record.retrieval_id,
                        artifact_sha256:
                            root_record.artifact_sha256,
                        persistence_receipt_sha256:
                            root_persistence_receipt_sha256,
                    },
            endorsements:
                V2AttestationTrustArtifactV1::
                    ImmutableTrustReference {
                        retrieval_id:
                            checkpoint_record.retrieval_id,
                        artifact_sha256:
                            checkpoint_record.artifact_sha256,
                        persistence_receipt_sha256:
                            checkpoint_persistence_receipt_sha256,
                    },
            trust_root_sha256: binding.trust_root_sha256,
            trust_checkpoint_sha256:
                binding.trust_checkpoint_sha256,
            revocation_epoch: binding.revocation_epoch,
            signer_revocation_receipt_sha256:
                revocation_record.artifact_sha256,
            signer_revocation_receipt_retrieval_id:
                revocation_record.retrieval_id,
            evidence_verification_receipt_sha256:
                verification_record.artifact_sha256,
            evidence_verification_receipt_retrieval_id:
                verification_record.retrieval_id,
            verified_at_epoch_ms: now,
        },
        signature: String::new(),
    };
    proof.signature = sign_provider_process_value(
        signing_key,
        V2_FRESH_RESPONSE_ATTESTATION_SIGNATURE_DOMAIN,
        &proof,
    )?;
    let proof_bytes =
        crate::canonical_json_bytes(&proof).map_err(|_| {
            V2RuntimeError::new(
                "provider_fresh_attestation_invalid",
                "trusted-host response attestation cannot be canonicalized",
            )
        })?;
    persist_provider_immutable_artifact(
        config,
        environment,
        "trusted-host-signed-attestation",
        &proof_bytes,
        &request.provider_operation_binding_sha256,
        signing_key,
        deadline,
    )?;
    Ok(proof_bytes)
}

#[cfg(target_os = "linux")]
fn immutable_trust_reference(
    artifact: &V2AttestationTrustArtifactV1,
) -> Result<(&str, &str, &str), V2RuntimeError> {
    match artifact {
        V2AttestationTrustArtifactV1::ImmutableTrustReference {
            retrieval_id,
            artifact_sha256,
            persistence_receipt_sha256,
        } => Ok((
            retrieval_id,
            artifact_sha256,
            persistence_receipt_sha256,
        )),
        V2AttestationTrustArtifactV1::InlineDerBundle { .. } => {
            Err(V2RuntimeError::new(
                "provider_trusted_host_inline_trust_forbidden",
                "TrustedHostNoTee requires persisted retrievable trust artifacts",
            ))
        }
    }
}

#[cfg(target_os = "linux")]
fn execute_provider_verify_trusted_host_fresh_attestation(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    canonical_payload: &[u8],
    deadline: &OperationDeadline,
) -> Result<Vec<u8>, V2RuntimeError> {
    let request: ProviderFreshEvidenceVerificationRequest =
        crate::decode_canonical_json(canonical_payload).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_fresh_attestation_verification_request_invalid",
                    "trusted-host verification request is not a closed DTO",
                )
            },
        )?;
    validate_provider_fresh_attestation_binding(
        config,
        environment,
        &request.binding,
    )?;
    let trust =
        verify_provider_operator_trust_bundle(config, deadline)?;
    let runtime_statement = config
        .trust_bundle
        .trusted_host_runtime
        .as_ref()
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_trusted_host_runtime_missing",
                "trusted-host verification lacks its operator-signed runtime statement",
            )
        })?;
    let proof = request.proof;
    let signature = proof.signature.clone();
    let mut unsigned_proof = proof.clone();
    unsigned_proof.signature.clear();
    let unsigned_proof_bytes =
        crate::canonical_json_bytes(&unsigned_proof).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_fresh_attestation_invalid",
                    "trusted-host attestation cannot be canonicalized",
                )
            },
        )?;
    let mut proof_message =
        V2_FRESH_RESPONSE_ATTESTATION_SIGNATURE_DOMAIN.to_vec();
    proof_message.extend_from_slice(&unsigned_proof_bytes);
    let inline_key_matches = match &proof.signer_key {
        V2AttestationSignerKeyV1::InlineEd25519PublicKey {
            public_key_base64,
            public_key_sha256,
        } => {
            public_key_sha256 == &config.key_material_sha256
                && base64::engine::general_purpose::STANDARD
                    .decode(public_key_base64)
                    .is_ok_and(|bytes| {
                        bytes
                            == provider_trusted_role_key(
                                config,
                                Some("runtime-attestation"),
                                &config.key_id,
                            )
                            .and_then(|key| {
                                base64::engine::general_purpose::STANDARD
                                    .decode(&key.public_key_base64)
                                    .ok()
                            })
                            .unwrap_or_default()
                    })
        }
        V2AttestationSignerKeyV1::ImmutableKeyReference {
            ..
        } => false,
    };
    if proof.api_version
            != V2_FRESH_RESPONSE_ATTESTATION_VERSION
        || proof.attestation_mode
            != V2AttestationMode::TrustedHost
        || proof.request_sha256
            != request.binding.request_sha256
        || proof.unsigned_response_sha256
            != request.binding.response_sha256
        || proof.output_manifest_sha256
            != request.binding.output_manifest_sha256
        || proof.custody_boot_id
            != request.binding.custody_boot_id
        || proof.authenticated_session_sha256
            != request.binding.authenticated_session_sha256
        || proof.client_identity_sha256
            != request.binding.client_identity_sha256
        || proof.role_identity_root_sha256
            != request.binding.role_identity_root_sha256
        || proof.proof_independent_pins_root_sha256
            != request
                .binding
                .proof_independent_pins_root_sha256
        || proof.trust_checkpoint_sha256
            != request.binding.trust_checkpoint_sha256
        || proof.revocation_epoch
            != request.binding.revocation_epoch
        || proof.custody_executable_measurement_sha256
            != request
                .binding
                .custody_executable_measurement_sha256
        || proof.custody_provider_config_sha256
            != request.binding.custody_provider_config_sha256
        || proof.custody_key_material_sha256
            != request.binding.custody_key_material_sha256
        || proof.custody_tee_measurement_sha256
            != request.binding.custody_tee_measurement_sha256
        || proof.provider_generation
            != request.binding.provider_generation
        || proof.monotonic_deadline
            != request.binding.monotonic_deadline
        || proof.deadline_at_epoch_ms
            != request.binding.deadline_at_epoch_ms
        || proof.issued_at_epoch_ms == 0
        || proof.issued_at_epoch_ms
            != proof.trust_evidence.verified_at_epoch_ms
        || proof.issued_at_epoch_ms
            > trust.trusted_now_epoch_ms
        || proof.expires_at_epoch_ms
            <= trust.trusted_now_epoch_ms
        || proof.expires_at_epoch_ms
            <= proof.issued_at_epoch_ms
        || proof.expires_at_epoch_ms
            > request.binding.deadline_at_epoch_ms
        || proof.expires_at_epoch_ms
            > config
                .trust_bundle
                .trusted_time
                .valid_until_epoch_ms
        || proof.expires_at_epoch_ms
            > runtime_statement.claim.expires_at_epoch_ms
        || proof.challenge_nonce
            != request.binding.challenge_nonce
        || proof.tee_report_binding.report_data_sha256
            != request.binding.expected_report_data_sha256
        || proof.signer_provider_id != config.provider_id
        || proof.signer_key_id != config.key_id
        || proof.signer_key_material_sha256
            != config.key_material_sha256
        || !inline_key_matches
        || !verify_provider_trusted_role_signature(
            config,
            Some("runtime-attestation"),
            &proof.signer_key_id,
            &proof_message,
            &signature,
        )
    {
        return Err(V2RuntimeError::new(
            "provider_fresh_attestation_verification_failed",
            "trusted-host attestation signature or exact response binding is invalid",
        ));
    }
    let evidence =
        retrieve_provider_immutable_artifact(
            config,
            environment,
            &proof.attestation_evidence_retrieval_id,
            Some("trusted-host-measurement-evidence"),
            deadline,
        )?;
    if evidence.record.artifact_sha256
            != proof.attestation_evidence_sha256
        || evidence.bytes
            != base64::engine::general_purpose::STANDARD
                .decode(&proof.attestation_evidence_base64)
                .map_err(|_| {
                    V2RuntimeError::new(
                        "provider_fresh_attestation_evidence_invalid",
                        "trusted-host evidence is not canonical base64",
                    )
                })?
    {
        return Err(V2RuntimeError::new(
            "provider_fresh_attestation_evidence_mismatch",
            "persisted trusted-host evidence does not match the inline signed evidence",
        ));
    }
    let measurement: ProviderTrustedHostMeasurementEvidence =
        crate::decode_canonical_json(&evidence.bytes).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_fresh_attestation_evidence_invalid",
                    "trusted-host measurement evidence is not a closed DTO",
                )
            },
        )?;
    let (
        trust_chain_retrieval_id,
        trust_chain_sha256,
        trust_chain_persistence_receipt,
    ) = immutable_trust_reference(
        &proof.trust_evidence.trust_chain,
    )?;
    let (
        endorsements_retrieval_id,
        endorsements_sha256,
        endorsements_persistence_receipt,
    ) = immutable_trust_reference(
        &proof.trust_evidence.endorsements,
    )?;
    let trust_chain = retrieve_provider_immutable_artifact(
        config,
        environment,
        trust_chain_retrieval_id,
        Some("operator-root-key"),
        deadline,
    )?;
    let endorsements = retrieve_provider_immutable_artifact(
        config,
        environment,
        endorsements_retrieval_id,
        Some("operator-trust-checkpoint"),
        deadline,
    )?;
    let revocation = retrieve_provider_immutable_artifact(
        config,
        environment,
        &proof
            .trust_evidence
            .signer_revocation_receipt_retrieval_id,
        Some("operator-revocation-checkpoint"),
        deadline,
    )?;
    let verification = retrieve_provider_immutable_artifact(
        config,
        environment,
        &proof
            .trust_evidence
            .evidence_verification_receipt_retrieval_id,
        Some("trusted-host-verification-receipt"),
        deadline,
    )?;
    let verification_receipt:
        ProviderTrustedHostEvidenceVerificationReceipt =
        crate::decode_canonical_json(&verification.bytes)
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_fresh_attestation_verification_invalid",
                    "trusted-host verification receipt is not a closed DTO",
                )
            })?;
    let receipt_signature =
        verification_receipt.signature.clone();
    let unsigned_receipt =
        crate::canonical_json_bytes(
            &verification_receipt.without_signature(),
        )
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_fresh_attestation_verification_invalid",
                "trusted-host verification receipt cannot be canonicalized",
            )
        })?;
    let mut receipt_message =
        b"serverware.response-v2/trusted-host-evidence-verification/v1\0"
            .to_vec();
    receipt_message.extend_from_slice(&unsigned_receipt);
    let trusted_runtime_statement_sha256 = config
        .trust_bundle
        .trusted_host_runtime
        .as_ref()
        .and_then(|statement| {
            crate::canonical_json_bytes(statement).ok()
        })
        .map(|bytes| {
            format!("sha256:{:x}", Sha256::digest(bytes))
        })
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_trusted_host_runtime_missing",
                "operator trusted-host runtime statement is unavailable",
            )
        })?;
    if measurement.api_version
            != PROVIDER_TRUSTED_HOST_MEASUREMENT_EVIDENCE_API_VERSION
        || measurement.provider_id != config.provider_id
        || measurement.provider_generation
            != config.provider_generation
        || measurement.request_sha256
            != request.binding.request_sha256
        || measurement.unsigned_response_sha256
            != request.binding.response_sha256
        || measurement.output_manifest_sha256
            != request.binding.output_manifest_sha256
        || measurement.custody_boot_id
            != request.binding.custody_boot_id
        || measurement.authenticated_session_sha256
            != request.binding.authenticated_session_sha256
        || measurement.client_identity_sha256
            != request.binding.client_identity_sha256
        || measurement.challenge_nonce
            != request.binding.challenge_nonce
        || measurement.custody_executable_measurement_sha256
            != request
                .binding
                .custody_executable_measurement_sha256
        || measurement.custody_provider_config_sha256
            != request.binding.custody_provider_config_sha256
        || measurement.custody_key_material_sha256
            != request.binding.custody_key_material_sha256
        || measurement.custody_tee_measurement_sha256
            != request.binding.custody_tee_measurement_sha256
        || measurement.response_signer_key_sha256
            != request.binding.response_signer_key_sha256
        || measurement.role_identity_root_sha256
            != request.binding.role_identity_root_sha256
        || measurement.proof_independent_pins_root_sha256
            != request
                .binding
                .proof_independent_pins_root_sha256
        || measurement.trust_root_sha256
            != request.binding.trust_root_sha256
        || measurement.trust_checkpoint_sha256
            != request.binding.trust_checkpoint_sha256
        || measurement.revocation_epoch
            != request.binding.revocation_epoch
        || measurement.runtime_statement_sha256
            != trusted_runtime_statement_sha256
        || measurement.trusted_time_statement_id
            != config
                .trust_bundle
                .trusted_time
                .statement_id
        || measurement.monotonic_deadline
            != request.binding.monotonic_deadline
        || measurement.deadline_at_epoch_ms
            != request.binding.deadline_at_epoch_ms
        || measurement.report_data_sha256
            != request.binding.expected_report_data_sha256
        || measurement.trust_chain_retrieval_id
            != trust_chain_retrieval_id
        || measurement.endorsements_retrieval_id
            != endorsements_retrieval_id
        || measurement.revocation_receipt_retrieval_id
            != proof
                .trust_evidence
                .signer_revocation_receipt_retrieval_id
        || trust_chain.record.artifact_sha256
            != trust_chain_sha256
        || trust_chain.persistence_receipt_sha256
            != trust_chain_persistence_receipt
        || measurement
            .trust_chain_persistence_receipt_sha256
            != trust_chain_persistence_receipt
        || endorsements.record.artifact_sha256
            != endorsements_sha256
        || endorsements.persistence_receipt_sha256
            != endorsements_persistence_receipt
        || measurement
            .endorsements_persistence_receipt_sha256
            != endorsements_persistence_receipt
        || revocation.record.artifact_sha256
            != proof.current_revocation_receipt_sha256
        || measurement
            .revocation_persistence_receipt_sha256
            != revocation.persistence_receipt_sha256
        || revocation.record.artifact_sha256
            != proof
                .trust_evidence
                .signer_revocation_receipt_sha256
        || verification.record.artifact_sha256
            != proof
                .trust_evidence
                .evidence_verification_receipt_sha256
        || verification_receipt.api_version
            != PROVIDER_TRUSTED_HOST_EVIDENCE_VERIFICATION_API_VERSION
        || verification_receipt.attestation_evidence_sha256
            != proof.attestation_evidence_sha256
        || verification_receipt.attestation_evidence_retrieval_id
            != proof.attestation_evidence_retrieval_id
        || verification_receipt.report_data_sha256
            != request.binding.expected_report_data_sha256
        || verification_receipt.trust_checkpoint_sha256
            != config
                .proof_independent_pins
                .trust_checkpoint_sha256
        || verification_receipt.revocation_epoch
            != config.proof_independent_pins.revocation_epoch
        || verification_receipt.verified_at_epoch_ms
            != proof.trust_evidence.verified_at_epoch_ms
        || !verify_provider_trusted_role_signature(
            config,
            Some("runtime-attestation"),
            &verification_receipt.signer_key_id,
            &receipt_message,
            &receipt_signature,
        )
    {
        return Err(V2RuntimeError::new(
            "provider_fresh_attestation_artifact_mismatch",
            "trusted-host attestation artifacts do not form an exact persisted signed chain",
        ));
    }
    let decision = ProviderFreshEvidenceDecision {
        attestation_evidence_sha256:
            proof.attestation_evidence_sha256,
        response_sha256: proof.unsigned_response_sha256,
        output_manifest_sha256:
            proof.output_manifest_sha256,
        authenticated_session_sha256:
            proof.authenticated_session_sha256,
        challenge_nonce: proof.challenge_nonce,
        custody_executable_measurement_sha256:
            proof.custody_executable_measurement_sha256,
        custody_provider_config_sha256:
            proof.custody_provider_config_sha256,
        custody_key_material_sha256:
            proof.custody_key_material_sha256,
        custody_tee_measurement_sha256:
            proof.custody_tee_measurement_sha256,
        trust_checkpoint_sha256:
            proof.trust_checkpoint_sha256,
        revocation_epoch: proof.revocation_epoch,
        provider_generation: proof.provider_generation,
        verified_at_epoch_ms:
            verification_receipt.verified_at_epoch_ms,
        current_revocation_receipt_sha256:
            proof.current_revocation_receipt_sha256,
        attestation_evidence_retrieval_id:
            proof.attestation_evidence_retrieval_id,
        report_data_sha256:
            proof.tee_report_binding.report_data_sha256,
        signer_key_sha256:
            proof.signer_key_material_sha256,
        trust_chain_sha256:
            trust_chain.record.artifact_sha256,
        endorsements_sha256:
            endorsements.record.artifact_sha256,
        trust_root_sha256:
            proof.trust_evidence.trust_root_sha256,
        signer_revocation_receipt_sha256:
            proof
                .trust_evidence
                .signer_revocation_receipt_sha256,
        signer_revocation_receipt_retrieval_id:
            proof
                .trust_evidence
                .signer_revocation_receipt_retrieval_id,
        evidence_verification_receipt_sha256:
            proof
                .trust_evidence
                .evidence_verification_receipt_sha256,
        evidence_verification_receipt_retrieval_id:
            proof
                .trust_evidence
                .evidence_verification_receipt_retrieval_id,
    };
    crate::canonical_json_bytes(&decision).map_err(|_| {
        V2RuntimeError::new(
            "provider_fresh_attestation_verification_response_invalid",
            "trusted-host verification decision cannot be canonicalized",
        )
    })
}

#[cfg(target_os = "linux")]
fn built_in_provider_operation_is_implemented(
    config: &MeasuredProviderProcessConfig,
    operation: ProviderSubchannelOperation,
) -> bool {
    match operation {
        ProviderSubchannelOperation::Preflight => true,
        ProviderSubchannelOperation::VerifyLiveContract => {
            config.role == "live-proof-verifier"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        ProviderSubchannelOperation::VerifyArchiveContract => {
            config.role == "archive-proof-verifier"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        ProviderSubchannelOperation::TrustedTime => {
            config.role == "trusted-time"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        ProviderSubchannelOperation::RuntimeReadiness => {
            config.role == "custody"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        ProviderSubchannelOperation::VerifyRuntimeAttestation => {
            config.role == "runtime-attestation"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        ProviderSubchannelOperation::Revocation => {
            config.role == "evidence-trust"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        ProviderSubchannelOperation::PublicReleaseSignature => {
            config.role == "public-release"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        ProviderSubchannelOperation::RecoveryAuthorization
        | ProviderSubchannelOperation::RecoveryResolution => {
            config.role == "recovery"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        ProviderSubchannelOperation::FenceRevoke => {
            config.role == "linearizable-store"
        }
        ProviderSubchannelOperation::EmergencyFenceRevoke => {
            config.role == "emergency-fence-revoker"
        }
        ProviderSubchannelOperation::EmergencyExecute => {
            config.role == "emergency-cleanup-executor"
        }
        ProviderSubchannelOperation::FreshResponseAttestation
        | ProviderSubchannelOperation::VerifyFreshResponseAttestation => {
            config.role == "runtime-attestation"
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
        }
        _ => false,
    }
}

#[cfg(target_os = "linux")]
fn built_in_implemented_operations(
    config: &MeasuredProviderProcessConfig,
) -> Vec<ProviderSubchannelOperation> {
    let mut operations = config
        .allowed_operations
        .iter()
        .copied()
        .filter(|operation| {
            built_in_provider_operation_is_implemented(
                config,
                *operation,
            )
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    if !operations.contains(&ProviderSubchannelOperation::Preflight) {
        operations.insert(0, ProviderSubchannelOperation::Preflight);
    }
    operations
}

#[cfg(target_os = "linux")]
struct ProviderProcessOperationOutput {
    canonical_payload: Vec<u8>,
    output_descriptors: Vec<ExactByteObjectDescriptor>,
    output_files: Vec<File>,
}

#[cfg(target_os = "linux")]
impl ProviderProcessOperationOutput {
    fn control(canonical_payload: Vec<u8>) -> Self {
        Self {
            canonical_payload,
            output_descriptors: Vec::new(),
            output_files: Vec::new(),
        }
    }
}

#[cfg(target_os = "linux")]
fn create_provider_output_object(
    object_id: String,
    media_type: ExactObjectMediaType,
    fd_index: u16,
    bytes: &[u8],
    deadline: &OperationDeadline,
) -> Result<(ExactByteObjectDescriptor, File), V2RuntimeError> {
    validate_identifier(&object_id)?;
    if bytes.is_empty()
        || bytes.len() as u64
            > RESPONSE_OBSERVATION_V2_MAX_OBJECT_BYTES
        || deadline.expired()?
    {
        return Err(V2RuntimeError::new(
            "provider_output_object_invalid",
            "provider output object is empty, overbound, or past deadline",
        ));
    }
    let name = CString::new("serverware-response-v2-provider-output")
        .map_err(|_| {
            V2RuntimeError::new(
                "provider_output_memfd_name_invalid",
                "static provider output memfd name is invalid",
            )
        })?;
    let raw = unsafe {
        libc::memfd_create(
            name.as_ptr(),
            libc::MFD_CLOEXEC | libc::MFD_ALLOW_SEALING,
        )
    };
    if raw < 0 {
        return Err(V2RuntimeError::new(
            "provider_output_memfd_failed",
            "create provider output sealed memfd",
        ));
    }
    let mut file =
        File::from(unsafe { OwnedFd::from_raw_fd(raw) });
    for chunk in bytes.chunks(64 * 1024) {
        if deadline.expired()? {
            return Err(V2RuntimeError::new(
                "provider_output_deadline",
                "provider output write exceeded the shared deadline",
            ));
        }
        file.write_all(chunk).map_err(|_| {
            V2RuntimeError::new(
                "provider_output_write_failed",
                "write provider output sealed memfd",
            )
        })?;
    }
    if deadline.expired()? {
        return Err(V2RuntimeError::new(
            "provider_output_deadline",
            "provider output exceeded the shared deadline before synchronization",
        ));
    }
    file.sync_all().map_err(|_| {
        V2RuntimeError::new(
            "provider_output_sync_failed",
            "synchronize provider output sealed memfd",
        )
    })?;
    let seals = libc::F_SEAL_SEAL
        | libc::F_SEAL_SHRINK
        | libc::F_SEAL_GROW
        | libc::F_SEAL_WRITE;
    if unsafe {
        libc::fcntl(file.as_raw_fd(), libc::F_ADD_SEALS, seals)
    } != 0
    {
        return Err(V2RuntimeError::new(
            "provider_output_seal_failed",
            "seal provider output memfd",
        ));
    }
    file.rewind().map_err(|_| {
        V2RuntimeError::new(
            "provider_output_rewind_failed",
            "rewind provider output sealed memfd",
        )
    })?;
    Ok((
        ExactByteObjectDescriptor {
            object_id,
            media_type,
            fd_index,
            byte_length: bytes.len() as u64,
            sha256: format!(
                "sha256:{:x}",
                Sha256::digest(bytes)
            ),
            required_seals: MemfdSealProfile::ImmutableV1,
        },
        file,
    ))
}

#[cfg(target_os = "linux")]
fn provider_unique_proof_document(
    objects: &ValidatedExactObjects,
    deadline: &OperationDeadline,
) -> Result<
    (Vec<u8>, super::ResponseObservationProofV2),
    V2RuntimeError,
> {
    let mut selected:
        Option<(String, Vec<u8>, super::ResponseObservationProofV2)> =
        None;
    for object in objects.by_fd_index.values() {
        if !matches!(
            object.descriptor.media_type,
            ExactObjectMediaType::CanonicalJson
                | ExactObjectMediaType::EvidenceBundle
        ) {
            continue;
        }
        let bytes = read_bounded_exact_object(object, deadline)?;
        let Ok(proof) = super::decode_canonical_proof(&bytes)
        else {
            continue;
        };
        let digest =
            format!("sha256:{:x}", Sha256::digest(&bytes));
        if let Some((selected_digest, _, _)) = &selected {
            if selected_digest != &digest {
                return Err(V2RuntimeError::new(
                    "provider_proof_document_ambiguous",
                    "provider request contains multiple distinct canonical proof documents",
                ));
            }
            continue;
        }
        selected = Some((digest, bytes, proof.wire().clone()));
    }
    selected
        .map(|(_, bytes, proof)| (bytes, proof))
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_proof_document_missing",
                "provider request does not contain one canonical response-observation proof",
            )
        })
}

#[cfg(target_os = "linux")]
fn execute_provider_contract_plan(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    request: &ProviderRpcRequestEnvelope,
    canonical_payload: &[u8],
    objects: ValidatedExactObjects,
    deadline: &OperationDeadline,
) -> Result<ProviderProcessOperationOutput, V2RuntimeError> {
    let trust =
        verify_provider_operator_trust_bundle(config, deadline)?;
    let runtime_claim = config
        .trust_bundle
        .trusted_host_runtime
        .as_ref()
        .map(|statement| statement.claim.clone())
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_trusted_host_runtime_missing",
                "contract verification requires an operator-signed runtime claim",
            )
        })?;
    let (proof_bytes, proof) =
        provider_unique_proof_document(&objects, deadline)?;
    if runtime_claim.runtime
        != proof.finalized_envelope.body.runtime
    {
        return Err(V2RuntimeError::new(
            "provider_proof_runtime_mismatch",
            "proof runtime does not match the operator-signed TrustedHostNoTee runtime",
        ));
    }
    let proof_sha256 =
        format!("sha256:{:x}", Sha256::digest(&proof_bytes));
    let object_id = format!(
        "provider-proof-document-{}",
        &proof_sha256[7..31]
    );
    let (proof_document, proof_file) =
        create_provider_output_object(
            object_id,
            ExactObjectMediaType::CanonicalJson,
            0,
            &proof_bytes,
            deadline,
        )?;
    let canonical_payload = match request.operation {
        ProviderSubchannelOperation::VerifyLiveContract => {
            let live: ProviderLiveContractRequestOwned =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_live_contract_request_invalid",
                            "live contract request is not a closed DTO",
                        )
                    })?;
            let canonical_request =
                crate::canonical_json_bytes(&live.request)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_live_contract_request_invalid",
                            "live contract operation cannot be canonicalized",
                        )
                    })?;
            let binding = live
                .request
                .mutation_binding()
                .ok_or_else(|| {
                    V2RuntimeError::new(
                        "provider_live_contract_read_forbidden",
                        "live contract verification requires a mutation request",
                    )
                })?;
            if format!(
                "sha256:{:x}",
                Sha256::digest(&canonical_request)
            ) != live.request_sha256
                || live.request_sha256
                    != environment.request_sha256
                || live.authenticated_client_identity_sha256
                    != binding.client_identity_sha256
                || live.deadline_at_epoch_ms
                    != environment.deadline_at_epoch_ms
                || binding.monotonic_deadline
                    != environment.monotonic_deadline
                || binding.attempt_id != environment.attempt_id
            {
                return Err(V2RuntimeError::new(
                    "provider_live_contract_binding_mismatch",
                    "live contract is not bound to the exact request, client, attempt, and shared deadline",
                ));
            }
            validate_identifier(
                &live.target_provider_operation_id,
            )?;
            crate::canonical_json_bytes(
                &ProviderLiveVerificationPlan {
                    proof_document: proof_document.clone(),
                    runtime_attestation: runtime_claim,
                    trusted_now_epoch_ms:
                        trust.trusted_now_epoch_ms,
                    trust_checkpoint_sha256:
                        trust.trust_checkpoint_sha256,
                    revocation_epoch:
                        config
                            .proof_independent_pins
                            .revocation_epoch,
                },
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_live_contract_plan_invalid",
                    "live contract plan cannot be canonicalized",
                )
            })?
        }
        ProviderSubchannelOperation::VerifyArchiveContract => {
            let archive: ProviderArchiveContractRequestOwned =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_archive_contract_request_invalid",
                            "archive contract request is not a closed DTO",
                        )
                    })?;
            let canonical_request =
                crate::canonical_json_bytes(&archive.request)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_archive_contract_request_invalid",
                            "archive contract operation cannot be canonicalized",
                        )
                    })?;
            let binding =
                archive.request.read_binding().ok_or_else(|| {
                    V2RuntimeError::new(
                        "provider_archive_contract_mutation_forbidden",
                        "archive contract verification requires a read-only request",
                    )
                })?;
            let checkpoint = proof
                .finalized_envelope
                .finalization_checkpoint_evidence
                .payload
                .clone();
            if format!(
                "sha256:{:x}",
                Sha256::digest(&canonical_request)
            ) != archive.request_sha256
                || archive.request_sha256
                    != environment.request_sha256
                || archive.authenticated_client_identity_sha256
                    != binding.client_identity_sha256
                || archive.deadline_at_epoch_ms
                    != environment.deadline_at_epoch_ms
                || binding.monotonic_deadline
                    != environment.monotonic_deadline
                || !is_sha256_digest(
                    &archive
                        .archive_store_operation_binding_sha256,
                )
                || !checkpoint.archival_verification_enabled
            {
                return Err(V2RuntimeError::new(
                    "provider_archive_contract_binding_mismatch",
                    "archive contract is not bound to the exact request, client, archive authority, and shared deadline",
                ));
            }
            let inclusion =
                super::HistoricalRuntimeAttestationInclusion {
                    finalized_at_epoch_ms:
                        checkpoint.finalized_at_epoch_ms,
                    trusted_time_epoch_ms:
                        checkpoint.trusted_time_epoch_ms,
                    trust_checkpoint_sha256:
                        checkpoint.trust_checkpoint_sha256.clone(),
                    revocation_epoch:
                        checkpoint.revocation_epoch,
                    historical_trust_policy_sha256:
                        checkpoint
                            .historical_trust_policy_sha256
                            .clone(),
                    historical_key_set_root_sha256:
                        checkpoint
                            .historical_key_set_root_sha256
                            .clone(),
                    historical_key_inclusion_proof_sha256:
                        checkpoint
                            .historical_key_inclusion_proof_sha256
                            .clone(),
                    historical_non_revocation_proof_sha256:
                        checkpoint
                            .historical_non_revocation_proof_sha256
                            .clone(),
                    runtime_attestation_inclusion_proof_sha256:
                        checkpoint
                            .runtime_attestation_inclusion_proof_sha256
                            .clone(),
                };
            crate::canonical_json_bytes(
                &ProviderArchiveVerificationPlan {
                    proof_document: proof_document.clone(),
                    runtime_attestation: runtime_claim,
                    historical_runtime_inclusion: inclusion,
                    finalization_checkpoint: checkpoint,
                    trusted_delivery_time_epoch_ms:
                        trust.trusted_now_epoch_ms,
                },
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_archive_contract_plan_invalid",
                    "archive contract plan cannot be canonicalized",
                )
            })?
        }
        _ => {
            return Err(V2RuntimeError::new(
                "provider_contract_operation_invalid",
                "provider contract plan operation is invalid",
            ))
        }
    };
    Ok(ProviderProcessOperationOutput {
        canonical_payload,
        output_descriptors: vec![proof_document],
        output_files: vec![proof_file],
    })
}

#[cfg(target_os = "linux")]
fn execute_provider_process_operation(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    request: &ProviderRpcRequestEnvelope,
    canonical_payload: &[u8],
    request_fds: Vec<OwnedFd>,
    signing_key: &ed25519_dalek::SigningKey,
    deadline: &OperationDeadline,
) -> Result<ProviderProcessOperationOutput, V2RuntimeError> {
    if matches!(
        request.operation,
        ProviderSubchannelOperation::VerifyLiveContract
            | ProviderSubchannelOperation::VerifyArchiveContract
    ) {
        let files =
            request_fds.into_iter().map(File::from).collect();
        let objects = validate_exact_object_files(
            &request.exact_objects,
            files,
            Some(deadline),
        )?;
        return execute_provider_contract_plan(
            config,
            environment,
            request,
            canonical_payload,
            objects,
            deadline,
        );
    }
    execute_provider_process_control_operation(
        config,
        environment,
        request,
        canonical_payload,
        request_fds,
        signing_key,
        deadline,
    )
    .map(ProviderProcessOperationOutput::control)
}

#[cfg(target_os = "linux")]
fn execute_provider_process_control_operation(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    request: &ProviderRpcRequestEnvelope,
    canonical_payload: &[u8],
    request_fds: Vec<OwnedFd>,
    signing_key: &ed25519_dalek::SigningKey,
    deadline: &OperationDeadline,
) -> Result<Vec<u8>, V2RuntimeError> {
    if matches!(
        request.operation,
        ProviderSubchannelOperation::FreshResponseAttestation
            | ProviderSubchannelOperation::VerifyFreshResponseAttestation
    ) {
        if !request_fds.is_empty()
            || !request.exact_objects.is_empty()
        {
            return Err(V2RuntimeError::new(
                "provider_attestation_descriptor_forbidden",
                "trusted-host attestation control operations do not accept file descriptors",
            ));
        }
        return match request.operation {
            ProviderSubchannelOperation::FreshResponseAttestation => {
                execute_provider_trusted_host_fresh_attestation(
                    config,
                    environment,
                    request,
                    canonical_payload,
                    signing_key,
                    deadline,
                )
            }
            ProviderSubchannelOperation::VerifyFreshResponseAttestation => {
                execute_provider_verify_trusted_host_fresh_attestation(
                    config,
                    environment,
                    canonical_payload,
                    deadline,
                )
            }
            _ => unreachable!(),
        };
    }
    match request.operation {
        ProviderSubchannelOperation::EmergencyExecute => {
            return execute_provider_emergency_manifest(
                config,
                environment,
                canonical_payload,
                request_fds,
                signing_key,
                deadline,
            );
        }
        _ => {
            if request_fds.len() != request.exact_objects.len() {
                return Err(V2RuntimeError::new(
                    "provider_process_descriptor_mismatch",
                    "provider request descriptor count does not match its exact-object manifest",
                ));
            }
            let files =
                request_fds.into_iter().map(File::from).collect();
            validate_exact_object_files(
                &request.exact_objects,
                files,
                Some(deadline),
            )?;
        }
    }
    match request.operation {
        ProviderSubchannelOperation::Preflight => {
            let preflight: ProviderPreflightRequest =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_process_preflight_invalid",
                            "provider preflight request is not a closed DTO",
                        )
                    })?;
            if preflight.role != config.role
                || preflight.role_identity_root_sha256
                    != config.role_identity_root_sha256
                || preflight
                    .proof_independent_pins_root_sha256
                    != config
                        .proof_independent_pins_root_sha256
            {
                return Err(V2RuntimeError::new(
                    "provider_process_preflight_role_mismatch",
                    "provider preflight is not bound to this role and its measured trust roots",
                ));
            }
            let implemented_operations =
                built_in_implemented_operations(config);
            let receipt = ProviderPreflightReceipt {
                role: config.role.clone(),
                attestation_mode: config.attestation_mode,
                provider_id: config.provider_id.clone(),
                provider_generation: config.provider_generation,
                executable_measurement_sha256:
                    environment.executable_sha256.clone(),
                provider_config_sha256:
                    environment.config_sha256.clone(),
                key_material_sha256:
                    config.key_material_sha256.clone(),
                tee_measurement_sha256:
                    config.tee_measurement_sha256.clone(),
                role_identity_root_sha256:
                    config.role_identity_root_sha256.clone(),
                proof_independent_pins_root_sha256:
                    config
                        .proof_independent_pins_root_sha256
                        .clone(),
                durable_fence_supported: implemented_operations
                    .contains(
                        &ProviderSubchannelOperation::FenceRevoke,
                    ),
                signed_attestation_supported:
                    implemented_operations.contains(
                        &ProviderSubchannelOperation::FreshResponseAttestation,
                    ),
                independent_hardware_attestation_supported: false,
                implemented_operations,
                authenticated_seqpacket: true,
                pidfd_kill_supported: true,
                cgroup_kill_supported: true,
                process_group_kill_supported: false,
                bounded_reap_supported: true,
                local_clock_claimed_as_trusted_time: false,
                configured_response_fallback: false,
            };
            crate::canonical_json_bytes(&receipt).map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_preflight_invalid",
                    "provider preflight receipt cannot be canonicalized",
                )
            })
        }
        ProviderSubchannelOperation::TrustedTime => {
            let request: ProviderBooleanDecision =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_trusted_time_request_invalid",
                            "trusted-time request is not a closed DTO",
                        )
                    })?;
            let trust = verify_provider_operator_trust_bundle(
                config,
                deadline,
            )?;
            if !request.accepted {
                return Err(V2RuntimeError::new(
                    "provider_trusted_time_request_denied",
                    "trusted-time request did not opt into the signed authority",
                ));
            }
            crate::canonical_json_bytes(
                &ProviderTrustedTimeDecision {
                    trusted_now_epoch_ms:
                        trust.trusted_now_epoch_ms,
                },
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_trusted_time_response_invalid",
                    "trusted-time decision cannot be canonicalized",
                )
            })
        }
        ProviderSubchannelOperation::RuntimeReadiness => {
            let request: ProviderBooleanDecision =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_readiness_request_invalid",
                            "runtime readiness request is not a closed DTO",
                        )
                    })?;
            let accepted = request.accepted
                && config.attestation_mode
                    == V2AttestationMode::TrustedHost
                && verify_provider_operator_trust_bundle(
                    config,
                    deadline,
                )
                .is_ok()
                && validate_provider_private_state_directory(
                    config,
                )
                .is_ok()
                && validate_provider_shared_state_directories(
                    config,
                    environment,
                )
                .is_ok();
            crate::canonical_json_bytes(
                &ProviderBooleanDecision { accepted },
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_readiness_response_invalid",
                    "runtime readiness decision cannot be canonicalized",
                )
            })
        }
        ProviderSubchannelOperation::VerifyRuntimeAttestation => {
            let verification:
                ProviderRuntimeAttestationRequestOwned =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_runtime_attestation_request_invalid",
                            "runtime-attestation request is not a supported closed DTO",
                        )
                    })?;
            let accepted =
                verify_provider_runtime_attestation_request(
                    config,
                    verification,
                    deadline,
                )?;
            crate::canonical_json_bytes(
                &ProviderBooleanDecision { accepted },
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_runtime_attestation_response_invalid",
                    "runtime-attestation decision cannot be canonicalized",
                )
            })
        }
        ProviderSubchannelOperation::Revocation => {
            let revocation: ProviderRevocationRequestOwned =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_revocation_request_invalid",
                            "revocation request is not a closed DTO",
                        )
                    })?;
            validate_identifier(&revocation.authorization_id)?;
            let accepted = revocation.revocation_epoch
                    == config
                        .trust_bundle
                        .revocation
                        .revocation_epoch
                && config
                    .trust_bundle
                    .revocation
                    .revoked_authorization_ids
                    .contains(&revocation.authorization_id);
            crate::canonical_json_bytes(
                &ProviderBooleanDecision { accepted },
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_revocation_response_invalid",
                    "revocation decision cannot be canonicalized",
                )
            })
        }
        ProviderSubchannelOperation::PublicReleaseSignature => {
            crate::canonical_json_bytes(
                &verify_provider_signature_request(
                    config,
                    "public-release",
                    canonical_payload,
                )?,
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_signature_response_invalid",
                    "public-release signature decision cannot be canonicalized",
                )
            })
        }
        ProviderSubchannelOperation::RecoveryAuthorization
        | ProviderSubchannelOperation::RecoveryResolution => {
            crate::canonical_json_bytes(
                &verify_provider_signature_request(
                    config,
                    "recovery",
                    canonical_payload,
                )?,
            )
            .map_err(|_| {
                V2RuntimeError::new(
                    "provider_signature_response_invalid",
                    "recovery signature decision cannot be canonicalized",
                )
            })
        }
        ProviderSubchannelOperation::FenceRevoke => {
            let fence: ProviderFenceRevocationRequest =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_process_fence_request_invalid",
                            "provider fence request is not a closed DTO",
                        )
                    })?;
            let (
                durable_fence_receipt_sha256,
                authority_revision,
                fence_quiescent,
            ) = revoke_provider_mutation_fence(
                environment,
                &fence.provider_operation_id,
                fence.provider_generation,
                fence.fencing_token,
                &fence.durable_start_receipt_sha256,
                &fence.mutation_fence_permit_sha256,
                deadline,
            )?;
            let mut receipt = ProviderFenceRevocationReceipt {
                provider_operation_id:
                    fence.provider_operation_id,
                provider_operation_binding_sha256:
                    fence.provider_operation_binding_sha256,
                provider_generation:
                    fence.provider_generation,
                fencing_token: fence.fencing_token,
                durable_fence_receipt_sha256,
                fence_quiescent,
                authority_revision,
                issued_at_epoch_ms: system_time_epoch_ms()?,
                signer_key_id: config.key_id.clone(),
                signer_key_material_sha256:
                    config.key_material_sha256.clone(),
                signature: String::new(),
            };
            receipt.signature = sign_provider_process_value(
                signing_key,
                b"serverware.response-v2/fence-revocation/v1\0",
                &receipt,
            )?;
            crate::canonical_json_bytes(&receipt).map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_fence_receipt_invalid",
                    "provider fence receipt cannot be canonicalized",
                )
            })
        }
        ProviderSubchannelOperation::EmergencyFenceRevoke => {
            let fence: EmergencyFenceRevocationRequest =
                crate::decode_canonical_json(canonical_payload)
                    .map_err(|_| {
                        V2RuntimeError::new(
                            "provider_process_fence_request_invalid",
                            "emergency fence request is not a closed DTO",
                        )
                    })?;
            let (
                durable_fence_receipt_sha256,
                authority_revision,
                fence_quiescent,
            ) = revoke_provider_mutation_fence(
                environment,
                &fence.target.provider_operation_id,
                fence.target.provider_generation,
                fence.target.fencing_token,
                &fence.target.durable_start_receipt_sha256,
                &fence.target.mutation_fence_permit_sha256,
                deadline,
            )?;
            let mut receipt =
                EmergencyFenceRevocationReceipt {
                    target_binding_sha256:
                        fence.target.target_binding_sha256,
                    provider_operation_id:
                        fence.target.provider_operation_id,
                    provider_generation:
                        fence.target.provider_generation,
                    fencing_token: fence.target.fencing_token,
                    process_identity_manifest_sha256:
                        fence.process_identity_manifest_sha256,
                    durable_fence_receipt_sha256,
                    fence_quiescent,
                    authority_revision,
                    issued_at_epoch_ms:
                        system_time_epoch_ms()?,
                    signer_key_id: config.key_id.clone(),
                    signer_key_material_sha256:
                        config.key_material_sha256.clone(),
                    signature: String::new(),
                };
            receipt.signature = sign_provider_process_value(
                signing_key,
                b"serverware.response-v2/emergency-fence-revocation/v1\0",
                &receipt,
            )?;
            crate::canonical_json_bytes(&receipt).map_err(|_| {
                V2RuntimeError::new(
                    "provider_process_fence_receipt_invalid",
                    "emergency fence receipt cannot be canonicalized",
                )
            })
        }
        _ => Err(V2RuntimeError::new(
            "provider_operation_unimplemented",
            "the measured provider binary does not implement this role operation; no configured-response fallback exists",
        )),
    }
}

#[cfg(target_os = "linux")]
fn execute_provider_emergency_manifest(
    config: &MeasuredProviderProcessConfig,
    environment: &ProviderProcessEnvironment,
    canonical_payload: &[u8],
    request_fds: Vec<OwnedFd>,
    _signing_key: &ed25519_dalek::SigningKey,
    deadline: &OperationDeadline,
) -> Result<Vec<u8>, V2RuntimeError> {
    let request: EmergencyExecutorRequest =
        crate::decode_canonical_json(canonical_payload).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_emergency_request_invalid",
                    "emergency executor request is not a closed DTO",
                )
            },
        )?;
    if request.descriptor_count != request_fds.len()
        || request.descriptor_count < 3
        || request.descriptor_count > PROVIDER_RPC_MAX_FDS
    {
        return Err(V2RuntimeError::new(
            "provider_emergency_descriptor_mismatch",
            "emergency executor descriptor count is invalid",
        ));
    }
    let manifest_fd = request_fds
        .last()
        .ok_or_else(|| {
            V2RuntimeError::new(
                "provider_emergency_manifest_missing",
                "emergency executor sealed manifest is missing",
            )
        })?
        .as_raw_fd();
    let seals = unsafe {
        libc::fcntl(manifest_fd, libc::F_GET_SEALS)
    };
    let required_seals = libc::F_SEAL_SEAL
        | libc::F_SEAL_SHRINK
        | libc::F_SEAL_GROW
        | libc::F_SEAL_WRITE;
    if seals < 0 || seals & required_seals != required_seals {
        return Err(V2RuntimeError::new(
            "provider_emergency_manifest_unsealed",
            "emergency executor manifest lacks immutable memfd seals",
        ));
    }
    if request.manifest_length == 0
        || request.manifest_length
            > RESPONSE_OBSERVATION_V2_MAX_CONTROL_BYTES as u64
    {
        return Err(V2RuntimeError::new(
            "provider_emergency_manifest_bounds_invalid",
            "emergency executor manifest length is invalid",
        ));
    }
    let manifest_length =
        usize::try_from(request.manifest_length).map_err(|_| {
            V2RuntimeError::new(
                "provider_emergency_manifest_bounds_invalid",
                "emergency executor manifest length is unsupported",
            )
        })?;
    let mut manifest_bytes = vec![0u8; manifest_length];
    let mut offset = 0usize;
    while offset < manifest_bytes.len() {
        let count = unsafe {
            libc::pread(
                manifest_fd,
                manifest_bytes[offset..].as_mut_ptr().cast(),
                manifest_bytes.len() - offset,
                offset as libc::off_t,
            )
        };
        if count <= 0 {
            return Err(V2RuntimeError::new(
                "provider_emergency_manifest_read_failed",
                "read exact emergency executor manifest",
            ));
        }
        offset = offset
            .checked_add(usize::try_from(count).unwrap_or(usize::MAX))
            .ok_or_else(|| {
                V2RuntimeError::new(
                    "provider_emergency_manifest_read_failed",
                    "emergency manifest read offset overflowed",
                )
            })?;
    }
    if format!("sha256:{:x}", Sha256::digest(&manifest_bytes))
        != request.manifest_sha256
    {
        return Err(V2RuntimeError::new(
            "provider_emergency_manifest_digest_mismatch",
            "emergency executor manifest does not match its request digest",
        ));
    }
    let manifest: EmergencyExecutorManifest =
        crate::decode_canonical_json(&manifest_bytes).map_err(
            |_| {
                V2RuntimeError::new(
                    "provider_emergency_manifest_invalid",
                    "emergency executor manifest is not a canonical closed DTO",
                )
            },
        )?;
    if crate::canonical_json_bytes(&manifest)
        .map(|bytes| bytes != manifest_bytes)
        .unwrap_or(true)
        || manifest.api_version != PROVIDER_RPC_API_VERSION
        || manifest.executor_generation
            != config.provider_generation
        || manifest.executor_operation_id
            != manifest.target.provider_operation_id
        || manifest.descriptor_count != request_fds.len()
        || manifest.cgroup_kill_index
            != manifest.pidfd_indices.len()
        || manifest.cgroup_events_index
            != manifest.cgroup_kill_index + 1
        || manifest.sealed_manifest_index
            != manifest.cgroup_events_index + 1
        || manifest.sealed_manifest_index + 1
            != request_fds.len()
        || manifest.pidfd_indices
            != (0..manifest.pidfd_indices.len())
                .collect::<Vec<_>>()
        || manifest.maximum_duration_ms == 0
        || manifest.maximum_duration_ms
            > PROVIDER_TERMINATION_DEADLINE_MS
        || manifest.absolute_deadline_epoch_ms
            != environment.deadline_at_epoch_ms
    {
        return Err(V2RuntimeError::new(
            "provider_emergency_manifest_binding_mismatch",
            "emergency manifest does not exactly bind descriptor roles, target, generation, and deadline",
        ));
    }
    let started = Instant::now();
    let cgroup_kill_fd =
        request_fds[manifest.cgroup_kill_index].as_raw_fd();
    let cgroup_write = unsafe {
        libc::write(
            cgroup_kill_fd,
            b"1\n".as_ptr().cast(),
            2,
        )
    };
    let cgroup_errno = if cgroup_write < 0 {
        std::io::Error::last_os_error().raw_os_error()
    } else {
        None
    };
    let cgroup_kill_attempted = cgroup_write == 2
        || cgroup_errno == Some(libc::ESRCH);
    let mut pidfd_kill_attempted = true;
    for index in &manifest.pidfd_indices {
        let result = unsafe {
            libc::syscall(
                libc::SYS_pidfd_send_signal,
                request_fds[*index].as_raw_fd(),
                libc::SIGKILL,
                std::ptr::null::<libc::siginfo_t>(),
                0,
            )
        };
        let error = if result < 0 {
            std::io::Error::last_os_error().raw_os_error()
        } else {
            None
        };
        pidfd_kill_attempted &=
            result == 0 || error == Some(libc::ESRCH);
    }
    let cgroup_events_fd =
        request_fds[manifest.cgroup_events_index].as_raw_fd();
    let mut pidfd_exit_observed =
        manifest.pidfd_indices.is_empty();
    let mut cgroup_empty_observed = false;
    let mut cgroup_events_bytes = Vec::new();
    while started.elapsed()
        < Duration::from_millis(manifest.maximum_duration_ms)
        && !deadline.expired().unwrap_or(true)
    {
        pidfd_exit_observed =
            manifest.pidfd_indices.iter().all(|index| {
                let mut pollfd = libc::pollfd {
                    fd: request_fds[*index].as_raw_fd(),
                    events: libc::POLLIN,
                    revents: 0,
                };
                unsafe { libc::poll(&mut pollfd, 1, 0) } == 1
                    && pollfd.revents
                        & (libc::POLLIN
                            | libc::POLLHUP
                            | libc::POLLERR)
                        != 0
            });
        let mut buffer = [0u8; 4096];
        let count = unsafe {
            libc::pread(
                cgroup_events_fd,
                buffer.as_mut_ptr().cast(),
                buffer.len(),
                0,
            )
        };
        if count > 0 {
            let count = usize::try_from(count).unwrap_or(0);
            cgroup_events_bytes.clear();
            cgroup_events_bytes
                .extend_from_slice(&buffer[..count]);
            cgroup_empty_observed =
                std::str::from_utf8(&cgroup_events_bytes)
                    .ok()
                    .map(|events| {
                        events.lines().any(|line| {
                            line.trim() == "populated 0"
                        })
                    })
                    .unwrap_or(false);
        }
        if pidfd_exit_observed && cgroup_empty_observed {
            break;
        }
        std::thread::sleep(Duration::from_millis(5));
    }
    if !cgroup_kill_attempted
        || !pidfd_kill_attempted
        || !pidfd_exit_observed
        || !cgroup_empty_observed
        || cgroup_events_bytes.is_empty()
    {
        return Err(V2RuntimeError::new(
            "provider_emergency_execution_unverified",
            "emergency executor could not prove stable-handle kill, pidfd exit, and cgroup emptiness within its independent bound",
        ));
    }
    let observation = EmergencyExecutorObservation {
        target_binding_sha256:
            manifest.target.target_binding_sha256,
        provider_operation_id:
            manifest.target.provider_operation_id,
        provider_generation:
            manifest.target.provider_generation,
        manifest_sha256: request.manifest_sha256,
        cgroup_kill_attempted,
        pidfd_kill_attempted,
        pidfd_exit_observed,
        cgroup_empty_observed,
        cgroup_events_sha256: format!(
            "sha256:{:x}",
            Sha256::digest(&cgroup_events_bytes)
        ),
        observed_at_epoch_ms: system_time_epoch_ms()?,
    };
    crate::canonical_json_bytes(&observation).map_err(|_| {
        V2RuntimeError::new(
            "provider_emergency_observation_invalid",
            "emergency executor observation cannot be canonicalized",
        )
    })
}
